const INDEX_HTML = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0b1220\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/icon-192.png\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Interpretia\">\n<title>Interpretia Live</title>\n<style>\n*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#111827;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\nmain{max-width:980px;margin:auto;padding:14px 14px 28px}.top{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}\nh1{font-size:22px;margin:0}.sub{font-size:12px;color:#667085;margin-top:3px}.status{padding:7px 10px;border-radius:999px;background:#e7eaf0;font-size:12px}\n.status.live{background:#dcfce7;color:#166534}.listen{width:100%;min-height:64px;border:0;border-radius:16px;background:#111827;color:white;font-size:19px;font-weight:800;margin-bottom:12px}\n.listen.active{background:#166534}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.ctrl{min-height:44px;border:1px solid #d9dee6;background:white;border-radius:11px;padding:9px 12px;font-size:14px}.danger{border-color:#f0b7b7;color:#b42318;background:#fff5f5}.install{border-color:#98a2b3;background:#f8fafc;font-weight:700}.install.hidden{display:none}\n.grid{display:grid;grid-template-columns:1fr;gap:10px}.card{background:#fff;border:1px solid #e0e4e9;border-radius:15px;padding:14px}.wide{grid-column:1/-1}\n.label{font-size:10px;font-weight:800;letter-spacing:.07em;text-transform:uppercase;color:#667085;margin-bottom:8px}.stream{min-height:112px;font-size:18px;line-height:1.55}\n.partial{opacity:.5}.history{max-height:240px;overflow:auto}.item{padding:9px 0;border-top:1px solid #e7e9ed;font-size:14px;line-height:1.45}.item:first-child{border-top:0}.item b{display:block;margin-top:3px}\n.termrow{padding:10px 0;border-top:1px solid #e7e9ed}.termrow:first-child{border-top:0}.term{font-weight:800}.explain{font-size:13px;color:#475467;line-height:1.45;margin-top:3px}\n.meta,.tip{font-size:11px;color:#667085;line-height:1.45}.details{display:grid;grid-template-columns:1fr 1fr;gap:7px}.detail{padding:9px;border-radius:10px;background:#f8fafc;font-size:13px}.detail b{display:block;font-size:10px;color:#667085;text-transform:uppercase;margin-bottom:3px}\n@media(min-width:760px){main{padding:22px}.grid{grid-template-columns:1fr 1fr}.stream{min-height:135px}}\n</style>\n</head>\n<body>\n<main>\n<div class=\"top\"><div><h1>Interpretia Live</h1><div class=\"sub\">Asistente de interpretación Español ↔ Inglés</div></div><div id=\"status\" class=\"status\">Listo</div></div>\n<button id=\"listen\" class=\"listen\">🎙️ Escuchar</button>\n<div class=\"toolbar\">\n<select id=\"direction\" class=\"ctrl\"><option value=\"en-es\">🇺🇸 Inglés → Español</option><option value=\"es-en\">🇪🇸 Español → Inglés</option></select>\n<select id=\"domain\" class=\"ctrl\"><option value=\"\">📚 Todos los glosarios</option></select>\n<button id=\"new\" class=\"ctrl\">＋ Nueva llamada</button>\n<button id=\"finish\" class=\"ctrl danger\">⏹️ Finalizar interpretación</button>\n<button id=\"install\" class=\"ctrl install\">📲 Instalar Interpretia</button>\n</div>\n<div class=\"grid\">\n<section class=\"card\"><div class=\"label\">Lo que se escucha</div><div id=\"heard\" class=\"stream\">Pulsa “Escuchar” y permite el micrófono.</div></section>\n<section class=\"card\"><div class=\"label\">Interpretación en vivo</div><div id=\"translation\" class=\"stream\">La interpretación aparecerá aquí por fragmentos.</div></section>\n<section class=\"card wide\"><div class=\"label\">Conversación reciente</div><div id=\"history\" class=\"history\"><div class=\"meta\">Sin fragmentos todavía.</div></div></section>\n<section class=\"card wide\"><div class=\"label\">🔎 Términos técnicos</div><div id=\"terms\"><div class=\"meta\">Se consultará el glosario automáticamente.</div></div></section>\n<section class=\"card wide\"><div class=\"label\">Datos importantes</div><div id=\"details\" class=\"details\"><div class=\"detail\"><b>Fechas</b>—</div><div class=\"detail\"><b>Números</b>—</div><div class=\"detail\"><b>Direcciones</b>—</div><div class=\"detail\"><b>Otros</b>—</div></div></section>\n</div>\n<div class=\"tip\">Versión gratuita: no requiere API Key. El reconocimiento de voz usa la capacidad del navegador y la traducción se realiza mediante un servicio web gratuito. La aplicación no guarda un historial en el servidor. Al pulsar “Finalizar interpretación” se detiene la escucha y se borra la conversación mostrada en esta sesión. Para mejor calidad, usa una fuente de audio externa clara y un micrófono cercano.</div>\n</main>\n<script>\nlet glossary=[], recognition=null, listening=false, history=[], lastFinal=\"\", translationBusy=false, translateController=null;\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#039;\"}[c]));\nconst norm=s=>String(s||\"\").toLowerCase().replace(/[’']/g,\"'\").replace(/[^a-záéíóúüñ0-9' ]/gi,\" \");\nconst EMBEDDED_GLOSSARY=[{\"english\":\"AC unit (Air-conditioning unit)\",\"spanish\":\"Unidad de aire acondicionado / \\nUnidad de climatización\",\"definition\":\"AC or air conditioning is a system designed to cool the air in your home. Some contractors or builders call an AC unit anything that conditions the air, hot or cold.\",\"industry\":\"Customer Service\",\"example_en\":\"The air-conditioning unit had broken down again.\",\"example_es\":\"La unidad de aire acondicionado se había dañado nuevamente.\",\"source\":\"Customer Service\"},{\"english\":\"ACA (Affordable Care Act)\",\"spanish\":\"Ley de cuidado de salud asequible\",\"definition\":\"The Affordable Care Act (ACA), also known as \\\"Obamacare\\\", is a comprehensive reform law, enacted in 2010, that increases health insurance coverage for the uninsured and implements reforms to the health insurance market.\",\"industry\":\"Health Insurance\",\"example_en\":\"The Affordable Care Act (ACA) gives more people a chance to have access to health insurance.\",\"example_es\":\"La ley de cuidado de salud asequible le da la oportunidad a más personas de acceder a un seguro de salud.\",\"source\":\"Customer Service\"},{\"english\":\"Academic Degree\",\"spanish\":\"Diploma académico / \\nTítulo académico /\\nLicenciatura\",\"definition\":\"An academic degree is a qualification awarded to a student upon successful completion of a course of study in higher education, usually at a college or university.\",\"industry\":\"School\",\"example_en\":\"He has an academic degree in psychology.\",\"example_es\":\"Él tiene un título académico en psicología.\",\"source\":\"Customer Service\"},{\"english\":\"Accessible\",\"spanish\":\"Accesible /\\nAlcanzable\",\"definition\":\"Easy to approach, reach, enter, speak with, or use.\",\"industry\":\"Social Services\",\"example_en\":\"The welfare office is easily accessible by public transport.\",\"example_es\":\"La oficina de Bienestar Social es accesible fácilmente por transporte público.\",\"source\":\"Customer Service\"},{\"english\":\"Accident\",\"spanish\":\"Accidente\",\"definition\":\"An unfortunate incident that happens unexpectedly and unintentionally, typically resulting in damage or injury.\",\"industry\":\"Auto Insurance\",\"example_en\":\"How did the accident happen?\",\"example_es\":\"¿Cómo ocurrió el accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Accommodations\",\"spanish\":\"Adaptaciones /\\nAcomodaciones\",\"definition\":\"Accommodations or adaptations are changes in educational environments or practices that help students overcome the barriers presented by a disability.\",\"industry\":\"School\",\"example_en\":\"Accommodations are available to children who receive services under IDEA or Section 504 of the Rehabilitation Act.\",\"example_es\":\"Hay adaptaciones que están disponibles para los niños que reciben servicios bajo la ley de educación para personas con discapacidades, o la sección 504 de la ley de rehabilitación.\",\"source\":\"Customer Service\"},{\"english\":\"Account\",\"spanish\":\"Cuenta\",\"definition\":\"A formal business arrangement providing for regular dealings or services (as in banking, advertising, email or store credit).\",\"industry\":\"Customer Service\",\"example_en\":\"I am sorry, but I cannot find your account.\",\"example_es\":\"Lo lamento, pero no puedo encontrar su cuenta.\",\"source\":\"Customer Service\"},{\"english\":\"Account holder\",\"spanish\":\"Titular de la cuenta\",\"definition\":\"The owner of an account.\",\"industry\":\"Customer Service\",\"example_en\":\"Only the account holder is allowed to make changes.\",\"example_es\":\"Solo el titular de la cuenta puede hacer cambios.\",\"source\":\"Customer Service\"},{\"english\":\"Account Specialist\",\"spanish\":\"Especialista en manejo de cuentas\",\"definition\":\"Serves customers by completing enrollments and conversion mailings; responding to requests and inquiries; resolving complaints; maintaining quality service.\",\"industry\":\"Finance\",\"example_en\":\"The account specialist will explain how this works.\",\"example_es\":\"El especialista en manejo de cuentas le explicará cómo funciona esto.\",\"source\":\"Customer Service\"},{\"english\":\"Account statement /\\nBank statement / \\nStatement /\",\"spanish\":\"Estado de cuenta /\\nExtracto bancario\",\"definition\":\"A document which shows amounts of money that you have received, spent, etc. A brief record of a financial account.\",\"industry\":\"Finance\",\"example_en\":\"I just received my account statement, and I see I am being charged a late fee even though I paid before the due date.\",\"example_es\":\"Acabo de recibir mi estado de cuenta y veo me están cobrando un cargo por mora aunque pagué antes de la fecha de vencimiento.\",\"source\":\"Customer Service\"},{\"english\":\"Accountability\",\"spanish\":\"Asumir la responsabilidad / Rendición de cuentas\",\"definition\":\"Accountability is an assurance that an individual or organization is evaluated on its performance or behavior related to something for which it is responsible. The term is related to responsibility but is regarded more from the perspective of oversight.\",\"industry\":\"General\",\"example_en\":\"The public demands accountability from its elected officials.\",\"example_es\":\"El público exige una rendición de cuentas de parte de sus funcionarios electos.\",\"source\":\"Customer Service\"},{\"english\":\"Accreditation\",\"spanish\":\"Acreditación /\\nReconocimiento / \\nCertificación\",\"definition\":\"The action or process of officially recognizing someone as having a particular status or being qualified to perform a particular activity.\",\"industry\":\"School\",\"example_en\":\"As with any other degree program, accreditation is an assurance that this school has met the generally recognized standards for culinary education.\",\"example_es\":\"Al igual que con cualquier otro programa de estudios, la acreditación es una garantía de que esta escuela ha cumplido con los estándares generalmente reconocidos para la educación culinaria.\",\"source\":\"Customer Service\"},{\"english\":\"ACH (Automated Clearing House)\",\"spanish\":\"Cámara de compensación automatizada\",\"definition\":\"The Automated Clearing House (ACH) is an electronic funds-transfer system that facilitates payments in the U.S. It acts as a financial hub and helps people and organizations move money from one bank account to another.\",\"industry\":\"Finance\",\"example_en\":\"Ma'am your check hasn't  been posted in  your account yet. That check is from a different bank and has to go through the ACH first.\",\"example_es\":\"Señora, su cheque no ha sido acreditado/debitado en su cuenta aún. Ese cheque es de un banco diferente y tiene que pasar por la Cámara de Compensación Automatizada primero.\",\"source\":\"Customer Service\"},{\"english\":\"Aches and pains\",\"spanish\":\"Malestares /\\nAchaques\",\"definition\":\"Minor pains and discomforts, typically in the muscles.\",\"industry\":\"Medical\",\"example_en\":\"I have aches and pains almost everyday but I think that comes with age.\",\"example_es\":\"Tengo malestares casi todos los días, pero creo que vienen con la edad.\",\"source\":\"Customer Service\"},{\"english\":\"Achievement Gap\",\"spanish\":\"Brecha en el rendimiento estudiantil\",\"definition\":\"It is the unequal output of educational results between two groups of students, such as high-income and low-income students.\",\"industry\":\"School\",\"example_en\":\"The benefits of small classes have reduced the student achievement gap in reading and science.\",\"example_es\":\"Los beneficios de las clases pequeñas han reducido la brecha en el rendimiento estudiantil en lectura y ciencias.\",\"source\":\"Customer Service\"},{\"english\":\"Acid reflux\",\"spanish\":\"Reflujo gástrico /\\nReflujo ácido\",\"definition\":\"A condition in which acidic gastric fluid is regurgitated into the esophagus, causing heartburn.\",\"industry\":\"Medical\",\"example_en\":\"After I eat tomatoes I get acid reflux.\",\"example_es\":\"Después de comer tomates tengo reflujo gástrico.\",\"source\":\"Customer Service\"},{\"english\":\"Acoustic insulation\",\"spanish\":\"Aislamiento acústico\",\"definition\":\"It is a process that uses a lightweight bulky material that absorbs sound wave energy, it reduces sound echo in homes, offices, and other buildings by absorbing sound as it’s penetrating the walls and ceilings.\",\"industry\":\"Home Insurance\",\"example_en\":\"Acoustic insulation is used to reduce sound energy echo within a space.\",\"example_es\":\"El aislamiento acústico se utiliza para reducir el eco de la energía sonora dentro de un espacio.\",\"source\":\"Customer Service\"},{\"english\":\"ACS (Administration for children services)\",\"spanish\":\"Departamento de servicios para menores /\\nDepartamento de servicios infantil\",\"definition\":\"ACS is an agency that protects and promotes safety and the well-being of children and families by providing child welfare, juvenile justice, and early care and education services.\",\"industry\":\"Social Services\",\"example_en\":\"ACS provides foster care services for children not able to safely remain at home.\",\"example_es\":\"El departamento de servicios a menores brinda servicios de cuidados de acogida para niños que no pueden permanecer en casa de manera segura.\",\"source\":\"Customer Service\"},{\"english\":\"Active\",\"spanish\":\"Activo/\\nVigente\",\"definition\":\"Currently in use or in effect.\",\"industry\":\"General\",\"example_en\":\"Your account is active, I have just checked the system.\",\"example_es\":\"Su cuenta está activa, justo acabo de revisar el sistema.\",\"source\":\"Customer Service\"},{\"english\":\"Acts of god\",\"spanish\":\"Eventos fortuitos\",\"definition\":\"An instance of uncontrollable natural forces in operation (often used in insurance claims).\",\"industry\":\"Insurance (general)\",\"example_en\":\"The flooding was surely an act of god.\",\"example_es\":\"La inundación fue sin duda un evento fortuito.\",\"source\":\"Customer Service\"},{\"english\":\"Actual cash value (ACV)\",\"spanish\":\"Valor real en efectivo\",\"definition\":\"The value of your property, based on the current cost to replace it minus depreciation.\",\"industry\":\"Home Insurance\",\"example_en\":\"The insurance company awarded him the actual cash value for the furniture that was destroyed in the fire.\",\"example_es\":\"La compañía de seguros le otorgó el valor real en efectivo de los muebles destruidos en el incendio.\",\"source\":\"Customer Service\"},{\"english\":\"Actuary\",\"spanish\":\"Actuario de seguros\",\"definition\":\"An actuary is a professional with advanced mathematical skills who deals with the measurement and management of risk and uncertainty.\",\"industry\":\"Home Insurance\",\"example_en\":\"Actuaries are involved in all business aspects, including planning insurance premiums.\",\"example_es\":\"Los actuarios están involucrados en todos los aspectos empresariales, incluida la planificación de las primas de seguros.\",\"source\":\"Customer Service\"},{\"english\":\"ADD (Attention-deficit disorder)\",\"spanish\":\"Trastorno de déficit de atención (TDA)\",\"definition\":\"A term used for people who have excessive difficulties with concentration without the presence of other ADHD symptoms such as excessive impulsiveness or hyperactivity.\",\"industry\":\"Medical\",\"example_en\":\"Educational strategies are always important for children with ADD.\",\"example_es\":\"Las estrategias educativas siempre son importantes para los niños o niñas con trastorno de déficit de atención.\",\"source\":\"Customer Service\"},{\"english\":\"Additional living expenses (ALE) coverage\",\"spanish\":\"Cobertura para gastos adicionales de alojamiento\",\"definition\":\"ALE coverage reimburses you for extra expenses if you’re forced to live elsewhere temporarily after a problem covered by your policy causes damage to your house and you file a claim.\",\"industry\":\"Home Insurance\",\"example_en\":\"The additional living expenses (ALE) coverage is a standard component of a homeowners insurance policy.\",\"example_es\":\"La cobertura para gastos adicionales de alojamiento es un componente estándar de una póliza de seguro de propietario de vivienda.\",\"source\":\"Customer Service\"},{\"english\":\"Address\",\"spanish\":\"Domicilio /\\nDirección\",\"definition\":\"The information about where a place is located or where someone lives.\",\"industry\":\"General\",\"example_en\":\"Is your mailing address the same as your home address?\",\"example_es\":\"¿Es su dirección de correspondencia la misma que su dirección de residencia?\",\"source\":\"Customer Service\"},{\"english\":\"Address on file\",\"spanish\":\"Dirección en el archivo /\\nDirección registrada\",\"definition\":\"An address which you have saved in some sort of record or filing system\",\"industry\":\"General\",\"example_en\":\"Please provide us with the address we have on file so we can forward your package.\",\"example_es\":\"Por favor proporciónenos la dirección que tenemos en el archivo para que podamos enviar su pedido.\",\"source\":\"Customer Service\"},{\"english\":\"ADHD (Attention-deficit/hyperactivity disorder)\",\"spanish\":\"Trastorno de déficit de atención con hiperactividad (TDAH)\",\"definition\":\"A chronic condition including attention difficulty, hyperactivity and impulsiveness.\",\"industry\":\"Medical\",\"example_en\":\"The main characteristics of ADHD are inattention, hyperactivity and impulsivity.\",\"example_es\":\"Las principales características del trastorno de déficit de atención con hiperactividad son la inatención, hiperactividad e impulsividad.\",\"source\":\"Customer Service\"},{\"english\":\"Adjuster\",\"spanish\":\"Liquidador(a) de daños /\\nPerita(o) de siniestros\",\"definition\":\"Insurance company employee in charge of processing claims to their resolution.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The adjuster will call you to take a recorded statement about the accident.\",\"example_es\":\"El perito de siniestro le llamará para tomarle una declaración grabada acerca del accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Admission, Review, and Dismissal (ARD)\",\"spanish\":\"Admisión, revisión y conclusión/salida del programa\",\"definition\":\"The Admission, Review, and Dismissal (ARD) team is a team of individuals that includes, at a minimum, parents, a special education teacher, someone qualified to interpret test results, district representation, and a general education teacher.  These individuals are responsible for the development and review of a child’s IEP, evaluation/re-evaluation, and behavior plans as needed.\",\"industry\":\"School\",\"example_en\":\"The ARD team must meet at least once a year by law; however, teachers or parents can call at any time.\",\"example_es\":\"El equipo de admisión, revisión y expulsión debe reunirse al menos una vez al año según la ley; sin embargo, los maestros o los padres pueden llamar en cualquier hora.\",\"source\":\"Customer Service\"},{\"english\":\"Advanced Placement (AP) Program\",\"spanish\":\"Programa de colocación avanzada /\\nPrograma de equivalencia universitaria\",\"definition\":\"The Advanced Placement (AP) program gives high school students the opportunity to take college-level work.\",\"industry\":\"School\",\"example_en\":\"AP classes can be a rewarding experience for students looking for a challenge.\",\"example_es\":\"Las clases de colocación avanzada pueden ser una experiencia gratificante para los estudiantes que estén buscando un desafío.\",\"source\":\"Customer Service\"},{\"english\":\"Advice nurse\",\"spanish\":\"Enfermera(o) consejera(o)\",\"definition\":\"Responsible for answering calls and providing appropriate information to assist callers in assessing needs for health services. They give appropriate clinical options and assist in assessing primary care, specialty care or community resources. They also educate callers on self-care advice and preventative measures.\",\"industry\":\"Medical\",\"example_en\":\"You can always call the advice nurse to find out if it is necessary to make an appointment with your doctor or if you should go immediately to the emergency room.\",\"example_es\":\"Usted siempre puede llamar a la enfermera consejera para averiguar si es necesario hacer una cita con su doctor o si debe ir de inmediato a la sala de emergencias.\",\"source\":\"Customer Service\"},{\"english\":\"Aerial\",\"spanish\":\"Antena / \\nAntena de televisión /\\nAntena de recepción por aire\",\"definition\":\"An aerial is a device or a piece of wire that receives television or radio signals and is usually attached to a radio, television, car, or building.\",\"industry\":\"Customer Service\",\"example_en\":\"Owners are responsible for the siting of television aerials and satellite dishes on their property.\",\"example_es\":\"Los propietarios son responsables de la ubicación de las antenas de recepción por aire de televisión y antenas parabólicas en su propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Affidavit\",\"spanish\":\"Declaración jurada\",\"definition\":\"A written statement that someone makes after promising officially to tell the truth.\",\"industry\":\"General\",\"example_en\":\"The lawyer submitted an affidavit before the trial.\",\"example_es\":\"El abogado presentó una declaración jurada antes del juicio.\",\"source\":\"Customer Service\"},{\"english\":\"Affordable\",\"spanish\":\"Asequible (NO ACCESIBLE)\",\"definition\":\"Being within the financial means of most people. Being economically able to pay for an asset or service\",\"industry\":\"Social Services\",\"example_en\":\"You may find affordable clothes at the Salvation Army.\",\"example_es\":\"Usted puede encontrar ropa asequible en Salvation Army.\",\"source\":\"Customer Service\"},{\"english\":\"Age of Majority\",\"spanish\":\"Mayoría de edad\",\"definition\":\"It is the age at which a child gains the rights to make his or her own decisions, including any decision related to education.\",\"industry\":\"General\",\"example_en\":\"Most states describe the age of majority as 18 years old.\",\"example_es\":\"La mayoría de los estados describen la mayoría de edad como 18 años.\",\"source\":\"Customer Service\"},{\"english\":\"AIDS (Acquired Immunodeficiency Syndrome)\",\"spanish\":\"SIDA (Síndrome de inmunodeficiencia adquirida)\",\"definition\":\"AIDS is the late stage of HIV infection that occurs when the body’s immune system is badly damaged because of the virus.\",\"industry\":\"Medical\",\"example_en\":\"The actor is receiving treatment for AIDS at a leading clinic.\",\"example_es\":\"El actor está recibiendo tratamiento contra el SIDA en una clínica líder.\",\"source\":\"Customer Service\"},{\"english\":\"Air-fare\",\"spanish\":\"Tarifa aérea\",\"definition\":\"It is the fee paid by a passenger for air transport and is made up of the charge for a passenger to fly from an origin to a destination and includes the conditions, rules and restrictions for travelling on the airline.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"Have you checked the price of a round-trip airfare to Asia or Africa lately?\",\"example_es\":\"¿Ha revisado últimamente el precio de la tarifa aérea de un viaje de ida y vuelta a Asia o África?\",\"source\":\"Customer Service\"},{\"english\":\"Airbag\",\"spanish\":\"Bolsa de aire\",\"definition\":\"A safety device inside a vehicle, consisting of a cushion designed to inflate rapidly in the event of a collision and positioned so as to protect passengers from being thrown.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did the airbags deploy when the car crashed?\",\"example_es\":\"¿Se desplegaron las bolsas de aire cuando el carro chocó?\",\"source\":\"Customer Service\"},{\"english\":\"Airborne\",\"spanish\":\"Aerotransportado / \\nAéreo\",\"definition\":\"In the air, or carried by air or wind or by an aircraft. Done or being in the air; being off the ground.\",\"industry\":\"Medical\",\"example_en\":\"Face masks protect from airborne particles.\",\"example_es\":\"Las mascarillas protegen de las partículas aéreas.\",\"source\":\"Customer Service\"},{\"english\":\"Airline ticket /\\nPlane ticket\",\"spanish\":\"Pasaje de avión /\\nBoleto de avión\",\"definition\":\"Document or electronic record, issued by an airline or a travel agency, that confirms that an individual is entitled to a seat on a flight on an aircraft. It may be one of two types: a paper ticket, which comprises coupons or vouchers; or an electronic ticket (commonly referred to as an e-ticket).\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"The electronic booking of an airline ticket can reduce the cost of the transaction from $8 to $1.\",\"example_es\":\"La reserva electrónica de un pasaje de avión puede reducir el coste de la transacción de 8 dólares a 1 dólar.\",\"source\":\"Customer Service\"},{\"english\":\"Airway\",\"spanish\":\"Vía(s) respiratoria(s)\",\"definition\":\"The passage by which air reaches a person's lungs.\",\"industry\":\"Medical\",\"example_en\":\"Please make sure your child's airways are clear.\",\"example_es\":\"Por favor, asegúrese de que las vías respiratorias de su niño estén despejadas.\",\"source\":\"Customer Service\"},{\"english\":\"Alien registration card / \\nPermanent resident card /\\nGreen card (Informal)\",\"spanish\":\"Carnet de extranjería /\\nTarjeta de residencia permanente\",\"definition\":\"An Alien Registration Card is the official name for the identification card given to lawful permanent residents by the USCIS to identify them as such. Other names for the alien registration card include green card, permanent resident card, and permanent visa.\",\"industry\":\"General\",\"example_en\":\"I have already been approved for the green card, but I haven´t received it by mail yet.\",\"example_es\":\"Ya he sido aprobada para la tarjeta de residencia permanente pero aún no la he recibido por correo.\",\"source\":\"Customer Service\"},{\"english\":\"Alimony\",\"spanish\":\"Pensión al/a la excónyuge\",\"definition\":\"Payments made to a spouse or former spouse under a separation or divorce agreement.\",\"industry\":\"Social Services\",\"example_en\":\"Do you receive alimony?\",\"example_es\":\"¿Usted recibe pensión al excónyuge?\",\"source\":\"Customer Service\"},{\"english\":\"Alley\",\"spanish\":\"Callejón /\\nPasadizo\",\"definition\":\"A narrow passageway between or behind buildings.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I did not see the car exit the alley.\",\"example_es\":\"No vi al carro salir del callejón.\",\"source\":\"Customer Service\"},{\"english\":\"Alternative School\",\"spanish\":\"Escuela alternativa\",\"definition\":\"It is a school that doesn’t provide the typical educational experience. Another way to think of it, is that it is designed to educate students who haven’t been successful in regular schools, often due to behavioral issues or learning disabilities.\",\"industry\":\"School\",\"example_en\":\"An alternative school may involve a range of different educational settings other than the typical school.\",\"example_es\":\"Una escuela alternativa puede involucrar una variedad de parámetros educativos diferentes a la escuela típica.\",\"source\":\"Customer Service\"},{\"english\":\"Amount\",\"spanish\":\"Monto /\\nCantidad\",\"definition\":\"A quantity of something, such as money.\",\"industry\":\"General\",\"example_en\":\"What is the amount due on the bill you received?\",\"example_es\":\"¿Cuál es el monto adeudado en la factura que recibió?\",\"source\":\"Customer Service\"},{\"english\":\"Annual out-of-pocket maximum\",\"spanish\":\"Responsabilidad máxima del\\npaciente /\\nLímite anual de gastos del paciente /\\nTope anual\",\"definition\":\"Refers to the most money an insured individual will have to pay out of his own pocket, during a policy period (usually a year) for health care services. When this limit is reached, your health plan will cover 100% of your qualified expenses.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Since you already reached your annual out-of-pocket maximum the insurance company will take care of your medical bills for rest of the year.\",\"example_es\":\"Dado que usted ya llegó al límite anual de gastos del paciente la compañía de seguro se hará cargo de sus facturas médicas por el resto del año.\",\"source\":\"Customer Service\"},{\"english\":\"Antibiotics\",\"spanish\":\"Antibióticos\",\"definition\":\"Drugs used to kill harmful bacteria and to cure infections (such as penicillin or its derivatives). Antibiotics inhibit the growth of and destroy microorganisms.\",\"industry\":\"Medical\",\"example_en\":\"It is important you take the antibiotics prescribed with food, until you run out. Don't stop taking them, even if you start feeling better.\",\"example_es\":\"Es importante que tome los antibióticos recetados con comida hasta que se terminen. No deje de tomarlos, incluso si empieza a sentirse mejor.\",\"source\":\"Customer Service\"},{\"english\":\"Antifreeze\",\"spanish\":\"Agente anticongelante\",\"definition\":\"A liquid, typically based on ethylene glycol, which can be added to water to lower the freezing point, chiefly used in the radiator of a motor vehicle\",\"industry\":\"Auto Insurance\",\"example_en\":\"To prevent the blocking of the liquid streaming valve, use antifreeze once a month in the winter time.\",\"example_es\":\"Para evitar el bloqueo de la válvula de flujo utilice un agente anticongelante una vez al mes durante el invierno.\",\"source\":\"Customer Service\"},{\"english\":\"Antihistamine\",\"spanish\":\"Antihistamínico\",\"definition\":\"Antihistamines are medicines often used to relieve symptoms of allergies, such as hay fever, hives, conjunctivitis and reactions to insect bites or stings.\",\"industry\":\"Medical\",\"example_en\":\"The doctor prescribed an antihistamine to treat her seasonal allergies.\",\"example_es\":\"El doctor le recetó un antihistamínico para tratar sus alergias estacionales.\",\"source\":\"Customer Service\"},{\"english\":\"Antitheft device\",\"spanish\":\"Dispositivo contra robos\",\"definition\":\"Refers to any device or method used to prevent or deter the unauthorized appropriation of items considered valuable.\",\"industry\":\"Customer Service\",\"example_en\":\"Your auto insurance premium will be lower because you have the antitheft device installed.\",\"example_es\":\"La prima del seguro de autos será más baja porque tiene instalado el dispositivo antirrobos.\",\"source\":\"Customer Service\"},{\"english\":\"Appendix\",\"spanish\":\"Apéndice\",\"definition\":\"The appendix is a small finger-shaped tube that branches off the first part of the large intestine.\",\"industry\":\"Medical\",\"example_en\":\"The appendix can become inflamed or infected, causing pain in the lower right part of the abdomen.\",\"example_es\":\"El apéndice puede inflamarse o infectarse, causando dolor en la parte inferior derecha del abdomen.\",\"source\":\"Customer Service\"},{\"english\":\"Appliances\",\"spanish\":\"Electrodomésticos\",\"definition\":\"Devices or instruments designed to perform a specific function, especially an electrical device, such as a washer or a toaster, for household use.\",\"industry\":\"Customer Service\",\"example_en\":\"Mr. Romero, my tenant, caused damages to my appliances due to his negligence. The technician performed troubleshooting on the stove, the refrigerator and the dishwasher.\",\"example_es\":\"El Sr. Romero, mi inquilino, causó daños a mis electrodomésticos debido a su imprudencia. El técnico realizó la reparación de la estufa, el refrigerador y el lavaplatos.\",\"source\":\"Customer Service\"},{\"english\":\"Applicant\",\"spanish\":\"Solicitante / \\nPostulante\",\"definition\":\"A person who formally requests something, such as a job, social services or admission to a college or university.\",\"industry\":\"General\",\"example_en\":\"Many applicants simply don't meet hiring requirements.\",\"example_es\":\"Muchos postulantes simplemente no cumplen los requisitos de contratación.\",\"source\":\"Customer Service\"},{\"english\":\"Application\",\"spanish\":\"Solicitud (NO APLICACIÓN)\",\"definition\":\"A form used in making a request for a service or purchase, to be filled out by an applicant, as for a loan, credit card, job, driver's license, etc.\",\"industry\":\"Social Services\",\"example_en\":\"Your credit card application has been approved.\",\"example_es\":\"Su solicitud de tarjeta de crédito ha sido aprobada.\",\"source\":\"Customer Service\"},{\"english\":\"Applied Behavior Analysis (ABA)\",\"spanish\":\"Análisis aplicado del\\ncomportamiento\",\"definition\":\"It is a technique used for correcting behavior and social skill deficits. It is based on an understanding of how positive reinforcement causes behaviors to repeat.\",\"industry\":\"School\",\"example_en\":\"One pillar of ABA is discrete trial training (DTT). This means breaking a skill down into its most basic steps and teaching it systematically.\",\"example_es\":\"Un pilar del análisis de comportamiento aplicado es el entrenamiento de prueba discreta. Esto significa desglosar una habilidad hasta sus pasos más básicos y enseñarla sistemáticamente.\",\"source\":\"Customer Service\"},{\"english\":\"Appointment\",\"spanish\":\"Cita\",\"definition\":\"An arrangement to meet a person or be at a place at a certain time.\",\"industry\":\"General\",\"example_en\":\"You are all set. Your appointment is on June 26th at 9:45 a.m.\",\"example_es\":\"Ya está todo listo. Su cita es el 26 de junio a las 9:45 a.m.\",\"source\":\"Customer Service\"},{\"english\":\"Appraisal\",\"spanish\":\"Tasación / \\nValuación\",\"definition\":\"An evaluation of a home insurance property claim by an authorized person to determine property value or damaged property value.\",\"industry\":\"Home Insurance\",\"example_en\":\"Many policies provide an appraisal process to resolve claim disputes.\",\"example_es\":\"Muchas pólizas proveen un proceso de tasación para resolver disputas en los reclamos\",\"source\":\"Customer Service\"},{\"english\":\"Appraiser\",\"spanish\":\"Tasador(a) /\\nEvaluador(a) /\\nAgente de avalúos\",\"definition\":\"One who estimates officially the cost or repairs or replacement of damaged property, such as a home or a car.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The appraiser inspected the vehicle and sent his report to the adjuster.\",\"example_es\":\"El tasador inspeccionó el vehículo y envió su reporte al liquidador de daños.\",\"source\":\"Customer Service\"},{\"english\":\"Approved\",\"spanish\":\"Aprobado\",\"definition\":\"To officially accept. (Context dependent) Refers to the act of officially agreeing to or accepting as satisfactory or meeting requirements.\",\"industry\":\"General\",\"example_en\":\"Your loan application has been approved.\",\"example_es\":\"Su solicitud de préstamo ha sido aprobada.\",\"source\":\"Customer Service\"},{\"english\":\"APR (Annual\\nPercentage Rate)\",\"spanish\":\"Tasa porcentual anual /\\nTasa de interés anual\",\"definition\":\"Describes the interest rate for a whole year (annualized), rather than just a monthly fee/rate, as applied on a loan, mortgage loan, credit card, etc. It is a charge expressed as an annual rate.\",\"industry\":\"Finance\",\"example_en\":\"Understanding the difference between APR or annual percentage rate and interest rate could save you thousands of dollars on your mortgage.\",\"example_es\":\"Entender la diferencia entre tasa de porcentaje anual y tasa de interés le puede ahorrar miles de dólares en su hipoteca.\",\"source\":\"Customer Service\"},{\"english\":\"ASP (Alternate-side parking)\",\"spanish\":\"Estacionamiento en lados alternos\",\"definition\":\"It is a traffic law that dictates on which side of a street cars can be parked on a given day.\",\"industry\":\"General\",\"example_en\":\"When alternate side parking is in effect, you’re not allowed to park on the side of the street that’s being cleaned.\",\"example_es\":\"Cuando el Estacionamiento en lados alternos está en vigencia, usted no tiene permitido estacionar en el lado de la calle que está siendo limpiado.\",\"source\":\"Customer Service\"},{\"english\":\"Arbitration award/\\nArbitral award\",\"spanish\":\"Laudo Arbitral\",\"definition\":\"Once the arbitrator or arbitration panel comes to a decision, an arbitration award is issued. This award may be a legally binding decision on not only the amount of the covered loss, but also fees, further damages, and/or potential disciplinary actions required to resolve the dispute.\",\"industry\":\"Insurance (general)\",\"example_en\":\"What would happen if you did not accept the arbitration award?\",\"example_es\":\"¿Qué pasaría si no aceptara el laudo arbitral?\",\"source\":\"Customer Service\"},{\"english\":\"Arbitrator\",\"spanish\":\"Árbitro / \\nMediador de seguro\",\"definition\":\"Arbitrators, mediators, and conciliators help opposing parties settle disputes outside of court. They hold private, confidential hearings, which are less formal than a court trial.\",\"industry\":\"Insurance (general)\",\"example_en\":\"The arbitrators are usually lawyers, but they do not necessarily have to be. Sometimes engineers, adjusters or claims executives can serve as insurance arbitrators.\",\"example_es\":\"Los árbitros suelen ser abogados, pero no necesariamente tienen que serlo. A veces, ingenieros, liquidadores de daños o ejecutivos de reclamaciones pueden actuar como mediadores de seguros.\",\"source\":\"Customer Service\"},{\"english\":\"Area code\",\"spanish\":\"Código de área\",\"definition\":\"A three-digit code that identifies one of the telephone areas into which the U.S. and certain other countries are divided and that precedes the local telephone number when dialing a call between areas.\",\"industry\":\"General\",\"example_en\":\"Please, give me your phone number including your area code.\",\"example_es\":\"Por favor, deme su número de teléfono incluyendo su código de área.\",\"source\":\"Customer Service\"},{\"english\":\"Armpit\",\"spanish\":\"Axila\",\"definition\":\"The hollow beneath the junction of the arm and shoulder.\",\"industry\":\"Medical\",\"example_en\":\"Place the tip of the thermometer in an armpit. Make sure the armpit is dry.\",\"example_es\":\"Coloque la punta del termómetro en una axila. Asegúrese de que la axila está seca.\",\"source\":\"Customer Service\"},{\"english\":\"Arrangement\",\"spanish\":\"Arreglo /\\nAcuerdo\",\"definition\":\"A plan for an event, or with the goal of fulfilling an obligation.\",\"industry\":\"General\",\"example_en\":\"We can offer a 6 month payment arrangement.\",\"example_es\":\"Podemos ofrecer un acuerdo de pago de 6 meses.\",\"source\":\"Customer Service\"},{\"english\":\"Arrest\",\"spanish\":\"Detención /\\nArresto\",\"definition\":\"To deprive (a person) of liberty by taking them into custody, under lawful authority.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"After your son's arrest, he will be taken to the county jail and will be held there until he appears before the judge.\",\"example_es\":\"Después del arresto de su hijo, él será llevado a la cárcel del condado y permanecerá ahí hasta que se presente ante un juez.\",\"source\":\"Customer Service\"},{\"english\":\"Arrival\",\"spanish\":\"Llegada\",\"definition\":\"The act or time of arriving.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"What is the date and time of your arrival?\",\"example_es\":\"¿Cuál es la fecha y hora de su llegada?\",\"source\":\"Customer Service\"},{\"english\":\"Artery\",\"spanish\":\"Arteria\",\"definition\":\"Any of the muscular-walled tubes forming part of the circulation system by which blood (mainly which has been oxygenated) is conveyed from the heart to all parts of the body.\",\"industry\":\"Medical\",\"example_en\":\"Chest pain is one of the effects of coronary artery disease.\",\"example_es\":\"El dolor de pecho es uno de los efectos de la enfermedad de las arterias coronarias.\",\"source\":\"Customer Service\"},{\"english\":\"Assault\",\"spanish\":\"Agresión (NO ASALTO)\",\"definition\":\"An intentional or reckless act that causes another person to expect to be subjected to immediate and unlawful violence.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"I need to know when the assault took place and if you recognize the assailant.\",\"example_es\":\"Necesito saber cuándo ocurrió la agresión física y si usted reconoce al agresor.\",\"source\":\"Customer Service\"},{\"english\":\"Assets\",\"spanish\":\"Bienes /\\nActivos\",\"definition\":\"It is a resource with economic value that an individual or corporation owns or controls with the expectation that it will provide a future benefit.\",\"industry\":\"Finance\",\"example_en\":\"The president placed his assets in a blind trust.\",\"example_es\":\"El presidente puso sus bienes en un fideicomiso ciego.\",\"source\":\"Customer Service\"},{\"english\":\"Assistant principal\",\"spanish\":\"Subdirector(a) / Vicedirector(a)\",\"definition\":\"A person who assists a principal in their work. They are education professionals who focus on the administrative work involved in operating a school. They are involved in overseeing teaching staff, and must ensure that the school standards for curriculum and discipline are followed.\",\"industry\":\"School\",\"example_en\":\"She refused to turn over her cellphone to her teacher, and then later to the assistant principal.\",\"example_es\":\"Ella se negó a entregar su teléfono celular a su maestro(a), y luego, más tarde, a su subdirector(a)\",\"source\":\"Customer Service\"},{\"english\":\"Assistive Technology (AT)\",\"spanish\":\"Dispositivos de apoyo o\\nauxiliares / \\nTecnología de Asistencia\",\"definition\":\"Any item, piece of equipment, software program, or product system that is used to increase, maintain, or improve the functional capabilities of persons with disabilities.\",\"industry\":\"School\",\"example_en\":\"Some examples of assistive technology can include walkers, wheelchairs, sound amplifiers, communication devices, pencil grips, or word prediction software.\",\"example_es\":\"Algunos ejemplos de tecnología de asistencia pueden incluir andadores, sillas de ruedas, amplificadores de sonido, dispositivos de comunicación, agarres para lápices o programas de predicción de palabras.\",\"source\":\"Customer Service\"},{\"english\":\"At fault\",\"spanish\":\"Tener la culpa /\\nCulpable\",\"definition\":\"Responsibility for a mistake or an offense; culpability.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The police determined you were at fault for the accident.\",\"example_es\":\"La policía determinó que usted tuvo la culpa del accidente.\",\"source\":\"Customer Service\"},{\"english\":\"ATM (Automated\\nTeller Machine)\",\"spanish\":\"Cajero automático\",\"definition\":\"An unattended machine, usually outside a bank, that automatically provides cash and performs other banking services on insertion of a special card by the account holder.\",\"industry\":\"Finance\",\"example_en\":\"I need some cash immediately and the ATM machines would limit the amount that I could withdraw.\",\"example_es\":\"Necesito algo de dinero inmediatamente y los cajeros automáticos limitarían la cantidad que pudiera retirar.\",\"source\":\"Customer Service\"},{\"english\":\"ATM Card\",\"spanish\":\"Tarjeta de cajero automático\",\"definition\":\"An ATM card is a dedicated payment card issued by a financial institution, which enables a customer to access their financial accounts via its and others' automated teller machines (ATMs).\",\"industry\":\"Finance\",\"example_en\":\"I will need your ATM card number or checking account number.\",\"example_es\":\"Necesitaré el número de su tarjeta de cajero automático o su número de cuenta corriente.\",\"source\":\"Customer Service\"},{\"english\":\"Augmentative and Alternative Communication Device (AAC Device)\",\"spanish\":\"Comunicación alternativa y mediante dispositivos de\\namplificación /\\nDispositivo de comunicación alternativa y aumentativa\",\"definition\":\"It is a tool that uses a method of communication other than speech to communicate an individual’s thoughts, needs, wants, and ideas.\",\"industry\":\"School\",\"example_en\":\"AAC devices can be electronic, like iPads, or manual, like communication boards.\",\"example_es\":\"Los dispositivos de comunicación alternativa y aumentativa pueden ser electrónicos, como los iPads, o manuales, como las pizarras de comunicación.\",\"source\":\"Customer Service\"},{\"english\":\"Auto loan /\\nCar loan\",\"spanish\":\"Préstamo vehicular / \\nPréstamo para automóvil\",\"definition\":\"It is a type of loan that allows you to borrow money from a lender and use that money to purchase a car.\",\"industry\":\"Finance\",\"example_en\":\"Auto loans are secured loans where the vehicle itself is used as a collateral.\",\"example_es\":\"Los préstamos vehiculares son préstamos garantizados en los que el propio vehículo se utiliza como garantía subsidiaria.\",\"source\":\"Customer Service\"},{\"english\":\"Automatic Payment\",\"spanish\":\"Pago automático\",\"definition\":\"Process that pays bills directly from a bank account through an electronic payment system; an individual will authorize payments to vendors on a regular basis. Vendors will submit requests for payment directly to the bank.\",\"industry\":\"Finance\",\"example_en\":\"You can stop the automatic payments at any time.\",\"example_es\":\"Usted puede detener los pagos automáticos en cualquier momento.\",\"source\":\"Customer Service\"},{\"english\":\"Automatic withdrawal\",\"spanish\":\"Retiro automático\",\"definition\":\"This transaction occurs when you grant your bank permission to make a payment to a creditor from your bank account.\",\"industry\":\"Finance\",\"example_en\":\"Customers can pay their bills through automatic withdrawal from their bank accounts.\",\"example_es\":\"Los clientes pueden pagar sus facturas a través de retiros automáticos de sus cuentas bancarias.\",\"source\":\"Customer Service\"},{\"english\":\"Baby bottle\",\"spanish\":\"Biberón\",\"definition\":\"A bottle with a nipple to drink directly from. It is typically used by infants and young children when a mother does not breastfeed.\",\"industry\":\"General\",\"example_en\":\"Make sure you hold the baby bottle properly to help your baby feed well.\",\"example_es\":\"Asegúrese de sostener el biberón apropiadamente para ayudar a que su bebé se alimente bien.\",\"source\":\"Customer Service\"},{\"english\":\"Baby formula\",\"spanish\":\"Fórmula para bebés /\\nFórmula para lactantes /\\nLeche infantil\",\"definition\":\"Food which contains nutrients to feed infants used as a complete or partial substitute for breast milk.\",\"industry\":\"General\",\"example_en\":\"If you’re unable to breastfeed, you will need to give the infant baby formula. We will provide some samples for you to take home.\",\"example_es\":\"Si no puede amamantar, deberá darle leche infantil a su bebé. Nosotros le proveeremos de algunas muestras para que se las lleve a casa.\",\"source\":\"Customer Service\"},{\"english\":\"Back rent\",\"spanish\":\"Alquiler atrasado\",\"definition\":\"It refers to overdue rental payments owed by a tenant to their landlord. It accumulates when rent isn't paid on time, leading to potential legal action.\",\"industry\":\"Customer Service\",\"example_en\":\"Understanding back rent is crucial for both renters and property owners to maintain a harmonious relationship.\",\"example_es\":\"Entender el alquiler atrasado es crucial para que tanto inquilinos como propietarios mantengan una relación armoniosa.\",\"source\":\"Customer Service\"},{\"english\":\"Backdated\",\"spanish\":\"Retroactivo\",\"definition\":\"To make something, especially a pay increase, effective from an earlier time.\",\"industry\":\"Customer Service\",\"example_en\":\"Unfortunately, we will have to backdate the interest rate on your loan.\",\"example_es\":\"Desafortunadamente, tendremos que hacer retroactiva la tasa de interés en su préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Backfire\",\"spanish\":\"Explosión del escape\",\"definition\":\"Refers to an engine that undergoes a mistimed explosion in the cylinder or exhaust.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Backfire occurs when unburned fuel moves back into the intake, and combusts.\",\"example_es\":\"La explosión o detonación del escape sucede cuando el combustible no quemado regresa hacia la toma y agarra fuego/ arde/ se prende en fuego.\",\"source\":\"Customer Service\"},{\"english\":\"Backpay\",\"spanish\":\"Pago retroactivo\",\"definition\":\"It is any form of unpaid financial compensation owed to an employee by their employer.\",\"industry\":\"Social Services\",\"example_en\":\"Back pay may come from work that was performed but never paid for, or could have been performed but the employee was prevented from performing.\",\"example_es\":\"Los pagos retroactivos pueden proceder de un trabajo que se realizó, pero nunca se pagó, o que pudo haberse realizado, pero se le impidió al empleado realizarlo.\",\"source\":\"Customer Service\"},{\"english\":\"Backrest\",\"spanish\":\"Respaldo\",\"definition\":\"A support for a person´s back when taking a seat.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I had the backrest upholstered in vinyl.\",\"example_es\":\"Hice que el respaldo sea tapizado en vinilo.\",\"source\":\"Customer Service\"},{\"english\":\"Bail\",\"spanish\":\"Fianza\",\"definition\":\"Security, usually a sum of money exchanged for the release of an arrested person as a guarantee of that person's appearance for trial.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Your bail has been set at $25,000. If you don't have the funds, you can see a bail bondsman.\",\"example_es\":\"Su fianza está fijada a $25,000. Si no tiene los fondos, puede ver a un fiador judicial.\",\"source\":\"Customer Service\"},{\"english\":\"Balance\",\"spanish\":\"Saldo (NO BALANCE)\",\"definition\":\"The amount of money you have in a bank account or an amount of money owed.\",\"industry\":\"Finance\",\"example_en\":\"Your available balance is $2,000.\",\"example_es\":\"Su saldo disponible es de $2,000.\",\"source\":\"Customer Service\"},{\"english\":\"Balance transfer\",\"spanish\":\"Transferencia de saldo\",\"definition\":\"To shift existing credit card debt to another card or account charging a low interest rate or even 0% interest, helping you to save money.\",\"industry\":\"Finance\",\"example_en\":\"I would like to make a balance transfer from my MasterCard ending in 4323 to take advantage of the promotional 0% interest for 12 months offered by Discover.\",\"example_es\":\"Quisiera hacer una transferencia de saldos de mi tarjeta MasterCard que termina en 4323 para aprovechar el interés promocional de 0% por 12 meses ofrecido por Discover.\",\"source\":\"Customer Service\"},{\"english\":\"Bathtub chair /\\nShower chair\",\"spanish\":\"Silla para la bañera o tina /\\nSilla para la ducha\",\"definition\":\"A shower chair is a seat made for bathtubs or showers. These seats are designed for use by people who are unable to stand to take a shower and must sit instead. With the use of shower chairs, elderly people and those with mobility problems are able to have some independence by bathing themselves or having help doing so.\",\"industry\":\"General\",\"example_en\":\"For many years he had to use a bathtub chair.\",\"example_es\":\"Ella tuvo que usar una silla para la bañera por muchos años.\",\"source\":\"Customer Service\"},{\"english\":\"Beany Hat\",\"spanish\":\"Gorro tejido\",\"definition\":\"A small close-fitting hat worn on the back of the head.\",\"industry\":\"General\",\"example_en\":\"It was very cold outside, so he decided to wear a beany hat before leaving the house.\",\"example_es\":\"Hacía mucho frío afuera, así que decidió usar un gorro tejido antes de salir de la casa.\",\"source\":\"Customer Service\"},{\"english\":\"Bedpan\",\"spanish\":\"Bacinilla\",\"definition\":\"A bedpan or bed pan is a device used as a receptacle for the urine and/or feces of a person who is confined to a bed and therefore not able to use a toilet or chamber pot.\",\"industry\":\"General\",\"example_en\":\"The nurse brought in a clean bedpan for the patient to use.\",\"example_es\":\"La enfermera trajo una bacinilla limpia para que el paciente la use.\",\"source\":\"Customer Service\"},{\"english\":\"Bedside commode\",\"spanish\":\"Inodoro portátil /\\nRetrete portátil /\\nBaño portátil\",\"definition\":\"A bedside commode is a portable toilet. It has no water supply or drainage and can be easily moved around for convenience. It is a great help to people who can't walk to the bathroom because of frailty or illness. A bedside commode is better than using a bedpan or urinal.\",\"industry\":\"Medical\",\"example_en\":\"The nurse will help you go to the bathroom using a bedside commode.\",\"example_es\":\"La enfermera le ayudará a ir al baño usando un inodoro portátil.\",\"source\":\"Customer Service\"},{\"english\":\"Behavior Intervention Plan (BIP)\",\"spanish\":\"Plan de Intervención para la modificación de la conducta /\\nPlan de Intervención para el comportamiento\",\"definition\":\"A Behavior Intervention Plan (BIP) is a written plan that identifies the specific strategies, interventions and supports the Individualized Education Program (IEP) Team will use to reinforce positive behaviors and decrease problem behaviors.\",\"industry\":\"School\",\"example_en\":\"The BIP should be based on multiple data sources, including a Functional Behavioral Assessment.\",\"example_es\":\"El plan de intervención para el comportamiento debe basarse en múltiples fuentes de datos, incluida una evaluación del comportamiento funcional.\",\"source\":\"Customer Service\"},{\"english\":\"Belly button / \\nNavel\",\"spanish\":\"Ombligo\",\"definition\":\"The belly button is an informal term for the navel. It refers to the scar on the abdomen that is caused when the umbilical cord is removed.\",\"industry\":\"Medical\",\"example_en\":\"An umbilical hernia appears as a bulge around the belly button.\",\"example_es\":\"Una hernia umbilical aparece como un bulto alrededor del ombligo.\",\"source\":\"Customer Service\"},{\"english\":\"Belt-sander /\\nElectric sander\",\"spanish\":\"Lijadora de banda /\\nLijadora eléctrica\",\"definition\":\"An electric tool fitted with a revolving abrasive belt, used in shaping and finishing wood and other materials.\",\"industry\":\"General\",\"example_en\":\"A belt-sander is powered by an electric motor, and it can either be portable or stationary.\",\"example_es\":\"Una lijadora de banda es alimentada por un motor eléctrico y puede ser portátil o estacionaria.\",\"source\":\"Customer Service\"},{\"english\":\"Benchmarks\",\"spanish\":\"Puntos de referencia\",\"definition\":\"Academic benchmarks involve setting measurable standards for evaluating one’s learning. Academic benchmarks may be set for individual students or for institutions when ranking themselves against others.\",\"industry\":\"School\",\"example_en\":\"An academic benchmark may be set at the beginning of a course for the set of concepts that students should know by the end of the term.\",\"example_es\":\"Se puede establecer un punto de referencia académico al comienzo de un curso para el conjunto de conceptos que los estudiantes deberían saber al final del trimestre.\",\"source\":\"Customer Service\"},{\"english\":\"Beneficiary\",\"spanish\":\"Beneficiaria(o)\",\"definition\":\"Person(s) who may become eligible to receive or is receiving benefits under an insurance policy.\",\"industry\":\"General\",\"example_en\":\"My beneficiaries are my two nephews. I never got married.\",\"example_es\":\"Mis beneficiarios son mis dos sobrinos. Yo nunca me casé.\",\"source\":\"Customer Service\"},{\"english\":\"Benefits\",\"spanish\":\"Beneficios\",\"definition\":\"Payment or service provided, receiving money from the government because of a low income or lack of income. An advantage or profit gained from something.\",\"industry\":\"Social Services\",\"example_en\":\"Your food stamps benefits will begin as of June 1st and the monthly amount will be $265.48.\",\"example_es\":\"Sus beneficios de cupones de alimentos empezarán a partir del primero de junio y la cantidad mensual será de $265.48.\",\"source\":\"Customer Service\"},{\"english\":\"Bifocal lenses\",\"spanish\":\"Lentes bifocales\",\"definition\":\"Bifocals are a type of eyeglasses that feature two different optical powers in one lens. The top part of a bifocal lens corrects distance vision, while a smaller portion at the bottom of the lens corrects near vision.\",\"industry\":\"Health Insurance\",\"example_en\":\"Bifocal lenses are a popular choice for people who need both distance and near vision correction.\",\"example_es\":\"Las lentes bifocales son una opción popular para quienes necesitan corrección de la vista tanto de lejos como de cerca.\",\"source\":\"Customer Service\"},{\"english\":\"Bill\",\"spanish\":\"Factura\",\"definition\":\"An itemized account of the separate cost of goods sold, services performed, or work done, a statement of charges, invoice.\",\"industry\":\"Customer Service\",\"example_en\":\"You have to pay the bill in full by the due date to have your services restored.\",\"example_es\":\"Tiene que pagar la factura por completo antes de la fecha límite para que sus servicios sean restaurados.\",\"source\":\"Customer Service\"},{\"english\":\"Bill of sale\",\"spanish\":\"Contrato de Compraventa\",\"definition\":\"Document that transfers ownership of goods from one person to another. (NOT real state)\",\"industry\":\"Customer Service\",\"example_en\":\"I have the bill of sale to prove the car is mine.\",\"example_es\":\"Tengo el contrato de compra-venta para probar que el carro es mío.\",\"source\":\"Customer Service\"},{\"english\":\"Billing department\",\"spanish\":\"Departamento de facturación\",\"definition\":\"Department within an organization, that prepares or sends out invoices to obtain payments for services or goods.\",\"industry\":\"Customer Service\",\"example_en\":\"Adjustments to your bill can be made by the billing department.\",\"example_es\":\"Los ajustes a su factura se pueden hacer en el departamento de facturación.\",\"source\":\"Customer Service\"},{\"english\":\"Birth certificate\",\"spanish\":\"Acta de nacimiento /\\nPartida de nacimiento /\\nCertificado de nacimiento\",\"definition\":\"An official document issued upon a person's birth, attesting to the date and place of birth, parentage, etc.\",\"industry\":\"General\",\"example_en\":\"You will need to provide your birth certificate and another form of approved identification to apply for the passport.\",\"example_es\":\"Necesitará proveer su acta de nacimiento y otro tipo de identificación aprobada para solicitar el pasaporte.\",\"source\":\"Customer Service\"},{\"english\":\"Birthmarks\",\"spanish\":\"Marcas de nacimiento /\\nManchas de nacimiento\",\"definition\":\"An unusual and typically permanent brown or red mark on someone's body from birth.\",\"industry\":\"Jail system\",\"example_en\":\"The majority of birthmarks are harmless.\",\"example_es\":\"La mayoría de las marcas de nacimiento son inocuas.\",\"source\":\"Customer Service\"},{\"english\":\"Bite\",\"spanish\":\"Mordedura (de\\nanimal, de serpiente) /\\nPicadura (de insecto)\",\"definition\":\"Refers to a person or an animal use of the teeth to cut into something in order to eat it.  An animal bite is an injury caused by the mouth and teeth of an animal (including humans).\",\"industry\":\"Medical\",\"example_en\":\"In some cases, a human bite can be more dangerous than an animal bite.\",\"example_es\":\"En algunos casos, las mordeduras humanas pueden ser más peligrosas que las de los animales.\",\"source\":\"Customer Service\"},{\"english\":\"Blackboard\",\"spanish\":\"Pizarra /\\nPizarrón\",\"definition\":\"It is a hard smooth usually dark surface used especially in a classroom for writing or drawing on with chalk.\",\"industry\":\"School\",\"example_en\":\"Alice rubbed the blackboard clean for the teacher.\",\"example_es\":\"Alice limpió la pizarra para el maestro.\",\"source\":\"Customer Service\"},{\"english\":\"Bladder\",\"spanish\":\"Vejiga\",\"definition\":\"A membranous sac in humans and other animals, in which urine is collected for excretion.\",\"industry\":\"Medical\",\"example_en\":\"My father needs a procedure to fix his bladder issues.\",\"example_es\":\"Mi papá necesita un procedimiento para arreglar sus problemas de vejiga.\",\"source\":\"Customer Service\"},{\"english\":\"Bleeding\",\"spanish\":\"Sangrado\",\"definition\":\"Escape of blood from an injured vessel\",\"industry\":\"Medical\",\"example_en\":\"He needs an ambulance, he is bleeding profusely.\",\"example_es\":\"Necesita una ambulancia, está sangrando profusamente.\",\"source\":\"Customer Service\"},{\"english\":\"Blended Learning\",\"spanish\":\"Aprendizaje semipresencial /\\nAprendizaje combinado\",\"definition\":\"In hybrid learning or blending learning, part of a student’s education takes place online (sometimes even from home) and some takes place face-to-face in a classroom or learning center.\",\"industry\":\"School\",\"example_en\":\"A teacher that combines online homework with in-person class time is using a blended learning approach.\",\"example_es\":\"Un maestro que combina la tarea en línea con el tiempo de clase presencial está utilizando un enfoque de aprendizaje semipresencial.\",\"source\":\"Customer Service\"},{\"english\":\"Blind curve\",\"spanish\":\"Curva sin visibilidad\",\"definition\":\"Type of curve, curve, curved segment of a road that prevents motorists from having ample visibility when driving.\",\"industry\":\"Auto Insurance\",\"example_en\":\"A vehicle spinning on a slippery road in a blind curve is the most dangerous peril on the road.\",\"example_es\":\"Un vehículo girando en una carretera resbaladiza en una curva sin visibilidad es el riesgo más peligroso en una carretera.\",\"source\":\"Customer Service\"},{\"english\":\"Blind spot\",\"spanish\":\"Punto ciego /\\nZona muerta\",\"definition\":\"Refers to an area around the vehicle that cannot be directly observed by the driver while at the controls, under existing circumstances.\",\"industry\":\"Auto Insurance\",\"example_en\":\"She was in my blind spot, that's why I hit her bumper.\",\"example_es\":\"Ella estaba en mi punto ciego, por eso golpeé a su parachoques.\",\"source\":\"Customer Service\"},{\"english\":\"Blinkers\",\"spanish\":\"Luces intermitentes\",\"definition\":\"A device that blinks, especially a vehicle's turn signal.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did you notice if the other driver had her blinkers on before changing lanes?\",\"example_es\":\"¿Notó si el otro conductor tenía sus luces intermitentes encendidas antes de cambiar de carril?\",\"source\":\"Customer Service\"},{\"english\":\"Blood\",\"spanish\":\"Sangre\",\"definition\":\"The red liquid that circulates in the arteries and veins of humans and other vertebrate animals, carrying oxygen to and carbon dioxide from the tissues of the body.\",\"industry\":\"Medical\",\"example_en\":\"We will do some blood tests to determine if there is an infection.\",\"example_es\":\"Le haremos unos exámenes de sangre para determinar si tiene una infección.\",\"source\":\"Customer Service\"},{\"english\":\"Blood alcohol level\",\"spanish\":\"Nivel de alcoholemia\",\"definition\":\"Refers to the concentration of alcohol in one's bloodstream, expressed as a percentage. This percentage is used to determine whether a person is legally intoxicated, especially for DUI law.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Your blood alcohol level exceeds 0.08%.\",\"example_es\":\"Su nivel de alcoholemia excede 0.08%.\",\"source\":\"Customer Service\"},{\"english\":\"Blood Pressure\",\"spanish\":\"Presión arterial\",\"definition\":\"The pressure of the blood in the circulatory system closely related to the force and rate of the heartbeat and the diameter and elasticity of the arterial walls.\",\"industry\":\"Medical\",\"example_en\":\"If you have problems with high blood presure you should avoid sodium in your diet.\",\"example_es\":\"Si usted tiene problemas de presión arterial alta, debería evitar el sodio en su dieta.\",\"source\":\"Customer Service\"},{\"english\":\"Blood pressure\\ncuff\",\"spanish\":\"Tensiómetro /\\nMedidor de la presión arterial\",\"definition\":\"An instrument for measuring blood pressure in the arteries, especially one consisting of a pressure gauge and a nylon or rubber cuff that wraps around the upper arm and inflates to constrict the arteries.\",\"industry\":\"Medical\",\"example_en\":\"Please do not move the blood pressure cuff while it is inflating.\",\"example_es\":\"Por favor, no mueva el tensiómetro mientras se está inflando.\",\"source\":\"Customer Service\"},{\"english\":\"Bloody stool\",\"spanish\":\"Defecación con sangre /\\nDefecación sanguinolenta /\\nHeces con sangre /\\nHeces sanguinolentas\",\"definition\":\"Refers to a sign that there is bleeding somewhere along the digestive tract.\",\"industry\":\"Medical\",\"example_en\":\"Bloody stool means there is bleeding somewhere in the digestive tract.\",\"example_es\":\"Defecación sanguinolenta significa que hay sangrado en alguna parte del tracto digestivo.\",\"source\":\"Customer Service\"},{\"english\":\"Board of Education\",\"spanish\":\"Junta de educación\",\"definition\":\"A board of education (or school board) consists of community members who are either elected or appointed to represent and make decisions about their public school district.\",\"industry\":\"School\",\"example_en\":\"Rather than politicians, board of education members are usually simply community leaders, parents, or retired school leaders or education professionals interested in making a difference.\",\"example_es\":\"En vez de políticos, los miembros de la junta de educación suelen ser simplemente líderes de la comunidad, padres o líderes escolares jubilados o profesionales de la educación interesados en hacer una diferencia.\",\"source\":\"Customer Service\"},{\"english\":\"Board up (the windows)\",\"spanish\":\"Tapiar las ventanas\",\"definition\":\"Boarding up entails installing boards to different openings in a building, chiefly the windows and doors.\",\"industry\":\"Home Insurance\",\"example_en\":\"You may board up your windows to prevent additional damage.\",\"example_es\":\"Puede tapiar las ventanas para evitar daños adicionales.\",\"source\":\"Customer Service\"},{\"english\":\"Bodily injury\",\"spanish\":\"Lesiones corporales /\\nDaños físicos\",\"definition\":\"Any physical or mental impairment suffered by an insured. It includes occupational diseases, auto injuries, work-related accidents and even death.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I am the adjuster for the bodily injuries suffered during the car accident with Mr. Lewis.\",\"example_es\":\"Yo soy el perito de siniestros para las lesiones corporales sufridas durante el accidente automovilístico con el señor Lewis.\",\"source\":\"Customer Service\"},{\"english\":\"Body shop\",\"spanish\":\"Taller de carrocería /\\nTaller de chapistería /\\nTaller de latonería\",\"definition\":\"A repair establishment specializing in non-mechanical damages to automobile framework and body.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You are all set to bring your car to the body shop for an inspection.\",\"example_es\":\"Está todo listo para que traiga su carro al taller de carrocería para una inspección.\",\"source\":\"Customer Service\"},{\"english\":\"Booster shot\",\"spanish\":\"Vacuna de refuerzo /\\nDosis de refuerzo\",\"definition\":\"A dose of a substance used to renew or increase the effect of a drug or immunizing agent.\",\"industry\":\"Medical\",\"example_en\":\"Many vaccines require a booster shot after the initial dose to continue immunizing the body.\",\"example_es\":\"Muchas vacunas requieren una dosis de refuerzo después de la dosis inicial para continuar inmunizando el organismo.\",\"source\":\"Customer Service\"},{\"english\":\"Borrow\",\"spanish\":\"Pedir prestado\",\"definition\":\"To obtain or receive (something) on loan with the promise or understanding of returning it or its equivalent.\",\"industry\":\"General\",\"example_en\":\"May I please borrow some money? I have not paid my rent yet.\",\"example_es\":\"¿Podría pedir prestado algo de dinero, por favor? No he pagado mi alquiler aún.\",\"source\":\"Customer Service\"},{\"english\":\"Bowel movement\",\"spanish\":\"Evacuación /\\nDeposición /\\nDefecación\",\"definition\":\"An act of passing usually solid waste through the rectum and anus.\",\"industry\":\"Medical\",\"example_en\":\"Not drinking enough water throughout the day may be the reason you don't have daily bowel movements.\",\"example_es\":\"El no tomar suficiente agua durante el día puede ser la razón por la que no está teniendo deposiciones diarias.\",\"source\":\"Customer Service\"},{\"english\":\"Braces\",\"spanish\":\"Frenillos - aparatos dentales (dental) /  \\nSoporte (ortopédico)\",\"definition\":\"(Dental) Braces are devices used in orthodontics that align and straighten teeth.\\n(Orthopedics) A device fitted to something, in particular a weak or injured part of the body, to give support. Example: A neck brace.\",\"industry\":\"Medical\",\"example_en\":\"My child needs braces but I cannot afford them, they're expensive.\",\"example_es\":\"Mi niña necesita frenillos, pero no los puedo pagar, son caros.\",\"source\":\"Customer Service\"},{\"english\":\"Brake (verb)\",\"spanish\":\"Frenar\",\"definition\":\"Halt or stop, refers to an interruption to continue driving a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I couldn't see the red light, it was raining a lot, therefore I couldn't brake in time.\",\"example_es\":\"No pude ver la luz roja, estaba lloviendo mucho, por lo tanto, no pude frenar a tiempo.\",\"source\":\"Customer Service\"},{\"english\":\"Branch\",\"spanish\":\"Sucursal\",\"definition\":\"A division of a business or other organization.\",\"industry\":\"General\",\"example_en\":\"You could go to the Dillon branch, they have Spanish speaking representatives who would be more than happy to assist you.\",\"example_es\":\"Ud. podría ir a la sucursal de Dillon, ellos tienen representantes que hablan español, quienes estarán felices de ayudarlo.\",\"source\":\"Customer Service\"},{\"english\":\"Brand\",\"spanish\":\"Marca / \\nDe patente\",\"definition\":\"A trademark or distinctive name identifying a product, service, or organization.\",\"industry\":\"General\",\"example_en\":\"The store was out of my favorite brand of coffee, so I ended up buying the store brand.\",\"example_es\":\"La tienda no tenía la marca de mi café favorito, así que terniné comprando la marca de la tienda.\",\"source\":\"Customer Service\"},{\"english\":\"Brand name\\nmedication\",\"spanish\":\"Medicamentos de marca\",\"definition\":\"A drug that has a trade name and is protected by a patent (can be produced and sold only by the company holding the patent).\",\"industry\":\"Health Insurance\",\"example_en\":\"The brand name medication will cost more than the generic product. You can check with the pharmacist to see if your health insurance will cover that.\",\"example_es\":\"El medicamento de marca costará más que el producto genérico. Puede confirmar con el farmaceuta para ver si su seguro de salud lo cubrirá.\",\"source\":\"Customer Service\"},{\"english\":\"Breast pump\",\"spanish\":\"Extractor de leche\",\"definition\":\"A breast pump is a mechanical device that lactating women use to extract milk from their breasts. They may be manual devices powered by hand or foot movements or automatic devices powered by electricity.\",\"industry\":\"General\",\"example_en\":\"A breast pump is exactly what it sounds like; it suctions milk out of your breasts so you can give it to your baby.\",\"example_es\":\"Un extractor de leche es exactamente lo que parece; succiona la leche de sus pechos para que pueda dársela a su bebé.\",\"source\":\"Customer Service\"},{\"english\":\"Breast self-examination\",\"spanish\":\"Autoexamen de los senos /\\nAutoexamen de mamas\",\"definition\":\"A screening method used in an attempt to detect early breast cancer.\",\"industry\":\"Medical\",\"example_en\":\"Do you perform a monthly breast self-exam?\",\"example_es\":\"¿Usted realiza mensualmente un autoexamen de los senos?\",\"source\":\"Customer Service\"},{\"english\":\"Breast-feeding\\nclinic\",\"spanish\":\"Clínica de lactancia materna /\\nClínica de amamantamiento\",\"definition\":\"Facilities committed to the protection, promotion and support of breast feeding. Breastfeeding is the optimal way to feed neonates and infants.\",\"industry\":\"Medical\",\"example_en\":\"The breastfeeding clinic is an important resource for new mothers.\",\"example_es\":\"La clínica de lactancia materna es un recurso importante para las nuevas madres.\",\"source\":\"Customer Service\"},{\"english\":\"Breathing\",\"spanish\":\"Respiración /\\nRespirar\",\"definition\":\"The passage of air into and out of the lungs to supply the body with oxygen.\",\"industry\":\"Medical\",\"example_en\":\"Is the patient awake and breathing?\",\"example_es\":\"¿Está el paciente despierto y respirando?\",\"source\":\"Customer Service\"},{\"english\":\"Breathing tube\",\"spanish\":\"Tubo respiratorio\",\"definition\":\"A tube inserted (as through the nose or mouth) into the trachea to maintain an unobstructed passageway, especially to deliver oxygen or anesthesia to the lungs.\",\"industry\":\"Medical\",\"example_en\":\"If the swelling continues we will insert a breathing tube.\",\"example_es\":\"Si la hinchazón continúa vamos a insertar un tubo respiratorio/ de respiración.\",\"source\":\"Customer Service\"},{\"english\":\"Breed\",\"spanish\":\"Raza\",\"definition\":\"A breed is a specific group of domestic animals having homogeneous appearance (phenotype), homogeneous behavior, and/or other characteristics that distinguish it from other organisms of the same species.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"How many dogs are there? Do you know what breed they are?\",\"example_es\":\"¿Cuántos perros hay? ¿Sabe de qué raza son?\",\"source\":\"Customer Service\"},{\"english\":\"Brief\",\"spanish\":\"Breve /\\nCorto /\\nRápido /\\nConciso\",\"definition\":\"Short in time, duration, length, or extent. A short, succinct statement.\",\"industry\":\"General\",\"example_en\":\"Please keep your answers brief and to the point\",\"example_es\":\"Por favor mantenga sus respuestas breves y concretas.\",\"source\":\"Customer Service\"},{\"english\":\"Broadside collision\",\"spanish\":\"Choque de costado /\\nChoque lateral\",\"definition\":\"Refers to where the side of one vehicle is impacted by the front or rear of another vehicle, forming a \\\"T\\\".\",\"industry\":\"Auto Insurance\",\"example_en\":\"According to the police report, this was a broadside collision.\",\"example_es\":\"De acuerdo con el informe de la policía se trataba de un choque de costado.\",\"source\":\"Customer Service\"},{\"english\":\"Broken down\",\"spanish\":\"Descompuesto / \\nAveriado /\",\"definition\":\"Not functioning due to a mechanical failure; worn-out.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My vehicle broke down on the side of the road and I need a tow truck\",\"example_es\":\"Mi vehículo se ha descompuesto al lado de la carretera y necesito una grúa.\",\"source\":\"Customer Service\"},{\"english\":\"Bronchi\",\"spanish\":\"Bronquios\",\"definition\":\"Plural form of bronchus. Any of the major air passages of the lungs that diverge from the windpipe.\",\"industry\":\"Medical\",\"example_en\":\"Breathing is difficult when the bronchi become swollen.\",\"example_es\":\"La respiración se dificulta cuando los bronquios se inflaman.\",\"source\":\"Customer Service\"},{\"english\":\"Brother-in-law / \\nSister-in-law\",\"spanish\":\"Cuñado / \\nCuñada\",\"definition\":\"A brother-in-law is the spouse of one's sister, while a sister-in-law is the spouse of one's brother.\",\"industry\":\"General\",\"example_en\":\"Peter is Jane's brother-in-law.\",\"example_es\":\"Peter es el cuñado de Jane.\",\"source\":\"Customer Service\"},{\"english\":\"Browser\",\"spanish\":\"Explorador / \\nNavegador /\\nBuscador\",\"definition\":\"A computer program for searching, especially on a worldwide network.\",\"industry\":\"Customer Service\",\"example_en\":\"To take the test, you may use your favorite browser.\",\"example_es\":\"Para rendir su examen, Ud. puede usar su navegador favorito.\",\"source\":\"Customer Service\"},{\"english\":\"Budget\",\"spanish\":\"Presupuesto\",\"definition\":\"Estimation of revenue and expenses over a specified future period of time. Shows how much they will need or be able to spend.\",\"industry\":\"General\",\"example_en\":\"The school budget is going to be cut again this year.\",\"example_es\":\"El presupuesto escolar de este año será recortado / reducido otra vez\",\"source\":\"Customer Service\"},{\"english\":\"Budget billing\",\"spanish\":\"Facturación presupuestada /\\nFacturación estandarizada\",\"definition\":\"Utility bills fluctuate based on consumption; as a result, consumers may have high and low monthly utility bills. Budget billing refers to a program, offered by utility companies, in which the cost of utility bills during high demand months is spread out through the entire year. By spreading the cost of high demand months over a 12 month period, consumers do not need to stress over their utility bills.\",\"industry\":\"Customer Service\",\"example_en\":\"My bills during the winter and summer months are much higher than other months of the year, so I think I should take advantage of the budget billing your company offers.\",\"example_es\":\"Mis cobros durante los meses de invierno y verano son mucho más altos que otros meses del año, creo que debo de aprovechar la facturación presupuestada que ofrece su compañía.\",\"source\":\"Customer Service\"},{\"english\":\"Bulk account\",\"spanish\":\"Cuenta colectiva /\\nCuenta comunitaria\",\"definition\":\"Bulk Account means an agreement between the company or any of its wholly-owned subsidiaries and the owner of a multiple residential dwelling or other property for the provision of cable service at a discounted or bulk rate to such multiple residential dwelling or other property.\",\"industry\":\"Customer Service\",\"example_en\":\"When the agent comes on the line, tell them you are a resident on a bulk account and tell them your apartment address, and your apartment number.\",\"example_es\":\"Cuando el agente se ponga al teléfono, dígale que usted es residente en una cuenta colectiva y dígale la dirección de su apartamento y el número de su apartamento.\",\"source\":\"Customer Service\"},{\"english\":\"Bumper\",\"spanish\":\"Parachoques /\\nParagolpes /\\nDefensa\",\"definition\":\"A horizontal bar fixed across the front or back of a motor vehicle to lessen or reduce shock or damage in a collision.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Headlight are set flush with the front bumper.\",\"example_es\":\"Los faros del carro están nivelados con el parachoques delantero.\",\"source\":\"Customer Service\"},{\"english\":\"Bundled services\",\"spanish\":\"Servicios incluidos /\\nPaquete de servicios /\\nCombo de servicios\",\"definition\":\"Refers to offering several products for sale as one combined product.\",\"industry\":\"Customer Service\",\"example_en\":\"Many companies offer a bundled services package which may include internet, phone and TV.\",\"example_es\":\"Muchas compañías ofrecen paquetes de servicios combinados los cuales pueden incluir Internet, teléfono y servicio de televisión.\",\"source\":\"Customer Service\"},{\"english\":\"Burglary\",\"spanish\":\"Usurpación de morada /\\nAllanamiento de morada /\\nMeterse a robar un inmueble\",\"definition\":\"Also called breaking and entering. It is an illegal entry into a building for the purposes of committing an offence. Usually that offence will be theft.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"I will purchase a home alarm system as there was recently a burglary in the neighborhood.\",\"example_es\":\"Compraré un sistema de alarma para la casa ya que recientemente hubo un robo en el vecindario.\",\"source\":\"Customer Service\"},{\"english\":\"Burning sensation\",\"spanish\":\"Ardor /\\nEscozor\",\"definition\":\"Refers to any sensations anywhere that elicit a feeling of warmth or intense heat that may or may not be accompanied by pain. Blazing, red-hot, smoldering, sensation.\",\"industry\":\"Medical\",\"example_en\":\"A burning sensation with urination may be an\\nindication of a UTI.\",\"example_es\":\"Una sensación de escozor/ardor al orinar puede ser una indicación de una infección de las vías urinarias.\",\"source\":\"Customer Service\"},{\"english\":\"Business days\",\"spanish\":\"Días hábiles /\\nDías laborables /\\nDías útiles\",\"definition\":\"A business day is considered every official working day of the week. Another common term is working day. Typically, these are the days between and including Monday to Friday and do not include public holidays and weekends.\",\"industry\":\"General\",\"example_en\":\"Your order will arrive in three business days. Please keep in mind this does not include weekends or the Monday holiday.\",\"example_es\":\"Su orden llegará en tres días hábiles. Por favor tenga en mente que esto no incluye los fines de semana o el lunes que es día festivo.\",\"source\":\"Customer Service\"},{\"english\":\"Buttock\",\"spanish\":\"Nalga /\\nGlúteo\",\"definition\":\"Either of the two round fleshy parts that form the lower rear area of a human trunk.\",\"industry\":\"Medical\",\"example_en\":\"I will inject on your baby's buttocks.\",\"example_es\":\"Inyectaré a su bebé en la nalga.\",\"source\":\"Customer Service\"},{\"english\":\"Call in sick\",\"spanish\":\"Reportarse enfermo\",\"definition\":\"Calling in sick refers to contacting your supervisor to tell them you're not feeling well and won't be at work.\",\"industry\":\"General\",\"example_en\":\"If you're feeling unwell, you may want to call in sick.\",\"example_es\":\"Si se está sintiendo mal, es mejor que se reporte enfermo.\",\"source\":\"Customer Service\"},{\"english\":\"Callback number\",\"spanish\":\"Número para devolver la llamada / \\nNúmero de devolución de llamada\",\"definition\":\"A telephone number, or other unique number or code assigned to an instrument, used by a primary public safety answering point to contact the instrument from which an incoming emergency call originates.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"May I have a callback number just in case the call gets disconnected?\",\"example_es\":\"¿Me puede brindar un número para devolver la llamada en caso de que la llamada se desconecte?\",\"source\":\"Customer Service\"},{\"english\":\"Cane\",\"spanish\":\"Bastón\",\"definition\":\"Device used primarily to aid walking, provide postural stability or support, or assist in maintaining a good posture.\",\"industry\":\"General\",\"example_en\":\"She was leaning on a cane after her recent knee surgery.\",\"example_es\":\"Ella se estaba apoyando en un bastón tras su reciente cirugía de rodilla.\",\"source\":\"Customer Service\"},{\"english\":\"Carbon monoxide detector\",\"spanish\":\"Detector de monóxido de carbono\",\"definition\":\"A carbon monoxide detector or CO detector is a device that detects the presence of the carbon monoxide (CO) gas to prevent carbon monoxide poisoning.\",\"industry\":\"General\",\"example_en\":\"By law, you must do an annual gas safety check and fit smoke and carbon monoxide detectors.\",\"example_es\":\"Por ley, Usted necesita hacer una revisión anual de seguridad al gas, e instalar detectores de humo y monóxido de carbono.\",\"source\":\"Customer Service\"},{\"english\":\"Cardiac arrest\",\"spanish\":\"Paro cardíaco\",\"definition\":\"A sudden, sometimes temporary, cessation of function of the heart.\",\"industry\":\"Medical\",\"example_en\":\"He passed out and was taken to the hospital, he had a cardiac arrest.\",\"example_es\":\"Él se desmayó y fue llevado al hospital, él tuvo un paro cardíaco.\",\"source\":\"Customer Service\"},{\"english\":\"Case number\",\"spanish\":\"Número de caso\",\"definition\":\"A reference number that may consist of all numbers, numbers and letters, or even include other characters such as a dash.\",\"industry\":\"Social Services\",\"example_en\":\"May I please have your case number?\",\"example_es\":\"¿Me podría brindar su número de caso por favor?\",\"source\":\"Customer Service\"},{\"english\":\"Case worker\",\"spanish\":\"Trabajador(a) de caso\",\"definition\":\"A type of social worker who is employed by a government agency, non-profit organization, or other group to take on the cases of individuals and provide them with advocacy, information or other services.\",\"industry\":\"Social Services\",\"example_en\":\"My case worker adviced me to call this number.\",\"example_es\":\"Mi trabajadora de caso me aconsejó que llamara a este número.\",\"source\":\"Customer Service\"},{\"english\":\"Cashier's Check\",\"spanish\":\"Cheque de caja\",\"definition\":\"It is a check drawn from the bank’s own funds, not yours, and signed by a cashier or teller. Unlike a regular check, the bank, not the check writer, guarantees payment of a cashier’s check. A cashier's check can also be called an official check.\",\"industry\":\"Finance\",\"example_en\":\"A cashier’s check is a safe way to make large payments.\",\"example_es\":\"Un cheque de caja es una forma segura de hacer pagos grandes.\",\"source\":\"Customer Service\"},{\"english\":\"Cast\",\"spanish\":\"Yeso\",\"definition\":\"A cast holds a broken bone (fracture) in place and prevents the area around it from moving as it heals.\",\"industry\":\"Medical\",\"example_en\":\"A short leg cast with a fiberglass top layer was used to treat a fractured foot.\",\"example_es\":\"Se utilizó un yeso corto con una capa superior de fibra de vidrio para tratar una fractura de pie.\",\"source\":\"Customer Service\"},{\"english\":\"Cavity\",\"spanish\":\"Caries\",\"definition\":\"Tooth decay.\",\"industry\":\"Medical\",\"example_en\":\"Dental caries or cavities, more commonly known as tooth decay, are caused by a breakdown of the tooth enamel.\",\"example_es\":\"Las caries dentales o cavidades dentales más comúnmente conocidos como deterioro dental, son causadas por la ruptura del esmalte dental.\",\"source\":\"Customer Service\"},{\"english\":\"CD (Certificate of deposit)\",\"spanish\":\"Certificado de depósito\",\"definition\":\"A certificate of deposit (CD) is a savings product that earns interest on a lump-sum deposit that's untouched for a predetermined period of time.\",\"industry\":\"Finance\",\"example_en\":\"The certificate of deposit will earn $500 independent of the market's fluctuation.\",\"example_es\":\"El certificado de depósito ganará $500, independientemente de la fluctuación del mercado.\",\"source\":\"Customer Service\"},{\"english\":\"Ceiling joist\",\"spanish\":\"Vigueta del techo\",\"definition\":\"Ceiling Joists are the horizontal members that provide a structure to fix the ceiling, and support and fix the diagonal rafters that define the roof shape and are attached at the top to a ridge beam.\",\"industry\":\"Home Insurance\",\"example_en\":\"Ceiling joists play a vital role in the structural support system of homes.\",\"example_es\":\"Las viguetas del techo desempeñan un papel vital en el sistema de soporte estructural de las viviendas.\",\"source\":\"Customer Service\"},{\"english\":\"Center for Poison Control (CPC) /\\nPoison control center (PCC)\",\"spanish\":\"Centro toxicológico /\\nCentro de toxicología\",\"definition\":\"It is a specialized unit that advises on and assists in the prevention, diagnosis and management of poisoning.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The Poison Control Center (PCC) offers poison prevention education and a 24-hour hotline for poisoning incidents.\",\"example_es\":\"El centro de toxicología ofrece educación sobre la prevención de intoxicaciones y una línea directa durante las 24 horas del día para incidentes por intoxicación.\",\"source\":\"Customer Service\"},{\"english\":\"Cerebrovascular accident (CVA)\",\"spanish\":\"Accidente cerebrovascular (ACV)\",\"definition\":\"The sudden death of some brain cells due to lack of oxygen when the blood flow to the brain is impaired by blockage or rupture of an artery to the brain. A CVA is a higher-register term for stroke.\",\"industry\":\"Medical\",\"example_en\":\"Visual field defects often occur as a consequence of cerebrovascular accident, linked with paralysis of a limb.\",\"example_es\":\"Los defectos del campo visual ocurren como consecuencia de un accidente cerebrovascular, ligados a parálisis de una extremidad.\",\"source\":\"Customer Service\"},{\"english\":\"Certification\",\"spanish\":\"Certificación\",\"definition\":\"A certification is a credential that you earn to show that you have specific skills or knowledge. They are usually tied to an occupation, technology, or industry.\",\"industry\":\"School\",\"example_en\":\"Certifications are usually offered by a professional organization or a company that specializes in a particular field or technology.\",\"example_es\":\"Las certificaciones generalmente son ofrecidas por una organización profesional o una empresa que se especializa en un campo o tecnología en particular.\",\"source\":\"Customer Service\"},{\"english\":\"Chafing\",\"spanish\":\"Escoriación / \\nRozadura\",\"definition\":\"A skin irritation that occurs where skin rubs against skin, clothing, or other material.\",\"industry\":\"Medical\",\"example_en\":\"If you wear tight-fitting clothes, it could irritate your skin and cause chafing.\",\"example_es\":\"Si usa ropa ajustada, podría irritar la piel y causar escoriación.\",\"source\":\"Customer Service\"},{\"english\":\"Chaining\",\"spanish\":\"Encadenamiento\",\"definition\":\"Chaining is a teaching method wherein sub-skills are reinforced in a sequence to enable the learner to perform more complex behaviors.\",\"industry\":\"School\",\"example_en\":\"Chaining is used in a huge range of situations, both for children and adults.\",\"example_es\":\"El encadenamiento se utiliza en una amplia gama de situaciones, tanto para niños como para adultos.\",\"source\":\"Customer Service\"},{\"english\":\"Change lane (noun)\",\"spanish\":\"Carril de cambio /\\nCarril de cruce /\\nCarril para doblar /\\nCarril para cruzar\",\"definition\":\"Refers to an auxiliary lane designed to separate turning vehicles from through vehicles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"It's good there was a change lane, otherwise I would have crashed.\",\"example_es\":\"Es bueno que hubiera un carril de cambio, de otra manera hubiera chocado.\",\"source\":\"Customer Service\"},{\"english\":\"Chapped skin\",\"spanish\":\"Piel agrietada\",\"definition\":\"Cracked, roughened, or reddened especially by the action of wind or cold.\",\"industry\":\"Medical\",\"example_en\":\"The skin on her face is chapped due to the sub-freezing temperatures.\",\"example_es\":\"La piel de su cara está agrietada debido a las temperaturas bajo cero.\",\"source\":\"Customer Service\"},{\"english\":\"Charge\",\"spanish\":\"Cobro\",\"definition\":\"To impose or ask as a price or fee.\",\"industry\":\"General\",\"example_en\":\"If you close your account now, you will be charged an early termination fee.\",\"example_es\":\"Si cierra su cuenta ahora, se le cobrará un cargo por terminación anticipada.\",\"source\":\"Customer Service\"},{\"english\":\"Chart\",\"spanish\":\"Cartilla médica\",\"definition\":\"A sheet of information in the form of a table, graph or diagram.\",\"industry\":\"Medical\",\"example_en\":\"The doctor will release you tomorrow according to his notes on your chart.\",\"example_es\":\"El doctor le dará de alta mañana de acuerdo a las notas en su cartilla médica.\",\"source\":\"Customer Service\"},{\"english\":\"Check-in\",\"spanish\":\"Registro de entrada /\\nRegistro de ingreso\",\"definition\":\"To register or record one's arrival somewhere, as at a hotel or airport.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"We have to hurry, the check-in is at 10!\",\"example_es\":\"¡Tenemos que apurarnos, el registro de entrada es a las 10!\",\"source\":\"Customer Service\"},{\"english\":\"Check-out\",\"spanish\":\"Registro de salida\",\"definition\":\"Record one's departure from a hotel by paying the bill, or from a conference or other function.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"You have to check-out in person.\",\"example_es\":\"Usted tiene que registrar su salida en persona.\",\"source\":\"Customer Service\"},{\"english\":\"Check-point\",\"spanish\":\"Punto de inspección\",\"definition\":\"A point (place or location) at which a check is performed\",\"industry\":\"Auto Insurance\",\"example_en\":\"The police will have checkpoints throughout the city to help deter drunk driving.\",\"example_es\":\"La policía tendrá puestos de control en toda la ciudad para ayudar a prevenir la conducción en estado de ebriedad.\",\"source\":\"Customer Service\"},{\"english\":\"Checking account\",\"spanish\":\"Cuenta corriente /\\nCuenta de cheques\",\"definition\":\"A bank account from which you can take money by writing checks\",\"industry\":\"Finance\",\"example_en\":\"Your checking account is free with direct deposit.\",\"example_es\":\"Su cuenta de cheques es gratis con depósito directo.\",\"source\":\"Customer Service\"},{\"english\":\"Cheekbone\",\"spanish\":\"Pómulo\",\"definition\":\"One of a pair of bones on each upper side of the face that forms the cheek and part of the eye socket.\",\"industry\":\"Medical\",\"example_en\":\"The cheekbones help give shape and structure to the face.\",\"example_es\":\"Los pómulos ayudan a dar forma y estructura al rostro.\",\"source\":\"Customer Service\"},{\"english\":\"Chicken Pox\",\"spanish\":\"Varicela\",\"definition\":\"Chickenpox is an infection caused by the varicella zoster virus. Most cases are in children under age 15, but older children and adults can get it. It spreads very easily from one person to another.\",\"industry\":\"Medical\",\"example_en\":\"Chicken pox often affects children and causes a fever and red spots on the skin.\",\"example_es\":\"La varicela a menudo afecta a niños y causa fiebre y manchas rojas en la piel.\",\"source\":\"Customer Service\"},{\"english\":\"Child protective services (CPS)\",\"spanish\":\"Servicio de protección al menor\",\"definition\":\"Child protective services (CPS) is a governmental agency responsible for investigating reports of child maltreatment, determining whether child abuse or neglect has occurred, and intervening to ensure a safe environment for the child.\",\"industry\":\"Social Services\",\"example_en\":\"CPS helps prevent further harm to children from intentional physical or mental injury, sexual abuse, exploitation or neglected by a person responsible for a child's health or welfare.\",\"example_es\":\"Los servicios de protección al menor ayudan a evitar que los niños sufran más daños por lesiones físicas o mentales intencionadas, abusos sexuales, explotación o negligencia por parte de una persona responsable de la salud o el bienestar de un niño.\",\"source\":\"Customer Service\"},{\"english\":\"Child support\",\"spanish\":\"Manutención de menores /\\nManutención para las(os) hijas(os)\",\"definition\":\"Child support is money paid by one parent to the other parent for the purpose of providing financial support to a child or children. Most frequently, child support is paid by the non-custodial parent to the custodial parent.\",\"industry\":\"Social Services\",\"example_en\":\"I have a checking bank account in which I receive the child support payment.\",\"example_es\":\"Tengo una cuenta corriente en la que recibo el pago de manutención de menores.\",\"source\":\"Customer Service\"},{\"english\":\"Chills\",\"spanish\":\"Escalofríos\",\"definition\":\"A sensation of coldness, often accompanied by shivering and pallor of the skin.\",\"industry\":\"Medical\",\"example_en\":\"When I had Covid, I had fever, chills and body aches.\",\"example_es\":\"Cuando tuve Covid, me dio fiebre, escalofríos y dolores corporales.\",\"source\":\"Customer Service\"},{\"english\":\"Chin\",\"spanish\":\"Barbilla /\\nMentón\",\"definition\":\"The part of a person's face below their mouth.\",\"industry\":\"Medical\",\"example_en\":\"To keep the helmet in position, fasten the strap beneath the chin.\",\"example_es\":\"Para mantener el casco en su posición, abroche la correa por debajo de la barbilla.\",\"source\":\"Customer Service\"},{\"english\":\"CHIP (Children's Health Insurance Program)\",\"spanish\":\"Programa de seguro de salud para niños\",\"definition\":\"CHIP provides low-cost health coverage to children in families that earn too much money to qualify for Medicaid. In some states, CHIP covers pregnant women.\",\"industry\":\"Social Services\",\"example_en\":\"In order to be eligible for CHIP, a child must be under 19 years of age and uninsured.\",\"example_es\":\"Para poder ser elegible para el programa de seguro de salud para niños, el niño debe ser menor de 19 años y no estar asegurado.\",\"source\":\"Customer Service\"},{\"english\":\"Chiropractor\",\"spanish\":\"Quiropráctica(o)\",\"definition\":\"A health care professional trained to diagnose and treat neuromuscular disorders, through manual adjustment and/or manipulation of the spine, bones and joints.\",\"industry\":\"Medical\",\"example_en\":\"A chiropractor can sometimes help reduce your back pain by stretching your spine.\",\"example_es\":\"Un médico quiropráctico puede algunas veces, ayudarle a reducir el dolor de espalda al elongar su columna vertebral.\",\"source\":\"Customer Service\"},{\"english\":\"Chlamydia\",\"spanish\":\"Clamidia\",\"definition\":\"A bacterial infection caused by  Chlamydia trachomatis. The infection can spread through the genital tract from various types of sexual contact.\",\"industry\":\"Medical\",\"example_en\":\"Because it is a bacterial infection, chlamydia can be treated with medication.\",\"example_es\":\"Ya que es una infección bacteriana, la clamidia puede ser tratada con medicamentos.\",\"source\":\"Customer Service\"},{\"english\":\"Choke\",\"spanish\":\"Atorarse /\\nAtragantarse\",\"definition\":\"Refers to a person or animal with severe difficulty in breathing because of a constricted or obstructed throat or a lack of air.\",\"industry\":\"Medical\",\"example_en\":\"Mrs. Doubtfire's chocking is one of the funniest scenes in comedy.\",\"example_es\":\"Una de las escenas más graciosas en comedia, es de la Sra. Doubtfire atragantándose.\",\"source\":\"Customer Service\"},{\"english\":\"Chronic\",\"spanish\":\"Crónico\",\"definition\":\"The term chronic is often applied when the course of the disease lasts for more than three months.\",\"industry\":\"Medical\",\"example_en\":\"For resistant or chronic acne patients, we also offer laser treatment.\",\"example_es\":\"Para pacientes con acné persistente o crónico, también ofrecemos tratamiento con láser.\",\"source\":\"Customer Service\"},{\"english\":\"Citation\",\"spanish\":\"Citación\",\"definition\":\"An official request for someone to appear in a law court.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The court issued a contempt citation against city council members who refused to comply with a court order.\",\"example_es\":\"El tribunal emitió una citación por desacato contra los miembros del concejo municipal que se negaron a cumplir una orden judicial.\",\"source\":\"Customer Service\"},{\"english\":\"Claim\",\"spanish\":\"Reclamación /\\nReclamo\",\"definition\":\"A demand for payment in accordance with an insurance policy. A demand for something due or believed to be due.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My claim numbers are 764902 for roof damage and 764909 for flood damage after the hail storm last week\",\"example_es\":\"Mis números de reclamos /reclamaciones son 764902 por daños en el techo y 764909 por daños por inundación después de la tormenta de granizo la semana pasada.\",\"source\":\"Customer Service\"},{\"english\":\"Classic Learning Test (CLT)\",\"spanish\":\"Prueba de aprendizaje clásica\",\"definition\":\"Is a college readiness exam that draw on classical texts to test student aptitude. While not accepted by all colleges, the CLT partners with a growing number of colleges, especially private, liberal arts colleges.\",\"industry\":\"School\",\"example_en\":\"Currently, more than 200 colleges accept the CLT as a complete replacement for the SAT or ACT.\",\"example_es\":\"Actualmente, más de 200 colegios aceptan la prueba de aprendizaje clásica como un completo reemplazo para la prueba de evaluación escolástica SAT o el examen de Ingreso a las universidades de Estados Unidos ACT .\",\"source\":\"Customer Service\"},{\"english\":\"Classroom\",\"spanish\":\"Salón de clases /\\nAula\",\"definition\":\"It is a learning space in which both children and adults learn. Classrooms are found in educational institutions of all kinds, ranging from preschools to universities, and may also be found in other places where education or training is provided.\",\"industry\":\"School\",\"example_en\":\"There are forty people in the classroom.\",\"example_es\":\"Hay cuarenta personas en el salón de clases.\",\"source\":\"Customer Service\"},{\"english\":\"Clerk\",\"spanish\":\"Oficinista\",\"definition\":\"A person employed in an office or bank to keep records, accounts, and undertake other routine administrative duties.\",\"industry\":\"General\",\"example_en\":\"That clerk is labouring for a promotion.\",\"example_es\":\"El oficinista está trabajando para un ascenso.\",\"source\":\"Customer Service\"},{\"english\":\"Clinic\",\"spanish\":\"Clínica\",\"definition\":\"An establishment or hospital department where outpatients are given treatment.\",\"industry\":\"Medical\",\"example_en\":\"Please bring your child to the clinic so we can assess his symptoms and provide treatment if needed.\",\"example_es\":\"Por favor traiga a su hijo a la clínica para poder evaluar sus síntomas y proveer tratamiento si es necesario.\",\"source\":\"Customer Service\"},{\"english\":\"Closing fees /\\nClosing costs\",\"spanish\":\"Tarifas de cierre / \\nCostos de cierre\",\"definition\":\"Closing costs are processing fees you pay to your lender when you close on your loan.\",\"industry\":\"Finance\",\"example_en\":\"Closing costs usually equal about 1 to 4% of your home's value.\",\"example_es\":\"Los costos de cierre generalmente equivalen a cerca del 1 y el 4% del valor de su vivienda.\",\"source\":\"Customer Service\"},{\"english\":\"Clutch\",\"spanish\":\"Embrague\",\"definition\":\"Refers to a mechanism for connecting and disconnecting an engine and the transmission system in a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You only need to activate the gas pedal and the clutch pedal to start the engine.\",\"example_es\":\"Sólo necesita pisar el acelerador y el pedal de embrague para que el motor arranque.\",\"source\":\"Customer Service\"},{\"english\":\"Co-insurance\",\"spanish\":\"Coaseguro / \\nCo seguro / \\nSeguro compartido\",\"definition\":\"Coinsurance is the percentage of costs a patient pays for medical expenses - such as a hospital stay, office visit, medical device, or prescription drug. Coinsurance is a form of cost-sharing, or splitting the cost of a service or medication between the insurance company and consumer.\",\"industry\":\"Health Insurance\",\"example_en\":\"According to your policy, you have a 20% co-insurance, and the insurance company covers 80%.\",\"example_es\":\"Según su póliza, usted tiene un coseguro del 20%, y la compañía de seguros cubre el 80%.\",\"source\":\"Customer Service\"},{\"english\":\"Co-pay /\\nCo-payment\",\"spanish\":\"Copago /\\nPago compartido /\\nPorción de pago\",\"definition\":\"A common feature of many health plans, where the insured pays a set out-of-pocket amount for health care services. Providers often charge co-pays for services such as doctor visits or prescriptions drugs.\",\"industry\":\"Health Insurance\",\"example_en\":\"Your copay for the specialist is $45.\",\"example_es\":\"Su porción de pago /copago por el especialista es de $45.\",\"source\":\"Customer Service\"},{\"english\":\"Co-signer\",\"spanish\":\"Aval /\\nFiador(a)\",\"definition\":\"A person who signs an official document (such as a loan) with another person.\",\"industry\":\"Finance\",\"example_en\":\"Because of your credit history, we will require a cosigner.\",\"example_es\":\"Debido a su historial de crédito se requerirá un aval/fiador.\",\"source\":\"Customer Service\"},{\"english\":\"Code\",\"spanish\":\"Código /\\nClave\",\"definition\":\"A set words, letters, figures, or other symbols identification or to protect private information.\",\"industry\":\"General\",\"example_en\":\"To access the system you need to type in the code.\",\"example_es\":\"Para acceder al sistema usted tiene que ingresar el código.\",\"source\":\"Customer Service\"},{\"english\":\"Cold sore\",\"spanish\":\"Úlcera bucal /\\nHerpes labial\",\"definition\":\"Cold sores are small blister-like spots that appear in or around the outside of the mouth and are caused by infection with the herpes simplex virus.\",\"industry\":\"Medical\",\"example_en\":\"Cold sores usually clear up after 2 weeks without leaving any scars.\",\"example_es\":\"Las úlceras bucales generalmente desaparecen después de 2 semanas sin dejar ninguna cicatriz.\",\"source\":\"Customer Service\"},{\"english\":\"Collateral (Noun)\",\"spanish\":\"Garantía /\\nGarantía subsidiaria\",\"definition\":\"Something pledged as security for repayment of a loan, to be forfeited in the event of a default.\",\"industry\":\"Finance\",\"example_en\":\"She put her house up as collateral for the bank loan.\",\"example_es\":\"Ella puso su casa como garantía para el préstamo bancario.\",\"source\":\"Customer Service\"},{\"english\":\"Collections (Collections department)\",\"spanish\":\"Departamento de cobranzas /\\nDepartamento de cobros\\n(NO COLECCIONES)\",\"definition\":\"A special department set up for the purpose of collecting/recovering payments on delinquent or past-due accounts. Not to be confused with a collections agency.\",\"industry\":\"Finance\",\"example_en\":\"Since we have not received payments for the months of April, May, June and July, your account will be sent to the Collections Department and the card will be cancelled.\",\"example_es\":\"Ya que no hemos recibido pagos por los meses de abril, mayo, junio y julio, su cuenta será enviada al departamento de cobranzas y la tarjeta será cancelada.\",\"source\":\"Customer Service\"},{\"english\":\"Collision\",\"spanish\":\"Colisión /\\nChoque\",\"definition\":\"A crash, an accident resulting from violent impact of a moving object. A forceful impact between two objects.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Luckily there were no injuries after the multiple  collision.\",\"example_es\":\"Afortunadamente no hubo lesiones después del choque múltiple.\",\"source\":\"Customer Service\"},{\"english\":\"Collision coverage\",\"spanish\":\"Cobertura contra choques\",\"definition\":\"Coverage that pays for the repair or replacement of a vehicle in case of accident; forms part of what is considered \\\"full coverage\\\" for automobile policies.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The collision coverage will pay for the damages to your car if you are at fault for the accident.\",\"example_es\":\"La cobertura contra choques pagará por los daños a su carro si usted es culpable del accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Come to rest (a car after an accident)\",\"spanish\":\"Pararse /\\nDetenerse\",\"definition\":\"Refers to the state of being motionless or settled.\",\"industry\":\"Auto Insurance\",\"example_en\":\"After the impact where did your vehicle come to rest?\",\"example_es\":\"Después del impacto ¿dónde paro su vehículo?\",\"source\":\"Customer Service\"},{\"english\":\"Common Core\",\"spanish\":\"Estándares comunes\",\"definition\":\"The Common Core is a set of national learning goals, launched in 2009, with math and English language learning goals laid out for each grade (from kindergarten through 12th grade).\",\"industry\":\"School\",\"example_en\":\"This Common Core asks students to use semicolons to link related sentences, with and without the help of conjunctive adverbs like “however,” “therefore,” or “subsequently.”\",\"example_es\":\"Este estándar común pide a los estudiantes que utilicen punto y coma para vincular oraciones relacionadas, con y sin la ayuda de adverbios conjuntivos, como \\\"sin embargo\\\", \\\"por lo tanto\\\" o \\\"posteriormente\\\".\",\"source\":\"Customer Service\"},{\"english\":\"Communicable disease\",\"spanish\":\"Enfermedad contagiosa /\\nEnfermedad contagiable /\\nEnfermedad transferible\",\"definition\":\"An infectious disease transmissible from person to person by direct contact with an affected individual or the individual's discharges or by indirect means.\",\"industry\":\"Medical\",\"example_en\":\"Most venereal diseases are communicable diseases.\",\"example_es\":\"La mayoría de las enfermedades venéreas\\nson enfermedades contagiosas.\",\"source\":\"Customer Service\"},{\"english\":\"Compact\",\"spanish\":\"Compacta(o)\",\"definition\":\"Something small, or densely packed.\",\"industry\":\"General\",\"example_en\":\"What type of car would you prefer: a luxury car or a compact car?\",\"example_es\":\"¿Qué tipo de carro preferiría: carro de lujo o compacto?\",\"source\":\"Customer Service\"},{\"english\":\"Comply (with)\",\"spanish\":\"Cumplir\",\"definition\":\"To act or be in accordance with wishes, requests, demands, requirements, conditions, etc.\",\"industry\":\"General\",\"example_en\":\"You have not complied with the terms of your payment arrangement.\",\"example_es\":\"No ha cumplido con los términos de su arreglo de pago.\",\"source\":\"Customer Service\"},{\"english\":\"Comprehension skills\",\"spanish\":\"Habilidades de comprensión\",\"definition\":\"Comprehension skills are the strategies a reader uses to construct meaning and retrieve information from a text.\",\"industry\":\"School\",\"example_en\":\"Comprehension skills are very much like thinking skills.\",\"example_es\":\"Las habilidades de comprensión son muy parecidas a las habilidades de pensamiento.\",\"source\":\"Customer Service\"},{\"english\":\"Comprehensive\\nCoverage\",\"spanish\":\"Cobertura contra todo riesgo / Cobertura integral\\n\\n(NO COMPRENSIBLE)\",\"definition\":\"Automobile coverage that pays for damages not directly related to an auto crash, that covers a wide array of events that can damage your car, including theft, vandalism, fires and natural disasters.\",\"industry\":\"Auto Insurance\",\"example_en\":\"As your vehicle was stolen, you must make a claim. It will be paid under the comprehensive coverage of your policy.\",\"example_es\":\"Ya que su vehículo fue robado, debe hacer un reclamo. Será pagado bajo la cobertura contra todo riesgo de su póliza.\",\"source\":\"Customer Service\"},{\"english\":\"Conflicting statements\",\"spanish\":\"Declaraciones contradictorias\",\"definition\":\"To be out of harmony or agreement, usually noticeably.\",\"industry\":\"General\",\"example_en\":\"There were conflicting statements from witnesses.\",\"example_es\":\"Hubo declaraciones contradictorias de parte de los testigos.\",\"source\":\"Customer Service\"},{\"english\":\"Congested\",\"spanish\":\"Congestionada(o)\",\"definition\":\"An abnormal or excessive accumulation of a body fluid. The term is used broadly in medicine, for example 'nasal congestion' referring to excess mucus and secretions in the air passages of the nose.\",\"industry\":\"Medical\",\"example_en\":\"I can't breathe, my nose is so congested.\",\"example_es\":\"No puedo respirar, mi nariz está muy congestionada.\",\"source\":\"Customer Service\"},{\"english\":\"Conjugal visit\",\"spanish\":\"Visita conyugal\",\"definition\":\"A conjugal visit is a scheduled period in which an inmate of a prison or jail is permitted to spend several hours or days in private with a visitor.\",\"industry\":\"Jail system\",\"example_en\":\"The inmate is allowed conjugal visits from his wife.\",\"example_es\":\"Al recluso se le permiten visitas conyugales de su esposa.\",\"source\":\"Customer Service\"},{\"english\":\"Constipation\",\"spanish\":\"Estreñimiento \\n\\n(NO constipado)\",\"definition\":\"The condition of being unable to easily release solid waste from your body; the condition of being unable to have a bowel movement easily.\",\"industry\":\"Medical\",\"example_en\":\"To avoid constipation you should eat plenty vegetables and fruit.\",\"example_es\":\"Para evitar el estreñimiento usted debería comer abundantes vegetales y frutas.\",\"source\":\"Customer Service\"},{\"english\":\"Contact lenses\",\"spanish\":\"Lentes de contacto\",\"definition\":\"Contact lenses, or simply contacts, are thin lenses placed directly on the surface of the eyes.\",\"industry\":\"Medical\",\"example_en\":\"In many cases, contact lenses can solve the problem.\",\"example_es\":\"En muchos casos, las lentes de contacto pueden solucionar el problema.\",\"source\":\"Customer Service\"},{\"english\":\"Contagious\",\"spanish\":\"Contagiosa(o)\",\"definition\":\"(of a disease) Spread from one person or organism to another by direct or indirect contact.\",\"industry\":\"Medical\",\"example_en\":\"Parents of students who suffer contagious diseases should notify school authorities.\",\"example_es\":\"Los padres de estudiantes que padecen enfermedades contagiosas deben avisar a las autoridades escolares.\",\"source\":\"Customer Service\"},{\"english\":\"Contagious\",\"spanish\":\"Contagioso\",\"definition\":\"(Of a disease) spread from one person or organism to another by direct or indirect contact.\",\"industry\":\"Medical\",\"example_en\":\"She was advised to stay away from people as she was still contagious.\",\"example_es\":\"Le aconsejaron que se mantuviera alejada de las personas, ya que seguía siendo contagiosa.\",\"source\":\"Customer Service\"},{\"english\":\"Context clues\",\"spanish\":\"Claves de contexto\",\"definition\":\"Context clues are aspects of the environment that facilitate accessing and retrieving information in memory.\",\"industry\":\"School\",\"example_en\":\"Using context clues is vital for reading comprehension as a way to learn new words independently, without the assistance of other people or dictionaries.\",\"example_es\":\"Usar pistas de contexto es vital para la comprensión lectora, como una forma de aprender nuevas palabras independientemente, sin la ayuda de otras personas o diccionarios.\",\"source\":\"Customer Service\"},{\"english\":\"Convicted\",\"spanish\":\"Condenado /\\nSentenciado\",\"definition\":\"Having officially been found guilty of a crime in a court of law.\",\"industry\":\"Jail system\",\"example_en\":\"The two suspects were convicted on terrorism charges.\",\"example_es\":\"Los dos sospechosos fueron condenados por cargos de terrorismo\",\"source\":\"Customer Service\"},{\"english\":\"Corner\",\"spanish\":\"Esquina\",\"definition\":\"The space between two converging lines or surfaces near their intersection; an angle, either external or internal.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The accident happened at the corner of Berry and 14th Ave.\",\"example_es\":\"El accidente pasó en la esquina de las avenidas Berry y 14.\",\"source\":\"Customer Service\"},{\"english\":\"Cough\",\"spanish\":\"Tos\",\"definition\":\"To expel air from the lungs suddenly and noisily, often to keep the respiratory passages free of irritating material. To force air through your throat with a short, loud noise often because you are sick.\",\"industry\":\"Medical\",\"example_en\":\"You can buy an over-the-counter cough syrup for your child.\",\"example_es\":\"Usted puede comprar jarabe para la tos de venta libre para su hijo.\",\"source\":\"Customer Service\"},{\"english\":\"Cough up\",\"spanish\":\"Expectorar /\\nToser\",\"definition\":\"To force liquids or fluids out of the lungs by strongly expelling air.\",\"industry\":\"Medical\",\"example_en\":\"To help you cough up the phlemg, try walking as much as you can.\",\"example_es\":\"Para ayudar a expectorar la flema, trate de caminar lo más que pueda.\",\"source\":\"Customer Service\"},{\"english\":\"Coverage\",\"spanish\":\"Cobertura\",\"definition\":\"The extent of protection afforded by an insurance policy.\",\"industry\":\"Insurance (general)\",\"example_en\":\"He said that what is covered is one item per each type of equipment I need.\",\"example_es\":\"Me dijo que lo que está cubierto es un artículo por cada tipo de equipo que necesito.\",\"source\":\"Customer Service\"},{\"english\":\"CPR (Cardiopulmonary\\nresuscitation)\",\"spanish\":\"Resucitación cardiopulmonar\\n(RCP) / \\nReanimación cardiopulmonar\",\"definition\":\"CPR is an emergency procedure for a person whose heart has stopped or is no longer breathing. CPR can maintain circulation and breathing until emergency help arrives.\",\"industry\":\"Medical\",\"example_en\":\"You can attend free CPR classes that the Red Cross offers so that you are prepared to help those in an emergency situation.\",\"example_es\":\"Puede asistir a clases gratuitas de resucitación cardiopulmonar que ofrece la Cruz Roja para que esté preparado para ayudar a aquellos en una situación de emergencia.\",\"source\":\"Customer Service\"},{\"english\":\"Cracked\",\"spanish\":\"Agrietado(a)\",\"definition\":\"Damaged and showing lines on the surface from having split without coming apart.\",\"industry\":\"General\",\"example_en\":\"Last night's hail cracked my windshield.\",\"example_es\":\"El granizo de anoche agrietó mi parabrisas.\",\"source\":\"Customer Service\"},{\"english\":\"Cramps\",\"spanish\":\"Cólicos (menstrual) /\\nCalambres (muscular) /\\nRetorcijones (abdominal)\",\"definition\":\"A painful, involuntary contraction of a muscle or muscles, typically caused by fatigue or strain.\",\"industry\":\"Medical\",\"example_en\":\"If you don't stretch before and after working out you may get cramps.\",\"example_es\":\"Si usted no se estira antes y después de ejercitarse, le podrían dar calambres.\",\"source\":\"Customer Service\"},{\"english\":\"Crash (verb)\",\"spanish\":\"Estrellarse / \\nColisionar\",\"definition\":\"To collide violently with an obstacle or another vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My friend crashed his car while driving home drunk after the party.\",\"example_es\":\"Mi amigo estrelló su carro mientras conducía ebrio a casa después de la fiesta.\",\"source\":\"Customer Service\"},{\"english\":\"Credit (verb)\",\"spanish\":\"Acreditar\",\"definition\":\"To add an amount of money to an account. Can also be to return an amount back to an account.\",\"industry\":\"Customer Service\",\"example_en\":\"Since the item was properly returned we will credit your account for the full original price.\",\"example_es\":\"Dado que el artículo se devolvió correctamente, acreditaremos en su cuenta el precio original completo.\",\"source\":\"Customer Service\"},{\"english\":\"Credit bureau\",\"spanish\":\"Oficina de crédito /\\nAgencia de crédito\",\"definition\":\"A credit bureau is a company that collects financial information about consumers, for example, debt and employment record, and sells the information to financial organizations who lend money.\",\"industry\":\"Finance\",\"example_en\":\"A credit provider must advise a debtor before reporting unfavorable information to a credit bureau.\",\"example_es\":\"Un proveedor de crédito debe informar al deudor antes de reportar información desfavorable a una agencia de crédito.\",\"source\":\"Customer Service\"},{\"english\":\"Credit card\",\"spanish\":\"Tarjeta de crédito\",\"definition\":\"A card entitling the owner to use funds from the issuing company up to a certain limit.\",\"industry\":\"Finance\",\"example_en\":\"I am calling because I lost my credit card and I would like to cancel it.\",\"example_es\":\"Estoy llamando porque perdí mi tarjeta de crédito y me gustaría cancelarla.\",\"source\":\"Customer Service\"},{\"english\":\"Credit Check\",\"spanish\":\"Verificación de crédito /\\nVerificación crediticia\",\"definition\":\"An examination of someone's credit history (record of paying debt) by a financial organization that is considering lending them money.\",\"industry\":\"Finance\",\"example_en\":\"Doing a credit check is a routine part of the loan process.\",\"example_es\":\"Hacer una verificación de crédito es una parte rutinaria del proceso de préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Credit limit\",\"spanish\":\"Límite de crédito\",\"definition\":\"The maximum amount of credit that a financial institution or other lender will extend to a debtor for a loan, credit card or line of credit.\",\"industry\":\"Finance\",\"example_en\":\"I called the bank and they told me I had reached my credit limit, that is the reason my card was declined.\",\"example_es\":\"Llamé al banco y me dijeron que había llegado a mi límite de crédito, esa es la razón por la que mi tarjeta fue rechazada\",\"source\":\"Customer Service\"},{\"english\":\"Credit report\",\"spanish\":\"Informe de crédito /\\nReporte de crédito\",\"definition\":\"A summary of your financial and debt management history.\",\"industry\":\"Finance\",\"example_en\":\"I will have to pull a credit report to see if you qualify for the loan.\",\"example_es\":\"Tendré que obtener un informe de crédito para saber si cumple los requisitos para el préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Credit score\",\"spanish\":\"Puntaje de crédito /\\nCalificación de crédito\",\"definition\":\"A number between 300-850 that depicts a consumer's creditworthiness. The higher the score, the better a borrower looks to potential lenders.\",\"industry\":\"Finance\",\"example_en\":\"When I applied for the loan, they told me my credit score is very good.\",\"example_es\":\"Cuando solicité el préstamo, me dijeron que mi puntaje de crédito es muy bueno.\",\"source\":\"Customer Service\"},{\"english\":\"Crime\",\"spanish\":\"Crimen /\\nDelito\",\"definition\":\"An action or omission that constitutes an offense that may be prosecuted by the state and is punishable by law.\",\"industry\":\"Jail system\",\"example_en\":\"You're not accused of any crime so I'm not harboring any fugitives.\",\"example_es\":\"No está acusado de ningún delito, así que no estoy escondiendo ningún fugitivo.\",\"source\":\"Customer Service\"},{\"english\":\"Crosswalk /\\nPedestrian crossing\",\"spanish\":\"Paso peatonal /\\nCruce de cebra\",\"definition\":\"A marked part of a road where pedestrians have right of way to cross.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I felt three impacts; and the third impact pushed me into the crosswalk.\",\"example_es\":\"Sentí tres impactos; y el tercer impacto me empujó hacia el cruce de cebra.\",\"source\":\"Customer Service\"},{\"english\":\"Cruise control\",\"spanish\":\"Piloto automático\",\"definition\":\"An electronic device in a motor vehicle that can be switched on to maintain a selected constant speed without the use of the accelerator.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Cruise control is a nice feature when you drive long distances.\",\"example_es\":\"El piloto automático es una buena característica cuando se conduce por largas distancias.\",\"source\":\"Customer Service\"},{\"english\":\"Crutches\",\"spanish\":\"Muletas\",\"definition\":\"A long stick with a crosspiece at the top, used as a support under the armpit by a person with an injury or disability.\",\"industry\":\"General\",\"example_en\":\"She had back and hip problems and was in severe pain, needing crutches to walk.\",\"example_es\":\"Ella tenía problemas de la espalda y caderas y tenía fuertes dolores, necesitando muletas para caminar.\",\"source\":\"Customer Service\"},{\"english\":\"CT (Computerized\\nTomography) scan\",\"spanish\":\"Tomografía computarizada\",\"definition\":\"A type of imaging that uses special x-ray equipment to make cross-sectional pictures of your body.\",\"industry\":\"Medical\",\"example_en\":\"The CT scan detected calcium deposits in your arteries.\",\"example_es\":\"La tomografía computarizada detectó depósitos de calcio en sus arterias.\",\"source\":\"Customer Service\"},{\"english\":\"Current\",\"spanish\":\"Actual /\\nAl Día /\\nAl Corriente\",\"definition\":\"Up to date, current, most recent.\",\"industry\":\"General\",\"example_en\":\"Could you please give me your current address, please?\",\"example_es\":\"¿Podría darme su dirección actual por favor?\",\"source\":\"Customer Service\"},{\"english\":\"Cut-off time\",\"spanish\":\"Hora de cierre /\\nHora Límite\",\"definition\":\"The latest time in any business day that a particular transaction, request or instruction can be processed.\",\"industry\":\"Finance\",\"example_en\":\"Our cut-off time is 5 p.m.\",\"example_es\":\"Nuestra hora de cierre es las 5 p.m.\",\"source\":\"Customer Service\"},{\"english\":\"CVV (Card Verification Value) /\\nCVC (Card verification code) / \\nCSC (Card Security Code)\",\"spanish\":\"Valor de verificación de tarjeta / Código de verificación de la tarjeta / \\nCódigo de seguridad de la tarjeta\",\"definition\":\"A three or four-digit security number that usually appears on the back or front of your credit or debit card.\",\"industry\":\"Finance\",\"example_en\":\"Just enter your 16-digit card number, expiration date, and CVV code.\",\"example_es\":\"Solo introduzca el número de 16 dígitos de su tarjeta, la fecha de vencimiento y el código de verificación de la tarjeta.\",\"source\":\"Customer Service\"},{\"english\":\"Daily basis\",\"spanish\":\"De forma diaria /\\nCon frecuencia diaria\",\"definition\":\"Daily basis refers to the regular or daily occurrence of an event or action, something that happens every day or is done every day.\",\"industry\":\"General\",\"example_en\":\"You have to take the medication on a daily basis.\",\"example_es\":\"Tiene que tomar el medicamento de forma diaria.\",\"source\":\"Customer Service\"},{\"english\":\"Damages\",\"spanish\":\"Daños /\\nPérdidas\",\"definition\":\"Destruction or a loss in value, usefulness, or ability resulting from an action or event. physical harm that is done to something or to someone's body.\",\"industry\":\"Insurance (general)\",\"example_en\":\"The results of the vehicle inspection show that there were previous damages, therefore we will only cover damages caused by this accident.\",\"example_es\":\"Los resultados de la inspección del vehículo muestran que habían daños previos, así que solo cubriremos daños causados por éste accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Deadline\",\"spanish\":\"Fecha límite\",\"definition\":\"The latest time or date by which something should be completed. The due date of a bill or task to be completed.\",\"industry\":\"General\",\"example_en\":\"Your food stamp application must be completed and received by the deadline indicated in the letter you received.\",\"example_es\":\"La solicitud de cupones de alimentos debe ser completada y recibida antes de la fecha limite indicada en la carta que usted recibió.\",\"source\":\"Customer Service\"},{\"english\":\"Dealer\",\"spanish\":\"Concesionario\",\"definition\":\"To sell or distribute something as a business.\",\"industry\":\"Customer Service\",\"example_en\":\"A car dealer can help you secure financing for the vehicle you wish to purchase.\",\"example_es\":\"Un concesionario de autos puede ayudar con la financiación del auto que desea comprar.\",\"source\":\"Customer Service\"},{\"english\":\"Dean\",\"spanish\":\"Decano\",\"definition\":\"Dean is a title employed in academic administrations such as colleges or universities for a person with significant authority over a specific academic unit, over a specific area of concern, or both.\",\"industry\":\"School\",\"example_en\":\"A dean is usually the head of a significant collection of departments within a university.\",\"example_es\":\"Un decano suele ser el jefe de un conjunto importante de departamentos dentro de una universidad.\",\"source\":\"Customer Service\"},{\"english\":\"Death certificate\",\"spanish\":\"Certificado de defunción\",\"definition\":\"A death certificate is an official document issued by the government, which declares cause of death, location of death, time of death and some other personal information about the deceased.\",\"industry\":\"General\",\"example_en\":\"We began our search by consulting Mike's father's death certificate.\",\"example_es\":\"Empezamos nuestra búsqueda consultando el certificado de defunción del padre de Mike.\",\"source\":\"Customer Service\"},{\"english\":\"Debris\",\"spanish\":\"Escombros\",\"definition\":\"The scattered remains of something broken or destroyed; rubble or wreckage.\",\"industry\":\"Insurance (general)\",\"example_en\":\"When I came back, the car was not there. There were only debris where I parked it last night. It seems that they even broke the window to get in.\",\"example_es\":\"Cuando regresé el carro ya no estaba ahí. Solo había escombros dónde lo estacioné anoche. Parece ser que inclusive rompieron la ventana para meterse.\",\"source\":\"Customer Service\"},{\"english\":\"Debts\",\"spanish\":\"Deudas\",\"definition\":\"Something, typically money, that is owed or due.\",\"industry\":\"Finance\",\"example_en\":\"I have two jobs to pay my debts.\",\"example_es\":\"Tengo dos trabajos para pagar mis deudas.\",\"source\":\"Customer Service\"},{\"english\":\"Deductible\",\"spanish\":\"Deducible\",\"definition\":\"The amount for which the insured is liable on each claim made on an insurance policy.\",\"industry\":\"Insurance (general)\",\"example_en\":\"You will have to pay a $500 deductible for the repairs to your vehicle.\",\"example_es\":\"Usted tendrá que pagar un deducible de $500 por las reparaciones de su vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Deeds of trust\",\"spanish\":\"Escrituras de fideicomiso\",\"definition\":\"A deed of trust is an agreement between a home buyer and a lender at the closing of a property. The agreement states that the home buyer will repay the home loan and the mortgage lender will hold the property’s legal title until the loan is paid in full.\",\"industry\":\"Finance\",\"example_en\":\"The loan was secured by a deed of trust on the entire properties of the railway company.\",\"example_es\":\"El préstamo estaba garantizado por una escritura de fideicomiso sobre la totalidad de las propiedades de la compañía ferroviaria\",\"source\":\"Customer Service\"},{\"english\":\"Default\",\"spanish\":\"Incumplimiento\",\"definition\":\"Default signifies that the account terms were not met and the lender has determined the debt will not be paid.\",\"industry\":\"Finance\",\"example_en\":\"If you default on you loan, your car will be repossessed.\",\"example_es\":\"Si tiene morosidad en su préstamo, el carro será embargado.\",\"source\":\"Customer Service\"},{\"english\":\"Defroster\",\"spanish\":\"Desempañador\",\"definition\":\"A system to clear condensation and thaw frost from the windshield, backglass, and/or side windows of a motor vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I noticed the defroster is still not working even though the vehicle has already been repaired.\",\"example_es\":\"Observé/noté que el desempañador aún no está funcionando a pesar de que el vehículo ya ha sido reparado.\",\"source\":\"Customer Service\"},{\"english\":\"Delinquency\",\"spanish\":\"Morosidad / \\nFalta de pago\",\"definition\":\"Delinquency means the account payment was not made on or before the payment due date.\",\"industry\":\"Finance\",\"example_en\":\"If a grace period exists then you are delinquent after the grace period expires and no, payment has been received by the mortgage company.\",\"example_es\":\"Si un periodo de gracia existe entonces a usted se le considera moroso después de que el periodo de gracia expira y no, la compañía de hipoteca no ha recibido el pago.\",\"source\":\"Customer Service\"},{\"english\":\"Delivery\",\"spanish\":\"Parto /\\nAlumbramiento /\\nDar a luz /\\nParir\",\"definition\":\"The act of giving birth; parturition.\",\"industry\":\"Medical\",\"example_en\":\"Did you plan on a natural delivery or birth? Do you plan to have the baby at home or at a hospital?\",\"example_es\":\"¿Planea un parto natural? ¿Planea tener al bebé en casa o en el hospital?\",\"source\":\"Customer Service\"},{\"english\":\"Dent /\",\"spanish\":\"Abolladura /\\nHendidura /\",\"definition\":\"A slight hollow in a hard, even surface made by a blow or by the exertion of pressure. Having the central part lower than the margin.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My vehicle is dented all over because of the hail storm.\",\"example_es\":\"Mi vehículo está todo abollado a causa de la tormenta de granizo.\",\"source\":\"Customer Service\"},{\"english\":\"Department of Health and Human Services  (HHS)\",\"spanish\":\"Departamento de servicios humanos y salud\",\"definition\":\"The Department of Health and Human Services (HHS) is a Cabinet-level government department that provides health and human services, and promotes research in social services, medicine, and public health.\",\"industry\":\"Social Services\",\"example_en\":\"The Department of Health and Human Services (HHS) protects the health of all americans and provides essential human services.\",\"example_es\":\"El departamento de servicios humanos y salud protege la salud de todos los americanos y provee servicios humanos esenciales.\",\"source\":\"Customer Service\"},{\"english\":\"Department of veteran affairs (VA)\",\"spanish\":\"Departamento de asuntos de los veteranos.\",\"definition\":\"The United States Department of Veterans Affairs (VA) is an agency of the federal government that provides benefits, health care, and cemetery services to military veterans.\",\"industry\":\"Social Services\",\"example_en\":\"The Department of Veteran Affairs (VA) supports those who serve or have served in defense of our nation, and their families.\",\"example_es\":\"El Departamento de asuntos de los veteranos apoya a quienes sirven o han servido en defensa de nuestra nación y a sus familias.\",\"source\":\"Customer Service\"},{\"english\":\"Departure\",\"spanish\":\"Salida\",\"definition\":\"The act of leaving somewhere.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"The arrival and departure dates and times are indicated on the plane reservation email.\",\"example_es\":\"Las horas y fechas de llegada y salida están indicadas en el correo electrónico de reservación del avión.\",\"source\":\"Customer Service\"},{\"english\":\"Deploy\",\"spanish\":\"Desplegar\",\"definition\":\"When a safety device in a car, consisting of a bag inflates automatically in an accident and prevents the passengers from being thrown forward.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did the airbags deploy when the accident happened?\",\"example_es\":\"¿Se desplegaron las bolsas de aire cuando ocurrió el accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Deposit\",\"spanish\":\"Depositar\",\"definition\":\"To put (money) in a bank account.\",\"industry\":\"Finance\",\"example_en\":\"We see a deposit of $200.\",\"example_es\":\"Vemos un depósito de $200.\",\"source\":\"Customer Service\"},{\"english\":\"Depreciation\",\"spanish\":\"Depreciación /\\nAmortización\",\"definition\":\"Depreciation is a reduction in the value of an asset with the passage of time, due in particular to wear and tear.\",\"industry\":\"Home Insurance\",\"example_en\":\"After three years, this car is projected to have a 43% depreciation.\",\"example_es\":\"Después de tres años, se prevé que este automóvil tendrá una depreciación del 43%.\",\"source\":\"Customer Service\"},{\"english\":\"Detour\",\"spanish\":\"Desvío /\\nDesviación\",\"definition\":\"A long or roundabout route taken to avoid something along the way.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The detour was confusing and I ended up on a one way street.\",\"example_es\":\"El desvío era confuso y terminé en una calle de una sola vía/un solo sentido.\",\"source\":\"Customer Service\"},{\"english\":\"Diabetes\",\"spanish\":\"Diabetes\",\"definition\":\"Any of a group of diseases characterized by high blood sugar (glucose) levels caused by insufficient production of insulin, impaired response to insulin, or both. With type 1 diabetes, your body does not make insulin. With type 2 diabetes, the more common type, your body does not make or use insulin well. Without enough insulin, the glucose stays in your blood.\",\"industry\":\"Medical\",\"example_en\":\"My grandmother had to give herself daily insulin injections and watch her sugar intake due to her diabetes.\",\"example_es\":\"Mi abuela tenía que darse inyecciones de insulina diariamente ella misma y controlar el consumo de azúcar debido a su diabetes.\",\"source\":\"Customer Service\"},{\"english\":\"Diagnosis\",\"spanish\":\"Diagnosis\",\"definition\":\"A diagnosis is the process of determining which disease or condition explains a person's symptoms and signs.\",\"industry\":\"Medical\",\"example_en\":\"A good diagnosis needs to take into account the patient's medical history.\",\"example_es\":\"Un buen diagnóstico necesita tener en cuenta el historial médico del paciente.\",\"source\":\"Customer Service\"},{\"english\":\"Diaper rash\",\"spanish\":\"Pañalitis /\\nDermatitis del pañal\",\"definition\":\"Diaper rash is any rash that affects your baby’s diaper area — their buttocks, genitals or thighs. Diaper rash is the most common skin condition in young infants that can make a baby's skin sore, red, scaly, and tender.\",\"industry\":\"Medical\",\"example_en\":\"To prevent diaper rash, change diapers frequently and use a diaper cream.\",\"example_es\":\"Para prevenir la pañalitis, cambie los pañales con frecuencia y use una crema para pañales.\",\"source\":\"Customer Service\"},{\"english\":\"Diapers\",\"spanish\":\"Pañales\",\"definition\":\"A piece of absorbent material wrapped around a baby's bottom and between their legs to absorb and retain urine and feces.\",\"industry\":\"General\",\"example_en\":\"Brand name diapers are more expensive than the generic ones.\",\"example_es\":\"Los pañales de marca son más costosos que los genéricos.\",\"source\":\"Customer Service\"},{\"english\":\"Diarrhea\",\"spanish\":\"Diarrea\",\"definition\":\"Loose, watery stools more than three times in one day. You may also have cramps, bloating, nausea and an urgent need to have a bowel movement.\",\"industry\":\"Medical\",\"example_en\":\"I need an appointment with the pediatrician as my son has diarrhea, a fever and was crying most of the night.\",\"example_es\":\"Necesito una cita con el pediatra ya que mi hijo tiene diarrea, fiebre y lloró gran parte de la noche.\",\"source\":\"Customer Service\"},{\"english\":\"Digits\",\"spanish\":\"Dígitos /\\nNúmeros\",\"definition\":\"Any of the Arabic numerals 1 to 9 and usually the symbol 0, especially when forming part of a number.\",\"industry\":\"General\",\"example_en\":\"I need the last 4 digits of your social security number.\",\"example_es\":\"Necesito los 4 últimos dígitos de su número del seguro social.\",\"source\":\"Customer Service\"},{\"english\":\"Diphtheria\",\"spanish\":\"Difteria\",\"definition\":\"Diphtheria is a serious bacterial infection that usually affects the mucous membranes of the nose and throat.\",\"industry\":\"Medical\",\"example_en\":\"Diphtheria is a serious infectious disease that can cause breathing difficulty.\",\"example_es\":\"La difteria es una enfermedad infecciosa grave que puede causar dificultad respiratoria.\",\"source\":\"Customer Service\"},{\"english\":\"Direct deposit\",\"spanish\":\"Depósito directo\",\"definition\":\"The electronic transfer of funds directly from the payer into the bank account of the recipient.\",\"industry\":\"Finance\",\"example_en\":\"I have a free-checking account where I receive a direct deposit from my employer.\",\"example_es\":\"Tengo una cuenta de cheques gratuita donde recibo depósito directo de mi empleador.\",\"source\":\"Customer Service\"},{\"english\":\"Direction\",\"spanish\":\"Dirección /\\nRumbo\",\"definition\":\"The course or path on which something is moving or pointing.\",\"industry\":\"General\",\"example_en\":\"What direction were you traveling, north, south, east, or west?\",\"example_es\":\"¿En qué dirección iba viajando, norte, sur, este u oeste?\",\"source\":\"Customer Service\"},{\"english\":\"Disability\",\"spanish\":\"Discapacidad /\\nIncapacidad\",\"definition\":\"Impairment of physical activity; the extent to which normal work or daily activities cannot be performed due to mental or physical injury or impairment.\",\"industry\":\"Social Services\",\"example_en\":\"I am your case manager for your work injury. How many days did the doctor say you would be on disability?\",\"example_es\":\"Yo soy su administrador de caso para su lesión de trabajo. ¿Cuántos días dijo el doctor que estaría en discapacidad/incapacidad?\",\"source\":\"Customer Service\"},{\"english\":\"Discharge (from the body)\",\"spanish\":\"Flujo /\\nSecreción\",\"definition\":\"Secretions.\",\"industry\":\"Medical\",\"example_en\":\"They developed a fever and a watery discharge from their eyes.\",\"example_es\":\"Desarrollaron fiebre y una secreción acuosa de sus ojos.\",\"source\":\"Customer Service\"},{\"english\":\"Discharge (release from the hospital)\",\"spanish\":\"Dar de alta\",\"definition\":\"The point at which the patient leaves the hospital and either returns home or is transferred to another facility such as one for rehabilitation or to a nursing home.\",\"industry\":\"Medical\",\"example_en\":\"I was discharged 5 days after giving birth. There were a few complications.\",\"example_es\":\"Me dieron de alta del hospital 5 días después que di a luz. Hubo algunas complicaciones.\",\"source\":\"Customer Service\"},{\"english\":\"Disciplinary Segregation /\\nDis-Seg\",\"spanish\":\"Aislamiento disciplinario\",\"definition\":\"Status assigned to an inmate, as a consequence from a violation of jail rules, which consists of confinement in a cell, room, or other housing unit, in isolation, segregated from inmates who are not on disciplinary segregation status.\",\"industry\":\"Jail system\",\"example_en\":\"He is in disciplinary segregation due to his violent behavior.\",\"example_es\":\"Está en aislamiento disciplinario debido a su comportamiento violento.\",\"source\":\"Customer Service\"},{\"english\":\"Disclaimer\",\"spanish\":\"Descargo de responsabilidad\",\"definition\":\"A defensive measure, used generally with the purpose of protection from unwanted claims or liability.\",\"industry\":\"Customer Service\",\"example_en\":\"Before you sign, read carefully all the disclaimers.\",\"example_es\":\"Antes de firmar, lea cuidadosamente todos los descargos de responsabilidad.\",\"source\":\"Customer Service\"},{\"english\":\"Disclosure\",\"spanish\":\"Divulgación\",\"definition\":\"A notice or a statement that lets people know relevant information that could help them make informed decisions about a service.\",\"industry\":\"Customer Service\",\"example_en\":\"Many collections agencies and banks have disclosures that are read before a call begins.\",\"example_es\":\"Muchos departamentos de cobranzas y bancos tienen divulgaciones que son leídas antes que empiece una llamada\",\"source\":\"Customer Service\"},{\"english\":\"Discomfort\",\"spanish\":\"Molestia /\\nMalestar\",\"definition\":\"An absence of comfort or ease; uneasiness, hardship, or mild pain. Being uneasy, anxious, or embarrassed.\",\"industry\":\"Medical\",\"example_en\":\"That procedure is usually more involved and causes more discomfort than the laparoscopic procedure.\",\"example_es\":\"Ese procedimiento es usualmente más complicado y causa más molestias/malestar que un procedimiento laparoscópico.\",\"source\":\"Customer Service\"},{\"english\":\"Disconnection /\\nShutoff\",\"spanish\":\"Desconexión\",\"definition\":\"To stop or end the supply of electricity, water, gas, etc., to (something, such as a piece of electronic equipment).\",\"industry\":\"Customer Service\",\"example_en\":\"I will move out of the state and I have already requested the disconnection of my utilities.\",\"example_es\":\"Me mudaré fuera del estado y ya solicité la desconexión de mis servicios públicos.\",\"source\":\"Customer Service\"},{\"english\":\"Ditch\",\"spanish\":\"Zanja\",\"definition\":\"A narrow channel dug in the ground, typically used for drainage alongside a road or the edge of a field.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My brakes failed and we ended up in the ditch.\",\"example_es\":\"Mis frenos fallaron y terminamos en la zanja.\",\"source\":\"Customer Service\"},{\"english\":\"Dizzy\",\"spanish\":\"Mareada(o)\",\"definition\":\"Having or involving a sensation of spinning around and losing one's balance.\",\"industry\":\"Medical\",\"example_en\":\"Please send an ambulance soon, my mother feels dizzy.\",\"example_es\":\"Por favor envíen una ambulancia pronto, mi madre se siente mareada.\",\"source\":\"Customer Service\"},{\"english\":\"DMV (Department of Motor Vehicles)\",\"spanish\":\"Departamento de Vehículos Motorizados\",\"definition\":\"A state agency in charge of administering vehicle registration and driver licensing and keeping driving records for drivers in the state, including tickets, accidents, etc.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You will have to go to the DMV in person to register the vehicle.\",\"example_es\":\"Tendrá que ir al departamento de vehículos motorizados en persona para registrar el vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Doing the Dutch / \\nThe “Dutch Act”\",\"spanish\":\"Reclusa(o) que planea suicidarse\",\"definition\":\"Inmate talk: To commit suicide\",\"industry\":\"Jail system\",\"example_en\":\"We are worried he only talks about the Dutch Act.\",\"example_es\":\"Estamos preocupados, él solo habla de suicidarse.\",\"source\":\"Customer Service\"},{\"english\":\"Donut hole\",\"spanish\":\"Lapso sin cobertura\",\"definition\":\"The “donut hole” essentially refers to where a drug plan may reach its limit on what it will cover for drugs.\",\"industry\":\"Health Insurance\",\"example_en\":\"The donut hole exists in the majority of Medicare prescription plans.\",\"example_es\":\"El lapso sin cobertura existe en la mayoría de los planes de medicamentos recetados de Medicare.\",\"source\":\"Customer Service\"},{\"english\":\"Dosage\",\"spanish\":\"Dosificación\",\"definition\":\"Refers to the duration or frequency at which a medicine must be taken or administered. The dosage is the dose, or amount of drug, plus when and how often to take it.\",\"industry\":\"Medical\",\"example_en\":\"The doctor will indicate the dosage of the new medication.\",\"example_es\":\"El médico le indicará la dosificación del nuevo medicamento.\",\"source\":\"Customer Service\"},{\"english\":\"Dose\",\"spanish\":\"Dosis\",\"definition\":\"Refers to a measured portion or a quantity of a medicine or a substance that must be taken at a time.\",\"industry\":\"Medical\",\"example_en\":\"That new dose is hard to take, the cough syrup does not taste good.\",\"example_es\":\"Esa nueva dosis es difícil de tomar, el jarabe para la tos no sabe bien.\",\"source\":\"Customer Service\"},{\"english\":\"Double park\",\"spanish\":\"Estacionarse paralelamente\",\"definition\":\"Park (a vehicle) alongside one that is already parked at the side of the road.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The witness statement indicates that you were double parked and opened your door without looking.\",\"example_es\":\"La declaración del testigo indica que estaba estacionado paralelamente y abrió la puerta sin mirar\",\"source\":\"Customer Service\"},{\"english\":\"Down payment\",\"spanish\":\"Pago inicial / Cuota Inicial / Anticipo\",\"definition\":\"An initial amount paid at the time of purchase.\",\"industry\":\"Finance\",\"example_en\":\"The deadline to make your down payment is July 30th. If you are not able to pay by that date, you may request an extension so that you don´t lose the opportunity to buy that house.\",\"example_es\":\"La fecha límite para hacer el pago inicial es el 30 de julio. Si no puede pagar para esa fecha, puede solicitar una extensión para que no pierda la oportunidad de comprar la casa.\",\"source\":\"Customer Service\"},{\"english\":\"DPT / DTP / DTaP / TdaP/ DTP vaccine\",\"spanish\":\"Vacuna contra la difteria, el tétanos y la tos ferina\",\"definition\":\"A vaccine used for active immunization against diphtheria, tetanus, and whooping cough. Sometimes this vaccine is called the bacterial triple shot, however, it is a different register.\",\"industry\":\"Medical\",\"example_en\":\"He got a shot for diphtheria, tetanus, and whooping cough.\",\"example_es\":\"Le pusieron las vacunas contra la difteria, tétanos y tosferina.\",\"source\":\"Customer Service\"},{\"english\":\"Drainage\",\"spanish\":\"Desagüe\",\"definition\":\"The system of water or waste liquids flowing away from somewhere into the ground or down pipes.\",\"industry\":\"Customer Service\",\"example_en\":\"The terrace is flooded because the drainage is clogged.\",\"example_es\":\"La terraza está inundada porque el desagüe está tapado.\",\"source\":\"Customer Service\"},{\"english\":\"Drainpipe\",\"spanish\":\"Tuberías de drenaje / \\nTubería de desagüe\",\"definition\":\"A drainpipe is a pipe attached to the side of a building, through which rainwater flows from the roof into a drain.\",\"industry\":\"Home Insurance\",\"example_en\":\"The drainpipe is choked up with rubbish.\",\"example_es\":\"La tubería de drenaje está obstruida con residuos.\",\"source\":\"Customer Service\"},{\"english\":\"Drivable\",\"spanish\":\"Conducible /\\nManejable\",\"definition\":\"Vehicle which use or operation is possible.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Was your car drivable after the accident or did it have to be towed?\",\"example_es\":\"¿Estaba su carro conducible después del accidente o tuvo que ser remolcado?\",\"source\":\"Customer Service\"},{\"english\":\"Drive Aisle\",\"spanish\":\"Pasillo vial\",\"definition\":\"A circulation route for vehicular traffic through a parking lot, site or property, and may connect to a driveway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"So, you were stopped in the drive aisle waiting for a car to pull out from the parking space and the other car rear-ended you, correct?\",\"example_es\":\"Entonces, usted estaba detenido en el pasillo vial, esperando que un auto saliera del puesto de estacionamiento y el otro auto le chocó por detrás, ¿correcto?\",\"source\":\"Customer Service\"},{\"english\":\"Drive-in facility\",\"spanish\":\"Centro de inspecciones\",\"definition\":\"Locations designated by auto insurance companies, where drivers can bring their vehicles to have damages inspected, in order to have an estimate of the repair costs. An insurance office designated to inspect and evaluate damages to automobiles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Please make an appointment at our drive-in facilities to have the damages to your vehicle appraised.\",\"example_es\":\"Por favor haga una cita en nuestro centro de inspecciones para evaluar los daños de su vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Drive-through bank\",\"spanish\":\"Auto banco\",\"definition\":\"Refers to a type of service provided by a business that allows customers to purchase products or receive services without leaving their cars.\",\"industry\":\"Finance\",\"example_en\":\"Instead of entering the branch you can use the drive-through for many of your banking needs.\",\"example_es\":\"En vez de entrar a la sucursal usted puede usar el auto banco para muchas de sus necesidades bancarias.\",\"source\":\"Customer Service\"},{\"english\":\"Driver's License\",\"spanish\":\"Licencia de conducir\",\"definition\":\"An official document or card which shows that you have the legal right to drive a vehicle. A permit, issued by a state's motor vehicle bureau, that allows the holder to drive a motor vehicle on public roads.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We need a valid driver's license.\",\"example_es\":\"Necesitamos una licencia de conducir válida.\",\"source\":\"Customer Service\"},{\"english\":\"Driveway\",\"spanish\":\"Entrada de carros / \\nEntrada\",\"definition\":\"A short road or paved area leading from a public road to a house or garage.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Drive your car into the garage, or at least park it on the driveway.\",\"example_es\":\"Mete el carro en el garaje, o al menos estaciónalo en la entrada.\",\"source\":\"Customer Service\"},{\"english\":\"Drizzle\",\"spanish\":\"Llovizna /\\nGarúa\",\"definition\":\"Rain that falls lightly in very small drops.\",\"industry\":\"General\",\"example_en\":\"There was a drizzle and the pavement was slippery.\",\"example_es\":\"Hubo una llovizna y el pavimento estaba resbaloso.\",\"source\":\"Customer Service\"},{\"english\":\"Drywall / \\nGypsum board /\\nWallboard\",\"spanish\":\"Cartón de yeso /\\nTablero de yeso / \\nPared\",\"definition\":\"Drywall, also known as gypsum board, or most popularly, plasterboard, is a construction material used to line interior walls and ceilings in both residential and commercial structures.\",\"industry\":\"Home Insurance\",\"example_en\":\"Each building had fireproof drywall to protect the stairwells.\",\"example_es\":\"Cada edificio tenía cartones de yeso ignífugos para proteger las escaleras.\",\"source\":\"Customer Service\"},{\"english\":\"Dual Enrollment\",\"spanish\":\"Inscripción doble\",\"definition\":\"Dual enrollment, also known as early college program, is the opportunity for high school students to be enrolled in high school and college classes at the same time, getting a jumpstart on their college degree.\",\"industry\":\"School\",\"example_en\":\"High school students who had a dual enrollment take classes at community colleges or other nearby colleges\",\"example_es\":\"Los estudiantes de secundaria que tenían una inscripción doble toman clases en colegios comunitarios u otros colegios cercanos.\",\"source\":\"Customer Service\"},{\"english\":\"Due date\",\"spanish\":\"Fecha de vencimiento\",\"definition\":\"The day by which something must be completed, done, paid, etc.\",\"industry\":\"Finance\",\"example_en\":\"Your payment should be made on or before the due date.\",\"example_es\":\"Su pago debe hacerse en o antes de la fecha de vencimiento.\",\"source\":\"Customer Service\"},{\"english\":\"DUI\",\"spanish\":\"Conducir bajo los efectos de alcohol y/o drogas\",\"definition\":\"Refers to the crime of driving a motor vehicle while impaired by alcohol or other drugs (including recreational drugs and those prescribed by physicians), to a level that renders the driver incapable of operating a motor vehicle safely.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"You are being charged with DUI-driving under the influence of drugs and/or alcohol. Is this your first offense?\",\"example_es\":\"Usted tiene cargos de conducir bajo los efectos de alcohol y/o droga. ¿es esta su primer ofensa?\",\"source\":\"Customer Service\"},{\"english\":\"Dull pain\",\"spanish\":\"Dolor sordo\",\"definition\":\"Pain lacking in force, intensity, or sharpness; type of pain that is not very strong but continues for a long time.\",\"industry\":\"Medical\",\"example_en\":\"Are you experiencing a dull pain, or is it sharp or burning?\",\"example_es\":\"¿Está experimentando un dolor sordo, o es agudo o ardor?\",\"source\":\"Customer Service\"},{\"english\":\"Dumpster\",\"spanish\":\"Basurero / \\nContenedor de Basura\",\"definition\":\"A large trash receptacle designed to be emptied into a truck.\",\"industry\":\"General\",\"example_en\":\"You may take all your trash bags and put them inside the dumpster in the back of the building.\",\"example_es\":\"Puede llevar todas sus bolsas de basura y ponerlas dentro del basurero en la parte de atrás del edificio.\",\"source\":\"Customer Service\"},{\"english\":\"Durable medical equipment (DME)\",\"spanish\":\"Equipo médico duradero\",\"definition\":\"Any equipment that provides therapeutic benefits to a patient in need because of certain conditions and/or illnesses.\",\"industry\":\"Medical\",\"example_en\":\"You can rent any durable medical equipment needed for your treatment.\",\"example_es\":\"Puede alquilar cualquier equipo médico duradero que necesite para su tratamiento.\",\"source\":\"Customer Service\"},{\"english\":\"Dwelling insurance\",\"spanish\":\"Seguro de vivienda\",\"definition\":\"Dwelling insurance covers a home that is not owner-occupied or is valued below the minimum coverage limit available for a homeowners policy.\",\"industry\":\"Home Insurance\",\"example_en\":\"If you have a mortgage, your financial institution will likely require you to have dwelling insurance.\",\"example_es\":\"Si tiene una hipoteca, es probable que su institución financiera le exija tener un seguro de vivienda.\",\"source\":\"Customer Service\"},{\"english\":\"DWI (Driving While Intoxicated)\",\"spanish\":\"Conducir/manejar en estado de ebriedad\",\"definition\":\"In one state, DUI might be the same as DWI, while in another state the two terms could be different. DUI refers to driving under the influence, while DWI may mean driving while intoxicated or driving while impaired. The precise definitions depend on the state.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Have you ever been charged with DWI?\",\"example_es\":\"¿Alguna vez le han puesto algún cargo por manejar en estado de ebriedad?\",\"source\":\"Customer Service\"},{\"english\":\"Earning (an income)\",\"spanish\":\"Generación de ingresos\",\"definition\":\"To gain or be paid (money or other payment) in return for work or service.\",\"industry\":\"General\",\"example_en\":\"What I earn is enough to cover my expenses.\",\"example_es\":\"Lo que gano es suficiente para cubrir mis gastos.\",\"source\":\"Customer Service\"},{\"english\":\"Eastbound\",\"spanish\":\"En dirección este /\\nRumbo al este\",\"definition\":\"Going towards the east.\",\"industry\":\"General\",\"example_en\":\"You were going eastbound, right?\",\"example_es\":\"Usted iba en dirección al este, ¿verdad?\",\"source\":\"Customer Service\"},{\"english\":\"EBT card\",\"spanish\":\"Tarjeta de transferencia electrónica de beneficios\",\"definition\":\"Through the EBT program, recipients of nutrition assistance are issued an electronic card similar to a debit card for payment of benefits directly to retailers. EBT is used most commonly for a program called SNAP, which provides food-purchasing assistance for low- and no-income people.\",\"industry\":\"Social Services\",\"example_en\":\"You cannot use your EBT card in an ATM.\",\"example_es\":\"Usted no puede usar su tarjeta de transferencia electrónica de beneficios en un cajero automático.\",\"source\":\"Customer Service\"},{\"english\":\"Effective date\",\"spanish\":\"Fecha de vigencia\",\"definition\":\"The date on which coverage begins. Date on which some service, agreement or right of use enters into effect.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Your coverage will begin on the effective date, which in your case is September 15th, 2016.\",\"example_es\":\"Su cobertura empezará en la fecha de vigencia, que en su caso es el 15 de septiembre del 2016.\",\"source\":\"Customer Service\"},{\"english\":\"Electrical panel /\\nBreaker panel\",\"spanish\":\"Panel eléctrico\",\"definition\":\"An electrical panel (a.k.a. breaker panel) is a metal box with a door, usually built into a wall in an out-of-the-way corner of your home. Inside, you’ll find all your home’s breaker switches.\",\"industry\":\"Home Insurance\",\"example_en\":\"If you have a fuse box, you won’t see any switches on your electrical panel; you’ll see screw-in fuses.\",\"example_es\":\"Si usted tiene una caja de fusibles, no verá ningún interruptor en su panel eléctrico; verá fusibles atornillados.\",\"source\":\"Customer Service\"},{\"english\":\"Elementary school\",\"spanish\":\"Escuela primaria\",\"definition\":\"A school for the first four to six grades, and usually including kindergarten.\",\"industry\":\"School\",\"example_en\":\"I have one of my daughters in elementary school.\",\"example_es\":\"Tengo a una de mis hijas en la escuela primaria.\",\"source\":\"Customer Service\"},{\"english\":\"Eligibility\",\"spanish\":\"Elegibilidad\",\"definition\":\"The fact of having the necessary qualities or satisfying the necessary conditions.\",\"industry\":\"General\",\"example_en\":\"The applicants must meet all requirements for eligibility.\",\"example_es\":\"Los solicitantes deben cumplir con todos los requerimientos para la elegibilidad.\",\"source\":\"Customer Service\"},{\"english\":\"Eligible\",\"spanish\":\"Elegible\",\"definition\":\"Meeting the stipulated requirements;\\nqualified.\",\"industry\":\"Social Services\",\"example_en\":\"Before you apply for SSI benefits, please make sure you are elegible.\",\"example_es\":\"Antes de que usted presente su solicitud para el Ingreso Suplementario del Seguro Social, por favor asegúrese de sea elegible.\",\"source\":\"Customer Service\"},{\"english\":\"Emergency\",\"spanish\":\"Emergencia\",\"definition\":\"An unexpected and usually dangerous situation that calls for immediate medical attention.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"I need to know the nature of your emergency in order to send the police, fire department or the paramedics.\",\"example_es\":\"Necesito saber el motivo de su emergencia para poder enviar a la policía, bomberos o paramédicos.\",\"source\":\"Customer Service\"},{\"english\":\"Emergency lights /\\nEmergency blinkers / \\nHazard lights\",\"spanish\":\"Luces de emergencias /\\nLuces intermitentes\",\"definition\":\"The flashing lights of a motor vehicle to indicate that the vehicle is stationary and temporarily obstructing the traffic.\",\"industry\":\"Auto Insurance\",\"example_en\":\"When you pull over on the road, don't forget to turn your emergency lights on.\",\"example_es\":\"Cuando se orille en la carretera, no olvide encender sus luces intermitentes.\",\"source\":\"Customer Service\"},{\"english\":\"Emergency Room (ER) /\\nEmergency Department (ED)\",\"spanish\":\"Sala de emergencias\",\"definition\":\"A hospital room or area that is used for treating people who need immediate medical care - abbreviation ER. The section of a health care facility for providing rapid treatment to victims of sudden illness or trauma.\",\"industry\":\"Medical\",\"example_en\":\"Please take the patient to the ER if there is any sudden loss of consciousness or excessive bleeding.\",\"example_es\":\"Por favor lleve al paciente a la sala de emergencias si hay una repentina pérdida de conciencia o sangrado excesivo.\",\"source\":\"Customer Service\"},{\"english\":\"Soaked\",\"spanish\":\"Empapado\",\"definition\":\"To make something completely wet by water or another liquid.\",\"industry\":\"General\",\"example_en\":\"He stood outside in the rain for a long time, his clothes were completely soaked.\",\"example_es\":\"Él estuvo parado afuera en la lluvia por un largo período de tiempo, su ropa estaba completamente empapada.\",\"source\":\"Customer Service\"},{\"english\":\"Emphysema\",\"spanish\":\"Enfisema\",\"definition\":\"A pathological condition of the lungs marked by an abnormal increase in the size of the air spaces, resulting in labored breathing and an increased susceptibility to infection.\",\"industry\":\"Medical\",\"example_en\":\"Emphysema is the reason why you feel short of breath most of the time.\",\"example_es\":\"Enfisema es la razón por la que se siente con falta de aliento la mayor parte del tiempo.\",\"source\":\"Customer Service\"},{\"english\":\"Employer\",\"spanish\":\"Empleador(a) / \\nPatrona, Patrón\",\"definition\":\"A person or company that has people who do work for wages or a salary.\",\"industry\":\"General\",\"example_en\":\"I need you to provide the name of your last employer and how often you were paid.\",\"example_es\":\"Necesito que provea el nombre de su último empleador y con qué frecuencia le pagaban.\",\"source\":\"Customer Service\"},{\"english\":\"Employment\",\"spanish\":\"Empleo\",\"definition\":\"An activity or service performed for another, especially for compensation or as an occupation.\",\"industry\":\"General\",\"example_en\":\"Employment plays an important role in the loan application process.\",\"example_es\":\"El empleo juega un papel importante en el proceso de solicitud de préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"EMS (Emergency Medical Service)\",\"spanish\":\"Servicio de emergencias médicas\",\"definition\":\"A system that provides emergency medical care. Once it is activated by an incident that causes serious illness or injury, the focus of EMS is emergency medical care of the patient(s).\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"EMS workers were called to the scene and pronounced her dead upon arrival.\",\"example_es\":\"Se llamó a los trabajadores del servicio de emergencias médicas y la declararon muerta al llegar.\",\"source\":\"Customer Service\"},{\"english\":\"EMT (Emergency Medical Technician)\",\"spanish\":\"Técnica(o) de emergencias médicas\",\"definition\":\"A first responder who is trained in basic medical knowledge and skills to provide immediate medical care to patients in an emergency. They are often the first emergency service providers to arrive on the scene of a crisis, such as an accident, medical emergency, fire or natural disaster.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"If you have special training or skills, such as EMT certification, let crew members know if you are willing to help.\",\"example_es\":\"Si posee entrenamiento o habilidades especiales, tal como certificación de técnica de emergencias médicas, informe a los miembros de la tripulación si está dispuesta a ayudar.\",\"source\":\"Customer Service\"},{\"english\":\"Endorsement /\\nInsurance Rider\",\"spanish\":\"Aval de seguro\",\"definition\":\"An insurance endorsement/rider is an amendment to an existing insurance contract that changes the terms of the original policy. An endorsement/rider can be issued at the time of purchase, mid-term or at renewal time. Insurance premiums may be affected and adjusted as a result.\",\"industry\":\"Insurance (general)\",\"example_en\":\"She added an endorsement to her life insurance policy that increased her coverage.\",\"example_es\":\"Ella agregó un aval de seguro a su póliza de seguro de vida que incrementó su cobertura.\",\"source\":\"Customer Service\"},{\"english\":\"Engine\",\"spanish\":\"Motor\",\"definition\":\"A motor that propels an automobile by converting thermal energy to power in order to produce force and motion.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The car has a four-cylinder engine.\",\"example_es\":\"El auto tiene un motor de cuatro cilindros.\",\"source\":\"Customer Service\"},{\"english\":\"Engineered wood flooring\",\"spanish\":\"Piso laminado\",\"definition\":\"Engineered wood flooring looks almost identical to the hardwood on the surface, but instead of a single wood plank, it's made of a high-quality plywood core with a thin layer of hardwood flooring on top.\",\"industry\":\"Home Insurance\",\"example_en\":\"Engineered wood flooring is a more affordable option, but it can't be refinished to extend its lifespan.\",\"example_es\":\"Los pisos laminados son una opción más asequible, pero no pueden ser restaurados para prolongar su vida útil.\",\"source\":\"Customer Service\"},{\"english\":\"Enroll (verb)\",\"spanish\":\"Inscribirse (NO ENROLARSE)\",\"definition\":\"To register and give information relevant to an insured's participation in an insurance plan. To officially register as a member of an institution, company or organization that provides services.\",\"industry\":\"Health Insurance\",\"example_en\":\"You must fill out an application to be able to enroll in this health insurance plan.\",\"example_es\":\"Usted debe llenar una solicitud para poder inscribirse en este plan de seguro de salud.\",\"source\":\"Customer Service\"},{\"english\":\"Enrolled\",\"spanish\":\"Inscrita(o) (NO ENROLADA)\",\"definition\":\"To officially register as a member of an institution, company or organization that provides services.\",\"industry\":\"General\",\"example_en\":\"Our system indicates that you are enrolled. It appears that you did it through the Internet. Do you remember doing that?\",\"example_es\":\"Nuestro sistema indica que usted está inscrito. Al parecer lo hizo por medio del Internet. ¿Recuerda haberlo hecho?\",\"source\":\"Customer Service\"},{\"english\":\"Entrance\",\"spanish\":\"Entrada /\\nPuerta\",\"definition\":\"The means or place of entry, such as a vestibule, passage, driveway, door or gate.\",\"industry\":\"General\",\"example_en\":\"Please park in the visitor parking and go to the south entrance where you will see the sign for the emergency room.\",\"example_es\":\"Por favor estaciónese en el estacionamiento de visitantes y vaya a la entrada sur donde verá el anuncio para la sala de emergencias.\",\"source\":\"Customer Service\"},{\"english\":\"Equipment\",\"spanish\":\"Aparato /\\nEquipo\",\"definition\":\"A set of tools or devices used or needed for\\na specific purpose or activity.\",\"industry\":\"Customer Service\",\"example_en\":\"The new equipment enabled us to finish the work in an hour.\",\"example_es\":\"El nuevo equipo nos permitió terminar el trabajo en una hora.\",\"source\":\"Customer Service\"},{\"english\":\"Equity\",\"spanish\":\"Valor líquido /\\nPlusvalía /\\nPatrimonio /\\nCapital\",\"definition\":\"Refers to the ownership of any asset after any liabilities associated with the asset are cleared.\",\"industry\":\"Finance\",\"example_en\":\"You do not have enough equity in your home to use as collateral for the loan.\",\"example_es\":\"No tiene suficiente valor líquido en su casa para usarla como colateral para el préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Escrow account\",\"spanish\":\"Cuenta de plica /\\nCuenta de depósitos en garantía /\\nCuenta de fondos en custodia\",\"definition\":\"An account designed to safely hold funds temporarily. For example, a bank can be the escrow provider holding deposits for taxes and insurance on a mortgage loan.\",\"industry\":\"Finance\",\"example_en\":\"We will set up an escrow account to pay for property taxes and insurance.\",\"example_es\":\"Vamos a establecer una cuenta de depósitos en garantía para pagar por los impuestos y el seguro de la propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Estimate\",\"spanish\":\"Presupuesto /\\nEstimación /\\nCálculo aproximado\",\"definition\":\"A statement of the approximate cost of work to be done, such as car repairs or a building project.\",\"industry\":\"Customer Service\",\"example_en\":\"The estimate is correct and it will cost you $750 dollars to fix and/or replace the windshield.\",\"example_es\":\"El presupuesto es correcto y le costará $750 dólares el arreglar y/o remplazar el parabrisas.\",\"source\":\"Customer Service\"},{\"english\":\"Evict\",\"spanish\":\"Desalojar\",\"definition\":\"To put a tenant out by legal process; to force someone to leave somewhere.\",\"industry\":\"General\",\"example_en\":\"Tenants who fall behind in their rent payment would risk being evicted.\",\"example_es\":\"Los inquilinos que se atrasen en el pago del alquiler correrían el riesgo de ser desalojados.\",\"source\":\"Customer Service\"},{\"english\":\"Exit (ramp)\",\"spanish\":\"(Rampa de) salida\",\"definition\":\"A highway ramp as in exit ramp / off-ramp which allows vehicles to exit a controlled-access highway, freeway or motorway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The road crew closed the exit ramp due to repairs to the pavement being done.\",\"example_es\":\"El equipo/la cuadrilla de carretera cerró la rampa de salida debido a reparaciones que se realizaban en el pavimento.\",\"source\":\"Customer Service\"},{\"english\":\"Expedite\",\"spanish\":\"Acelerar /\\nAgilizar\",\"definition\":\"To speed up the progress or execute\\nquickly.\",\"industry\":\"Customer Service\",\"example_en\":\"To expedite the approval process, you can apply online.\",\"example_es\":\"Para acelerar el proceso de aprobación, puede realizar la solicitud en línea.\",\"source\":\"Customer Service\"},{\"english\":\"Expiration date\",\"spanish\":\"Fecha de vencimiento\",\"definition\":\"The date after which something (as a credit card) is no longer in effect; the date after which a product (as food or medicine) should not be sold because of an expected decline in quality or effectiveness.\",\"industry\":\"Customer Service\",\"example_en\":\"I need the expiration date on your credit card, month and year only.\",\"example_es\":\"Necesito la fecha de vencimiento de su tarjeta de crédito, solamente el mes y el año.\",\"source\":\"Customer Service\"},{\"english\":\"Expire\",\"spanish\":\"Vencer /\\nCaducar /\\nExpirar\",\"definition\":\"The ending date of an agreement or contract period.\",\"industry\":\"Customer Service\",\"example_en\":\"When do my benefits expire and do I have to go through the enrollment process from the beginning?\",\"example_es\":\"¿Cuándo se vencen mis beneficios, y tengo que pasar por el proceso de inscripción desde el inicio?\",\"source\":\"Customer Service\"},{\"english\":\"Extended School Year (ESY)\",\"spanish\":\"Año escolar prolongado / \\nAño lectivo prolongado /\\nServicios de año escolar extendido /\",\"definition\":\"In special education, extended school year is a provision that allows students to receive instruction during school “vacation” periods to prevent serious regression of previously learned skills.\",\"industry\":\"School\",\"example_en\":\"Extended school year eligibility is determined by a student’s Individualized Education Program (IEP) Team.\",\"example_es\":\"La elegibilidad para el año escolar prolongado la determina el equipo del programa de educación Individualizada del estudiante.\",\"source\":\"Customer Service\"},{\"english\":\"Extracurricular activities\",\"spanish\":\"Actividades extracurriculares /\\nActividades extraescolares / \\nActividades extraacadémicas\",\"definition\":\"Activities performed by students, that fall outside the realm of the normal curriculum of school, college or university education. These activities enable students to apply academic skills in a real-world context.\",\"industry\":\"School\",\"example_en\":\"Extracurricular activities allow students to reinforce the lessons learned in the classroom.\",\"example_es\":\"Las actividades extracurriculares permiten a los estudiantes reforzar las lecciones aprendidas en el salón de clases.\",\"source\":\"Customer Service\"},{\"english\":\"Factory-installed\",\"spanish\":\"Instalado de fábrica\",\"definition\":\"Equipment or feature installed in an article during the manufacturing process.\",\"industry\":\"Customer Service\",\"example_en\":\"A user wants to re-install a factory-installed program which he had removed.\",\"example_es\":\"Un usuario desea reinstalar un programa instalado de fábrica que había eliminado.\",\"source\":\"Customer Service\"},{\"english\":\"Failure to thrive (FTT)\",\"spanish\":\"Falta de desarrollo /\\nFalta de evolución\",\"definition\":\"Failure to thrive (FTT) Indicates insufficient weight gain or absence of appropriate physical growth in children.\",\"industry\":\"School\",\"example_en\":\"Failure to thrive is not a disease or disorder itself. Rather, it's a sign that a child is undernourished.\",\"example_es\":\"La falta de desarrollo no es una enfermedad o trastorno en sí. Más bien, es un signo de que un niño está desnutrido.\",\"source\":\"Customer Service\"},{\"english\":\"Father-in-law /\\nMother-in-law\",\"spanish\":\"Suegro / \\nSuegra\",\"definition\":\"One's spouse's parents.\",\"industry\":\"General\",\"example_en\":\"I have a very strained relationship with my mother-in-law.\",\"example_es\":\"Tengo una relación muy tensa con mi suegra.\",\"source\":\"Customer Service\"},{\"english\":\"Feces /\\nExcrement /\\nStool /\\nFecal matter\",\"spanish\":\"Excremento /\\nHeces/ \\nMateria fecal\",\"definition\":\"Solid waste passed out of the body.\",\"industry\":\"Medical\",\"example_en\":\"We have detected blood in your excrement (feces) and we need to know where it is coming from.\",\"example_es\":\"Hemos detectado sangre en su excremento (heces fecales) y necesitamos saber de dónde viene.\",\"source\":\"Customer Service\"},{\"english\":\"Fee\",\"spanish\":\"Cargo /\\nTarifa /\\nCuota\",\"definition\":\"A payment made to a company or professional person in exchange for services, i.e.: bank's fees, attorney's fees, an admission's fee, etc.\",\"industry\":\"Customer Service\",\"example_en\":\"There is a fee on my account I don't recognize.\",\"example_es\":\"Hay un cargo en mi cuenta que no reconozco.\",\"source\":\"Customer Service\"},{\"english\":\"Fee schedule\",\"spanish\":\"Tarifa preindicada /\\nLista de precios preindicados\",\"definition\":\"A comprehensive listing of fee maximums used to reimburse a physician and/or other providers on a fee-for-service basis.\",\"industry\":\"Health Insurance\",\"example_en\":\"That's your co-pay for the visit, it is based on the agreed fee schedule with the facility you went to.\",\"example_es\":\"Ese es su copago por la visita, se basa en la tarifa preindicada acordada con el establecimiento a donde fue.\",\"source\":\"Customer Service\"},{\"english\":\"Felony\",\"spanish\":\"Delito mayor\",\"definition\":\"Serious crimes, such as murder, rape, or robbery, punishable by a more stringent sentence than that given for a misdemeanor.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The charge against you is a felony. If found guilty, it carries a sentence up to 10 years in a state prison.\",\"example_es\":\"El cargo en su contra es un delito mayor. Si es encontrado culpable, conlleva una sentencia de hasta 10 años en una prisión estatal.\",\"source\":\"Customer Service\"},{\"english\":\"FEMA (Federal Emergency Management Agency)\",\"spanish\":\"Agencia Federal de Gestión de Emergencias\",\"definition\":\"The Federal Emergency Management Agency (FEMA) is an agency of the United States Department of Homeland Security (DHS), initially created under President Jimmy Carter, that supports citizens and emergency personnel to build, sustain, and improve the nation's capability to prepare for, protect against, respond to, recover from, and mitigate all hazards.\",\"industry\":\"General\",\"example_en\":\"Since 1979, the Federal Emergency Management Agency (FEMA) has been the Federal Government's lead agency in responding to and recovering from many of the Nation's greatest moments of crisis.\",\"example_es\":\"Desde 1979, la Agencia Federal de Gestión de Emergencias ha sido la agencia líder del gobierno federal en la respuesta y recuperación de muchos de los mayores momentos de crisis de la nación.\",\"source\":\"Customer Service\"},{\"english\":\"Fender (car) /\\nMudguard (bicycle)\",\"spanish\":\"Guardafango /\\nGuardabarros /\\nGuardalodos /\\nSalpicadera\",\"definition\":\"A guard over each wheel of a motor vehicle, for example, that is shaped and positioned so as to block the splashing of water or mud.\",\"industry\":\"Auto Insurance\",\"example_en\":\"When I left my house in the morning I noticed the damages to the fender.\",\"example_es\":\"Cuando salí de mi casa en la mañana me di cuenta de los daños en el guardafangos.\",\"source\":\"Customer Service\"},{\"english\":\"Fender bender\",\"spanish\":\"Choque leve\",\"definition\":\"A minor collision between motor vehicles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I really wouldn't call it an accident because nothing happened; it was more of a fender bender.\",\"example_es\":\"Realmente no lo llamaría un accidente, porque no pasó nada; fue más un choque leve.\",\"source\":\"Customer Service\"},{\"english\":\"Fever /\\nTemperature\",\"spanish\":\"Fiebre /\\nTener temperatura\",\"definition\":\"An abnormally high body temperature, usually accompanied by shivering, headache, and in severe instances, delirium.\",\"industry\":\"Medical\",\"example_en\":\"How high is your baby's fever?\",\"example_es\":\"¿Qué tan alta tiene la fiebre su bebé?\",\"source\":\"Customer Service\"},{\"english\":\"Field sobriety test\",\"spanish\":\"Prueba de sobriedad en el sitio /\\nPrueba de sobriedad en el lugar\",\"definition\":\"The Standardized Field Sobriety Test (SFST) is a battery of 3 tests performed during a traffic stop in order to determine if a driver is impaired. The 3 tests that make up the SFST are the horizontal gaze nystagmus (HGN), the walk-and-turn, and the one-leg stand tests.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"You were pulled over by the officer as your car was weaving in and out of traffic. He was authorized to conduct a field sobriety test to see if you were under the influence of drugs or alcohol.\",\"example_es\":\"Fue detenido por el oficial ya que su carro estaba moviéndose dentro y fuera del tráfico. Él estaba autorizado a hacer una prueba de sobriedad en el sitio para ver si usted estaba bajo los efectos de drogas o alcohol.\",\"source\":\"Customer Service\"},{\"english\":\"File taxes (verb)\",\"spanish\":\"Declarar impuestos\",\"definition\":\"Generation of a tax return.\",\"industry\":\"Finance\",\"example_en\":\"Did you file taxes in 2022?\",\"example_es\":\"¿Usted declaró impuestos en 2022?\",\"source\":\"Customer Service\"},{\"english\":\"Fill a prescription (verb)\",\"spanish\":\"Surtir una receta /\\nSurtir una medicina\",\"definition\":\"Presenting a prescription provided by a healthcare professional to a pharmacy who in turn dispenses the medication listed in the prescription.\",\"industry\":\"Medical\",\"example_en\":\"Because of the strength of the medication, I have to be there in person with my ID when they fill my prescription for the first time.\",\"example_es\":\"Debido a la concentración del medicamento, debo estar ahí en persona con mi documento de identidad cuando surtan mi receta por primera vez.\",\"source\":\"Customer Service\"},{\"english\":\"Fine (context dependent) /\\nPenalties\",\"spanish\":\"Multa\",\"definition\":\"Refers to a sum of money required to be paid especially to the government as a penalty for an offense.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Do I have to pay the $100 fine right away or can I make monthly payments? I want to get my car back as I need it to commute to my job.\",\"example_es\":\"¿Tengo que pagar la multa de $100 inmediatamente o puedo hacer pagos mensuales? Quiero recuperar mi carro ya que lo necesito para ir a mi trabajo.\",\"source\":\"Customer Service\"},{\"english\":\"Fine motor skills\",\"spanish\":\"Habilidad motriz fina /\\nDestreza motriz de los músculos menores /\\nHabilidad motora de\\nlos músculos finos\",\"definition\":\"Fine motor skills are the ability to make movements using the small muscles in our hands and wrists. We rely on these skills to do key tasks in school, at work, and in everyday life.\",\"industry\":\"School\",\"example_en\":\"There are things you can do at home to help improve fine motor skills.\",\"example_es\":\"Hay cosas que puedes hacer en casa para ayudar a mejorar la destreza motriz de los músculos finos.\",\"source\":\"Customer Service\"},{\"english\":\"Fingerprints\",\"spanish\":\"Huellas dactilares /\\nHuellas digitales\",\"definition\":\"A mark made by the pattern of ridges on the pad of a human finger.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Your fingerprints were at the scene of the crime, both on the entrance and bedroom doors of the home.\",\"example_es\":\"Sus huellas dactilares estaban en la escena del crimen, en puertas tanto de la entrada de la casa como de la recámara.\",\"source\":\"Customer Service\"},{\"english\":\"Firefighter /\\nFireman\",\"spanish\":\"Bombero\",\"definition\":\"A firefighter is a first responder trained in firefighting, primarily to control and extinguish fires that threaten life and property, as well as to rescue people from confinement or dangerous situations.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The firefighter rushed into the burning building to rescue a child.\",\"example_es\":\"El bombero entró corriendo al edificio en llamas para rescatar a un niño.\",\"source\":\"Customer Service\"},{\"english\":\"Fishtail (verb)\",\"spanish\":\"Colearse\",\"definition\":\"Refers to a vehicle skidding in a way that makes a fishtail movement.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The scariest moment was when the car started to fishtail.\",\"example_es\":\"El momento más aterrador fue cuando el carro empezó a colearse.\",\"source\":\"Customer Service\"},{\"english\":\"Fixed interest rate\",\"spanish\":\"Tasa fija de interés\",\"definition\":\"An interest rate that does not change over the life of a loan or other form of credit.\",\"industry\":\"Finance\",\"example_en\":\"We are offering a fixed interest rate of 6% for the life of the loan and you may be able to refinance at a lower rate later on.\",\"example_es\":\"Estamos ofreciendo una tasa fija de interés del 6% por el plazo del préstamo y usted podría refinanciar a una tasa más baja más adelante.\",\"source\":\"Customer Service\"},{\"english\":\"Flame-retardant insulation / \\nFireproof insulation\",\"spanish\":\"Aislamiento ignífugo\",\"definition\":\"Flame-retardant insulation slows the spread of flames and helps to protect the structure of a building.\",\"industry\":\"Home Insurance\",\"example_en\":\"A flame-retardant insulating material is a critical component in buildings because it can prevent diffusion in the event of a fire.\",\"example_es\":\"Un material aislante ignífugo es un componente crítico en los edificios porque puede evitar la difusión en caso de incendio.\",\"source\":\"Customer Service\"},{\"english\":\"Flash Flood\",\"spanish\":\"Inundación súbita /\\nInundación repentina /\\nInundación relámpago\",\"definition\":\"Flash floods are usually characterized by raging torrents after heavy rains that rip through river beds, urban streets, or mountain canyons sweeping everything before them.\",\"industry\":\"General\",\"example_en\":\"It is even possible to experience a flash flood in areas not immediately receiving rain.\",\"example_es\":\"Incluso es posible experimentar una inundación repentina en áreas que no reciben lluvia inmediatamente.\",\"source\":\"Customer Service\"},{\"english\":\"Flight\",\"spanish\":\"Vuelo\",\"definition\":\"A scheduled airline trip.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"Your flight should arrive at 12:00 noon Pacific time so you will have plenty of time before the bus leaves at 2:00 PM.\",\"example_es\":\"Su vuelo deberá llegar a las 12:00 del mediodía horario del pacifico y tendrá suficiente tiempo antes de que el bus se vaya a las 2:00 pm.\",\"source\":\"Customer Service\"},{\"english\":\"Flip over /\\nTip over\\nOverturn\",\"spanish\":\"Volcar /\\nVolcarse\",\"definition\":\"Turn upside down.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I'm calling to report a flipped over vehicle in the middle of the road.\",\"example_es\":\"Estoy llamando para reportar que un vehículo se volcó en medio de la carretera.\",\"source\":\"Customer Service\"},{\"english\":\"Flipped classroom\",\"spanish\":\"Salón de clases invertido /\\nAula invertida\",\"definition\":\"In the flipped classroom model, students learn new material independently through homework rather than by being introduced to it during class. Then, teachers use class time for engaging and applying that new learning material.\",\"industry\":\"School\",\"example_en\":\"One of the goals of the flipped classroom model is to make the classroom experience more individualized and interactive\",\"example_es\":\"Una de las metas del salón de clases invertido es hacer que la experiencia en el salón de clases sea más individualizada e interactiva.\",\"source\":\"Customer Service\"},{\"english\":\"Flood Advisory\",\"spanish\":\"Aviso de inundación\",\"definition\":\"A flood advisory is issued when flooding is not expected to be bad enough to issue a warning.\",\"industry\":\"General\",\"example_en\":\"A flood advisory is the lowest level of weather alerts for flooding.\",\"example_es\":\"Un aviso de inundación es el nivel más bajo de alertas meteorológicas por inundaciones.\",\"source\":\"Customer Service\"},{\"english\":\"Flood Warning\",\"spanish\":\"Advertencia de inundación / \\nAlerta de inundación\",\"definition\":\"A flood warning is issued when the hazardous weather event is imminent or already happening.\",\"industry\":\"General\",\"example_en\":\"A flood warning is issued when flooding is imminent or occurring.\",\"example_es\":\"Una advertencia de inundación se emite cuando las inundaciones son inminentes o están ocurriendo.\",\"source\":\"Customer Service\"},{\"english\":\"Flood Watch\",\"spanish\":\"Amenaza de inundación /\\nRiesgo de inundación\",\"definition\":\"A flood watch is issued when conditions are favorable for a specific hazardous weather event to occur. A Flood Watch is issued when conditions are favorable for flooding. It does not mean flooding will occur, but it is possible.\",\"industry\":\"General\",\"example_en\":\"The potential for flooding also resulted in the issuance of a flash flood watch for the entirety of the island.\",\"example_es\":\"La posibilidad de inundaciones también resultó en la emisión de una amenaza de inundación para toda la isla.\",\"source\":\"Customer Service\"},{\"english\":\"Fog\",\"spanish\":\"Neblina\",\"definition\":\"Vapor condensed to fine particles of water suspended in the lower atmosphere that differs from cloud only in being near the ground.\",\"industry\":\"General\",\"example_en\":\"My visibility was limited by dense fog, I couldn't see much.\",\"example_es\":\"Mi visibilidad estaba limitada por la espesa neblina, no se veía mucho.\",\"source\":\"Customer Service\"},{\"english\":\"Foggy\",\"spanish\":\"Con neblina\",\"definition\":\"Full of or accompanied by fog; filled or abounding with fog.\",\"industry\":\"Auto Insurance\",\"example_en\":\"How were the weather conditions the day of the accident? Was it rainy or foggy; was the road wet or slippery?\",\"example_es\":\"¿Cómo estaban las condiciones climáticas el día del accidente? ¿Estaba lloviendo o había neblina? ¿La carretera estaba mojada o resbaladiza?\",\"source\":\"Customer Service\"},{\"english\":\"Follow-up\",\"spanish\":\"Seguimiento /\\nContinuación\",\"definition\":\"To pursue further attention to reinforce an initial action. Med: a routine examination of a patient after  or surgical treatment. A doctor's visits to check on the progress a patient is making following a procedure or treatment for a condition.\",\"industry\":\"General\",\"example_en\":\"You will be back for your follow-up appointment in 30 days.\",\"example_es\":\"Va a regresar para su cita de seguimiento en 30 días.\",\"source\":\"Customer Service\"},{\"english\":\"Food bank\",\"spanish\":\"Banco de alimentos\",\"definition\":\"A place where stocks of food, typically basic provisions and non-perishable items, are supplied free of charge to people in need.\",\"industry\":\"Social Services\",\"example_en\":\"In its first year of operation, the food bank managed to offer food to almost one hundred organizations.\",\"example_es\":\"En su primer año de operaciones, el banco de alimentos logró ofrecer comida a casi cien organizaciones.\",\"source\":\"Customer Service\"},{\"english\":\"Food poisoning\",\"spanish\":\"Intoxicación con alimentos /\\nEnvenenamiento por comestibles\",\"definition\":\"Illness caused by bacteria or other toxins in food, typically with vomiting and diarrhea.\",\"industry\":\"Medical\",\"example_en\":\"We're here to inspect your restaurant due to the number of food poisoning cases reported in the last week.\",\"example_es\":\"Estamos aquí para inspeccionar su restaurante debido al número de casos de intoxicación con alimentos reportados en la última semana.\",\"source\":\"Customer Service\"},{\"english\":\"Food stamps\",\"spanish\":\"Cupones de alimentos / \\nVales de comida /\\nCupones de comida /\\nVales de despensa\",\"definition\":\"Government benefits provided to eligible low-income individuals to be used to purchase food products.\",\"industry\":\"Social Services\",\"example_en\":\"Have you ever applied for food stamps or any other assistance programs?\",\"example_es\":\"¿Alguna vez ha solicitado cupones de alimentos u otros programas de asistencia?\",\"source\":\"Customer Service\"},{\"english\":\"Foreclosure\",\"spanish\":\"Ejecución hipotecaria\",\"definition\":\"Foreclosure occurs when a lender repossesses a house because the homeowner has defaulted (failure to pay) on their mortgage loan or home equity line of credit.\",\"industry\":\"Finance\",\"example_en\":\"Please be aware that foreclosure and other collection procedures will continue during the refinancing process.\",\"example_es\":\"Por favor sepa que la ejecución hipotecaria y otros procedimientos de cobros continuarán durante el proceso de refinanciamiento.\",\"source\":\"Customer Service\"},{\"english\":\"Forge / \\nFalsify (verb)\",\"spanish\":\"Falsificar\",\"definition\":\"To make or produce a fraudulent imitation of (a signature, banknote, etc) or to commit forgery. To alter in order to commit fraud.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"They forged documents to enter the country.\",\"example_es\":\"Falsificaron documentos para entrar al país.\",\"source\":\"Customer Service\"},{\"english\":\"Forms\",\"spanish\":\"Formularios /\\nPlanillas (NO FORMAS)\",\"definition\":\"Refers to formatted documents with spaces in which to write/enter or select data.\",\"industry\":\"General\",\"example_en\":\"You need to fill out, sign and date each of the forms you received for the bank to approve your loan application.\",\"example_es\":\"Necesita llenar, firmar y fechar cada uno de los formularios que recibió para que el banco apruebe su solicitud de préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Formulary medication\",\"spanish\":\"Medicamentos de la lista de medicamentos aprobados /\\nMedicamento de la lista de medicinas aprobadas por el seguro de salud\",\"definition\":\"Formularies are lists that have the insurance carriers preferred drugs. You can normally find both generic and brand name drugs in the formularies.\",\"industry\":\"Health Insurance\",\"example_en\":\"The doctor prescribed a formulary medication which does appear on the list of approved medications by the insurance company.\",\"example_es\":\"El doctor recetó un medicamento de la lista de medicinas aprobadas el cual sí aparece en la lista de medicamentos aprobados por la compañía de seguros.\",\"source\":\"Customer Service\"},{\"english\":\"Foster care\",\"spanish\":\"Cuidados de acogida / \\nCentro de acogida\",\"definition\":\"A system in which a minor has been placed into a group home, private home of a state-certified caregiver, or with a family member approved by the state.\",\"industry\":\"Social Services\",\"example_en\":\"Until the children's parents are located, they will be placed in the foster care system.\",\"example_es\":\"Hasta que los padres de los niños sean localizados, se les colocará en el sistema de cuidados de acogida.\",\"source\":\"Customer Service\"},{\"english\":\"Foundation\",\"spanish\":\"Cimiento\",\"definition\":\"The foundation of a building or civil structure is the element that connects it to the ground. It's located at the very bottom of the construction, in direct contact with the soil, and acts to transfer loads safely from the building to the ground.\",\"industry\":\"Home Insurance\",\"example_en\":\"Foundations can be either shallow or deep, referring to the depth of the soil in which the foundation is built.\",\"example_es\":\"Los cimientos pueden ser poco profundos o profundos, en referencia a la profundidad del suelo en el que se construyen los cimientos.\",\"source\":\"Customer Service\"},{\"english\":\"Four wheel drive\",\"spanish\":\"4x4 /\\nDoble tracción /\\nTracción en las cuatro llantas\",\"definition\":\"A transmission system that provides power directly to all four wheels of a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I'm interested in renting a vehicle with four wheel drive.\",\"example_es\":\"Estoy interesado en alquilar un vehículo con tracción en las cuatro llantas.\",\"source\":\"Customer Service\"},{\"english\":\"Fraud\",\"spanish\":\"Fraude /\\nFraudulento\",\"definition\":\"Deliberate deception, trickery, or cheating intended to gain an advantage.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Common types of insurance fraud are staged accidents, exaggerated injuries, and inflated medical bills.\",\"example_es\":\"Tipos comunes de fraude de seguro son accidentes falsos, lesiones exageradas, facturas médicas con precios inflados.\",\"source\":\"Customer Service\"},{\"english\":\"Free of charge\",\"spanish\":\"Gratuito /\\nSin cargo / \\nLibre de cargo\",\"definition\":\"Does not cost anything; available at no cost.\",\"industry\":\"General\",\"example_en\":\"Entrance to the museum is free of charge on Sundays.\",\"example_es\":\"La entrada al museo es gratuita los domingos.\",\"source\":\"Customer Service\"},{\"english\":\"Freeway\",\"spanish\":\"Autopista\",\"definition\":\"An express highway, especially one with controlled access.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Was traffic heavy on the freeway at that time of day?\",\"example_es\":\"¿Estaba el tráfico pesado en la autopista a esa hora del día?\",\"source\":\"Customer Service\"},{\"english\":\"Full continuum of services\",\"spanish\":\"Gama completa de servicios\",\"definition\":\"A continuum of services refers to the range of special education and related services that are available to assist any student in a school or school district to provide instruction in the least restrictive environment.\",\"industry\":\"School\",\"example_en\":\"A full continuum of services is available for all students who qualify for special education.\",\"example_es\":\"Una gama completa de servicios está disponible para todos los estudiantes quienes califiquen para la educación especial.\",\"source\":\"Customer Service\"},{\"english\":\"Full Coverage\",\"spanish\":\"Cobertura Completa (NO FULL COVER)\",\"definition\":\"This term denotes a combination of coverage bundled into one policy. The full coverage designation typically means that the policy includes liability coverage, comprehensive coverage and collision; thus, the insured party is protected against the three major sources of loss.\",\"industry\":\"Auto Insurance\",\"example_en\":\"On this insurance policy, would you like to have liability or full coverage for your vehicle? The price will depend on the type of coverage that you select.\",\"example_es\":\"¿En esta póliza de seguro, quiere tener seguro de responsabilidad civil o cobertura completa para su vehículo? El precio dependerá del tipo de cobertura que usted seleccione.\",\"source\":\"Customer Service\"},{\"english\":\"Functional Behavioral Assessment\",\"spanish\":\"Evaluación de la\\nconducta funcional\",\"definition\":\"Functional Behavioral Assessment (FBA) is a process for identifying problem behaviors and developing interventions\\nto improve or eliminate those behaviors.\",\"industry\":\"School\",\"example_en\":\"A functional behavioral assessment (FBA) helps educators to understand what function the problem behavior serves for the student.\",\"example_es\":\"La evaluación de la conducta funcional ayuda a los educadores a entender qué función cumple la conducta problemática para el estudiante.\",\"source\":\"Customer Service\"},{\"english\":\"Furnace\",\"spanish\":\"Calefacción / \\nCalentador ambiental /\\nCalentador principal\",\"definition\":\"Refers to an enclosed structure used to provide heat or high-temperature heating.\",\"industry\":\"Customer Service\",\"example_en\":\"The technician will have to come out to check the furnace and reset the pilot light.\",\"example_es\":\"El técnico tendrá que ir a revisar el calentador principal y reiniciar la luz del piloto.\",\"source\":\"Customer Service\"},{\"english\":\"Gallbladder\",\"spanish\":\"Vesícula /\\nVesícula biliar\",\"definition\":\"A membranous muscular sac in which bile from the liver is stored—called also cholecyst.\",\"industry\":\"Medical\",\"example_en\":\"The stomach pain can be caused by gallbladder stones, so we need to do more tests.\",\"example_es\":\"El dolor de estómago puede ser causado por las piedras en la vesícula, por lo que necesitamos hacer más pruebas.\",\"source\":\"Customer Service\"},{\"english\":\"Galvanized steel pipes\",\"spanish\":\"Tuberías de acero\\ngalvanizado\",\"definition\":\"Galvanized pipes are steel pipes that have been dipped in a protective zinc coating to prevent corrosion and rust.\",\"industry\":\"Home Insurance\",\"example_en\":\"Galvanized pipes have a life span of between 40 and 100 years.\",\"example_es\":\"Las tuberías de acero galvanizado tienen una vida útil de entre 40 y 100 años.\",\"source\":\"Customer Service\"},{\"english\":\"Gardener\",\"spanish\":\"Jardinero\",\"definition\":\"A person who tends and cultivates a garden as a hobby or for a living.\",\"industry\":\"General\",\"example_en\":\"He works as a part-time gardener.\",\"example_es\":\"Él trabaja como jardinero a tiempo parcial\",\"source\":\"Customer Service\"},{\"english\":\"Gas leak\",\"spanish\":\"Fuga de gas /\\nEscape de gas\",\"definition\":\"The escape of natural gas or other gaseous product from a pipeline or other containment into a living area or any other area where the gas should not be present.\",\"industry\":\"Customer Service\",\"example_en\":\"If you experience a gas leak it is imperative that you call 911 right away in addition to contacting your gas and electric provider.\",\"example_es\":\"Si sucede una fuga de gas es de suma importancia que llame al 911 rápidamente aparte de contactar a sus proveedores de gas y electricidad.\",\"source\":\"Customer Service\"},{\"english\":\"Gaze\",\"spanish\":\"Mirada\",\"definition\":\"To look steadily and intently, especially in admiration, surprise, or thought.\",\"industry\":\"General\",\"example_en\":\"She stood gazing at herself in the mirror.\",\"example_es\":\"Ella se quedó de pie mirándose en el espejo.\",\"source\":\"Customer Service\"},{\"english\":\"Gear shift\",\"spanish\":\"Palanca de cambio de velocidades\",\"definition\":\"A device used to engage or disengage gears in a transmission or similar mechanism.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The gear shift is stuck and I can't move it.\",\"example_es\":\"La palanca de cambio de velocidades está atascada y no puedo moverla.\",\"source\":\"Customer Service\"},{\"english\":\"Generic\",\"spanish\":\"Genérica(o)\",\"definition\":\"Relating to or being a product that is sold or distributed without any brand name, especially as a discount alternative to a brand-name product.\",\"industry\":\"General\",\"example_en\":\"The generic drug will typically cost you less than a brand name medication.\",\"example_es\":\"El medicamento genérico típicamente le costará menos que el medicamento de marca.\",\"source\":\"Customer Service\"},{\"english\":\"German measles (rubella)\",\"spanish\":\"Sarampión alemán /\\nRubeola\",\"definition\":\"Rubella is an infection caused by a virus. It is usually mild with fever and a rash. About half of the people who get rubella do not have symptoms. There is no treatment for measles, but the measles-mumps-rubella (MMR) vaccine can prevent it.\",\"industry\":\"Medical\",\"example_en\":\"The signs and symptoms of German measles may begin with 1-2 days of mild fever and swollen, tender lymph nodes, usually in the back of the neck or behind the ears.\",\"example_es\":\"Los signos y síntomas del sarampión alemán pudieran empezar con 1 - 2 días de fiebre leve, inflamación y sensibilidad en los nódulos linfáticos usualmente detrás del cuello o atrás de las orejas.\",\"source\":\"Customer Service\"},{\"english\":\"Glucometer\",\"spanish\":\"Glucómetro\",\"definition\":\"A glucometer is used to measure the amount of glucose in your blood. It’s a portable medical device that tests your blood through a fingerstick sample.\",\"industry\":\"General\",\"example_en\":\"Glucose measurements were taken immediately with a glucometer.\",\"example_es\":\"Las medidas de glucosa fueron tomadas inmediatamente con un glucómetro.\",\"source\":\"Customer Service\"},{\"english\":\"Good state of repair\",\"spanish\":\"Buen estado de conservación\",\"definition\":\"A property that doesn't have structural problems such as dry rot, damp or faulty wiring.\",\"industry\":\"Home Insurance\",\"example_en\":\"Your property must be in a good state of repair for you to insure it.\",\"example_es\":\"Su propiedad debe estar en buen estado de conservación para que pueda asegurarla.\",\"source\":\"Customer Service\"},{\"english\":\"Goosebumps\",\"spanish\":\"Piel de gallina\",\"definition\":\"A roughness of the skin produced by erection of its papillae especially from cold, fear, or a sudden feeling of excitement. Called also goose pimples.\",\"industry\":\"Medical\",\"example_en\":\"When I saw the injured pet, I got goosebumps.\",\"example_es\":\"Cuando vi a la mascota herida se me puso la piel de gallina.\",\"source\":\"Customer Service\"},{\"english\":\"Grace period\",\"spanish\":\"Período de gracia\",\"definition\":\"The allotted time during which a payment can be made without penalty and without entry upon credit records as delinquent or in default.\",\"industry\":\"Finance\",\"example_en\":\"There will be a 10-day grace period after the payment due date. Please make sure we receive the amount due by that date to avoid a late fee.\",\"example_es\":\"Habrá un periodo de gracia de 10 días después de la fecha de vencimiento para hacer el pago. Por favor asegúrese de que recibamos la cantidad adeudada para esa fecha para evitar un cargo por pago atrasado.\",\"source\":\"Customer Service\"},{\"english\":\"Grade Point Average (GPA)\",\"spanish\":\"Promedio de calificaciones\",\"definition\":\"A grade point average measures the average of all the final grades a student has received.\",\"industry\":\"School\",\"example_en\":\"GPA is one factor used in class rank, academic awards, and college admissions.\",\"example_es\":\"El promedio de calificaciones es un factor utilizado en el rango escolar, los premios académicos y las admisiones universitarias.\",\"source\":\"Customer Service\"},{\"english\":\"Grades\",\"spanish\":\"Calificaciones / \\nNotas\",\"definition\":\"Grades are essentially a way to measure or quantify learning and intellectual progress using objective criteria.\",\"industry\":\"School\",\"example_en\":\"She got good grades at school but she has changed since meeting this guy.\",\"example_es\":\"Ella obtuvo buenas calificaciones en la escuela pero ha cambiado desde que conoció a este chico.\",\"source\":\"Customer Service\"},{\"english\":\"Grant (N)\",\"spanish\":\"Subsidio / \\nBeca / \\nAyuda económica\",\"definition\":\"An amount of money given, especially by the government, to a person or organization for a special purpose.\",\"industry\":\"Social Services\",\"example_en\":\"We got a government grant for setting up our business, but they took it all back again in taxes.\",\"example_es\":\"Obtuvimos un subsidio del gobierno para establecer nuestro negocio, pero nos lo quitaron todo de nuevo en impuestos.\",\"source\":\"Customer Service\"},{\"english\":\"Grant (V)\",\"spanish\":\"Otorgar / \\nConceder\",\"definition\":\"To give or allow someone something, usually in an official way.\",\"industry\":\"Finance\",\"example_en\":\"When you grant permission to the bank, they will be able to log into your account.\",\"example_es\":\"Cuando le otorga permiso al banco, ellos podrán ingresar a su cuenta.\",\"source\":\"Customer Service\"},{\"english\":\"Groin\",\"spanish\":\"Ingle\",\"definition\":\"The area between the abdomen and the thigh on either side of the body.\",\"industry\":\"Medical\",\"example_en\":\"He received several kicks to the groin.\",\"example_es\":\"Recibió varias patadas en la ingle.\",\"source\":\"Customer Service\"},{\"english\":\"Gross monthly income\",\"spanish\":\"Ingreso mensual bruto\",\"definition\":\"Monthly income before deductions like taxes, insurance, retirement, social security are made.\",\"industry\":\"Finance\",\"example_en\":\"You will need to provide your gross monthly income, which is the amount before taxes and other deductions are made.\",\"example_es\":\"Necesitará proveer su ingreso mensual bruto, que es la cantidad antes de impuestos y otras deducciones.\",\"source\":\"Customer Service\"},{\"english\":\"Gross motor skills\",\"spanish\":\"Habilidad motriz gruesa /\\nHabilidad motora de los\\nmúsculos gruesos\",\"definition\":\"Gross motor skills are abilities that let us do tasks that involve large muscles in our torso, legs, and arms. They involve whole-body movements.\",\"industry\":\"Medical\",\"example_en\":\"We use gross motor skills for all sorts of physical activities, from running to raking leaves.\",\"example_es\":\"Utilizamos las habilidades motrices gruesas para todo tipo de actividades físicas, desde correr hasta rastrillar hojas.\",\"source\":\"Customer Service\"},{\"english\":\"Guest\",\"spanish\":\"Huésped\",\"definition\":\"An individual who pays for meals or accommodations at a restaurant, hotel, or other establishment; a patron.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"I am a guest at this hotel and would like to find out what other services the hotel provides.\",\"example_es\":\"Soy un huésped en este hotel y quisiera saber qué otros servicios ofrece el hotel.\",\"source\":\"Customer Service\"},{\"english\":\"Gutter\",\"spanish\":\"Canaleta\",\"definition\":\"A gutter is a plastic or metal channel fixed to the lower edge of the roof of a building, which rain water drains into.\",\"industry\":\"Home Insurance\",\"example_en\":\"I climbed onto the roof and removed the leaves from the gutter.\",\"example_es\":\"Subí al tejado y quité las hojas de la canaleta.\",\"source\":\"Customer Service\"},{\"english\":\"Gynecology\",\"spanish\":\"Ginecología\",\"definition\":\"The branch of medicine that deals with the female reproductive system, its diseases, and their treatment.\",\"industry\":\"Medical\",\"example_en\":\"In order to schedule a gynecology appointment, you need a referral from your primary care doctor.\",\"example_es\":\"Para poder agendar una cita en ginecología, necesita una remisión de su médico de cabecera.\",\"source\":\"Customer Service\"},{\"english\":\"Hacking cough\",\"spanish\":\"Tos seca y frecuente\",\"definition\":\"A short, dry, frequent cough.\",\"industry\":\"Medical\",\"example_en\":\"A prolonged hacking cough is reason to see your doctor.\",\"example_es\":\"Una tos prolongada, seca y frecuente es razón para ver a su médico.\",\"source\":\"Customer Service\"},{\"english\":\"Hacksaw\",\"spanish\":\"Sierra para metales /\\nSierra de acero\",\"definition\":\"A saw with a narrow fine-toothed blade set in a frame, used especially for cutting metal.\",\"industry\":\"General\",\"example_en\":\"This is a mechanical hacksaw that clamps to the rail, ensuring a straight cut.\",\"example_es\":\"Esta es una sierra para metales mecánica que se sujeta al raíl, garantizando un corte recto.\",\"source\":\"Customer Service\"},{\"english\":\"Hail\",\"spanish\":\"Granizo\",\"definition\":\"Small, hard balls of ice that fall from the sky like rain.\",\"industry\":\"General\",\"example_en\":\"Hail storms are of frequent occurrence in Colorado.\",\"example_es\":\"Las tormentas de granizo son frecuentes en Colorado.\",\"source\":\"Customer Service\"},{\"english\":\"Hand truck\",\"spanish\":\"Carretilla de mano\",\"definition\":\"An L-shaped box-moving handcart with handles at one end, wheels at the base, with a small ledge to set objects on, flat against the floor when the hand-truck is upright.\",\"industry\":\"General\",\"example_en\":\"Most commercial hand trucks used for beverage and food service deliveries are resistant but very light.\",\"example_es\":\"La mayoría de las carretillas de mano industriales usadas para entrega de servicio de alimentos y bebidas son resistentes pero muy ligeras.\",\"source\":\"Customer Service\"},{\"english\":\"Handling fee\",\"spanish\":\"Tarifa de tramitación /\\nTarifa de gestión /\\nGastos administrativos\",\"definition\":\"A handling fee is an amount charged to customers on top of their order subtotal and shipping fees. It covers the cost of expenses related to fulfillment, specifically packing fees based on required labor.\",\"industry\":\"Customer Service\",\"example_en\":\"The company says it will not charge either buyers or sellers a handling fee or a commission.\",\"example_es\":\"La empresa dice que no cobrará ni a los compradores ni a los vendedores una tarifa de tramitación o comisión.\",\"source\":\"Customer Service\"},{\"english\":\"Hard credit check / \\nHard inquiry\",\"spanish\":\"Investigación de crédito exhaustiva / \\nIndagacion de crédito incidente\",\"definition\":\"When a lender or company requests to review your credit report as part of the loan application process, that request is recorded on your credit report as a hard inquiry, and it usually will impact your credit score.\",\"industry\":\"Finance\",\"example_en\":\"Any time you apply for a credit account of any kind, the lender will pull your credit report, resulting in a hard inquiry.\",\"example_es\":\"Cada vez que solicita una cuenta de crédito de cualquier tipo, el prestamista obtendrá su informe de crédito, lo que resulta en una investigación de crédito exhaustiva.\",\"source\":\"Customer Service\"},{\"english\":\"Headlights\",\"spanish\":\"Faros\",\"definition\":\"A light on the front of a vehicle (such as a car or motorcycle).\",\"industry\":\"Auto Insurance\",\"example_en\":\"The car only had one headlight on, the right one.\",\"example_es\":\"El carro solo tenía un faro encendido, el derecho.\",\"source\":\"Customer Service\"},{\"english\":\"Heal (verb)\",\"spanish\":\"Sanar /\\nCicatrizar\",\"definition\":\"To make or become well again, especially after a cut or other injury.\",\"industry\":\"Medical\",\"example_en\":\"It took a long time for the wounds to heal.\",\"example_es\":\"Tomó bastante tiempo para que las heridas sanen.\",\"source\":\"Customer Service\"},{\"english\":\"Health plan /\\nInsurance plan\",\"spanish\":\"Plan de salud /\\nPlan de seguro\",\"definition\":\"An insurance plan that covers medical expenses.\",\"industry\":\"Health Insurance\",\"example_en\":\"Do you have a health plan that would cover this illness? Otherwise, you will have to pay out of pocket and it will be very expensive.\",\"example_es\":\"¿Tiene un plan de salud que cubra esta enfermedad? De otra manera usted tendrá que pagar de su propio bolsillo y será muy costoso.\",\"source\":\"Customer Service\"},{\"english\":\"Heart\",\"spanish\":\"Corazón\",\"definition\":\"The chambered muscular organ in vertebrates that pumps blood received from the veins into the arteries, thereby maintaining the flow of blood through the entire circulatory system.\",\"industry\":\"Medical\",\"example_en\":\"Have you or any family members suffered from any diseases or disorders of the heart, liver or kidneys?\",\"example_es\":\"¿Usted o algún miembro de su familia ha sufrido de enfermedades o trastornos del corazón, hígado o riñones?\",\"source\":\"Customer Service\"},{\"english\":\"Heart attack\",\"spanish\":\"Ataque al corazón /\\nAtaque cardíaco /\\nInfarto\",\"definition\":\"Most heart attacks happen when a clot in the coronary artery blocks the supply of blood and oxygen to the heart. Often this leads to an irregular heartbeat that causes a severe decrease in the pumping function of the heart.\",\"industry\":\"Medical\",\"example_en\":\"Please, note that if you continue smoking, you are at a greater risk of a heart attack, in addition to other serious medical conditions.\",\"example_es\":\"Por favor, sepa que si continúa fumando tiene mayor riesgo de tener un ataque cardíaco, aparte de otras condiciones médicas graves.\",\"source\":\"Customer Service\"},{\"english\":\"Heart murmur\",\"spanish\":\"Soplo cardíaco\",\"definition\":\"Heart murmurs are unique heart sounds produced when blood flows across a heart valve or blood vessel.\",\"industry\":\"Medical\",\"example_en\":\"You have a mild heart murmur that poses no risk.\",\"example_es\":\"Usted tiene un soplo cardíaco leve que no representa ningún riesgo.\",\"source\":\"Customer Service\"},{\"english\":\"Heartburn\",\"spanish\":\"Acidez estomacal\",\"definition\":\"Heartburn is discomfort or actual pain caused by digestive acid moving into the tube that carries swallowed food to your stomach (esophagus).\",\"industry\":\"Medical\",\"example_en\":\"As heartburn is usually worse when you're lying down in bed, you should avoid lying flat.\",\"example_es\":\"Debido a que la acidez estomacal normalmente empeora cuando está recostado, debe evitar acostarse en posición plana.\",\"source\":\"Customer Service\"},{\"english\":\"High blood pressure\",\"spanish\":\"Presión arterial alta / \\nPresión sanguínea alta\",\"definition\":\"A long term medical condition in which the blood pressure in the arteries is persistently elevated.\",\"industry\":\"Medical\",\"example_en\":\"People who are overweight may experience medical problems such as high blood pressure and diabetes, so it is important to eat a healthy diet.\",\"example_es\":\"Personas que tienen sobrepeso pueden padecer problemas de salud como presión arterial alta y diabetes, así que es importante que coma una dieta saludable.\",\"source\":\"Customer Service\"},{\"english\":\"Highway patrol\",\"spanish\":\"Patrulla de caminos /\\nPolicía vial\",\"definition\":\"A police unit that oversees and enforces traffic safety compliance on roads and highways.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The Highway patrol came to the site of the accident and placed red flares for people to slow down.\",\"example_es\":\"La patrulla de caminos vino al sitio del accidente y puso luces rojas para que la gente manejara más despacio\",\"source\":\"Customer Service\"},{\"english\":\"Hinged side door (in a van)\",\"spanish\":\"Puerta lateral pivotante / \\nPuerta lateral plegable\",\"definition\":\"A movable door typically consisting of a panel that swings on hinges or that slides or rotates.\",\"industry\":\"Auto Insurance\",\"example_en\":\"They broke the lock on the hinged side door and stole the tools.\",\"example_es\":\"Rompieron la cerradura de la puerta lateral pivotante y se robaron las herramientas.\",\"source\":\"Customer Service\"},{\"english\":\"Hit and run\",\"spanish\":\"Chocar y huir /\\nChocar y darse a la fuga\",\"definition\":\"When a driver who is involved in an accident leaves the scene without providing information to the other drivers or the police.\",\"industry\":\"Auto Insurance\",\"example_en\":\"As a misdemeanor, hit and run carries a possible sentence of up to six months in the county jail as well as a fine up to $1,000.00 dollars, or both.\",\"example_es\":\"Como delito menor, chocar y huir puede conllevar una sentencia de hasta seis meses en la prisión del condado así como una multa de hasta $1,000.00 dólares, o ambas.\",\"source\":\"Customer Service\"},{\"english\":\"HIV (Human Immunodeficiency Virus)\",\"spanish\":\"VIH (Virus de la Inmunodeficiencia Humana)\",\"definition\":\"HIV is a virus that attacks cells that help the body fight infection, making a person more vulnerable to other infections and diseases.\",\"industry\":\"Medical\",\"example_en\":\"HIV is spread by contact with certain bodily fluids of an infected person, most commonly during unprotected sex.\",\"example_es\":\"El VIH se transmite por contacto con determinados fluidos corporales de una persona infectada, normalmente durante relaciones sexuales sin protección.\",\"source\":\"Customer Service\"},{\"english\":\"Hives\",\"spanish\":\"Ronchas /\\nUrticaria\",\"definition\":\"Refers to an allergic skin reaction causing localized redness, swelling, and itching.\",\"industry\":\"Medical\",\"example_en\":\"I'm allergic to seafood, I break out in hives when I eat any.\",\"example_es\":\"Soy alérgico a los mariscos; cuando los como me salen ronchas.\",\"source\":\"Customer Service\"},{\"english\":\"HMO (Health Maintenance Organization)\",\"spanish\":\"Organización para el mantenimiento de la salud\",\"definition\":\"A health maintenance organization (HMO) is an organization that provides health coverage with providers under contract. An HMO differs from traditional health by the contracts it has with its providers. HMO usually only pay for care within the network. You choose a primary care doctor who coordinates most of your care.\",\"industry\":\"Health Insurance\",\"example_en\":\"I am not sure if I have an HMO or a PPO plan and do I need to select a PCP?\",\"example_es\":\"No estoy segura si tengo un plan de organización para el mantenimiento de la salud o un plan de proveedores preferenciales. Y ¿debo escoger un doctor de cabecera?\",\"source\":\"Customer Service\"},{\"english\":\"Hoarseness\",\"spanish\":\"Ronquera /\\nCarraspera /\\nVoz ronca\",\"definition\":\"Hoarseness refers to a difficulty making sounds when trying to speak. Vocal sounds may be weak, breathy, scratchy, or husky, and the pitch or quality of the voice may change.\",\"industry\":\"Medical\",\"example_en\":\"That chronic hoarseness will stop when you quit smoking.\",\"example_es\":\"Esa ronquera crónica se le quitará cuando deje de fumar.\",\"source\":\"Customer Service\"},{\"english\":\"Hole puncher /\\nHole punch\",\"spanish\":\"Perforadora de papel\",\"definition\":\"A hole puncher is an office tool that is used to create holes in sheets of paper, often for the purpose of collecting the sheets in a binder or folder.\",\"industry\":\"General\",\"example_en\":\"Use a small hole puncher to punch holes at both ends of each strip.\",\"example_es\":\"Use una perforadora de papel pequeña para perforar agujeros en ambos extremos de cada tira.\",\"source\":\"Customer Service\"},{\"english\":\"Home care provider\",\"spanish\":\"Proveedor(a) de atención domiciliaria\",\"definition\":\"Worker, who assists elderly or disabled adults with daily living activities at the person's home, such as preparing meals, housekeeping, transportation.\",\"industry\":\"Health Insurance\",\"example_en\":\"Older people get the best care and services when they feel comfortable with the home care providers they have chosen.\",\"example_es\":\"Los adultos mayores reciben los mejores cuidados y servicios cuando se sienten a gusto con los proveedores de atención médica que ellos escogieron.\",\"source\":\"Customer Service\"},{\"english\":\"Home emergency insurance\",\"spanish\":\"Seguro de emergencias en el hogar\",\"definition\":\"Cover that provides a 24h call out service for emergency repairs on your property. It includes callouts for problems with plumbing, internal electrics, pest control, drains, gas supply, boiler & heating and security.\",\"industry\":\"Home Insurance\",\"example_en\":\"Home emergency insurance can cover things like a blocked drain, a burst pipe or your boiler breaking down.\",\"example_es\":\"El seguro de emergencias en el hogar puede cubrir cosas como un desagüe atascado, una tubería rota, o una caldera averiada.\",\"source\":\"Customer Service\"},{\"english\":\"Home Equity Line\",\"spanish\":\"Línea de crédito sobre el patrimonio de la propiedad\",\"definition\":\"A home equity line of credit works like a credit card. The homeowner is allowed to borrow up to a certain amount for the life of the loan. During that time he can withdraw money as needed. As he pays off the principal, his credit revolves and he can use it again.\",\"industry\":\"Finance\",\"example_en\":\"If you prefer a home equity line of credit, you would only pay interests on the amount you use from the home equity line of credit and you pay as you go. This works like any revolving line of credit, just like a credit card, but your house remains as collateral.\",\"example_es\":\"Si prefiere una línea de crédito sobre el patrimonio de la propiedad, usted pagaría intereses solo en la cantidad que use de la línea de crédito y paga sobre la marcha. Esto funciona como cualquier línea de crédito rotativa, como una tarjeta de crédito, pero su casa se queda como garantía.\",\"source\":\"Customer Service\"},{\"english\":\"Home Equity Loan\",\"spanish\":\"Préstamo sobre el patrimonio de la propiedad\",\"definition\":\"A loan secured or guaranteed by the equity value in the borrower's home.\",\"industry\":\"Finance\",\"example_en\":\"You have a fixed home equity loan of 6% and should make your payments each month by the due date for the life of the loan.\",\"example_es\":\"Tiene un préstamo sobre el patrimonio de la propiedad fijo del 6% y debe hacer sus pagos cada mes en la fecha límite por la duración de plazo del préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Homeowner\",\"spanish\":\"Propietaria(o) de una vivienda /\\nDueña(o) de casa /\\nPoseedor(a) de casa propia\",\"definition\":\"Proprietor, owner of a home, an individual who owns a home.\",\"industry\":\"General\",\"example_en\":\"The homeowner is responsible to pay for property taxes and home insurance if he/she has not set up an escrow account.\",\"example_es\":\"El propietario de la vivienda es responsable de pagar los impuestos de la propiedad y el seguro de la casa si él/ella no ha establecido una cuenta de plica.\",\"source\":\"Customer Service\"},{\"english\":\"Homeowners\\ninsurance\",\"spanish\":\"Seguro para propietarias(os) de vivienda /\\nSeguro de viviendas\",\"definition\":\"Policies designed to protect the property of homeowners, as well as the legal liability derived from owning said property.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Homeowner's insurance is considered mandatory if you plan to purchase the property.\",\"example_es\":\"El seguro para viviendas es considerado obligatorio si usted planea comprar la propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Homeschooling\",\"spanish\":\"Enseñanza académica en el hogar /\\nEducación en el hogar / \\nEscuela en casa\",\"definition\":\"Homeschooling is the process of educating your children in the home.\",\"industry\":\"School\",\"example_en\":\"Each state has different rules and policies regarding homeschooling.\",\"example_es\":\"Cada estado tiene reglas y políticas diferentes con respecto a la educación en el hogar.\",\"source\":\"Customer Service\"},{\"english\":\"Homework\",\"spanish\":\"Tareas\",\"definition\":\"Schoolwork that a student is required to do at home; work or study done in preparation for a certain event or situation.\",\"industry\":\"School\",\"example_en\":\"Have you finished your English homework yet?\",\"example_es\":\"¿Ha terminado ya su tarea de inglés?\",\"source\":\"Customer Service\"},{\"english\":\"Horn /\\nTo honk\",\"spanish\":\"Bocina - claxon - corneta /\\nTocar la bocina - tocar el claxon\",\"definition\":\"A sound-making device that vehicles are equipped with, to use as a warning noise.\",\"industry\":\"Auto Insurance\",\"example_en\":\"He was backing up from his parking space and although I honked my horn several times, he did not stop. I did not have a chance to get out of the way.\",\"example_es\":\"Él estaba retrocediendo de su espacio de estacionamiento y a pesar de que toqué la bocina varias veces, él no paró. Yo no tuve oportunidad de quitarme del camino.\",\"source\":\"Customer Service\"},{\"english\":\"Hospice care\",\"spanish\":\"Cuidado de hospicio - terminal  /\\nCuidado - Atención para deshauciadas(os)\",\"definition\":\"Hospice care is specialized care that provides physical comfort and emotional, social and spiritual support for people nearing the end of life.\",\"industry\":\"Medical\",\"example_en\":\"Hospice care may or may not be covered.\",\"example_es\":\"Los cuidados de hospicio podrían estar cubiertos o no.\",\"source\":\"Customer Service\"},{\"english\":\"Hospital bed\",\"spanish\":\"Cama de hospital\",\"definition\":\"A bed having side rails that can be raised or lowered and a mattress base in three jointed sections so that the head, foot, or middle may be raised by a crank or motor, allowing a patient to lie in various positions, as a therapeutic aid or for comfort.\",\"industry\":\"General\",\"example_en\":\"He was sitting upright in his hospital bed, propped up by pillows.\",\"example_es\":\"Estaba sentado erguido en su cama de hospital, apoyado sobre almohadas.\",\"source\":\"Customer Service\"},{\"english\":\"Housing Authority\",\"spanish\":\"Autoridad de vivienda\",\"definition\":\"Public entity that has the ability to use financial resources for critical community projects. Housing authority helps provide decent, safe and affordable housing to low-income families through its public housing, rental subsidy and voucher programs.\",\"industry\":\"Social Services\",\"example_en\":\"Housing authority determines whether housing conditions are unsafe, unsanitary, or substandard and investigate methods for improving such conditions.\",\"example_es\":\"La autoridad de vivienda determina si las condiciones de la vivienda son inseguras, insalubres o deficientes e investiga métodos para mejorar dichas condiciones.\",\"source\":\"Customer Service\"},{\"english\":\"HRA (Human Resources Administration)\",\"spanish\":\"Administración de recursos humanos\",\"definition\":\"The Human Resources Administration (HRA) is dedicated to fighting poverty and income inequality by providing New Yorkers in need with essential benefits such as Food Assistance and Emergency Rental Assistance.\",\"industry\":\"Social Services\",\"example_en\":\"The Human Resources Administration (HRA) is the nation's largest social services agency and assists over three million low‐income and vulnerable New Yorkers annually\",\"example_es\":\"La administración de recursos humanos es la agencia de servicios sociales más grande del país y ayuda anualmente a más de tres millones de neoyorquinos vulnerables y de bajos ingresos.\",\"source\":\"Customer Service\"},{\"english\":\"Hubcap\",\"spanish\":\"Tapa de la llanta /\\nTapa de la rueda del carro\",\"definition\":\"A metal or plastic cover for the hub of a motor vehicle's wheel.\",\"industry\":\"Auto Insurance\",\"example_en\":\"It's so strange, they didn't steal the tires, just the hubcaps.\",\"example_es\":\"Es tan extraño, no se robaron las llantas, solo las tapas de las llantas.\",\"source\":\"Customer Service\"},{\"english\":\"Hyperopia /\\nFarsightedness\",\"spanish\":\"Hipermetropía\",\"definition\":\"Farsightedness (also called hyperopia) is a refractive error. This is when the eye does not refract—or bend—light properly.\",\"industry\":\"Medical\",\"example_en\":\"Astigmatism can occur in addition to nearsightedness and farsightedness.\",\"example_es\":\"El astigmatismo puede ocurrir además de la miopía y la hipermetropía.\",\"source\":\"Customer Service\"},{\"english\":\"I.K.  Inmate\\nKitchen\",\"spanish\":\"Cocina para\\nreclusas(os) / presas(os)\",\"definition\":\"Kitchen facility area in which some inmates can work.\",\"industry\":\"Jail system\",\"example_en\":\"I got burned while helping in the IK while preparing breakfast.\",\"example_es\":\"Me quemé cuando ayudaba en la cocina para reclusos preparando el desayuno.\",\"source\":\"Customer Service\"},{\"english\":\"ICU (Intensive Care Unit)\",\"spanish\":\"Unidad de cuidados intensivos (UCI)\",\"definition\":\"A hospital unit in which is concentrated special equipment and specially trained personnel for the care of seriously ill patients requiring immediate and continuous attention (intensive care).\",\"industry\":\"Medical\",\"example_en\":\"Your father has been sent to the ICU as his renal failure is serious and he needs to be monitored closely.\",\"example_es\":\"Su padre fue enviado a la unidad de cuidados intensivos ya que su insuficiencia renal es seria y él requiere ser monitoreado muy de cerca.\",\"source\":\"Customer Service\"},{\"english\":\"IDEA (Individuals with Disabilities Education Act)\",\"spanish\":\"Ley para la Educación de las Personas Discapacitadas\",\"definition\":\"The Individuals with Disabilities Education Act (IDEA) is a law that makes available a free appropriate public education to eligible children with disabilities throughout the nation and ensures special education and related services to those children.\",\"industry\":\"School\",\"example_en\":\"They discussed the key points addressed by the IDEA that teachers should take into consideration when dealing with students with disabilities.\",\"example_es\":\"Ellos conversaron sobre los puntos clave abordados por la ley para la educación de las personas discapacitadas que los maestros deben tener en consideración al tratar con estudiantes con discapacidades.\",\"source\":\"Customer Service\"},{\"english\":\"Identification (ID)\",\"spanish\":\"identificación\",\"definition\":\"A means of proving a person's identity, especially in the form of official papers: such as a birth certificate or driver's license, that identifies one.\",\"industry\":\"General\",\"example_en\":\"The woman who was on passport control asked me if I had any other form of identification.\",\"example_es\":\"La mujer que estaba en control de pasaportes me preguntó si tenía otro tipo de identificación.\",\"source\":\"Customer Service\"},{\"english\":\"Illness\",\"spanish\":\"Enfermedad\",\"definition\":\"Illness is a period of sickness affecting a human or a health condition or disease that is affecting the body or mind.\",\"industry\":\"Medical\",\"example_en\":\"It takes time to adjust when you are told you have a chronic illness.\",\"example_es\":\"Lleva tiempo adaptarse cuando te dicen que tienes una enfermedad crónica.\",\"source\":\"Customer Service\"},{\"english\":\"Immunization record /\\nVaccination record\",\"spanish\":\"Cartilla de vacunación /\\nCuadro de vacunas / \\nBoleta de vacunación /\\nTarjeta de vacunación /\\nRegistro/historial de vacunas\",\"definition\":\"Immunization records provide a history of all the vaccines you or your child received. This record may be required for certain jobs, travel abroad, or school registration.\",\"industry\":\"Medical\",\"example_en\":\"Do I need to take my child's immunization record with me when I enroll him for school?\",\"example_es\":\"¿Necesito llevar el registro de vacunas de mi hijo cuando lo inscriba en la escuela?\",\"source\":\"Customer Service\"},{\"english\":\"Impairment\",\"spanish\":\"Deterioro / \\nDeficiencia /\\nDiscapacidad\",\"definition\":\"Deterioration in the functioning of a body part, organ, or system that can be temporary or permanent and can result from injury or disease\",\"industry\":\"Medical\",\"example_en\":\"He has a visual impairment in the right eye.\",\"example_es\":\"El tiene un deterioro visual en el ojo derecho.\",\"source\":\"Customer Service\"},{\"english\":\"Implications\",\"spanish\":\"Implicaciones / \\nConsecuencias\",\"definition\":\"An implication is something that is suggested, or happens, indirectly. When you left the gate open and the dog escaped, you were guilty by implication. Implication has many different senses. Usually, when used in the plural, implications are effects or consequences that may happen in the future.\",\"industry\":\"General\",\"example_en\":\"The company is cutting back its spending and I wonder what the implications will be for our department.\",\"example_es\":\"La empresa está recortando sus gastos y me pregunto cuáles serán las consecuencias para nuestro departamento.\",\"source\":\"Customer Service\"},{\"english\":\"Implied consent\",\"spanish\":\"Consentimiento implícito\",\"definition\":\"Implied consent is consent that is not given explicitly, but which can be inferred based on the individual's actions and the facts of a particular situation.\",\"industry\":\"General\",\"example_en\":\"There is implied consent in day-to-day treatment decisions that patients reach with their doctors.\",\"example_es\":\"Hay un consentimiento implícito en las decisiones de tratamiento diarias a las que llegan pacientes con sus doctores.\",\"source\":\"Customer Service\"},{\"english\":\"Impounded\",\"spanish\":\"Confiscado /\\nIncautado\",\"definition\":\"Seize and take legal custody of a vehicle (or something, especially goods, or documents) because of an infringement of a law or regulation.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Your vehicle has been impounded because you owe more than $3,000 in parking tickets.\",\"example_es\":\"Su vehículo ha sido confiscado porque usted debe más de $3,000 en multas de estacionamiento.\",\"source\":\"Customer Service\"},{\"english\":\"In-network\",\"spanish\":\"Dentro de la red de proveedores\",\"definition\":\"Refers to providers or health care facilities that are part of a health plan's network of providers with which it has negotiated a discount.\",\"industry\":\"Health Insurance\",\"example_en\":\"Please make sure that you see an in-network doctor.\",\"example_es\":\"Por favor asegúrese de ver un médico dentro de la red de proveedores.\",\"source\":\"Customer Service\"},{\"english\":\"Income\",\"spanish\":\"Ingresos\",\"definition\":\"Money received, especially on a regular basis, for labor or services, sales of goods, or profit from investments. The amount of monetary or other returns, either earned or unearned, accruing over a given period of time.\",\"industry\":\"General\",\"example_en\":\"What is your annual income?\",\"example_es\":\"¿Cuál es su ingreso anual?\",\"source\":\"Customer Service\"},{\"english\":\"Income tax\",\"spanish\":\"Impuesto sobre la renta\",\"definition\":\"Income tax is a tax you pay on your income, which is used to fund public services, pay government obligations, and provide goods for citizens.\",\"industry\":\"Finance\",\"example_en\":\"You pay income tax on all your earnings, not just your salary.\",\"example_es\":\"Usted paga el impuesto sobre la renta por todas sus ganancias, no solo por su salario.\",\"source\":\"Customer Service\"},{\"english\":\"Individualized Education Program (IEP)\",\"spanish\":\"Programa de educación individualizada\",\"definition\":\"This is a plan or program developed to ensure that a child with an identified disability who is attending an elementary or secondary educational institution receives specialized instruction and related services.\",\"industry\":\"School\",\"example_en\":\"School staff and parents meet to discuss, develop, and review the student's IEP. They make sure that the IEP meets their needs.\",\"example_es\":\"El personal de la escuela y los padres se reúnen para conversar, desarrollar y revisar el programa de educación individualizada del estudiante. Ellos se aseguran que el programa de educación individualizada cumpla con sus necesidades.\",\"source\":\"Customer Service\"},{\"english\":\"Individualized Family Services Plan (IFSP)\",\"spanish\":\"Plan de Servicio Familiar Individualizado\",\"definition\":\"This plan maps out early intervention services a child will receive (from birth to the child’s third birthday). The IFSP is written documentation of a child’s current functional levels, specific needs, goals of treatment, and the treatment plan\",\"industry\":\"Social Services\",\"example_en\":\"The IFSP should be the result of cooperative planning between you and the team of other people who are learning about your child.\",\"example_es\":\"El plan de servicio familiar individualizado debe ser el resultado de una planificación cooperativa entre usted y el equipo de otras personas que están aprendiendo sobre su hijo.\",\"source\":\"Customer Service\"},{\"english\":\"Infants\",\"spanish\":\"Lactantes (NO INFANTES)\",\"definition\":\"A child in the first period of life; being in an early stage of development.\",\"industry\":\"Social Services\",\"example_en\":\"Infants and children from 1 to 4 years of age are also eligible.\",\"example_es\":\"Los lactantes y los niños de 1 a 4 años de edad también son elegibles.\",\"source\":\"Customer Service\"},{\"english\":\"Infection\",\"spanish\":\"Infección\",\"definition\":\"The invasion of bodily tissue by pathogenic microorganisms that proliferate, resulting in tissue injury that can progress to disease.\",\"industry\":\"Medical\",\"example_en\":\"Infection is the major cause of death in children under the age of 5 years in this population.\",\"example_es\":\"La infección es la principal causa de muerte en niños menores de 5 años en esta población.\",\"source\":\"Customer Service\"},{\"english\":\"Initial enrollment period\",\"spanish\":\"Periodo de inscripción inicial\",\"definition\":\"Initial Enrollment Period determines if people over 65 are eligible for Medicare benefits.\",\"industry\":\"Health Insurance\",\"example_en\":\"The Medicare Initial Enrollment Period is the first opportunity people over 65 have to enroll in Original Medicare Part A (hospital insurance) and Part B (medical insurance).\",\"example_es\":\"El Período de inscripción inicial (IEP) de Medicare es la primera oportunidad que tienen las personas mayores de 65 años para inscribirse en la Parte A (seguro hospitalario) y la Parte B (seguro médico) de Medicare Original.\",\"source\":\"Customer Service\"},{\"english\":\"Injured\",\"spanish\":\"Lesionado /\\nHerido\",\"definition\":\"Harmed, damaged, or impaired physically.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Were you injured in this accident?\",\"example_es\":\"¿Se lastimó/se lesionó en este accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Injuries\",\"spanish\":\"Lesiones /\\nLastimaduras /\\nHeridas\",\"definition\":\"Harm or damage. An act or event that causes someone or something to no longer be fully healthy or in good condition. Physical damage or harm done to or suffered by a person.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Did anyone involved in the accident suffer any injuries?\",\"example_es\":\"¿Alguien implicado en el accidente sufrió lesiones/heridas?\",\"source\":\"Customer Service\"},{\"english\":\"Inpatient\",\"spanish\":\"Paciente hospitalizada(o) /\\nPaciente internada(o)\",\"definition\":\"A patient who stays in a hospital while under\\ntreatment.\",\"industry\":\"Medical\",\"example_en\":\"This will be covered as an inpatient procedure.\",\"example_es\":\"Esto será cubierto como un procedimiento de paciente hospitalizado.\",\"source\":\"Customer Service\"},{\"english\":\"Inspect (verb)\",\"spanish\":\"Inspeccionar\",\"definition\":\"To look at something closely, typically to assess their condition.\",\"industry\":\"Insurance (general)\",\"example_en\":\"The appraiser will come out to inspect the damages to the vehicle.\",\"example_es\":\"El tasador va a ir a inspeccionar los daños del vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Installments\",\"spanish\":\"Pagos /\\nAbonos/ \\nCuotas\",\"definition\":\"Payments, as in a series of payments. A sum of money due as one of several equal payments for something, spread over an agreed period of time, commonly due on a specific date.\",\"industry\":\"Finance\",\"example_en\":\"Can I make monthly installments towards my deposit?\",\"example_es\":\"¿Puedo hacer pagos mensuales hacia mi depósito?\",\"source\":\"Customer Service\"},{\"english\":\"Insufficient funds, non-\\nsufficient funds\",\"spanish\":\"Fondos insuficientes\",\"definition\":\"Insufficient funds occur when someone tries to purchase an item using a check or debit card without having enough money in his or her bank account. A situation in which one does not have enough deposited in a bank account to cover all checks and/or electronic withdrawals.\",\"industry\":\"Finance\",\"example_en\":\"Yes sir, check number 132 was returned due to insufficient funds.\",\"example_es\":\"Sí señor, el cheque número 132 rebotó por fondos insuficientes.\",\"source\":\"Customer Service\"},{\"english\":\"Insurance\",\"spanish\":\"Seguro\",\"definition\":\"An agreement in which a person makes regular payments to a company and the company promises to pay money if the person is injured or dies, or to pay money equal to the value of something (such as a house or car) if it is damaged, lost, or stolen. Coverage by contract in which one party agrees to cover another for loss that occurs under the terms of the contract.\",\"industry\":\"Insurance (general)\",\"example_en\":\"It’s a good thing I have flood insurance, because we are close to the lake and the rain lasted all night.\",\"example_es\":\"Es bueno que tengo seguro contra inundación porque estamos cerca del lago y la lluvia duró toda la noche.\",\"source\":\"Customer Service\"},{\"english\":\"Insurance broker\",\"spanish\":\"Corredor(a) de seguros\",\"definition\":\"A qualified sales person, who searches for insurance coverage at the lowest cost and providing the highest benefit to the buyer.\",\"industry\":\"Insurance (general)\",\"example_en\":\"We paid an insurance broker to look for insurance on our behalf.\",\"example_es\":\"Le pagamos a una corredora de seguros para buscar un seguro por nosotros.\",\"source\":\"Customer Service\"},{\"english\":\"Insurance carrier /\\nInsurer\",\"spanish\":\"Compañía de seguros /\\nAseguradora\",\"definition\":\"An insurance carrier is a company that creates and manages insurance policies and is typically the financial resource behind them.\",\"industry\":\"Insurance (general)\",\"example_en\":\"The insurance policy is a legal contract between the insurance carrier and the insured party.\",\"example_es\":\"La póliza de seguro es un contrato legal entre la compañía de seguros y el asegurado.\",\"source\":\"Customer Service\"},{\"english\":\"Insured\",\"spanish\":\"Asegurada(o)\",\"definition\":\"A person whose life or property is insured. One who has or is covered by an insurance policy.\",\"industry\":\"Insurance (general)\",\"example_en\":\"We determined our insured is not at fault for the accident.\",\"example_es\":\"Determinamos que nuestro asegurado no es culpable del accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Interest\",\"spanish\":\"Intereses\",\"definition\":\"Interest is the monetary charge for borrowing money—generally expressed as a percentage, such as an annual percentage rate (APR).\",\"industry\":\"Finance\",\"example_en\":\"A lot of our income comes from the interest of the money we lend.\",\"example_es\":\"Gran parte de nuestros ingresos viene de los intereses del dinero que prestamos.\",\"source\":\"Customer Service\"},{\"english\":\"Interest rate\",\"spanish\":\"Tasa de interés\",\"definition\":\"The proportion of a loan that is charged as interest to the borrower, typically expressed as an annual percentage of the loan outstanding.\",\"industry\":\"Finance\",\"example_en\":\"The advantage of consolidating your debts is that at the end you would only have one monthly payment and one interest rate.\",\"example_es\":\"La ventaja de consolidar sus deudas es que al final usted solo tendrá un pago mensual y solo una tasa de interés.\",\"source\":\"Customer Service\"},{\"english\":\"Intersection\",\"spanish\":\"Intersección\",\"definition\":\"An intersection is a junction or an area of the roadway where two or more roads cross or meet.  An intersection can be four-way (or crossroads), three way (T-junction or Y-junction, sometimes refer to as a fork), or five or more ways. An intersection can also be any place where a public entrance or exit joins a road. A private driveway is not an intersection.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The golden rule when you're coming up to an intersection is 'be prepared to stop'.\",\"example_es\":\"La regla de oro cuando se acerca a una intersección es \\\"prepárese para detenerse\\\".\",\"source\":\"Customer Service\"},{\"english\":\"Interview\",\"spanish\":\"Entrevista\",\"definition\":\"A meeting at which information is obtained from a person.\",\"industry\":\"General\",\"example_en\":\"Thank you for agreeing to this interview to determine your eligibility for coverage.\",\"example_es\":\"Gracias por estar de acuerdo en hacer esta entrevista para determinar su elegibilidad para la cobertura.\",\"source\":\"Customer Service\"},{\"english\":\"Intrauterine Device (IUD)\",\"spanish\":\"Dispositivo Intrauterino (DIU)\",\"definition\":\"A contraceptive device fitted inside the uterus and physically preventing the implantation of fertilized ova.\",\"industry\":\"Medical\",\"example_en\":\"I want an appointment with my OB/GYN so he can tell me which IUD I can use.\",\"example_es\":\"Quiero una cita con mi obstetra/ginecólogo para que me pueda decir cuál dispositivo intrauterino puedo usar.\",\"source\":\"Customer Service\"},{\"english\":\"Invalid\",\"spanish\":\"Inválido\",\"definition\":\"Not legally or factually valid, not in force, null, void.\",\"industry\":\"General\",\"example_en\":\"We cannot accept liability if you are refused entry because of invalid documents.\",\"example_es\":\"No podemos aceptar responsabilidad si le niegan la entrada por presentar documentos inválidos.\",\"source\":\"Customer Service\"},{\"english\":\"IRA (Individual retirement account)\",\"spanish\":\"Cuenta individual de jubilación\",\"definition\":\"Retirement savings account with tax advantages that individuals can open to save and invest in the long term.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"Payout from an individual retirement account may not begin until a certain age.\",\"example_es\":\"Es posible que el pago de una cuenta individual de jubilación no comience hasta una cierta edad.\",\"source\":\"Customer Service\"},{\"english\":\"IRS (Internal Revenue Service)\",\"spanish\":\"Servicio de impuestos internos\",\"definition\":\"The Internal Revenue Service (IRS) is a government agency that administers tax laws and collects federal taxes from U.S. individual and corporate taxpayers.\",\"industry\":\"General\",\"example_en\":\"The Internal Revenue Service (IRS) provides United States taxpayers with help to understand and fulfill their tax responsibilities under the tax law.\",\"example_es\":\"El Servicio de Impuestos Internos provee a los contribuyentes tributarios de Estados Unidos ayuda para entender y cumplir con sus responsabilidades tributarias según la ley de impuestos.\",\"source\":\"Customer Service\"},{\"english\":\"Issue (verb)\",\"spanish\":\"Emitir /\\nExpedir /\\nExtender\",\"definition\":\"The act of issuing a or giving something like a document, or payment such as a check.\",\"industry\":\"General\",\"example_en\":\"They will issue a check or make a payment directly into your bank account.\",\"example_es\":\"Emitirán un cheque o realizarán un pago directamente a su cuenta bancaria.\",\"source\":\"Customer Service\"},{\"english\":\"Itching\",\"spanish\":\"Picazón /\\nPicor /\\nComezón\",\"definition\":\"Skin tingling or irritation that makes you want to scratch the affected area.\",\"industry\":\"Medical\",\"example_en\":\"Is the rash on your arm itching or burning? If so, you will need to make an appointment with a dermatologist.\",\"example_es\":\"¿El sarpullido en su brazo le da picazón o ardor? Y si es así, deberá hacer una cita con el dermatólogo.\",\"source\":\"Customer Service\"},{\"english\":\"ITIN (Individual Taxpayer Identification Number)\",\"spanish\":\"Número de identificación personal del contribuyente\",\"definition\":\"The Individual Taxpayer Identification number (ITIN) is a tax processing number issued by the Internal Revenue Service. The IRS issues ITINs to people who are required to have a United States taxpayer identification number, but who do not have or meet the requirements to obtain a Social Security number (SSN) from the Social Security Administration (SSA).\",\"industry\":\"General\",\"example_en\":\"If you don't have a Social Security number, you could make your tax return with the Individual Taxpayer Identification Number (ITIN).\",\"example_es\":\"Si usted no tiene un número de seguro social, usted podría hacer su declaración de impuestos con el número de identificación personal del contribuyente.\",\"source\":\"Customer Service\"},{\"english\":\"Jewelry\",\"spanish\":\"Joyas /\\nJoyería\",\"definition\":\"Personal ornaments, such as necklaces, rings, or bracelets, that are typically made from or contain jewels and precious metal.\",\"industry\":\"General\",\"example_en\":\"Do you have any jewelry or valuable personal belongings?\",\"example_es\":\"¿Tiene alguna joya o pertenencias de valor?\",\"source\":\"Customer Service\"},{\"english\":\"Kick-in\",\"spanish\":\"Entrar en vigencia / \\nEntrar en vigor /\",\"definition\":\"Depending on the insurance company, policies could kick-in either immediately upon you signing or after short time in the future, generally up to two weeks.\",\"industry\":\"Insurance (general)\",\"example_en\":\"I signed my insurance policy yesterday morning, how long do I have to wait for it to kick in?\",\"example_es\":\"Firmé mi póliza de seguro ayer por la mañana, ¿cuánto tiempo tengo que esperar para que entre en vigencia?\",\"source\":\"Customer Service\"},{\"english\":\"Kidney\",\"spanish\":\"Riñón\",\"definition\":\"The kidneys are a pair of organs that are found on either side of the spine, just below the rib cage in the back. The kidneys remove waste and extra water from the blood (as urine).\",\"industry\":\"Medical\",\"example_en\":\"After a couple of tests, his kidney doctor found out he had kidney failure.\",\"example_es\":\"Después de un par de pruebas, su doctor de los riñones descubrió que tenía insuficiencia renal.\",\"source\":\"Customer Service\"},{\"english\":\"Laboratory\",\"spanish\":\"Laboratorio\",\"definition\":\"A room or building with special equipment for\\ndoing scientific experiments and tests.\",\"industry\":\"Medical\",\"example_en\":\"Results are usually available between 10 days to 14 days, depending on the laboratory.\",\"example_es\":\"Según el laboratorio, los resultados suelen estar listos entre 10 y 14 días.\",\"source\":\"Customer Service\"},{\"english\":\"Lancets\",\"spanish\":\"Lancetas\",\"definition\":\"A lancet is a small, sharp needle used to prick the skin and draw blood. It is an essential part of the diabetes management process.\",\"industry\":\"General\",\"example_en\":\"Finger pricks are usually done using a device called a lancet.\",\"example_es\":\"Las punciones en el dedo generalmente se hacen usando un dispositivo llamado lanceta.\",\"source\":\"Customer Service\"},{\"english\":\"Land\",\"spanish\":\"Terreno\",\"definition\":\"Land is a generally flat portion of space, of earth, in which you have nothing built, it is only an area in which there is no building or something that covers its surface.\",\"industry\":\"General\",\"example_en\":\"She proceeded to purchase land from the surrounding owners.\",\"example_es\":\"Ella procedió a comprar terrenos a los propietarios de los alrededores.\",\"source\":\"Customer Service\"},{\"english\":\"Landlady /\\nLandlord\",\"spanish\":\"Arrendadora (o) /\\nPropietaria(o) /\\nDueña(o) de vivienda\",\"definition\":\"An individual that owns and rents land, buildings, or dwelling units.\",\"industry\":\"General\",\"example_en\":\"Please call your landlord to report any problems with interior plumbing or electricity.\",\"example_es\":\"Por favor llame al propietario para reportar cualquier problema con la plomería interior o la electricidad.\",\"source\":\"Customer Service\"},{\"english\":\"Landmark\",\"spanish\":\"Punto de referencia / \\nHito (Context dependent)\",\"definition\":\"A usually large object on land that is easy to see and can help a person find the way to a place near it.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The Golden Gate Bridge is a famous landmark in San Francisco.\",\"example_es\":\"El Puente Golden Gate es un punto de referencia famoso en San Francisco.\",\"source\":\"Customer Service\"},{\"english\":\"Landscaping\",\"spanish\":\"Paisajismo\",\"definition\":\"The process of making a yard or other piece of land more attractive by altering the existing design, adding ornamental features, and planting trees and shrubs.\",\"industry\":\"General\",\"example_en\":\"Landscaping refers to any activity that modifies the visible features of an area of land.\",\"example_es\":\"El paisajismo se refiere a cualquier actividad que modifique las características visibles de un área de terreno.\",\"source\":\"Customer Service\"},{\"english\":\"Landslide /\\nLandslip\",\"spanish\":\"Derrumbe\",\"definition\":\"When the ground around your property slides downwards. Often caused by too much rain causing soil or rock slip.\",\"industry\":\"Home Insurance\",\"example_en\":\"His house was damaged due to a landslide after a heavy storm.\",\"example_es\":\"Su casa resultó dañada por un derrumbe tras una fuerte tormenta.\",\"source\":\"Customer Service\"},{\"english\":\"Lane\",\"spanish\":\"Carril\",\"definition\":\"A division of a road marked off with painted lines and intended to separate single lines of traffic according to speed or direction.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Which lane were you in?\",\"example_es\":\"¿En cuál carril estaba/iba usted?\",\"source\":\"Customer Service\"},{\"english\":\"Lapse\",\"spanish\":\"Caducidad /\\nCaducar\",\"definition\":\"The termination of an insurance policy because a renewal premium is not paid by the end of the grace period.\",\"industry\":\"Insurance (general)\",\"example_en\":\"She didn't pay the premium and her insurance policy lapsed.\",\"example_es\":\"Ella no pagó la prima y su póliza de seguro caducó.\",\"source\":\"Customer Service\"},{\"english\":\"Late fee\",\"spanish\":\"Cargo por demora /\\nCargo por pago atrasado\",\"definition\":\"An extra charge assessed if a payment is made after the due date.\",\"industry\":\"Finance\",\"example_en\":\"In order to avoid late fees, you may want to authorize an automatic withdrawal. We would draft the money from your bank account on the day you authorize us to do so.\",\"example_es\":\"Para evitar cargos por demora, tal vez quiera autorizar un retiro automático. Nosotros debitaríamos el dinero de su cuenta bancaria el día que usted nos autorice para hacerlo.\",\"source\":\"Customer Service\"},{\"english\":\"Laxative\",\"spanish\":\"Laxante\",\"definition\":\"A drug or medicine tending to stimulate or facilitate evacuation of the bowels.\",\"industry\":\"Medical\",\"example_en\":\"Laxatives can be used for occasional relief of constipation.\",\"example_es\":\"Los laxantes se pueden usar para el alivio ocasional del estreñimiento.\",\"source\":\"Customer Service\"},{\"english\":\"Lay-off\",\"spanish\":\"Cese laboral (noun) /\\nCesar (verb)\",\"definition\":\"The act of suspending or dismissing an employee, as for lack of work or because of corporate reorganization.\",\"industry\":\"Social Services\",\"example_en\":\"I was recently laid off from my job and need to know how soon I can apply for unemployment benefits.\",\"example_es\":\"Fui cesado de mi trabajo recientemente y necesito saber qué tan pronto puedo solicitar beneficios de desempleo.\",\"source\":\"Customer Service\"},{\"english\":\"Layover\",\"spanish\":\"Escala\",\"definition\":\"A stop during a trip, for refueling, changing planes, or picking up/dropping off passengers.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"Your flight departs at 8:00 am Pacific time and you have a layover in New York City before changing planes, arriving in Rome the next day.\",\"example_es\":\"Su vuelo despega a las 8:00 am horario del pacífico y tiene una escala en la ciudad de Nueva York antes de cambiar aviones, llegando a Roma al día siguiente.\",\"source\":\"Customer Service\"},{\"english\":\"Lease agreement\",\"spanish\":\"Contrato de arrendamiento\",\"definition\":\"A contract conferring possession of land, and any profits of the land, for life or a certain period as long as the terms of the contract continue to be met.\",\"industry\":\"General\",\"example_en\":\"I signed the lease agreement of my new office today.\",\"example_es\":\"Hoy firmé el contrato de arrendamiento de mi nueva oficina.\",\"source\":\"Customer Service\"},{\"english\":\"Least restrictive environment (LRE)\",\"spanish\":\"Entorno Académico de Restricción Mínima /\\nAmbiente menos restrictivo\",\"definition\":\"LRE means that a child with a disability must be educated within the same classroom as typical mainstreamed non-disabled peers to the fullest extent possible in order to ensure that a disabled child is receiving a free appropriate public education (FAPE).\",\"industry\":\"School\",\"example_en\":\"LRE isn't a place, it is a principle that guides a child's education program.\",\"example_es\":\"El entorno académico de restricción mínima no es un lugar, es un principio que guía el programa educativo de un niño.\",\"source\":\"Customer Service\"},{\"english\":\"Legal guardian\",\"spanish\":\"Tutor(a) legal\",\"definition\":\"A legal guardian is a person who has the legal authority (and the corresponding duty) to care for the personal and property interests of another person, called a ward.\",\"industry\":\"Social Services\",\"example_en\":\"Should a student withdraw from the school, the student's parents or legal guardian undertake to give a notice of termination.\",\"example_es\":\"Si un estudiante se retira de la escuela, sus padres o tutor legal se comprometen a entregar un aviso de rescisión.\",\"source\":\"Customer Service\"},{\"english\":\"Legal resident\",\"spanish\":\"Residente legal\",\"definition\":\"The immigration status of a person authorized to live and work in the United States of America permanently.\",\"industry\":\"Social Services\",\"example_en\":\"He traveled to the United States to visit his son, who was already a legal resident.\",\"example_es\":\"Viajó a los Estados Unidos para visitar a su hijo, quien ya era residente legal.\",\"source\":\"Customer Service\"},{\"english\":\"Lend\",\"spanish\":\"Prestar\",\"definition\":\"To give for temporary use on condition that the same or its equivalent will be returned.\",\"industry\":\"General\",\"example_en\":\"I can lend you a pen so you can fill out the application.\",\"example_es\":\"Le puedo prestar un bolígrafo para que pueda llenar la solicitud.\",\"source\":\"Customer Service\"},{\"english\":\"Lender /\\nCreditor\",\"spanish\":\"Prestamista /\\nAcreedor\",\"definition\":\"A lender is an individual, a group, or a financial institution that lends funds with the expectation that the funds will be repaid.\",\"industry\":\"Finance\",\"example_en\":\"The lender is now preparing themself for a potential sale.\",\"example_es\":\"El prestamista se está preparando ahora para una posible venta.\",\"source\":\"Customer Service\"},{\"english\":\"Letter of separation /\\nTermination letter\",\"spanish\":\"Carta de desvinculación /\\nCarta de despido\",\"definition\":\"A letter of termination is a formal notice to inform an employee they will be dismissed from their current employment.\",\"industry\":\"General\",\"example_en\":\"Due to the violations of the terms in your contract, you will receive your termination letter by the end of the day.\",\"example_es\":\"Debido a la violación de los términos de su contrato, usted recibirá su carta de desvinculación al finalizar el día.\",\"source\":\"Customer Service\"},{\"english\":\"Liability insurance\",\"spanish\":\"Seguro de responsabilidad civil\",\"definition\":\"Liability insurance only pays for bodily injuries or property damage suffered by others when you are at fault in an accident.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Since the accident was your fault, the other driver will be covered under the liability insurance portion of your policy.\",\"example_es\":\"Ya que el accidente fue su culpa, el otro conductor estará cubierto bajo la porción de seguro de responsabilidad civil de su póliza.\",\"source\":\"Customer Service\"},{\"english\":\"License Plate\",\"spanish\":\"Placa /\\nMatrícula (NO Patente)\",\"definition\":\"A metal plate affixed to a vehicle that shows a series of numbers and letters that are used to identify the vehicle, indicating that it has been registered with the state.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Was that a license plate from the State of Virginia?\",\"example_es\":\"¿Era una placa del estado de Virginia?\",\"source\":\"Customer Service\"},{\"english\":\"License plate number\",\"spanish\":\"Número de Placa (de un automóvil) /\\nNúmero de matrícula\",\"definition\":\"A metal plate that bears a sequence of numbers, letters, or both and is issued by a government to identify an officially registered vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I gave the officer the license plate number of the other car that was involved in the accident. I hope they can find the guy who ran the red light.\",\"example_es\":\"Le di al oficial el número de placa del carro que estuvo involucrado en el accidente. Espero que encuentren al tipo que se pasó la luz roja.\",\"source\":\"Customer Service\"},{\"english\":\"Lien\",\"spanish\":\"Derecho de retención\",\"definition\":\"A lien is the legal right of a creditor to sell the collateral property of a debtor who fails to meet the obligations of a loan contract.\",\"industry\":\"Finance\",\"example_en\":\"The lien of the property persists until the debt is paid.\",\"example_es\":\"El derecho de retención de la propiedad persiste hasta que se pague la deuda.\",\"source\":\"Customer Service\"},{\"english\":\"Life event\",\"spanish\":\"Suceso vital /\\nAcontecimiento vital\",\"definition\":\"A very important event in someone's life, such as marriage, the birth of a child, or the death of a family member.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Moving house can be a very stressful life event.\",\"example_es\":\"Mudarse de casa puede ser un suceso vital muy estresante.\",\"source\":\"Customer Service\"},{\"english\":\"Lifeguard\",\"spanish\":\"Salvavidas\",\"definition\":\"A lifeguard is a person who works at a beach or swimming pool and rescues people when they are in danger of drowning.\",\"industry\":\"General\",\"example_en\":\"During the summer she worked as a lifeguard.\",\"example_es\":\"Ella trabajó como salvavidas durante el verano.\",\"source\":\"Customer Service\"},{\"english\":\"Light duty\",\"spanish\":\"Trabajo ligero /\\nTrabajo liviano\",\"definition\":\"Light duty is the term that is used for work that a treating doctor says will fall within the physical restrictions of an injured worker while that worker continues to heal from a work-related injury or illness.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"I didn't return to work until two months after the accident, only taking on light duties in the beginning.\",\"example_es\":\"No regresé a trabajar hasta dos meses después del accidente, solo realicé trabajos ligeros al principio.\",\"source\":\"Customer Service\"},{\"english\":\"Lightheaded\",\"spanish\":\"Sentir como que se va a desmayar /\\nAturdido\",\"definition\":\"Lightheadedness is when you feel like fainting or about to pass out. Some people call it feeling woozy. Lightheadedness is related to dizziness. Dizziness is when you feel unsteady or are having trouble keeping your balance.\",\"industry\":\"Medical\",\"example_en\":\"Standing up too quickly usually makes her lightheaded.\",\"example_es\":\"Levantarse demasiado rápido generalmente hace que sienta como que se va a desmayar.\",\"source\":\"Customer Service\"},{\"english\":\"Limb\",\"spanish\":\"Extremidad\",\"definition\":\"An arm or leg of a person or four-legged animal, or a bird's wing.\",\"industry\":\"Medical\",\"example_en\":\"Keep your limb elevated to reduce swelling.\",\"example_es\":\"Mantenga la extremidad elevada para reducir la hinchazón.\",\"source\":\"Customer Service\"},{\"english\":\"Listlessness\",\"spanish\":\"Falta de energía\",\"definition\":\"Refers to an individual characterized by lack of interest, energy, or spirit. Inactivity resulting from lethargy or lack of vigor.\",\"industry\":\"Medical\",\"example_en\":\"I'm very concerned about my daughter, she's had listlessness for 2 days.\",\"example_es\":\"Estoy muy preocupada por mi hija, ha estado con falta de energía por 2 días.\",\"source\":\"Customer Service\"},{\"english\":\"Livestock\",\"spanish\":\"Ganado\",\"definition\":\"Animals kept on a farm or traded as a source of income, such as cows, sheep, chickens, and pigs.\",\"industry\":\"General\",\"example_en\":\"They can no longer afford to keep livestock on their farms.\",\"example_es\":\"Ellos ya no pueden permitirse mantener el ganado en sus granjas.\",\"source\":\"Customer Service\"},{\"english\":\"Loan\",\"spanish\":\"Préstamo\",\"definition\":\"Something lent or furnished on condition of being returned, especially a sum of money lent at interest for a period of time.\",\"industry\":\"Finance\",\"example_en\":\"You have a 30-year loan.\",\"example_es\":\"Usted tiene un préstamo de 30 años.\",\"source\":\"Customer Service\"},{\"english\":\"Loan modification\",\"spanish\":\"Modificación de préstamo\",\"definition\":\"A loan modification is a change to the original terms of your mortgage loan. It may involve a reduction in the interest rate, an extension of the length of time for repayment, a different type of loan, or any combination of the three.\",\"industry\":\"Finance\",\"example_en\":\"Unfortunately, due to your credit score, you do not qualify for a loan modification at this time.\",\"example_es\":\"Desafortunadamente, debido a su puntaje crediticio, no califica para una modificación de préstamo en este momento.\",\"source\":\"Customer Service\"},{\"english\":\"Lobby\",\"spanish\":\"Vestíbulo /\\nRecibidor\",\"definition\":\"A hall, foyer, or waiting room at or near the entrance  to a building, such as a hotel or theater.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"When you arrive at the hotel, please go to the lobby to check in.\",\"example_es\":\"Cuando llegue al hotel, por favor vaya al vestíbulo para registrarse.\",\"source\":\"Customer Service\"},{\"english\":\"Log in\",\"spanish\":\"Ingresar\",\"definition\":\"The process of identifying oneself to a computer, usually by entering one's username and password.\",\"industry\":\"Customer Service\",\"example_en\":\"You need a password to log in.\",\"example_es\":\"Necesita una contraseña para ingresar.\",\"source\":\"Customer Service\"},{\"english\":\"Long term\",\"spanish\":\"Largo plazo\",\"definition\":\"Lasting, staying, or extending over a long time.\",\"industry\":\"General\",\"example_en\":\"These changes may improve profits now, but they are going to cost us money in the long term.\",\"example_es\":\"Estos cambios pueden mejorar las ganancias ahora, pero nos costarán dinero a largo plazo.\",\"source\":\"Customer Service\"},{\"english\":\"Loss of appetite\",\"spanish\":\"Pérdida del apetito /\\nFalta de apetito\",\"definition\":\"A reduced or lack of desire to eat.\",\"industry\":\"Medical\",\"example_en\":\"One of the side effects is loss of appetite.\",\"example_es\":\"Uno de los efectos secundarios es la pérdida de apetito.\",\"source\":\"Customer Service\"},{\"english\":\"Lost wages\",\"spanish\":\"Salario perdido /\\nSalario no devengado\",\"definition\":\"Wages or employment compensation that was lost and unable to be earned as a result of an injury caused by the acts of another person or party.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"The property was received as compensation for personal injuries, except for any payment made for lost wages.\",\"example_es\":\"La propiedad fue recibida como compensación por lesiones personales, a excepción de cualquier pago realizado por salario perdido.\",\"source\":\"Customer Service\"},{\"english\":\"Lozenge /\\nCough drop\",\"spanish\":\"Caramelo para la tos /\\nPastilla para la tos /\\nTrocisco\",\"definition\":\"A small, typically medicated tablet intended to be dissolved slowly in the mouth to temporarily stop coughs, lubricate, and soothe irritated tissues of the throat\",\"industry\":\"Medical\",\"example_en\":\"The doctor recommended a Lozenge for my throat irritation and cough.\",\"example_es\":\"El doctor recomendó un caramelo para la tos, para mi irritación en la garganta y tos.\",\"source\":\"Customer Service\"},{\"english\":\"Lump sum\",\"spanish\":\"Suma global /\\nSuma total\",\"definition\":\"A lump sum amount is defined as a single complete sum of money.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"Pharmacists who fabricate drugs are paid a lump sum.\",\"example_es\":\"Se les paga una suma global a las farmacéuticas que fabrican medicamentos.\",\"source\":\"Customer Service\"},{\"english\":\"Mail /\\nCorrespondence\",\"spanish\":\"Correspondencia\",\"definition\":\"Communication by the exchange of letters, emails, or other forms of written messages.\",\"industry\":\"General\",\"example_en\":\"My friend and I have been exchanging correspondence for over twenty years.\",\"example_es\":\"Mi amiga y yo hemos estado intercambiando correspondencia por más de 20 años.\",\"source\":\"Customer Service\"},{\"english\":\"Mailing address\",\"spanish\":\"Dirección de correspondencia /\\nDirección postal\",\"definition\":\"The address at which a person or business receives letters or packages, which can be different from the place where they work or live.\",\"industry\":\"General\",\"example_en\":\"I need to know your mailing address if it is different from the physical address of the property.\",\"example_es\":\"Necesito saber su dirección postal si es que es diferente a la dirección física de la propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Make (context dependent)\",\"spanish\":\"Marca\",\"definition\":\"It refers to the manufacturer or company that makes a product such as an appliance, car, or machine.\",\"industry\":\"Customer Service\",\"example_en\":\"What is your car's make and model?\",\"example_es\":\"¿Cuál es la marca y modelo de su carro?\",\"source\":\"Customer Service\"},{\"english\":\"Manager\",\"spanish\":\"Gerente\",\"definition\":\"One who administers, controls or directs a business or other enterprise.\",\"industry\":\"General\",\"example_en\":\"She was promoted to manager in less than a year.\",\"example_es\":\"La ascendieron a gerente en menos de un año.\",\"source\":\"Customer Service\"},{\"english\":\"Manufacturer's defect\",\"spanish\":\"Defecto de fabricante\",\"definition\":\"A deviation from design specifications during production resulting in a product’s defect, frailty or shortcoming.\",\"industry\":\"Customer Service\",\"example_en\":\"The equipment came with a warranty against manufacturer's defects.\",\"example_es\":\"El equipo vino con una garantía por defecto de fabricante.\",\"source\":\"Customer Service\"},{\"english\":\"Marital Status\",\"spanish\":\"Estado Civil\",\"definition\":\"A person's state of being single, married, separated, divorced, or widowed.\",\"industry\":\"General\",\"example_en\":\"What is your marital status, are you single, married, divorced, separated or widowed?\",\"example_es\":\"¿Cuál es su estado civil, es usted soltero, casado, divorciado, separado o viudo?\",\"source\":\"Customer Service\"},{\"english\":\"Market price /\\nMarket value\",\"spanish\":\"Precio/valor del mercado\",\"definition\":\"The price at which a product or service is selling in the open market/the value of a business, property, etc., in terms of what can be sold for on the open market. The amount for which something can be sold on a given market. Often contrasted with book value.\",\"industry\":\"Insurance (general)\",\"example_en\":\"If the car is a total loss, what is the market price you are estimating then?\",\"example_es\":\"Si el carro es pérdida total, ¿cuál es el precio de mercado que está calculando?\",\"source\":\"Customer Service\"},{\"english\":\"Measles\",\"spanish\":\"Sarampión\",\"definition\":\"Measles is an infectious disease caused by a virus. It spreads easily from person to person. It causes a blotchy red rash. Sometimes measles can lead to serious problems. There is no treatment for measles, but the MMR vaccine can prevent it. \\\"German measles\\\", also known as rubella, is a completely different illness.\",\"industry\":\"Medical\",\"example_en\":\"Measles starts with fever, runny nose, cough, red eyes, and sore throat. It's followed by a rash that spreads over the body.\",\"example_es\":\"El sarampión empieza con fiebre, secreción nasal, tos, ojos rojos y dolor de garganta. Seguido por una erupción que se esparce por todo el cuerpo.\",\"source\":\"Customer Service\"},{\"english\":\"Mechanic\",\"spanish\":\"Mecánica(o)\",\"definition\":\"Someone whose occupation is repairing and maintaining automobiles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"If you smell gas, take the car to your mechanic.\",\"example_es\":\"Si huele a gas, lleve el auto a su mecánico.\",\"source\":\"Customer Service\"},{\"english\":\"Median (strip)\",\"spanish\":\"Franja central\",\"definition\":\"The strip of land between the lanes of opposing traffic on a divided highway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The median was under construction.\",\"example_es\":\"La franja central estaba bajo construcción.\",\"source\":\"Customer Service\"},{\"english\":\"Medicaid\",\"spanish\":\"Medicaid (proper name)\",\"definition\":\"Medicaid in the United States is a federal and state program that helps with healthcare costs for some people with limited income and resources. Medicaid also offers benefits including nursing home care and personal care services.\",\"industry\":\"Social Services\",\"example_en\":\"Medicaid is financed jointly by the federal government and the states.\",\"example_es\":\"Medicaid es financiado en conjunto por el gobierno federal y los estados.\",\"source\":\"Customer Service\"},{\"english\":\"Medical history\",\"spanish\":\"Historial médico /\\nHistorial clínico /\\nAntecedentes médicos\",\"definition\":\"It's a set of information the physicians collect over medical interviews, like past surgical history, family medical history, social history, allergies, and medications the patient is taking or may have recently stopped taking. It involves the patient, and eventually people close to him, so to collect reliable/objective information for managing the medical diagnosis and proposing efficient medical treatments.\",\"industry\":\"Medical\",\"example_en\":\"Do you have any medical history? Like, high blood pressure, diabetes or heart disease?\",\"example_es\":\"¿Tiene usted algún historial médico? ¿Como presión arterial alta, diabetes o enfermedades cardíacas?\",\"source\":\"Customer Service\"},{\"english\":\"Medical Record Number\",\"spanish\":\"Número de expediente médico /\\nNúmero de registro médico\",\"definition\":\"A number that identifies a patient at a medical facility.  The number identifies the chronological written  account of a patient's medical examination and  treatment history, physician's physical findings,  medications and therapeutic procedures etc.\",\"industry\":\"Health Insurance\",\"example_en\":\"Can you please give me your medical record number to look for providers in your area?\",\"example_es\":\"¿Por favor, me puede dar su número de expediente médico para buscar proveedores en su área?\",\"source\":\"Customer Service\"},{\"english\":\"Medicare\",\"spanish\":\"Medicare (proper name)\",\"definition\":\"Medicare is a national program that subsidizes healthcare services for anyone age 65 or older, younger people with specific eligibility criteria, and people with certain diseases.\\nMedicare is divided into four categories: Medicare Part A, Part B, Part C (also called Medicare Advantage), and Part D for prescription drugs.\",\"industry\":\"Social Services\",\"example_en\":\"Since my elderly mother has poor health, Medicare is her supplier of health care should she need medical attention.\",\"example_es\":\"Debido a que mi anciana madre tiene problemas de salud, Medicare es su proveedor de cuidado de la salud en caso necesite atención médica.\",\"source\":\"Customer Service\"},{\"english\":\"Medication\",\"spanish\":\"Medicina /\\nMedicamento\",\"definition\":\"A substance used for  treatment, especially a medicine or drug.\",\"industry\":\"Medical\",\"example_en\":\"Sorry, that medication does not come in liquid form.\",\"example_es\":\"Lo lamento, pero esa medicina no viene en forma líquida.\",\"source\":\"Customer Service\"},{\"english\":\"Member\",\"spanish\":\"Miembro\",\"definition\":\"One that belongs to a group or organization, such as a bank, insurance company, church, music band.\",\"industry\":\"General\",\"example_en\":\"That service is only available to members of our community.\",\"example_es\":\"Ese servicio solo está disponible para los miembros de nuestra comunidad.\",\"source\":\"Customer Service\"},{\"english\":\"Member ID\",\"spanish\":\"Número de identificación de\\nmiembro\",\"definition\":\"Identification number of one that belongs to a group or organization.\",\"industry\":\"General\",\"example_en\":\"I need the name of the policy holder and member ID number to look up the policy.\",\"example_es\":\"Necesito el nombre del titular de la póliza y el número de identificación de miembro para buscar la póliza.\",\"source\":\"Customer Service\"},{\"english\":\"Membership (card)\",\"spanish\":\"Membresía (tarjeta)\",\"definition\":\"A card certifying membership and the identity of the bearer in an organization or insurance company.\",\"industry\":\"General\",\"example_en\":\"Enjoy free online access when you have a membership from your local library.\",\"example_es\":\"Disfrute del acceso gratuito en línea al tener una membresía de su biblioteca local.\",\"source\":\"Customer Service\"},{\"english\":\"Mess hall\",\"spanish\":\"Comedor de reclusos\",\"definition\":\"A room or building where groups of people, especially inmates or soldiers, eat together.\",\"industry\":\"Jail system\",\"example_en\":\"He fainted at our table in the mess hall.\",\"example_es\":\"Se desmayó en nuestra mesa en el comedor.\",\"source\":\"Customer Service\"},{\"english\":\"Meter reading\",\"spanish\":\"Lectura del medidor\",\"definition\":\"Refers to a person who visits a dwelling to read a gas or electricity meter for billing purposes.\",\"industry\":\"Customer Service\",\"example_en\":\"A technician will go out to your home to take a meter reading which will determine how much electricity you consumed last month.\",\"example_es\":\"Un técnico irá a su casa para tomar la lectura del medidor la cual determinará cuánta electricidad se consumió el mes anterior.\",\"source\":\"Customer Service\"},{\"english\":\"Meter reading\",\"spanish\":\"Etiqueta del medidor /\\nPlaca del medidor\",\"definition\":\"Sometimes referred to as utility badges, meter tags are used to help organize and streamline the inspection process.\",\"industry\":\"Customer Service\",\"example_en\":\"You are not to cut, remove or modify the meter tag in any fashion.\",\"example_es\":\"No debe cortar, quitar ni modificar la etiqueta del medidor de ninguna manera.\",\"source\":\"Customer Service\"},{\"english\":\"Migraines\",\"spanish\":\"Migrañas /\\nJaqueca\",\"definition\":\"A recurring acute headache characterized by severe throbbing pain, vertigo, nausea, vomiting, and photophobia, which may last for hours or days.\",\"industry\":\"Medical\",\"example_en\":\"She knew she suffered from migraine but had been unable to identify the cause.\",\"example_es\":\"Ella sabía que sufría de migraña, pero no le fue posible determinar la causa.\",\"source\":\"Customer Service\"},{\"english\":\"Minimum balance\",\"spanish\":\"Saldo mínimo\",\"definition\":\"A minimum monthly balance in a bank account to avoid monthly service fees.\",\"industry\":\"Finance\",\"example_en\":\"You must maintain a minimum balance of $10 in your account to avoid fees.\",\"example_es\":\"Debe mantener un saldo mínimo de $10 en su cuenta para evitar cargos.\",\"source\":\"Customer Service\"},{\"english\":\"Misdemeanor\",\"spanish\":\"Delito menor\",\"definition\":\"Refers to a criminal offense that is less serious than a felony and generally punishable by a fine, a jail term of up to a year, or both.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"You have a long history of committing misdemeanor crimes which may affect your sentencing.\",\"example_es\":\"Usted tiene un largo historial de delitos menores cometidos los cuales pueden afectar su sentencia.\",\"source\":\"Customer Service\"},{\"english\":\"MMR vaccine (triple shot)\",\"spanish\":\"Vacuna contra sarampión, paperas y rubeola\\n(Vacuna triple viral)\",\"definition\":\"The MMR vaccine is a vaccine against measles, mumps, and rubella.\",\"industry\":\"Medical\",\"example_en\":\"Many colleges also require a second MMR shot for incoming students.\",\"example_es\":\"Varias facultades también piden una segunda vacuna contra sarampión, paperas y rubeola para nuevos estudiantes\",\"source\":\"Customer Service\"},{\"english\":\"Mobile wallet\",\"spanish\":\"Billetera electrónica / \\nBilletera digital /\\nMonedero virtual\",\"definition\":\"A mobile wallet is a type of virtual wallet that stores credit card numbers, debit card numbers, and loyalty card numbers. It is accessible through an app installed on a mobile device, such as a smartphone or tablet.\",\"industry\":\"Finance\",\"example_en\":\"Customers use mobile wallets to make in-store payments, and it is a convenient payment method compared to paying with cash or carrying physical credit cards.\",\"example_es\":\"Los clientes utilizan los monederos virtuales para hacer pagos en las tiendas y es un método de pago conveniente en comparación con pagar en efectivo o llevar tarjetas de crédito físicas.\",\"source\":\"Customer Service\"},{\"english\":\"Model\",\"spanish\":\"Modelo\",\"definition\":\"The model of an object is a physical representation that shows what it looks like or how it works. \\nRefers to a particular brand of vehicle sold by a manufacturer, usually within a range of models, usually of different sizes or capabilities.\",\"industry\":\"General\",\"example_en\":\"What is your car's year, make and model?\",\"example_es\":\"¿Cuál es el año, marca y modelo de su carro?\",\"source\":\"Customer Service\"},{\"english\":\"Modification\",\"spanish\":\"Modificación /\\nReestructuración\",\"definition\":\"The act of altering or changing a contract, or a purchase contract, or altering the terms of such purchase.\",\"industry\":\"General\",\"example_en\":\"A contract modification could be approved in writing or by oral agreement.\",\"example_es\":\"Una modificación del contrato puede ser aprobada por escrito o por un acuerdo verbal.\",\"source\":\"Customer Service\"},{\"english\":\"Money order\",\"spanish\":\"Giro postal\",\"definition\":\"A money order is a certificate, that allows the named individual to receive cash on‐demand. A money order functions much like a check, in that the person who purchased the money order may stop payment.\",\"industry\":\"Finance\",\"example_en\":\"If you do not have a checking account, please send a money order to make your payment on time.\",\"example_es\":\"Si no tiene una cuenta corriente, por favor envíe un giro postal para realizar su pago a tiempo.\",\"source\":\"Customer Service\"},{\"english\":\"Monthly\",\"spanish\":\"Mensualmente\",\"definition\":\"Once a month.\",\"industry\":\"General\",\"example_en\":\"To get a free checking account, you need a monthly direct deposit.\",\"example_es\":\"Para recibir una cuenta corriente gratis necesita un depósito directo mensualmente.\",\"source\":\"Customer Service\"},{\"english\":\"Monthly payments\",\"spanish\":\"Mensualidades\",\"definition\":\"A payment that has to be made every month by a specified date.\",\"industry\":\"Finance\",\"example_en\":\"$717.60 is the total price for your washer and dryer, your monthly payments will be $59.80 for the next 12 months.\",\"example_es\":\"El precio total es $717.60 por su lavadora y secadora, sus mensualidades serán $59.80 por los próximos 12 meses.\",\"source\":\"Customer Service\"},{\"english\":\"Mortgage\",\"spanish\":\"Hipoteca\",\"definition\":\"An agreement (loan) under which a person borrows money to buy property, and the lender may take possession of the property if the borrower fails to repay the money.\",\"industry\":\"Finance\",\"example_en\":\"They hope to pay off the mortgage on their home soon.\",\"example_es\":\"Esperan pagar el préstamo hipotecario de su casa pronto.\",\"source\":\"Customer Service\"},{\"english\":\"Mortgage insurance\",\"spanish\":\"Seguro hipotecario\",\"definition\":\"Mortgage insurance is an insurance policy that protects a mortgage lender or titleholder if the borrower defaults on payments, passes away, or is otherwise unable to meet the contractual obligations of the mortgage.\",\"industry\":\"Finance\",\"example_en\":\"Private mortgage insurance protects the lender against the default of higher risk loans.\",\"example_es\":\"El seguro hipotecario privado protege al prestamista contra el incumplimiento de préstamos de mayor riesgo.\",\"source\":\"Customer Service\"},{\"english\":\"Mortgage Lender\",\"spanish\":\"Prestamista hipotecario\",\"definition\":\"A mortgage lender is a bank or financial company that provides financing that is related to real estate.\",\"industry\":\"Finance\",\"example_en\":\"Mortgage lenders offer cheaper rates to borrowers with a larger deposit.\",\"example_es\":\"Los prestamistas hipotecarios ofrecen tasas más baratas a los prestatarios con un depósito mayor.\",\"source\":\"Customer Service\"},{\"english\":\"Mother's maiden name\",\"spanish\":\"Apellido materno /\\nApellido de soltera de la madre\",\"definition\":\"It refers to the mother's unmarried name. Usually the surname or birth name she used before she married and took her husband's last name.\",\"industry\":\"Customer Service\",\"example_en\":\"A woman may choose to go back to using her mother's maiden name after a divorce.\",\"example_es\":\"Una mujer puede optar por usar su apellido materno nuevamente después de un divorcio.\",\"source\":\"Customer Service\"},{\"english\":\"Moving violation\",\"spanish\":\"Infracción con el vehículo en movimiento /\\nInfracción de tránsito /\\nCitación de tránsito de vehículo en marcha\",\"definition\":\"A moving violation is a breach of state traffic laws, rules, or statutes that occur while a vehicle's in motion.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Is there anything I can do to remove these moving violations from my record?\",\"example_es\":\"¿Hay algo que pueda hacer para eliminar estas citaciones de tránsito de vehículo en marcha de mis registros?\",\"source\":\"Customer Service\"},{\"english\":\"MRI (Magnetic Resonance Imaging)\",\"spanish\":\"Resonancia magnética /\\nImágenes por resonancia magnética\",\"definition\":\"MRI uses a large magnet and radio waves to look at organs and structures inside your body.\",\"industry\":\"Medical\",\"example_en\":\"We have scheduled an MRI as it is an extremely accurate method of disease detection throughout the body because the other tests failed to provide sufficient information.\",\"example_es\":\"Hemos programado una imagen por resonancia magnética ya que es un método extremamente preciso para la detección de enfermedades en todo el cuerpo porque las otras pruebas fallaron al no proporcionar suficiente información.\",\"source\":\"Customer Service\"},{\"english\":\"Mud flap\",\"spanish\":\"Lodera /\\nPolveadora\",\"definition\":\"A flap that hangs behind the wheel of a vehicle and is designed to prevent water, mud, and stones thrown up from the road from hitting the bodywork of the vehicle or any following vehicles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Mud flap laws vary from state to state.\",\"example_es\":\"Leyes sobre loderas varían de estado a estado.\",\"source\":\"Customer Service\"},{\"english\":\"Mudguard\",\"spanish\":\"Guardabarros /\\nGuardafangos /\\nSalpicadera\",\"definition\":\"A curved strip or cover over a wheel of a vehicle, especially a bicycle or motorcycle, designed to protect the vehicle and rider from water and dirt thrown up from the road.\",\"industry\":\"Auto Insurance\",\"example_en\":\"After the accident, the mudguard was bent and touching the wheel.\",\"example_es\":\"Después del accidente el guardabarros estaba doblado y tocando la rueda.\",\"source\":\"Customer Service\"},{\"english\":\"Mumps\",\"spanish\":\"Paperas /\\nParótidas /\\nParotiditis\",\"definition\":\"An infectious disease characterized by swelling of the salivary glands, especially the parotid glands, and sometimes of the pancreas, testes, or ovaries. There is no treatment for mumps, but the measles-mumps-rubella (MMR) vaccine can prevent it.\",\"industry\":\"Medical\",\"example_en\":\"As there have been recent outbreaks of mumps, it is important to have all school age children vaccinated.\",\"example_es\":\"Ya que ha habido recientes brotes de paperas, es importante vacunar a todos los menores en edad escolar.\",\"source\":\"Customer Service\"},{\"english\":\"Myopia /\\nNearsightedness\",\"spanish\":\"Miopía\",\"definition\":\"Nearsightedness (myopia) is a common vision condition in which near objects appear clear, but objects farther away look blurry.\",\"industry\":\"Medical\",\"example_en\":\"She wears eyeglasses to correct her myopia.\",\"example_es\":\"Ella usa anteojos para corregir su miopía.\",\"source\":\"Customer Service\"},{\"english\":\"Nape (of the neck)\",\"spanish\":\"Nuca\",\"definition\":\"Back of the neck.\",\"industry\":\"Medical\",\"example_en\":\"Is the pain you are experiencing in the nape of the neck the same as in your shoulders? Can you describe the pain and rate the pain on a scale of 1 to 10?\",\"example_es\":\"¿El dolor que está sintiendo en la nuca es el mismo dolor que siente en sus hombros? ¿Puede describir el dolor en una escala del 1 al 10?\",\"source\":\"Customer Service\"},{\"english\":\"Nauseated\",\"spanish\":\"Con náuseas /\\nNauseabunda(o)\",\"definition\":\"Make (someone) feel sick; affect with nausea.\",\"industry\":\"Medical\",\"example_en\":\"When I woke up, I felt nauseated.\",\"example_es\":\"Cuando me levanté, me sentí nauseabunda.\",\"source\":\"Customer Service\"},{\"english\":\"Navigation system\",\"spanish\":\"Sistema de navegación\",\"definition\":\"Car navigation systems receive signals from satellites and identify the vehicle's position and direction, then direct the driver to a destination.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The navigation system uses GPS signals to determine the vehicle's current location and direction.\",\"example_es\":\"El sistema de navegación utiliza señales de GPS para determinar la ubicación y dirección actual del vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Nebulizer\",\"spanish\":\"Nebulizador\",\"definition\":\"A nebulizer is a small machine that turns liquid medicine into a mist that can be easily inhaled. You sit with the machine and breathe in the medicine through a connected mouthpiece or facemask. This allows the medicine to enter the lungs directly.\",\"industry\":\"General\",\"example_en\":\"The drug was administered with a nebulizer, a device that turns a liquid substance into an aerosol.\",\"example_es\":\"El medicamento fue administrado con un nebulizador, un dispositivo que convierte una sustancia líquida en aerosol.\",\"source\":\"Customer Service\"},{\"english\":\"Net monthly income\",\"spanish\":\"Ingreso mensual neto\",\"definition\":\"Monthly income after all deductions are made (what  employees take home)\",\"industry\":\"Finance\",\"example_en\":\"What is your net monthly income or take-home pay?\",\"example_es\":\"¿Cuál es su ingreso mensual neto o el pago que lleva a casa?\",\"source\":\"Customer Service\"},{\"english\":\"Neurologist\",\"spanish\":\"Neuróloga(o)\",\"definition\":\"A specialist in the anatomy, functions, and disorders of nerves and the nervous system.\",\"industry\":\"Medical\",\"example_en\":\"As your headaches are becoming more severe and frequent, I am going to refer you to a neurologist.\",\"example_es\":\"Ya que sus dolores de cabeza se han hecho más graves y frecuentes, lo voy a remitir con un neurólogo.\",\"source\":\"Customer Service\"},{\"english\":\"New for old insurance\",\"spanish\":\"Seguro a valor de nuevo\",\"definition\":\"New for old policies mean that no deduction is made for wear and tear. A full replacement is made for items lost, stolen or damaged.\",\"industry\":\"Home Insurance\",\"example_en\":\"If you were to lose or damage your 2-year-old iPhone, your new for old insurance will pay out for a new one of equivalent value to the original.\",\"example_es\":\"Si se perdiera o se estropeara su iPhone de 2 años, su seguro a valor de nuevo le pagará uno nuevo de valor equivalente al original.\",\"source\":\"Customer Service\"},{\"english\":\"NICU (Neonatal Intensive Care Unit)\",\"spanish\":\"Unidad de Cuidados Intensivos Neonatales\",\"definition\":\"NICU is an intensive care unit specializing in the care of ill or premature newborn infants. Usually, this name is reserved for the type of nurseries where the highest level of care can be provided to newborn babies.\",\"industry\":\"Medical\",\"example_en\":\"The low birth weight and extreme frailty of premature babies requires a stay in the neonatal intensive care unit (NICU), probably for several weeks.\",\"example_es\":\"El bajo peso al nacer y la fragilidad extrema de los bebés prematuros requiere una estadía en la unidad de cuidados intensivos neonatales, probablemente por varias semanas.\",\"source\":\"Customer Service\"},{\"english\":\"Niece\",\"spanish\":\"Sobrina\",\"definition\":\"A daughter of one's brother, brother-in-law, sister or sister-in-law.\",\"industry\":\"General\",\"example_en\":\"My niece and nephew need to be added as beneficiaries to my life insurance policy as I am their legal guardian.\",\"example_es\":\"Mi sobrina y sobrino necesitan ser agregados como beneficiarios a mi póliza de seguro de vida ya que yo soy su tutor legal.\",\"source\":\"Customer Service\"},{\"english\":\"No (left/right) turn sign\",\"spanish\":\"Señal de no virar /\\nSeñal de no voltear\",\"definition\":\"This traffic sign indicates that right or left turns are prohibited.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The other driver ignored the no-turn signal.\",\"example_es\":\"El otro conductor ignoró la señal de no virar.\",\"source\":\"Customer Service\"},{\"english\":\"No fault laws\",\"spanish\":\"Leyes independientes de culpabilidad\",\"definition\":\"Laws enacted by states forcing insured parties to file injury claims through their own insurance companies, regardless of fault.\",\"industry\":\"Auto Insurance\",\"example_en\":\"In states with no-fault laws, P.I.P (Personal Injury Protection) is usually required.\",\"example_es\":\"En estados con leyes independientes de culpabilidad, la protección contra daños personales usualmente es requerida.\",\"source\":\"Customer Service\"},{\"english\":\"No Outlet sign\",\"spanish\":\"Rótulo/aviso de calle sin salida\",\"definition\":\"The no-outlet or dead end sign may be used at the entrance of a single road or street that terminates in a dead end or cul-de-sac, to indicate there is no other exit.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The no outlet sign was blocked by a truck.\",\"example_es\":\"El aviso de calle sin salida estaba bloqueado por un camión.\",\"source\":\"Customer Service\"},{\"english\":\"Non-payment\",\"spanish\":\"Falta de pago /\\nMorosidad /\\nIncumplimiento del pago\",\"definition\":\"Not paying for services rendered.\",\"industry\":\"Finance\",\"example_en\":\"Your services will be disconnected for non-payment if we do not receive the current amount due in 48 hours.\",\"example_es\":\"Sus servicios serán desconectados por falta de pago si no recibimos el monto actual en 48 horas.\",\"source\":\"Customer Service\"},{\"english\":\"Non-perishable\",\"spanish\":\"Alimentos no perecederos\",\"definition\":\"Food that is not subject to spoilage or decay.\",\"industry\":\"Social Services\",\"example_en\":\"She said employees are asked to donate money and nonperishable foods.\",\"example_es\":\"Ella dijo que se les pide a los empleados donar dinero y alimentos no perecederos.\",\"source\":\"Customer Service\"},{\"english\":\"Non-renewal\",\"spanish\":\"No renovación\",\"definition\":\"A decision by an insurance company not to renew a policy.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Nonrenewal means your insurance company has decided not to renew your policy for a new term.\",\"example_es\":\"La no renovación quiere decir que su compañía de seguros ha decidido no renovar su póliza para un nuevo período.\",\"source\":\"Customer Service\"},{\"english\":\"Non-saturated fats\",\"spanish\":\"Grasas no saturadas\",\"definition\":\"An unsaturated fat is a fat or fatty acid in which there is at least one double bond within the fatty acid chain.\",\"industry\":\"Medical\",\"example_en\":\"Unsaturated fats are an important supply of calories and, therefore, energy to the human body.\",\"example_es\":\"Las grasas no saturadas son un importante suministro de calorías y, por lo tanto, energía para el cuerpo humano.\",\"source\":\"Customer Service\"},{\"english\":\"Non-stop (flight)\",\"spanish\":\"Sin escala\",\"definition\":\"A flight that goes from the place of origin to the destination, without making any stops.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"We took a non-stop flight to Los Angeles.\",\"example_es\":\"Tomamos un vuelo sin escala a Los Ángeles.\",\"source\":\"Customer Service\"},{\"english\":\"Non-trucking liability insurance (NTL)\",\"spanish\":\"Seguro de responsabilidad civil para camiones en uso no comercial\",\"definition\":\"Non-trucking liability (NTL) insurance provides coverage for any non-business use of your trucks, such as non-economic purposes for personal convenience that are outside your business’s control or direction.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Non-trucking liability insurance protects owner-operators when the truck isn't being used for business.\",\"example_es\":\"El seguro de responsabilidad civil para camiones en uso no comercial protege al propietario cuando el camión no se utiliza para fines de negocio.\",\"source\":\"Customer Service\"},{\"english\":\"Non-verbal\",\"spanish\":\"No verbal / \\nSin uso del habla\",\"definition\":\"Not involving or using words; lacking or appearing to lack the ability to engage in speech.\",\"industry\":\"School\",\"example_en\":\"Practice will help you improve how you speak as well as your use of non-verbal communication.\",\"example_es\":\"La práctica le ayudará a mejorar su forma de hablar y su uso de la comunicación no verbal.\",\"source\":\"Customer Service\"},{\"english\":\"Nosebleed\",\"spanish\":\"Hemorragia nasal /\\nSangrado de la nariz /\\nSangrado nasal /\\nNariz sangrante\",\"definition\":\"It is the common occurrence of bleeding from the nose. It is usually noticed when the blood drains out through the nostrils.\",\"industry\":\"Medical\",\"example_en\":\"Dry nasal passages can lead to nosebleeds.\",\"example_es\":\"Las vías nasales secas pueden provocar hemorragias nasales.\",\"source\":\"Customer Service\"},{\"english\":\"Notice (noun)\",\"spanish\":\"Notificación\",\"definition\":\"Advance notification of intention to end an arrangement, contract, etc.\",\"industry\":\"General\",\"example_en\":\"General Assistance pays for your housing, so you were not supposed to receive a notice of eviction.\",\"example_es\":\"La Asistencia General paga su vivienda, entonces usted no debió recibir una notificación de desalojo.\",\"source\":\"Customer Service\"},{\"english\":\"Numbness\",\"spanish\":\"Entumecimiento /\\nAdormecimiento\",\"definition\":\"Numbness describes a loss of sensation or feeling in a part of your body. It's often accompanied by or combined with other changes in sensation, such as a pins-and-needles feeling, burning or tingling.\",\"industry\":\"Medical\",\"example_en\":\"Are you experiencing any numbness or tingling in your fingers and toes?\",\"example_es\":\"¿Está sintiendo entumecimiento u hormigueo en los dedos de las manos o de los pies?\",\"source\":\"Customer Service\"},{\"english\":\"Nurse case manager\",\"spanish\":\"Enfermera(o) encargada(o) del caso / \\nEnfermera (o) administrador (a) del caso) / \\nEnfermera(o) gerente del caso\",\"definition\":\"A nurse case manager is responsible for: Helping an injured worker to obtain the medical care that he or she needs; serving as a liaison between all parties involved in the workers’ compensation claim; providing information to an insurance adjuster regarding doctors’ visits and treatment authorization.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"The nurse case manager's role focuses on providing advice and medication to the patient.\",\"example_es\":\"El rol de la enfermera encargada del caso se centra en brindar asesoramiento y medicamento al paciente.\",\"source\":\"Customer Service\"},{\"english\":\"Nurse practitioner\",\"spanish\":\"Enfermera(o) facultativa(o) /\\nEnfermera(o) especializada(o)\",\"definition\":\"A nurse who is qualified to treat certain conditions without the direct supervision of a doctor. A registered nurse who is qualified through advanced training to assume some of the duties and responsibilities formerly assumed only by a physician.\",\"industry\":\"Medical\",\"example_en\":\"We can offer you an appointment with nurse practitioner Susan.\",\"example_es\":\"Podemos ofrecerle una cita con la enfermera facultativa Susan.\",\"source\":\"Customer Service\"},{\"english\":\"Nurse’s office\",\"spanish\":\"Enfermería\",\"definition\":\"A specialized practice of nursing that protects and promotes student health, enables optimal development, and advances academic success.\",\"industry\":\"School\",\"example_en\":\"Evelyn felt warm to the touch, she was sent to the nurse's office to check her temperature.\",\"example_es\":\"Evelyn se sentía caliente al tacto, la enviaron a la enfermería para revisar su temperatura.\",\"source\":\"Customer Service\"},{\"english\":\"OB/GYN\",\"spanish\":\"Ginecobstetra\",\"definition\":\"An obstetrician-gynecologist, or OB-GYN, is a healthcare professional that specializes in female reproductive health.\",\"industry\":\"Medical\",\"example_en\":\"You should see your OB/GYN every four weeks throughout your first and second trimester.\",\"example_es\":\"Debería ver a su ginecobstetra cada cuatro semanas durante el primer y segundo trimestre.\",\"source\":\"Customer Service\"},{\"english\":\"Obstetrician\",\"spanish\":\"Obstetra\",\"definition\":\"A physician who specializes in obstetrics. Specialist in pregnancy and related conditions (often also experienced in gynecology).\",\"industry\":\"Medical\",\"example_en\":\"As your pregnancy test came back positive, you need to make monthly appointments with your obstetrician and make sure to take your prenatal vitamins.\",\"example_es\":\"Ya que su prueba de embarazo fue positiva, necesita hacer citas mensuales con el obstetra y asegurarse de tomar sus vitaminas prenatales.\",\"source\":\"Customer Service\"},{\"english\":\"Occupational Therapy (OT)\",\"spanish\":\"Terapia ocupacional\",\"definition\":\"The overall responsibility of a school-based occupational therapy is to furnish support and provide interventions for students to engage in school activities and achieve independence within the school setting.\",\"industry\":\"Medical\",\"example_en\":\"Studies show that occupational therapy at school is helpful for children with disabilities.\",\"example_es\":\"Los estudios muestran que la terapia ocupacional en la escuela es útil para los niños con discapacidades.\",\"source\":\"Customer Service\"},{\"english\":\"Occurrence\",\"spanish\":\"Incidente\",\"definition\":\"Something that takes place or comes to pass. \\nThe action, fact, or instance of occurring. Something that happens; event; incident.\",\"industry\":\"General\",\"example_en\":\"Complaints seemed to be an everyday occurrence.\",\"example_es\":\"Las quejas parecían ser un incidente del día a día.\",\"source\":\"Customer Service\"},{\"english\":\"Odometer\",\"spanish\":\"Indicador de millaje /\\nOdómetro\",\"definition\":\"An instrument for measuring the distance traveled by a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Odometer tampering is a serious crime.\",\"example_es\":\"La manipulación del odómetro es un delito grave.\",\"source\":\"Customer Service\"},{\"english\":\"Off ramp\",\"spanish\":\"Rampa de salida /\\nCarril de salida en pendiente\",\"definition\":\"A highway ramp as in exit ramp / off-ramp which allows vehicles to exit a controlled-access highway, freeway or motorway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The driver did not turn on his turn signal to indicate he was going to take the off ramp.\",\"example_es\":\"El chofer no puso sus luces de cruce para indicar que iba a tomar la rampa de salida.\",\"source\":\"Customer Service\"},{\"english\":\"Office visit\",\"spanish\":\"Consulta\",\"definition\":\"Office visit where a patient seeks care or advice from a health care provider.\",\"industry\":\"Health Insurance\",\"example_en\":\"He charges $225 for a 40-minute physical examination and $150 for a 20-minute office visit.\",\"example_es\":\"Él cobra $225 por un examen físico de 40 minutos y $150 por una consulta de 20 minutos.\",\"source\":\"Customer Service\"},{\"english\":\"On demand\",\"spanish\":\"A la carta\",\"definition\":\"Refers to systems which allow users to select and watch/listen video or audio content when they choose to, rather than having to watch at a specific broadcast time.\",\"industry\":\"Customer Service\",\"example_en\":\"Am I able to watch my favorite programs at any time if I pay for the additional 'on demand' service?\",\"example_es\":\"¿Podré ver mis programas favoritos en cualquier momento si pago por los servicios adicionales a la carta?\",\"source\":\"Customer Service\"},{\"english\":\"On ramp\",\"spanish\":\"Rampa de entrada /\\nCarril de entrada en pendiente\",\"definition\":\"A highway ramp as in entry ramp / on-ramp which allows vehicles to enter a controlled-access highway, freeway or motorway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The on ramp is closed for repairs.\",\"example_es\":\"La rampa de entrada está cerrada por reparaciones.\",\"source\":\"Customer Service\"},{\"english\":\"One time payment\",\"spanish\":\"Pago único\",\"definition\":\"A one time payment is a one-off, non-recurring payment option where the third party payment processing is authorized to collect a payment from a utility customer's credit card or bank account.\",\"industry\":\"Finance\",\"example_en\":\"The settlement included a one-time payment of more than $595,000.\",\"example_es\":\"El acuerdo incluyó un pago único de más de 595,000 dólares.\",\"source\":\"Customer Service\"},{\"english\":\"One way street\",\"spanish\":\"Calle de una sola vía\",\"definition\":\"A street or road that only allows traffic movement in one direction only; a one-way traffic only.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I was given a ticket for driving the wrong way on a one way street.\",\"example_es\":\"Me dieron una boleta de infracción por conducir en sentido contrario en una calle de una sola vía.\",\"source\":\"Customer Service\"},{\"english\":\"Online\",\"spanish\":\"En línea\",\"definition\":\"Connected to a computer, a computer network, or the Internet.\",\"industry\":\"General\",\"example_en\":\"To expedite the approval process, you can apply online.\",\"example_es\":\"Para acelerar el proceso de aprobación, puede realizar la solicitud en línea.\",\"source\":\"Customer Service\"},{\"english\":\"Open enrollment period\",\"spanish\":\"Período de inscripción abierto\",\"definition\":\"The annual period when people can enroll in a marketplace health insurance plan, or renew, change or cancel their health insurance.\",\"industry\":\"Health Insurance\",\"example_en\":\"You can only add coverage during the open enrollment period.\",\"example_es\":\"Sólo puede añadir cobertura durante el periodo de inscripción abierto.\",\"source\":\"Customer Service\"},{\"english\":\"Orthodontist\",\"spanish\":\"Ortodoncista\",\"definition\":\"A dentist who specializes in the treatment of irregularities in the teeth (especially of alignment and occlusion) and jaws, including the use of braces.\",\"industry\":\"Medical\",\"example_en\":\"Please, remember the orthodontist will be seeing you at three today.\",\"example_es\":\"Por favor, recuerde que el ortodoncista lo verá hoy a las tres.\",\"source\":\"Customer Service\"},{\"english\":\"OTC \\n(over the counter)\",\"spanish\":\"Medicamentos de venta libre /\\nMedicinas sin receta\",\"definition\":\"OTC medicines are drugs you can buy without a prescription.\",\"industry\":\"Medical\",\"example_en\":\"Two of the medications I want you to take are over-the-counter medications and you don't need a prescription for those.\",\"example_es\":\"Dos de los medicamentos que quiero que tome son medicamentos de venta libre y no necesita receta.\",\"source\":\"Customer Service\"},{\"english\":\"Out of network\",\"spanish\":\"Fuera de la red (de proveedores)\",\"definition\":\"Usually refers to physicians, hospitals or other health care providers who are considered non participants in an plan (usually an HMO or PPO).\",\"industry\":\"Health Insurance\",\"example_en\":\"Mr. Luna, you're responsible for the bill because you went to see an out-of-network provider.\",\"example_es\":\"Señor Luna, usted es responsable por la factura ya que fue a ver a un proveedor fuera de la red.\",\"source\":\"Customer Service\"},{\"english\":\"Out-of-pocket expense\",\"spanish\":\"Dinero de su bolsillo /\\nDe su propio dinero /\\nQue corre por su cuenta\",\"definition\":\"Refers to costs that individuals pay out of their own cash reserves.\",\"industry\":\"Health Insurance\",\"example_en\":\"You must also be aware that out of pocket expenses can occur when you make a claim.\",\"example_es\":\"También debe tener en cuenta que los gastos de su propio dinero se pueden dar cuando realice un reclamo.\",\"source\":\"Customer Service\"},{\"english\":\"Outstanding payment /\\nOutstanding balance\",\"spanish\":\"Pago pendiente /\\nSaldo pendiente\",\"definition\":\"Outstanding payment means the value of any payment that remains outstanding after the date on which that payment was due to be made in accordance with a previous agreement.\",\"industry\":\"Finance\",\"example_en\":\"We are still awaiting the outstanding payment from our client.\",\"example_es\":\"Todavía estamos esperando el pago pendiente de nuestro cliente.\",\"source\":\"Customer Service\"},{\"english\":\"Overdraft\",\"spanish\":\"Sobregiro\",\"definition\":\"A deficit in a bank account balance caused by drawing more money than the account holds.\",\"industry\":\"Finance\",\"example_en\":\"You can add overdraft protection to your account to avoid paying a fee.\",\"example_es\":\"Puede añadir protección contra sobregiros a su cuenta para evitar el pago de un cargo.\",\"source\":\"Customer Service\"},{\"english\":\"Overdraft fee\",\"spanish\":\"Cargo por sobregiro\",\"definition\":\"A fee charged when a withdrawal from an individual's bank account exceeds the available balance.\",\"industry\":\"Finance\",\"example_en\":\"The bank has charged you an overdraft fee of $30 as there were not enough funds in your account to cover the check posted yesterday.\",\"example_es\":\"El banco le ha cobrado un cargo por sobregiro de $30 ya que no había suficientes fondos en su cuenta para cubrir el cheque que fijó en la cuenta ayer.\",\"source\":\"Customer Service\"},{\"english\":\"Overdue payment\",\"spanish\":\"Pago atrasado\",\"definition\":\"Overdue payments are simply dues to a vendor supplying a product or a service on credit or a lender that advances a loan to a borrower.\",\"industry\":\"General\",\"example_en\":\"We need to collect any overdue payments.\",\"example_es\":\"Vamos a necesitar cobrar cualquier pago atrasado.\",\"source\":\"Customer Service\"},{\"english\":\"Overnight (delivery)/\\nNext day (delivery)\",\"spanish\":\"(Entrega) de un día para otro\",\"definition\":\"Guaranteed delivery of package or letter on the day following the shipment date.\",\"industry\":\"Customer Service\",\"example_en\":\"When you place an order before noon, it is usually delivered overnight.\",\"example_es\":\"Cuando realiza un pedido antes de mediodía, normalmente se entrega de un día para otro.\",\"source\":\"Customer Service\"},{\"english\":\"Overpass /\\nFlyover\",\"spanish\":\"Puente elevado /\\nPaso elevado\",\"definition\":\"A passage, roadway, or bridge that crosses above another roadway.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did you file a police report for the rock throwing incident that occurred on the overpass?\",\"example_es\":\"¿Presentó un informe policial por el incidente de lanzamiento de piedras que ocurrió en el paso elevado?\",\"source\":\"Customer Service\"},{\"english\":\"Overturned\",\"spanish\":\"Se volcó (volcarse)\",\"definition\":\"Insurance: tip (something) over so that it is on its side or upside down. [Flipped over]\",\"industry\":\"Auto Insurance\",\"example_en\":\"It was slippery, I pushed the breaks but the car overturned.\",\"example_es\":\"Estaba resbaladizo, pisé los frenos pero el carro terminó volcado.\",\"source\":\"Customer Service\"},{\"english\":\"Oxygen tank\",\"spanish\":\"Tanque de oxígeno\",\"definition\":\"An oxygen tank is an oxygen storage vessel, which is either held under pressure in gas cylinders, or as liquid oxygen in a cryogenic storage tank.\",\"industry\":\"General\",\"example_en\":\"My hotel had an oxygen tank in the lobby for travelers struggling with the altitude.\",\"example_es\":\"Mi hotel tenía un tanque de oxígeno en el vestíbulo para los viajeros que tenían problemas con la altitud.\",\"source\":\"Customer Service\"},{\"english\":\"P.O. Box\",\"spanish\":\"Apartado postal /\\nBuzón postal /\\nCaja postal\",\"definition\":\"A numbered box in a post office assigned to a person or organization, in which mail for them is kept until collected.\",\"industry\":\"Customer Service\",\"example_en\":\"Please send my bills to my new P.O. Box address as I have trouble getting mail at the home address.\",\"example_es\":\"Por favor envíe mis cobros a mi nueva caja postal ya que tengo problemas en obtener el correo en mi dirección de casa.\",\"source\":\"Customer Service\"},{\"english\":\"Pain\",\"spanish\":\"Dolor\",\"definition\":\"Medical: physical suffering or discomfort caused by illness or injury.\",\"industry\":\"Medical\",\"example_en\":\"On a scale of 1 to 10, how bad is your pain?\",\"example_es\":\"En una escala de 1 a 10 ¿qué tan fuerte es su dolor?\",\"source\":\"Customer Service\"},{\"english\":\"Painkiller\",\"spanish\":\"Analgésico\",\"definition\":\"A medicine, such as an analgesic drug, that relieves pain.\",\"industry\":\"Medical\",\"example_en\":\"She received strong painkillers but the pain did not go away.\",\"example_es\":\"Le dieron analgésicos fuertes, pero el dolor no desapareció.\",\"source\":\"Customer Service\"},{\"english\":\"Pale\",\"spanish\":\"Pálida(o)\",\"definition\":\"Used to describe a person's face or skin if it has less color than usual, for example when the person is or ill or frightened, or if it has less color than people generally have.\",\"industry\":\"Medical\",\"example_en\":\"I've lost weight, I feel bad and I'm very pale.\",\"example_es\":\"He perdido peso, me siento mal y estoy muy pálida.\",\"source\":\"Customer Service\"},{\"english\":\"Palliative care\",\"spanish\":\"Cuidados paliativos\",\"definition\":\"Palliative care is specialized medical care for people living with a serious illness. This type of care is focused on providing relief from the symptoms and stress of the illness. The goal is to improve quality of life for both the patient and the family.\",\"industry\":\"Medical\",\"example_en\":\"The team was able to arrange for five new bedside commodes to be purchased for use in the palliative care ward.\",\"example_es\":\"El equipo pudo concertar la compra de cinco nuevos inodoros portátiles para su uso en la sala de cuidados paliativos.\",\"source\":\"Customer Service\"},{\"english\":\"Pap smear\",\"spanish\":\"Papanicolaou\",\"definition\":\"The Papanicolaou test, Pap smear or Pap test, is a procedure to test for cervical cancer in people with a cervix.\",\"industry\":\"Medical\",\"example_en\":\"We will call you if the results of your pap smear return abnormal.\",\"example_es\":\"Le llamaremos si los resultados de su Papanicolaou regresan anormales.\",\"source\":\"Customer Service\"},{\"english\":\"Paperwork\",\"spanish\":\"Documentación /\\nPapeleo\",\"definition\":\"Written documents such as forms, records, or letters.\",\"industry\":\"Social Services\",\"example_en\":\"Please fill out all of the paperwork we sent; have all forms filled out, signed and dated before you return them to our office.\",\"example_es\":\"Por favor llene todo el papeleo que enviamos; tenga todos los documentos llenos, firmados y con fecha antes de regresarlos a nuestra oficina.\",\"source\":\"Customer Service\"},{\"english\":\"Paramedics\",\"spanish\":\"Paramédicas(os)\",\"definition\":\"Members of an ambulance crew trained in a number of life-saving skills, including infusion and cardiac care.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The ambulances are usually staffed by intensive care doctors, nurses and paramedics.\",\"example_es\":\"Las ambulancias normalmente están provistas de doctores de cuidados intensivos, enfermeros y paramédicos.\",\"source\":\"Customer Service\"},{\"english\":\"Parent-teacher conference\",\"spanish\":\"Conferencia entre padres y maestros\",\"definition\":\"A parent-teacher conference helps to communicate to parents the areas their child is excelling in and to give them specific ideas of how to improve upon their child’s performance in school.\",\"industry\":\"School\",\"example_en\":\"Conducting effective parent-teacher conferences can boost family involvement in the classroom and help promote positive outcomes for the teacher, the students, and the school.\",\"example_es\":\"Llevar a cabo conferencias efectivas entre padres y maestros puede impulsar la participación familiar en el salón de clases y ayudar a promover resultados positivos para el maestro, los estudiantes y la escuela.\",\"source\":\"Customer Service\"},{\"english\":\"Parole\",\"spanish\":\"Libertad condicional\",\"definition\":\"The release of a prisoner temporarily (for a special purpose) or permanently before the completion of a sentence, on the promise of good behavior.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"He committed a burglary while on parole.\",\"example_es\":\"Él cometió una usurpación de morada mientras estaba en libertad condicional.\",\"source\":\"Customer Service\"},{\"english\":\"Pass out\",\"spanish\":\"Desmayarse /\\nDesvanecerse\",\"definition\":\"Temporary loss of consciousness, to faint; become unconscious.\",\"industry\":\"Medical\",\"example_en\":\"My father passed out and is not breathing! Please send the ambulance right away!\",\"example_es\":\"¡Mi papá se desvaneció y no está respirando! ¡Por favor, mande una ambulancia rápidamente!\",\"source\":\"Customer Service\"},{\"english\":\"Passengers\",\"spanish\":\"Pasajeros\",\"definition\":\"Insurance: a person(s) who is traveling from one place to another in a car, bus, train, ship, airplane, etc., and who is not driving or working on it.\",\"industry\":\"Insurance (general)\",\"example_en\":\"How many passengers were there in your vehicle?\",\"example_es\":\"¿Cuántos pasajeros iban en su vehículo?\",\"source\":\"Customer Service\"},{\"english\":\"Password\",\"spanish\":\"Contraseña\",\"definition\":\"A secret word or phrase that must be used to gain admission to something.\",\"industry\":\"General\",\"example_en\":\"Your password should contain a minimum of 8 characters, letters, numbers and one symbol. Please make sure to write it down in a secure place.\",\"example_es\":\"Su contraseña deberá tener un mínimo de 8 caracteres, letras, números y un símbolo. Por favor asegúrese de escribirlo en un lugar seguro.\",\"source\":\"Customer Service\"},{\"english\":\"Pay per view\",\"spanish\":\"Pago por evento\",\"definition\":\"Refers to a type of paid television service by which a subscriber of a television service provider can purchase events to view via private telecast. The broadcaster shows the event at the same time to everyone ordering it.\",\"industry\":\"Customer Service\",\"example_en\":\"The pay per view movie will cost $4.99 and you will see that charge on your next bill.\",\"example_es\":\"La película de pago por evento costará $4.99 y verá ese cargo en su siguiente factura.\",\"source\":\"Customer Service\"},{\"english\":\"Paycheck\",\"spanish\":\"Cheque de pago /\\nCheque de sueldo /\\nCheque de salario /\\nCheque de nómina\",\"definition\":\"A check issued to an employee in payment of salary or wages.\",\"industry\":\"General\",\"example_en\":\"How often does your employer send out your paychecks, weekly, bi-weekly or monthly?\",\"example_es\":\"¿Qué tan seguido envía su empleador los cheques de pago, semanal, quincenal, o mensual?\",\"source\":\"Customer Service\"},{\"english\":\"Payment arrangement\",\"spanish\":\"Arreglo de pago /\\nAcuerdo de pago\",\"definition\":\"An agreement between an entity and the borrower, in which the borrower agrees to pay back a certain amount of money each month to repay the debt.\",\"industry\":\"Finance\",\"example_en\":\"We tried to work out a payment arrangement with the creditors.\",\"example_es\":\"Tratamos de concretar un arreglo de pago con los prestamistas.\",\"source\":\"Customer Service\"},{\"english\":\"Payoff /\\nPay off\",\"spanish\":\"Liquidación (noun) /\\nLiquidar (verb) / \\nSaldar (verb)\",\"definition\":\"The act of paying a debt or creditor in full.\",\"industry\":\"Finance\",\"example_en\":\"Can you give me the amount needed to pay off my credit card?\",\"example_es\":\"¿Me puede decir la cantidad para saldar/liquidar mi tarjeta de crédito?\",\"source\":\"Customer Service\"},{\"english\":\"Payoff amount\",\"spanish\":\"Monto a pagar / \\nMonto de liquidación\",\"definition\":\"Your payoff amount is how much you will actually have to pay to satisfy the terms of your loan and completely pay off your debt.\",\"industry\":\"Finance\",\"example_en\":\"The best way to get the accurate payoff amount is to contact your lender.\",\"example_es\":\"La mejor forma de conseguir el monto a pagar preciso es contactando a su prestamista.\",\"source\":\"Customer Service\"},{\"english\":\"Payroll\",\"spanish\":\"Nómina /\\nPaga /\\nPlanilla\",\"definition\":\"The total sum of money to be paid out to employees at a given time.\",\"industry\":\"General\",\"example_en\":\"As soon as you become an employee you will be added to our official payroll and your benefits will start after 6 months.\",\"example_es\":\"Tan pronto como se convierta en empleado será agregado a nuestra nómina oficial y sus beneficios empezarán después de 6 meses.\",\"source\":\"Customer Service\"},{\"english\":\"Paystub /\\nCheck stub\",\"spanish\":\"Talón de pago /\\nTalonario de pago /\\nTalones de cheque /\\nRecibo de pago /\\nColilla de pago /\\nComprobantes de pago del trabajo\",\"definition\":\"A part of a check that is kept for record keeping purposes. For example, the stub is the part of a payroll check that includes information about the current paycheck as well as payments to date.\",\"industry\":\"Social Services\",\"example_en\":\"I need the last 6 paystubs, a copy of your social security card, and a letter from your employer as to when you were hired to work full time.\",\"example_es\":\"Necesito los últimos 6 talones de pago, copia de su tarjeta de seguro social, y una carta de su empleador mostrando cuándo fue contratado para trabajar tiempo completo.\",\"source\":\"Customer Service\"},{\"english\":\"PCP (Primary Care\\nPhysician)\",\"spanish\":\"Médica(o) de cabecera /\\nMédica(o) principal / Doctor(a) de cabecera\",\"definition\":\"A physician who provides both the first contact for a person with an undiagnosed health concern as well as continuing care of varied  conditions, not limited by cause, organ system, or diagnosis.\",\"industry\":\"Medical\",\"example_en\":\"As you are new to the plan, please select a PCP from our list of family doctors or pediatricians. This way your children will see the same doctor for all of your routine medical needs.\",\"example_es\":\"Ya que es nuevo en el plan, por favor seleccione a un médico de cabecera de nuestra lista de doctores de familia o pediatras. De esta manera sus hijos verán al mismo doctor para todas sus necesidades médicas rutinarias.\",\"source\":\"Customer Service\"},{\"english\":\"Pediatrician\",\"spanish\":\"Pediatra\",\"definition\":\"A medical practitioner specializing in children and their diseases.\",\"industry\":\"Medical\",\"example_en\":\"The pediatrician will be here in a couple of minutes; have your child undress and put this robe on.\",\"example_es\":\"El pediatra estará aquí en un par de minutos, por favor desvista a su hijo y póngale esta bata.\",\"source\":\"Customer Service\"},{\"english\":\"Penalties\",\"spanish\":\"Penalizaciones /\\nSanciones\",\"definition\":\"Punishment imposed for breaking a law, rule, or contract.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The company was given severe penalties for the violation.\",\"example_es\":\"La empresa recibió penalizaciones severas por la infracción.\",\"source\":\"Customer Service\"},{\"english\":\"Pending balance\",\"spanish\":\"Saldo pendiente\",\"definition\":\"Amount of money waiting to be paid, as in a debt.\",\"industry\":\"Finance\",\"example_en\":\"A pending balance often occurs when you use your debit card – your bank is aware of the transaction, but the retailer may not submit the charge for payment until the end of the business day, leaving it in a pending status.\",\"example_es\":\"El saldo pendiente se produce a menudo cuando se usa la tarjeta de débito: el banco está al tanto de la transacción, pero es posible que el comerciante no envíe el cargo para su pago hasta el final del día laborable, dejándolo en estado pendiente.\",\"source\":\"Customer Service\"},{\"english\":\"Performance\",\"spanish\":\"Desempeño /\\nRendimiento\",\"definition\":\"The action or process of carrying out or accomplishing an action, task, or function.\",\"industry\":\"School\",\"example_en\":\"I need to talk to you about Sylvie’s performance since online classes started.\",\"example_es\":\"Necesito hablar con usted sobre el desempeño de Sylvie desde que empezaron las clases en línea.\",\"source\":\"Customer Service\"},{\"english\":\"Peril\",\"spanish\":\"Peligro /\\nRiesgo\",\"definition\":\"A property insurance term referring to the possible cause of loss such as a fire or a windstorm. “Peril” is always very dangerous, usually life-threatening.\",\"industry\":\"Home Insurance\",\"example_en\":\"Get homeowners insurance for protection against common perils.\",\"example_es\":\"Obtenga un seguro de propietario de vivienda para protegerse contra los peligros más comunes.\",\"source\":\"Customer Service\"},{\"english\":\"Pertussis\",\"spanish\":\"Pertussis\",\"definition\":\"A contagious bacterial disease chiefly affecting children, characterized by convulsive coughs followed by a whoop, also known as whooping cough; however, it is a different register.\",\"industry\":\"Medical\",\"example_en\":\"Pertussis is a highly contagious respiratory infection.\",\"example_es\":\"La pertussis es una infección respiratoria sumamente contagiosa.\",\"source\":\"Customer Service\"},{\"english\":\"PEX pipes (Cross-linked polyethylene pipes)\",\"spanish\":\"Tubería de polietileno reticulado\",\"definition\":\"PEX is a high-temperature flexible plastic pressure pipe. It is widely used for plumbing, water service, fire protection, hydronic heating and cooling, snow and ice melting and ground source geothermal piping systems.\",\"industry\":\"Home Insurance\",\"example_en\":\"The red and blue PEX pipes are used for hot and cold water supply.\",\"example_es\":\"Las tuberías de polietileno reticulado rojas y azules son usadas para el suministro de agua fría y caliente.\",\"source\":\"Customer Service\"},{\"english\":\"Pharmacy\",\"spanish\":\"Farmacia\",\"definition\":\"A store where medicinal drugs are dispensed and sold.\",\"industry\":\"Medical\",\"example_en\":\"Many drugs are sold over the counter, and patients ask pharmacies for advice on their ailments.\",\"example_es\":\"Muchas medicinas se venden sin receta médica y los pacientes piden consejos en las farmacias sobre sus dolencias.\",\"source\":\"Customer Service\"},{\"english\":\"Phlegm\",\"spanish\":\"Flema\",\"definition\":\"The thick viscous substance secreted by the mucous membranes of the respiratory passages, especially when produced in excessive or abnormal quantities, e.g., when someone is suffering from a cold.\",\"industry\":\"Medical\",\"example_en\":\"No matter how hard I cough, I don't seem to clear the phlegm from my lungs.\",\"example_es\":\"No importa lo fuerte que tosa no logro despejar la flema de mis pulmones.\",\"source\":\"Customer Service\"},{\"english\":\"Photochromic lenses\",\"spanish\":\"Lentes fotocromáticas\",\"definition\":\"Photochromic lenses are eyeglass lenses where photochromic molecules on the lens react to light and change their structure, causing the lens to darken.\",\"industry\":\"Medical\",\"example_en\":\"Photochromic lenses are lenses that darken in response to UV light.\",\"example_es\":\"Las lentes fotocromáticas son lentes que se oscurecen en respuesta a la luz ultravioleta.\",\"source\":\"Customer Service\"},{\"english\":\"Physical (exam)\",\"spanish\":\"Examen Físico\",\"definition\":\"An examination, usually done by a physician to determine the state of a person's health, identify risk factors for disease, or verify fitness.\",\"industry\":\"Medical\",\"example_en\":\"A physical exam can be general or specific to a particular problem.\",\"example_es\":\"Un examen físico puede ser general o específico con respecto a un problema en particular.\",\"source\":\"Customer Service\"},{\"english\":\"Physical therapy /\\nPhysiotherapy\",\"spanish\":\"Terapia física /\\nFisioterapia\",\"definition\":\"Therapy that uses physical agents: exercise and massage and other modalities. The main difference between physical therapy and physiotherapy is how they focus on healing.\",\"industry\":\"Medical\",\"example_en\":\"The aim of physical therapy is to relieve pain, help you move better or strengthen weakened muscles.\",\"example_es\":\"El objetivo de la terapia física, es aliviar el dolor, ayudarle a moverse mejor o fortalecer los músculos debilitados.\",\"source\":\"Customer Service\"},{\"english\":\"Pick-up truck\",\"spanish\":\"Camioneta\",\"definition\":\"A small truck with an enclosed cab and open back.\",\"industry\":\"Auto Insurance\",\"example_en\":\"As I was getting in the pick-up truck, the bull hit the rear right side.\",\"example_es\":\"Cuando me estaba subiendo a la camioneta el toro le pegó por el lado trasero derecho.\",\"source\":\"Customer Service\"},{\"english\":\"Pile-up accident /\\nMulti-car collision / crash\",\"spanish\":\"Choque en cadena /\\nChoque múltiple /\\nColisión múltiple /\",\"definition\":\"Multi-car collision, multi-vehicle collision, pile-up, or chain-reaction crash) is a traffic accident that consist of a massive collision of several or many moving vehicles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Yes, it was a multi-car collision, four cars in total.\",\"example_es\":\"Sí, fue un choque múltiple, cuatro carros en total.\",\"source\":\"Customer Service\"},{\"english\":\"PIN (Personal Identification Number)\",\"spanish\":\"Número de identificación personal\",\"definition\":\"A numeric password used to authenticate a user to a system.\",\"industry\":\"Customer Service\",\"example_en\":\"A new PIN will be sent in the mail.\",\"example_es\":\"Un nuevo número de identificación personal se le enviará por correo.\",\"source\":\"Customer Service\"},{\"english\":\"Pins and needles\",\"spanish\":\"Sensación de Hormigueo y Adormecimiento\",\"definition\":\"A sensation of uncomfortable tingling or prickling, usually felt in the hands or feet. A common cause is leaning awkwardly on a limb, which presses against the nerves.\",\"industry\":\"Medical\",\"example_en\":\"The test shows that the pins and needles you are experiencing are caused by a pinched nerve.\",\"example_es\":\"La prueba muestra que la sensación de hormigueo y adormecimiento que está experimentando es causada por un nervio pellizcado.\",\"source\":\"Customer Service\"},{\"english\":\"PIP (Personal Injury\\nProtection)\",\"spanish\":\"Protección contra daños personales /\\nCobertura contra daños personales\",\"definition\":\"This coverage provides personal injuries benefits in states with no-fault laws. Coverage usually applies to the insured, all members of the insured’s household, any passengers and any pedestrian struck by an insured’s vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The medical claims for you and the others injured in the accident will be covered by the PIP portion of your policy.\",\"example_es\":\"Los reclamos médicos para usted y de los demás lesionados en el accidente serán cubiertos por la protección contra daños personales de su póliza.\",\"source\":\"Customer Service\"},{\"english\":\"PLAAFP (Present Level of Academic Achievement and Functional Performance)\",\"spanish\":\"Niveles actuales de logro académico y desempeño funcional\",\"definition\":\"The purpose of the PLAAFP is to identify the kinds and amount of special education services your child may need. The very first PLAAFP for your child describes his skills and abilities based on his initial special education evaluation.\",\"industry\":\"School\",\"example_en\":\"The Present Levels of Academic Achievement and Functional Performance statement (PLAAFP) are a key part of your child’s Individualized Education Program (IEP).\",\"example_es\":\"La declaración de los niveles actuales de logro académico y desempeño funcional son una parte clave del programa de educación individualizada de su hijo.\",\"source\":\"Customer Service\"},{\"english\":\"Plumbing\",\"spanish\":\"Fontanería /\\nGasfitería /\\nPlomería /\\nCañería\",\"definition\":\"The system of pipes, tanks, fittings, and other apparatus required for the water supply, heating, and sanitation in a building.\",\"industry\":\"General\",\"example_en\":\"We did all the plumbing work in our house ourselves.\",\"example_es\":\"Nosotros mismos hicimos todo el trabajo de fontanería en nuestra casa.\",\"source\":\"Customer Service\"},{\"english\":\"PMI (Private mortgage insurance)\",\"spanish\":\"Seguro hipotecario privado\",\"definition\":\"Private mortgage insurance (PMI) is a type of mortgage insurance you might be required to buy if you take out a conventional loan with a down payment of less than 20 percent of the purchase price.\",\"industry\":\"Finance\",\"example_en\":\"PMI protects the lender, not you, if you stop making payments on your loan.\",\"example_es\":\"El Seguro hipotecario privado protege al prestamista, no a usted, si deja de hacer los pagos de su préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Point of impact\",\"spanish\":\"Punto de impacto\",\"definition\":\"Part of an object where an impact has taken place.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I need to know the exact point of impact of the two vehicles involved in the accident.\",\"example_es\":\"Necesito saber el punto de impacto exacto de los dos vehículos involucrados en el accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Policy\",\"spanish\":\"Póliza\",\"definition\":\"A document detailing the terms and conditions of a contract of insurance.\",\"industry\":\"Insurance (general)\",\"example_en\":\"I am calling about my life insurance policy. It is a term policy and I believe I can surrender it in July. Is that right? I am going to need some money and that would be great if I can cash it in.\",\"example_es\":\"Estoy llamando sobre mi póliza de seguro de vida. Es una póliza temporal y creo que puedo cancelarla en julio. ¿Es eso correcto? Voy a necesitar dinero y sería genial si pudiera cobrarlo.\",\"source\":\"Customer Service\"},{\"english\":\"Policyholder\",\"spanish\":\"Titular de la póliza /\\nPólizahabiente\",\"definition\":\"A person or group in whose name an insurance policy is held.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Who is the policyholder, you or your husband?\",\"example_es\":\"¿Quién es el titular/polizahabiente? ¿Usted o su esposo?\",\"source\":\"Customer Service\"},{\"english\":\"Power brakes\",\"spanish\":\"Frenos de potencia\",\"definition\":\"Refers to a system of hydraulics used to slow down or stop most motor vehicles\",\"industry\":\"Auto Insurance\",\"example_en\":\"If the car has power brakes, run the engine while performing this procedure.\",\"example_es\":\"Si el vehículo tiene frenos de potencia, encienda el motor durante este procedimiento.\",\"source\":\"Customer Service\"},{\"english\":\"Power trunk\",\"spanish\":\"Maletero automático\",\"definition\":\"Refers to a vehicle's power operated trunk.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I wouldn't call it a fender bender, because after the accident the power trunk stopped working.\",\"example_es\":\"No lo llamaría un choque leve, ya que después del accidente el maletero automático dejó de funcionar.\",\"source\":\"Customer Service\"},{\"english\":\"PPO (Preferred Provider Organization)\",\"spanish\":\"Organización de Proveedores Preferenciales /\\nOrganización de proveedores Preferentes\",\"definition\":\"A preferred provider organization (PPO) is a managed care organization of health providers who contract with an insurer or third-party administrator (TPA) to provide health  coverage to policy holders represented by the insurer or TPA.\",\"industry\":\"Health Insurance\",\"example_en\":\"Because you have a PPO plan, you do not need a referral to see a specialist.\",\"example_es\":\"Debido a que tiene un plan de Organización de Proveedores Preferenciales usted no necesita una remisión para ver a un especialista.\",\"source\":\"Customer Service\"},{\"english\":\"Pre-approved\",\"spanish\":\"Pre-aprobado /\\nPreviamente aprobado\",\"definition\":\"To approve an applicant for a loan, for example) in advance, sometimes even before an application is submitted.\",\"industry\":\"Finance\",\"example_en\":\"The council keeps a list of preapproved contractors that departments can hire.\",\"example_es\":\"El consejo mantiene una lista de contratistas preaprobados que los departamentos pueden contratar.\",\"source\":\"Customer Service\"},{\"english\":\"Pre-approved loan\",\"spanish\":\"Préstamo preaprobado\",\"definition\":\"When you’re pre-approved for a loan, it means the lender provisionally agrees to lend you the money, based on the preliminary information you give them.\",\"industry\":\"Finance\",\"example_en\":\"Get to learn about the eligibility criteria, and the process to avail a pre-approved loan.\",\"example_es\":\"Conozca los criterios de elegibilidad y el proceso para aprovechar un préstamo preaprobado.\",\"source\":\"Customer Service\"},{\"english\":\"Precinct\",\"spanish\":\"Comisaría\",\"definition\":\"The police station situated in and having jurisdiction over a subdivision or district of a city or town.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The suspect was taken to the local precinct.\",\"example_es\":\"El sospechoso fue llevado a la comisaría local.\",\"source\":\"Customer Service\"},{\"english\":\"Preferred language\",\"spanish\":\"Idioma de preferencia\",\"definition\":\"The self-identified language, which the client prefers to use in a service or any other encounter.\",\"industry\":\"Customer Service\",\"example_en\":\"Their preferred language is French.\",\"example_es\":\"Su idioma de preferencia es el francés.\",\"source\":\"Customer Service\"},{\"english\":\"Preferred shop\",\"spanish\":\"Taller preferido /\\nTaller de preferencia\",\"definition\":\"Shop used by auto insurance companies to refer their clients to, formally or informally.  These usually have an established history of excellent service.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The car was taken to the preferred shop, which  is an auto repair shop pre-approved by your insurance company that participates in a direct repair program.\",\"example_es\":\"El coche fue llevado al taller preferido, que es un taller de reparación de automóviles preaprobado por su compañía de seguros que participa en un programa de reparación directa.\",\"source\":\"Customer Service\"},{\"english\":\"Premium (context dependent)\",\"spanish\":\"Prima /\\nPrima del seguro /\\nCuota del seguro\",\"definition\":\"The cost of an insurance policy; the consideration paid by the insured to the insurer for protection.\",\"industry\":\"Insurance (general)\",\"example_en\":\"The premium or cost of the car insurance will be approximately $150 per month.\",\"example_es\":\"La prima o costo del seguro será aproximadamente de $150 por mes.\",\"source\":\"Customer Service\"},{\"english\":\"Prescribed\",\"spanish\":\"Recetado (NO PRESCRITO)\",\"definition\":\"When a practitioner advises and authorizes the use of a medicine or treatment for someone, especially in writing.\",\"industry\":\"Medical\",\"example_en\":\"I do not remember if the doctor prescribed Diazepam of 5 or 10 mgs.\",\"example_es\":\"No recuerdo si el doctor me ha recetado Diazepam de 5 o de 10 miligramos.\",\"source\":\"Customer Service\"},{\"english\":\"Prescription drug /\\nPrescription medication\",\"spanish\":\"Fármaco recetado / con receta\\nMedicamento recetado / con receta\",\"definition\":\"A prescription drug is a pharmaceutical drug that is permitted to be dispensed only to those with a medical prescription.\",\"industry\":\"Health Insurance\",\"example_en\":\"The co-payments per visit and prescription drugs were higher this year.\",\"example_es\":\"Los copagos por visita y medicamentos recetados fueron mayores este año.\",\"source\":\"Customer Service\"},{\"english\":\"Pressure-cooker\",\"spanish\":\"Olla a presión\",\"definition\":\"A pressure cooker is a sealed chamber that traps the steam generated as its contents are heated. As steam builds, pressure increases, driving the boiling point of water. In general, this higher temperature shortens cooking times.\",\"industry\":\"General\",\"example_en\":\"I cooked a delicious stew in the pressure-cooker.\",\"example_es\":\"Cociné un guiso delicioso en la olla a presión.\",\"source\":\"Customer Service\"},{\"english\":\"Preventive care\",\"spanish\":\"Cuidados preventivos\",\"definition\":\"Preventive care helps detect or prevent serious diseases and medical problems before they can become major. Annual check-ups, immunizations, and flu shots, as well as certain tests and screenings, are a few examples of preventive care. This may also be called routine care.\",\"industry\":\"Medical\",\"example_en\":\"Immunizations are considered preventive care.\",\"example_es\":\"Las vacunas son consideradas como cuidados preventivos.\",\"source\":\"Customer Service\"},{\"english\":\"Procedural safeguards\",\"spanish\":\"Amparo procesal / \\nGarantías procesales /\\nSalvaguardias procesales\",\"definition\":\"Procedural safeguards to protect the rights of children with disabilities and their parents. These safeguards include the right to participate in all meetings, to examine all educational records, and to obtain an independent educational evaluation (IEE) of the child.\",\"industry\":\"School\",\"example_en\":\"Under the Individuals with Disabilities Education Act (IDEA), you and your child have legal protections during the evaluation and IEP process. These protections are called procedural safeguards.\",\"example_es\":\"Según la Ley para la Educación de las Personas Discapacitadas, usted y su hijo tienen protecciones legales durante la evaluación y el proceso del programa de educación individualozado. Estas protecciones se denominan amparos procesales.\",\"source\":\"Customer Service\"},{\"english\":\"Process\",\"spanish\":\"Proceso /\\nTrámite\",\"definition\":\"A series of actions that produce something or that lead to a particular result.\",\"industry\":\"Social Services\",\"example_en\":\"The review process takes 30 days.\",\"example_es\":\"El proceso de revisión tarda 30 días.\",\"source\":\"Customer Service\"},{\"english\":\"Processing fee\",\"spanish\":\"Cuota/cargo/costo de procesamiento /\\nCuota/cargo/costo por tramitación\",\"definition\":\"Charges for paperwork services or miscellaneous services, incurred in the course of business transactions.\",\"industry\":\"Finance\",\"example_en\":\"You agree to pay the Operator  the processing fee and any other fee that may apply.\",\"example_es\":\"Usted se compromete a pagar al Operador el costo de procesamiento y cualquier otro cargo que pueda aplicarse.\",\"source\":\"Customer Service\"},{\"english\":\"Prompt fading\",\"spanish\":\"Desvanecimiento de la ayuda /\\nExtinción\",\"definition\":\"Prompt fading is the process of gradually reducing the level, magnitude, timing, etc. of prompts to work towards independence.\",\"industry\":\"School\",\"example_en\":\"When they are ready to be more independent, prompt fading can be gradually applied.\",\"example_es\":\"Cuando ellos estén listos para ser más independientes, se puede aplicar gradualmente un desvanecimiento de la ayuda.\",\"source\":\"Customer Service\"},{\"english\":\"Prompting\",\"spanish\":\"Incitación\",\"definition\":\"Prompting is a technique that uses questions or other stimuli to motivate people to perform a certain action or to remember something in particular.\",\"industry\":\"School\",\"example_en\":\"Prompting is a way to get student's attention and make them act in a certain way.\",\"example_es\":\"La incitación es una forma de llamar la atención de los estudiantes y hacerlos actuar de cierta manera.\",\"source\":\"Customer Service\"},{\"english\":\"Proof\",\"spanish\":\"Comprobante /\\nPrueba\",\"definition\":\"Evidence that establishes or helps to establish the truth, validity, quality of something.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Do they have any proof that it was Hampson who stole the goods?\",\"example_es\":\"¿Tienen alguna prueba de que fue Hampson quien robó la mercancía?\",\"source\":\"Customer Service\"},{\"english\":\"Proof of income\",\"spanish\":\"Comprobante de ingresos /\\nPrueba de ingresos\",\"definition\":\"Document that proves how much a person earns.\",\"industry\":\"Social Services\",\"example_en\":\"Based on program guidelines, a proof of income may be required for program approval.\",\"example_es\":\"En función de las directrices del programa, es posible que se exija una prueba de ingresos para la aprobación del programa.\",\"source\":\"Customer Service\"},{\"english\":\"Property tax\",\"spanish\":\"Impuestos a la propiedad\",\"definition\":\"A property tax is primarily levied on immovable property like land and buildings, as well as on tangible personal property that is movable, like vehicles and equipment.\",\"industry\":\"Finance\",\"example_en\":\"Property taxes are the single largest source of state and local revenue in the U.S., and help fund schools, roads, police, and other services.\",\"example_es\":\"Los impuestos a la propiedad son la mayor fuente de ingresos estatales y locales en los Estados Unidos, y ayudan a financiar escuelas, carreteras, policía y otros servicios.\",\"source\":\"Customer Service\"},{\"english\":\"Prorated\",\"spanish\":\"Prorrateado /\\nCobro proporcional\",\"definition\":\"Payment divided in a proportional way based on time of usage. If you use something for less time than you're scheduled to use it for, it's fair to expect that you'll only be charged for the time you used.\",\"industry\":\"Customer Service\",\"example_en\":\"With prorated billing, charges are calculated based on the cost per day.\",\"example_es\":\"Con la facturación prorrateada, los cargos son calculados basados en el costo por día.\",\"source\":\"Customer Service\"},{\"english\":\"Provider\",\"spanish\":\"Proveedor(a)\",\"definition\":\"Someone that provides a service, such as a health care provider.\",\"industry\":\"Health Insurance\",\"example_en\":\"The provider will examine you now.\",\"example_es\":\"El proveedor lo examinará ahora.\",\"source\":\"Customer Service\"},{\"english\":\"Public safety answering point (PSAP)\",\"spanish\":\"Punto de respuesta de seguridad pública\",\"definition\":\"An entity responsible for receiving 911 calls and processing those calls according to a specific operational policy.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Public Safety Answering Points (PSAPs) are also known as 911 call centers.\",\"example_es\":\"Los puntos de respuesta de seguridad pública también son conocidos como centros de llamadas del 911.\",\"source\":\"Customer Service\"},{\"english\":\"Purchase\",\"spanish\":\"Compra\",\"definition\":\"To get (something) by paying money for it\",\"industry\":\"General\",\"example_en\":\"The interest on purchases is 19.99%.\",\"example_es\":\"El interés sobre las compras es 19.99%.\",\"source\":\"Customer Service\"},{\"english\":\"Qualify (verb)\",\"spanish\":\"Calificar\",\"definition\":\"To meet the necessary requirements to receive a service, loan, or position.\",\"industry\":\"Social Services\",\"example_en\":\"Unfortunately, you do not qualify for Medicaid due to your high income.\",\"example_es\":\"Desafortunadamente usted no califica para Medicaid debido a sus altos ingresos.\",\"source\":\"Customer Service\"},{\"english\":\"Quarter\",\"spanish\":\"Trimestre\",\"definition\":\"Taking place four times a year. A period of time consisting of three months.\",\"industry\":\"General\",\"example_en\":\"The economy entered a low-growth phase in the first quarter of the year.\",\"example_es\":\"La economía entró en una fase de bajo crecimiento en el primer trimestre del año.\",\"source\":\"Customer Service\"},{\"english\":\"Quarter panel (rear/front/right/left)\",\"spanish\":\"Panel (frontal/ trasero/ izquierdo/ derecho) /\\nPanel posterior o delantero, e izquierdo o derecho /\\nCuarta sección trasera o frontal e izquierda o derecha / \\nAleta (regionalism)\",\"definition\":\"A quarter panel refers to any body panel (exterior surface) of an automobile.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The rear quarter panel sustained extensive damage. He hit the left rear panel on my car with his truck.\",\"example_es\":\"El panel trasero, sufrió extensos daños.  Él golpeó el panel trasero izquierdo de mi carro con su camioneta.\",\"source\":\"Customer Service\"},{\"english\":\"Quote\",\"spanish\":\"Cotización (NO CUOTA)\",\"definition\":\"Information about the cost of an insurance policy given to the prospective insured by the insurance company.\",\"industry\":\"Insurance (general)\",\"example_en\":\"I can give you a quote for a 6 or 12 month policy which will tell you how much you will pay each month or year.\",\"example_es\":\"Le puedo dar una cotización para una póliza de 6 o 12 meses que le indicará cuanto pagará cada mes\",\"source\":\"Customer Service\"},{\"english\":\"Rash\",\"spanish\":\"Erupción /\\nUrticaria /\\nSarpullido\",\"definition\":\"Refers to breaking out (eruption) of the skin. A rash can be caused by an underlying  condition, hormonal cycles, allergies, or contact with irritating substances.\",\"industry\":\"Medical\",\"example_en\":\"Every time I eat oranges, I get a rash.\",\"example_es\":\"Cada vez que como naranjas me sale un sarpullido.\",\"source\":\"Customer Service\"},{\"english\":\"Re-qualify\",\"spanish\":\"Calificar de nuevo /\\nVolver a calificar\",\"definition\":\"To show or meet the necessary requirements to continue to receive a service, loan, or position.\",\"industry\":\"Social Services\",\"example_en\":\"The case manager told me I have to re-qualify this week.\",\"example_es\":\"La gerente de caso me dijo que tengo que volver a calificar esta semana.\",\"source\":\"Customer Service\"},{\"english\":\"Real estate\",\"spanish\":\"Bienes raíces /\\nBienes inmuebles\",\"definition\":\"Real estate is property consisting of land and the buildings on it, along with its natural resources such as growing crops, minerals or water.\",\"industry\":\"Home Insurance\",\"example_en\":\"By investing in real estate, he was one of the richest men in the United States.\",\"example_es\":\"Invirtiendo en bienes raíces, fue uno de los hombres más ricos en los Estados Unidos.\",\"source\":\"Customer Service\"},{\"english\":\"Real estate agent\",\"spanish\":\"Agente inmobiliario\",\"definition\":\"Real estate agents are licensed professionals who get compensated for representing buyers and sellers in property transactions.\",\"industry\":\"Home Insurance\",\"example_en\":\"After graduating from high school, he became a real estate agent and spent a number of years selling commercial real estate.\",\"example_es\":\"Después de graduarse de la escuela secundaria, se convirtió en un agente inmobiliario y pasó varios años vendiendo bienes raíces comerciales.\",\"source\":\"Customer Service\"},{\"english\":\"Rear view mirror\",\"spanish\":\"Espejo retrovisor\",\"definition\":\"A small angled mirror fixed inside the windshield of a motor vehicle, enabling the driver to see the vehicle or road behind.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I tried to adjust the rearview mirror and it fell off.\",\"example_es\":\"Traté de ajustar el espejo retrovisor y se cayó.\",\"source\":\"Customer Service\"},{\"english\":\"Rear-end (verb)\",\"spanish\":\"Choque por detrás /\\nGolpe por detrás /\\nChoque trasero\",\"definition\":\"A traffic accident where a vehicle crashes into the vehicle in front of it.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I was rear-ended on my way home.\",\"example_es\":\"Me chocaron por detrás cuando estaba de camino a casa.\",\"source\":\"Customer Service\"},{\"english\":\"Recall\",\"spanish\":\"Retirar / \\nRetirar del mercado\",\"definition\":\"When a company recalls a product, they ask the shops or the people who have bought that product to return it because there is something wrong with it.\",\"industry\":\"Customer Service\",\"example_en\":\"The company recalled the defective auto tires.\",\"example_es\":\"La empresa retiró los neumáticos defectuosos.\",\"source\":\"Customer Service\"},{\"english\":\"Receipt\",\"spanish\":\"Recibo\",\"definition\":\"A receipt is a written acknowledgment that a specified article or payment has been received.\",\"industry\":\"Customer Service\",\"example_en\":\"Would you like a copy of your receipt?\",\"example_es\":\"¿Le gustaría una copia de su recibo?\",\"source\":\"Customer Service\"},{\"english\":\"Reckless driving\",\"spanish\":\"Manejar de forma imprudente /\\nConducción temeraria\",\"definition\":\"Major moving violation related to aggressive driving which unreasonably interferes with the free and proper use of the public highway, or unreasonably endangers other drivers or pedestrians.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"In New York, reckless driving is considered a misdemeanor and not a felony, however, the possible consequences might be significant.\",\"example_es\":\"En Nueva York, manejar de forma imprudente es considerado un delito menor y no un delito grave; sin embargo, las posibles consecuencias pueden ser significativas.\",\"source\":\"Customer Service\"},{\"english\":\"Recorded\",\"spanish\":\"Grabado\",\"definition\":\"The act or process of storing sounds or images on tape or a disk.\",\"industry\":\"General\",\"example_en\":\"This call may be recorded for quality assurance purposes.\",\"example_es\":\"Esta llamada pudiera ser grabada para propósitos de control de calidad.\",\"source\":\"Customer Service\"},{\"english\":\"Recorded statement\",\"spanish\":\"Declaración grabada\",\"definition\":\"A formal oral declaration, usually taken within hours or days after a loss or accident, especially with regard to facts or claims. The statements are audio recorded by an adjuster.\",\"industry\":\"Insurance (general)\",\"example_en\":\"We will need to take a recorded statement from both drivers involved in the accident.\",\"example_es\":\"Necesitaremos tomar una declaración grabada de ambos conductores involucrados en el accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Records\",\"spanish\":\"Expedientes, registros\",\"definition\":\"Official document that gives/contains information. A  document or set of documents that memorializes and  provides objective evidence of activities performed, events  occurred, results achieved, or statements made.\",\"industry\":\"General\",\"example_en\":\"According to our records, you have not made a payment since last July and you need to bring the account current.\",\"example_es\":\"De acuerdo a nuestros registros, usted no ha hecho un pago desde julio y necesita poner la cuenta al día.\",\"source\":\"Customer Service\"},{\"english\":\"Red-eye flight\",\"spanish\":\"Vuelo nocturno\",\"definition\":\"In commercial aviation, a red-eye flight refers to a flight that departs at night and arrives the next morning, especially when the total flight time is insufficient for passengers to get a full night's sleep.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"I took the red-eye flight from California to New York last night and now I am exhausted.\",\"example_es\":\"Anoche tomé un vuelo nocturno de California a Nueva York y ahora estoy agotado.\",\"source\":\"Customer Service\"},{\"english\":\"Reduce /\\nBring down\",\"spanish\":\"Reducir\",\"definition\":\"To make (something) smaller in size, amount, number, etc.\",\"industry\":\"General\",\"example_en\":\"A modification may reduce your monthly loan payment.\",\"example_es\":\"Una modificación puede reducir su pago mensual del préstamo.\",\"source\":\"Customer Service\"},{\"english\":\"Refer\",\"spanish\":\"Referir /\\nRemitir\",\"definition\":\"To send (someone or something) to a particular person or  place for treatment, help, advice, etc.\\nRefers to the process of directing or redirecting a patient to an appropriate specialist or agency for definitive treatment, aid. Information or decision\",\"industry\":\"General\",\"example_en\":\"To help you lose weight, I can refer you to a nutritionist who can help you plan your meals; I also suggest you join a gym and start working out at least 5 days a week.\",\"example_es\":\"Para ayudarle a perder peso, le puedo referir a un nutricionista que le puede ayudar a planear sus comidas; también le sugiero que se inscriba en un gimnasio y empiece a hacer ejercicio por lo menos 5 días a la semana\",\"source\":\"Customer Service\"},{\"english\":\"Reference\",\"spanish\":\"Referencia\",\"definition\":\"A unique identifier such as a number, assigned to any transaction to locate and obtain specific information.\",\"industry\":\"Customer Service\",\"example_en\":\"A reference number is a unique identifier assigned to any financial transaction including those made using a credit or debit card.\",\"example_es\":\"Un número de referencia es una identificación única, asignada a toda transacción, incluyendo aquellas realizadas usando una tarjeta de débito o crédito.\",\"source\":\"Customer Service\"},{\"english\":\"Referral\",\"spanish\":\"Referido /\\nRemisión /\\nDerivación\",\"definition\":\"Instructions given to a patient directing or redirecting their case to an appropriate specialist or agency for definitive treatment.\",\"industry\":\"Medical\",\"example_en\":\"I will give you a referral to a cardiologist.\",\"example_es\":\"Le daré una remisión a un cardiólogo.\",\"source\":\"Customer Service\"},{\"english\":\"Refill\",\"spanish\":\"Resurtir /\\nVolver a surtir\",\"definition\":\"To fill a prescription again. Something provided again; a second or later filling of a medical prescription.\",\"industry\":\"Medical\",\"example_en\":\"How many times can I refill the medication you prescribed or do I need a new prescription every month?\",\"example_es\":\"¿Cuántas veces puedo volver a surtir el medicamento que me recetó o necesito una nueva receta cada mes?\",\"source\":\"Customer Service\"},{\"english\":\"Refund\",\"spanish\":\"Reembolso\",\"definition\":\"To give money back, especially when someone isn't satisfied with an item they bought or the service they got.\",\"industry\":\"Customer Service\",\"example_en\":\"If you still have your receipt, you may take the appliance to the store and they can give you a refund.\",\"example_es\":\"Si todavía tiene su recibo, puede llevar el electrodoméstico a la tienda y le podrán dar un reembolso.\",\"source\":\"Customer Service\"},{\"english\":\"Registered\",\"spanish\":\"Registrada(o) / \\nMatriculada(o) /\\nCertificada (o) /\\nInscribió /\\nRegistró /\\nCertificó\",\"definition\":\"Recorded, as in a register, list or book, enrolled.\",\"industry\":\"Social Services\",\"example_en\":\"Please provide the email address you used when you first registered your account.\",\"example_es\":\"Por favor suministre el correo electrónico que usó cuando inscribió la cuenta por primera vez.\",\"source\":\"Customer Service\"},{\"english\":\"Reimbursement\",\"spanish\":\"Reembolso\",\"definition\":\"Reimbursement is money paid to an employee or customer, or another party, as repayment for a business expense, insurance, taxes, or other costs.\",\"industry\":\"General\",\"example_en\":\"Employees can apply for reimbursement of travel expenses.\",\"example_es\":\"Los empleados pueden solicitar el reembolso de los viáticos.\",\"source\":\"Customer Service\"},{\"english\":\"Reinstatement\",\"spanish\":\"Restablecimiento / Restitución / \\nReinstauración\",\"definition\":\"The process by which an insurance company puts a policy back in force after it lapsed because of nonpayment of renewal premiums.\",\"industry\":\"Insurance (general)\",\"example_en\":\"If you meet the necesary requirements, we will proceed with the reinstatement of your insurance policy.\",\"example_es\":\"Si cumple con los requisitos necesarios, procederemos con el restablecimiento de su póliza de seguro.\",\"source\":\"Customer Service\"},{\"english\":\"Relationship\",\"spanish\":\"Relación\",\"definition\":\"The way in which two or more people or things are connected.\",\"industry\":\"General\",\"example_en\":\"What is your relationship to the patient and the medical record number?\",\"example_es\":\"¿Cuál es su relación con el paciente y el número de registro médico?\",\"source\":\"Customer Service\"},{\"english\":\"Renewal\",\"spanish\":\"Renovación\",\"definition\":\"The act of extending the period of time when something is effective or valid: the act of renewing something.\",\"industry\":\"Customer Service\",\"example_en\":\"You need to renew your driver's license before it expires.\",\"example_es\":\"Necesita renovar su licencia de conducir antes de que se venza.\",\"source\":\"Customer Service\"},{\"english\":\"Rent\",\"spanish\":\"Alquilar (NO RENTA)\",\"definition\":\"To obtain occupancy or use of (another's property) in return for regular payments.\",\"industry\":\"General\",\"example_en\":\"Do you rent or own your home? If you rent, I need the name and other contact information of the owner of the property.\",\"example_es\":\"¿Alquila o es dueño de su casa? Si alquila, necesito el nombre y otra información de contacto del dueño de la propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Repairs\",\"spanish\":\"Reparaciones /\\nArreglos\",\"definition\":\"To restore to sound condition after damage.\",\"industry\":\"Auto Insurance\",\"example_en\":\"When will the repairs to my car be completed? I need my car to go to work as the bus service is very slow where I live.\",\"example_es\":\"¿Cuándo serán terminadas las reparaciones de mi carro? Necesito mi carro para ir al trabajo ya que el servicio de bus es muy lento donde yo vivo.\",\"source\":\"Customer Service\"},{\"english\":\"Replace (verb)\",\"spanish\":\"Reemplazar\",\"definition\":\"To provide a substitute for something broken or unsatisfactory.\",\"industry\":\"Customer Service\",\"example_en\":\"They replaced the roof, which was damage during the hurricane.\",\"example_es\":\"Reemplazaron el techo que fue dañado durante el huracán.\",\"source\":\"Customer Service\"},{\"english\":\"Report\",\"spanish\":\"Reporte /\\ninforme\",\"definition\":\"An account given of a particular matter, especially in the form of an official document, after thorough investigation or consideration by an appointed person or body.\",\"industry\":\"General\",\"example_en\":\"According to the police report, you were standing on the corner when the fire began.\",\"example_es\":\"Según el informe de la policía usted estaba parado en la esquina cuando empezó el incendio.\",\"source\":\"Customer Service\"},{\"english\":\"Report card\",\"spanish\":\"Boleta de calificaciones\",\"definition\":\"A report card communicates a student's performance academically. In most places, the report card is issued by the school to the student or the student's parents once to four times yearly.\",\"industry\":\"School\",\"example_en\":\"His report card pointed up his talent for math.\",\"example_es\":\"Su boleta de calificaciones destacó su talento para las matemáticas.\",\"source\":\"Customer Service\"},{\"english\":\"Request\",\"spanish\":\"Solicitar /\\nPedir\",\"definition\":\"To make a request to or of.\",\"industry\":\"Social Services\",\"example_en\":\"I requested a loan modification and I haven't received it.\",\"example_es\":\"Solicité una modificación de préstamo y no la he recibido.\",\"source\":\"Customer Service\"},{\"english\":\"Requirements\",\"spanish\":\"Requisitos\",\"definition\":\"A prerequisite, something that is required or needed to qualify for something, or to complete a task.\",\"industry\":\"Social Services\",\"example_en\":\"I would like to refinance my home; what are the requirements and how soon can I start the process?\",\"example_es\":\"Quisiera refinanciar mi casa; ¿cuáles son los requisitos y que tan rápido puedo empezar el proceso?\",\"source\":\"Customer Service\"},{\"english\":\"Reservation\",\"spanish\":\"Reservación\",\"definition\":\"An arrangement by which accommodations are secured in advance, as in a hotel or restaurant or on an airplane.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"Your reservation is confirmed for 6 nights at the Disney Resort Hotel beginning on July 1st.\",\"example_es\":\"Su reservación está confirmada para 6 noches en el Disney Resort Hotel empezando el primero de julio.\",\"source\":\"Customer Service\"},{\"english\":\"Reside (verb)\",\"spanish\":\"Residir /\\nVivir\",\"definition\":\"Have one's permanent home in a particular place, be situated.\",\"industry\":\"Customer Service\",\"example_en\":\"Where do you currently reside? Do any other family members live with you?\",\"example_es\":\"¿Dónde vive actualmente? ¿Algunos otros familiares viven con usted?\",\"source\":\"Customer Service\"},{\"english\":\"Resources\",\"spanish\":\"Recursos\",\"definition\":\"An amount of money that is used for a special purpose\",\"industry\":\"General\",\"example_en\":\"You do not have enough resources to qualify for that type of home.\",\"example_es\":\"No tiene suficientes recursos para calificar a ese tipo de préstamos.\",\"source\":\"Customer Service\"},{\"english\":\"Restraining order\",\"spanish\":\"Orden de alejamiento\",\"definition\":\"A legally binding order of the court, enforceable by law enforcement officials as well as the court. Such protective orders are issued, not only to protect victims from violence, but from other forms of abuse, nuisance, and stalking.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"There are many steps to follow in order to get a domestic violence restraining order.\",\"example_es\":\"Hay varios pasos a seguir para obtener una orden de restricción por violencia doméstica.\",\"source\":\"Customer Service\"},{\"english\":\"Retirement\",\"spanish\":\"Jubilación\",\"definition\":\"Ceasing to work from active working life. The time of life when someone chooses to permanently leave the workforce behind.\",\"industry\":\"Social Services\",\"example_en\":\"The average retirement age in the US is 64, and the average retirement age in all states ranges from 61 to 67.\",\"example_es\":\"La edad promedio de jubilación en los EE. UU. es 64 años, y la edad promedio de jubilación en todos los estados oscila entre 61 y 67 años.\",\"source\":\"Customer Service\"},{\"english\":\"Reverse\",\"spanish\":\"Ir retrocediendo /\\nIr en reversa /\\nRetroceder\",\"definition\":\"To move backwards.\",\"industry\":\"Auto Insurance\",\"example_en\":\"When I put the car into reverse, I backed up into another car. It was not intentional as I did not see the other car.\",\"example_es\":\"Cuando puse el carro en reversa, retrocedí contra otro carro. No fue intencionalmente ya que yo no vi el otro carro.\",\"source\":\"Customer Service\"},{\"english\":\"Rideshare coverage\",\"spanish\":\"Cobertura de red de transporte / \\nCobertura de viajes compartidos\",\"definition\":\"Rideshare coverage protects you and your vehicle if you drive for a ridesharing service such as Uber or Lyft.\",\"industry\":\"Auto Insurance\",\"example_en\":\"While affordable, adding rideshare coverage will increase the price of your personal auto policy.\",\"example_es\":\"Si bien es asequible, agregar la cobertura de red de transporte aumentará el precio de su póliza de automóvil personal.\",\"source\":\"Customer Service\"},{\"english\":\"Right of way\",\"spanish\":\"Derecho de paso /\\nDerecho de vía /\\nDerecho al paso\",\"definition\":\"A way of determining which vehicle, among two or more, will be allowed to continue on its path before the others.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I had the right of way. The other driver did not stop at the stop sign.\",\"example_es\":\"Yo tenía derecho de vía. El otro conductor no paró en la señal de alto.\",\"source\":\"Customer Service\"},{\"english\":\"Road conditions\",\"spanish\":\"Condiciones de la carretera\",\"definition\":\"Different factors that describe and determine the ease with which a road can be driven; such as the condition of the pavement, slippery road surface, puddles of water, mud or ice in each lane.\",\"industry\":\"Auto Insurance\",\"example_en\":\"What were the road conditions at the time of the accident?\",\"example_es\":\"¿Cuáles eran las condiciones de la carretera en el momento del accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Roadside assistance\",\"spanish\":\"Cobertura de asistencia en la\\ncarretera /\\nAsistencia vial\",\"definition\":\"An optional automobile insurance coverage that may be purchased for an additional premium; this coverage provides for gasoline, and some minor repairs.\",\"industry\":\"Auto Insurance\",\"example_en\":\"An optional coverage like Roadside Assistance can be added to your policy. This will help if your car breaks down or you have a flat tire, etc.\",\"example_es\":\"Una cobertura opcional como asistencia en carretera puede ser agregada a su póliza. Esto ayudará si su carro se descompone o si tiene una llanta desinflada, etc.\",\"source\":\"Customer Service\"},{\"english\":\"Robbery\",\"spanish\":\"Robo con violencia /\\nDelito de robo violento\",\"definition\":\"Robbery is the crime of taking or attempting to take something of value by force or threat of force or by putting the victim in fear.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"In many states, robbery is considered a felony.\",\"example_es\":\"En muchos estados el robo con violencia es considerado un delito mayor.\",\"source\":\"Customer Service\"},{\"english\":\"Rollator / \\nWalker with a seat\",\"spanish\":\"Andador con asiento\",\"definition\":\"A rollator consists of a frame with three or four large wheels, handlebars, and a built-in seat. It is mainly used for patients who need a walker only for balance but not for weight-bearing.\",\"industry\":\"Medical\",\"example_en\":\"If your condition requires you to stop and rest often, a rollator could be a better choice for you.\",\"example_es\":\"Si su condición requiere que usted se detenga y descanse con frecuencia, un andador con asiento podría ser una mejor elección para usted.\",\"source\":\"Customer Service\"},{\"english\":\"Rotavirus vaccine\",\"spanish\":\"Vacuna contra el rotavirus\",\"definition\":\"The rotavirus vaccine is the best way to protect your child against rotavirus disease, which can spread easily among infants and young children. The virus can cause severe watery diarrhea, vomiting, fever, and abdominal pain.\",\"industry\":\"Medical\",\"example_en\":\"The rotavirus vaccine is administered by putting drops in the child's mouth.\",\"example_es\":\"La vacuna contra el rotavirus se administra poniendo gotas en la boca del niño.\",\"source\":\"Customer Service\"},{\"english\":\"Round-trip\",\"spanish\":\"Viaje de ida y vuelta\",\"definition\":\"A trip from one place to another and back.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"I would like to purchase a round trip ticket from Los Angeles to Las Vegas near the end of December.\",\"example_es\":\"Quisiera comprar un boleto de ida y vuelta de Los Ángeles a Las Vegas a finales de diciembre.\",\"source\":\"Customer Service\"},{\"english\":\"Routing number\",\"spanish\":\"Número de ruta bancaria /\\nNúmero de identificación bancaria\",\"definition\":\"The routing number is a nine digit bank code which appears on the bottom of checks identifying the financial institution on which it was drawn.\",\"industry\":\"Finance\",\"example_en\":\"The routing number is the bank identification number and appears on the bottom left hand side of your check.\",\"example_es\":\"El número de ruta es el número de identificación del banco y aparece en la esquina inferior izquierda de su cheque.\",\"source\":\"Customer Service\"},{\"english\":\"Rubella \\n(German measles)\",\"spanish\":\"Rubéola \\n(Sarampión alemán)\",\"definition\":\"A usually mild contagious viral disease characterized by fever, mild upper respiratory congestion, and a fine red rash lasting a few days.\",\"industry\":\"Medical\",\"example_en\":\"Nowadays, less than 10 people in the United States have rubella each year.\",\"example_es\":\"Actualmente, menos de 10 personas en los Estados Unidos tienen rubeola cada año.\",\"source\":\"Customer Service\"},{\"english\":\"Running boards\",\"spanish\":\"Estribos /\\nEscalones \\n(para subirse a vehículos altos)\",\"definition\":\"A footboard extending along the side of a vehicle, typically found on trucks, SUVs, and some early models of automobiles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Our auto policy does not cover running boards or steps.\",\"example_es\":\"Nuestra póliza de automóviles no cubre estribos ni escalones.\",\"source\":\"Customer Service\"},{\"english\":\"Salvage value /\\nScrap value\",\"spanish\":\"Valor residual /\\nValor de rescate\",\"definition\":\"The value assigned by an insurer to property deemed beyond repair, or whose value is less than the actual cost of repair.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We can calculate the cost of labor and parts to fix or replace each affected item and estimate the salvage value of the total loss vehicle.\",\"example_es\":\"Podemos hacer un cálculo del costo de la mano de obra y las partes para arreglar o remplazar cada artículo dañado y calcular el valor residual del vehículo de pérdida total.\",\"source\":\"Customer Service\"},{\"english\":\"Sander\",\"spanish\":\"Lijadora\",\"definition\":\"A sander is a power tool used to smooth surfaces by abrasion with sandpaper. Sanders have a means to attach the sandpaper and a mechanism to move it rapidly contained within a housing with means to hand-hold it or fix it to a workbench.\",\"industry\":\"General\",\"example_en\":\"The sander was hand-operated and sanded the second and third axles.\",\"example_es\":\"La lijadora fue operada manualmente y lijó el segundo y tercer eje.\",\"source\":\"Customer Service\"},{\"english\":\"Sash window\",\"spanish\":\"Ventana de guillotina\",\"definition\":\"A sash window is a window which consists of two frames placed one above the other. The window can be opened by sliding one frame over the other. The sash is the movable part of the window that contains the glass panes.\",\"industry\":\"Home Insurance\",\"example_en\":\"The room has large sash windows on two of its sides.\",\"example_es\":\"La habitación tiene ventanas de guillotina grandes en dos de sus lados.\",\"source\":\"Customer Service\"},{\"english\":\"Satellite dish /\\nParabolic antennas\",\"spanish\":\"Antena parabólica\",\"definition\":\"Parabolic antennas, also referred to as \\\"dish\\\" antennas, had been in use long before satellite television. The term satellite dish was coined in 1978 during the beginning of the satellite television industry, and came to refer to dish antennas that send and/or receive signals from communications satellites.\",\"industry\":\"Customer Service\",\"example_en\":\"Last winter, he installed a satellite dish for his television set.\",\"example_es\":\"El instaló una antena parabólica el invierno pasado, para su equipo de televisión.\",\"source\":\"Customer Service\"},{\"english\":\"Savings account\",\"spanish\":\"Cuenta de ahorros\",\"definition\":\"A bank account that lets you store your money securely while typically earning interest. This means the bank pays you to keep your funds deposited.\",\"industry\":\"Finance\",\"example_en\":\"We offer 4% interest in our savings account.\",\"example_es\":\"Ofrecemos un 4% de interés en nuestras cuentas de ahorros.\",\"source\":\"Customer Service\"},{\"english\":\"Saw (n)\",\"spanish\":\"Sierra\",\"definition\":\"A hand tool for cutting wood or other materials, typically with a long, thin serrated steel blade and operated using a backward and forward movement.\",\"industry\":\"General\",\"example_en\":\"I used a saw to cut off the thick branches.\",\"example_es\":\"Usé una sierra para cortar las ramas gruesas.\",\"source\":\"Customer Service\"},{\"english\":\"Scalp\",\"spanish\":\"Cuero cabelludo\",\"definition\":\"The skin covering the head, excluding the face.\",\"industry\":\"Medical\",\"example_en\":\"Hair tonics will improve the condition of your hair and scalp.\",\"example_es\":\"Los tónicos capilares mejorarán la condición de su cabello y cuero cabelludo.\",\"source\":\"Customer Service\"},{\"english\":\"Scar\",\"spanish\":\"Cicatriz\",\"definition\":\"A mark that is left on your skin after a wound heals.\",\"industry\":\"Medical\",\"example_en\":\"The scar will not be very visible.\",\"example_es\":\"La cicatriz no será muy visible.\",\"source\":\"Customer Service\"},{\"english\":\"Schedule\",\"spanish\":\"Progammar /\\nAgendar\",\"definition\":\"To arrange or plan (an event) to take place at a particular time.\",\"industry\":\"Customer Service\",\"example_en\":\"If you need to schedule an appointment to renew your license plates, you must call from Monday to Friday.\",\"example_es\":\"Si desea programar una cita con para renovar sus placas, debe llamar de lunes a viernes.\",\"source\":\"Customer Service\"},{\"english\":\"Scholarship\",\"spanish\":\"Beca\",\"definition\":\"A scholarship is financial support awarded to a student, based on academic achievement or other criteria that may include financial need for the purpose of schooling.\",\"industry\":\"School\",\"example_en\":\"The organization is offering five $5,000 scholarships.\",\"example_es\":\"La organización está ofreciendo 5 becas de 5,000 dólares.\",\"source\":\"Customer Service\"},{\"english\":\"School desk\",\"spanish\":\"Pupitre\",\"definition\":\"A piece of furniture typically having a flat top for writing, reading, or using a computer, and often drawers or compartments.\",\"industry\":\"School\",\"example_en\":\"My school desk is cluttered with papers and books.\",\"example_es\":\"Mi pupitre está repleto de papeles y libros.\",\"source\":\"Customer Service\"},{\"english\":\"School District\",\"spanish\":\"Distrito escolar\",\"definition\":\"A school district is a geographical area including several schools, which are governed by one particular authority.\",\"industry\":\"School\",\"example_en\":\"Each village has a school district including a nursery for children between 3 and 5 years of age and a primary school with children aged from 6 to 11 years.\",\"example_es\":\"Cada pueblo tiene un distrito escolar, que incluye una guardería para niños de entre 3 y 5 años y una escuela primaria con niños de 6 a 11 años.\",\"source\":\"Customer Service\"},{\"english\":\"Scratch\",\"spanish\":\"Raspón /\\nRaya /\\nRaspadura\",\"definition\":\"Score or mark the surface of (something) with a sharp or pointed object.\",\"industry\":\"Medical\",\"example_en\":\"As I told the police, my girlfriend became jealous and scratched my car.\",\"example_es\":\"Como le dije a la policía, mi novia se puso celosa y rayó mi coche.\",\"source\":\"Customer Service\"},{\"english\":\"Screech\",\"spanish\":\"Chillido\",\"definition\":\"A loud shrill, harsh, or high-pitched sound.\",\"industry\":\"General\",\"example_en\":\"He was driving so fast that we could all hear the screech of brakes when he got to the traffic light.\",\"example_es\":\"Él manejaba tan rápido que todos pudimos oír el chillido de los frenos cuando llegó al semáforo.\",\"source\":\"Customer Service\"},{\"english\":\"Screening\",\"spanish\":\"Prueba de despistaje /\\nPrueba evaluatoria /\\nCribado\",\"definition\":\"A test designed to identify and eliminate those who are not affected by a disease.\",\"industry\":\"Medical\",\"example_en\":\"They perform regular screenings to rule out cervical cancer.\",\"example_es\":\"Ellos realizan pruebas de despistaje de manera regular para descartar cáncer de cuello uterino.\",\"source\":\"Customer Service\"},{\"english\":\"Search box\",\"spanish\":\"Casilla de búsqueda\",\"definition\":\"A rectangular field on screen that accepts typed-in text in order to look up something or launch a search for related information. Also called a \\\"search bar\\\".\",\"industry\":\"Customer Service\",\"example_en\":\"There was a typing mistake in the seach box, hence the faulty result.\",\"example_es\":\"Había un error de digitación en la casilla de búsqueda, de allí el resultado defectuoso.\",\"source\":\"Customer Service\"},{\"english\":\"Seasonal allergies\",\"spanish\":\"Alergias estacionales / Alergias de temporada\",\"definition\":\"Allergic responses that occur seasonally or year-round causing itchy, watery eyes, sneezing and other similar symptoms.\",\"industry\":\"Medical\",\"example_en\":\"Seasonal allergies symptoms can be reduced with antihistamine medication.\",\"example_es\":\"Los síntomas de las alergias estacionales se pueden reducir con medicamentos antihistamínicos.\",\"source\":\"Customer Service\"},{\"english\":\"Seatbelt\",\"spanish\":\"Cinturón de seguridad\",\"definition\":\"A belt or strap securing a person to prevent injury, especially in a vehicle or aircraft.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Were all of the passengers wearing their seatbelts at the time of the accident?\",\"example_es\":\"¿Todos sus pasajeros llevaban puesto el cinturón de seguridad en el momento del accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Section 504\",\"spanish\":\"Plan 504\",\"definition\":\"A 504 plan helps a child who meets the criteria for a disability that interferes with accessing their education. The 504 plan outlines accommodations and modifications that the student needs to ensure academic success and their ability to access their learning environment.\",\"industry\":\"School\",\"example_en\":\"Students with a 504 plan learn alongside their peers rather than receiving individualized special education instructions.\",\"example_es\":\"Los estudiantes con un plan 504 aprenden junto con sus compañeros en lugar de recibir instrucciones de educación especial individualizada.\",\"source\":\"Customer Service\"},{\"english\":\"Section 8\",\"spanish\":\"Sección 8\",\"definition\":\"Housing Authority section 8 provides rental assistance payments on behalf of eligible low-income individuals and families, including people who are elderly or have disabilities.\",\"industry\":\"Social Services\",\"example_en\":\"The Section 8 Housing authority program is the largest and most successful low-income housing assistance program in the country.\",\"example_es\":\"El programa de autoridad de vivienda - sección 8 es el programa de asistencia de vivienda para personas de bajos ingresos más grande y exitoso del país.\",\"source\":\"Customer Service\"},{\"english\":\"Security deposit\",\"spanish\":\"Depósito de seguridad\",\"definition\":\"A sum of money held in trust either as an initial part-payment in a purchasing process.\",\"industry\":\"Customer Service\",\"example_en\":\"As you are a new customer, we require a security deposit of $250 to set up your gas and electrical service.\",\"example_es\":\"Ya que es un nuevo cliente, requerimos un depósito de garantía de $250 para conectar el servicio de gas y electricidad.\",\"source\":\"Customer Service\"},{\"english\":\"Seizure\",\"spanish\":\"Ataque convulsivo /\\nEpisodio de convulsión\",\"definition\":\"A sudden attack with physical manifestations (as convulsions, sensory disturbances, or loss of consciousness) resulting from abnormal electrical discharges in the brain (as in epilepsy).\",\"industry\":\"Medical\",\"example_en\":\"Your medical record indicates you suffer from seizures.\",\"example_es\":\"Su expediente médico indica que usted padece de ataques convulsivos.\",\"source\":\"Customer Service\"},{\"english\":\"Self-Directed Learning\",\"spanish\":\"Aprendizaje autodirigido\",\"definition\":\"Self-directed learning refers to an education style where students are given the freedom to choose their own activities and experiences during the school day.\",\"industry\":\"School\",\"example_en\":\"Self-directed learning is usually much more informal than traditional education.\",\"example_es\":\"El aprendizaje autodirigido generalmente es mucho más informal que la educación tradicional.\",\"source\":\"Customer Service\"},{\"english\":\"Self-employment\",\"spanish\":\"Trabajo por cuenta propia /\\nTrabajo autónomo\",\"definition\":\"Earning one's livelihood directly from one's own trade or business rather than as an employee of another.\",\"industry\":\"Social Services\",\"example_en\":\"I prefer self-employment, I can set my own schedule.\",\"example_es\":\"Prefiero el trabajo autónomo, puedo establecer mi propio horario.\",\"source\":\"Customer Service\"},{\"english\":\"Self-pay\",\"spanish\":\"Autopago / \\nPagado por su cuenta\",\"definition\":\"To pay (something, such as a medical bill) with one's own money rather than money from another source (such as a medical insurance company)\",\"industry\":\"Health Insurance\",\"example_en\":\"Sir, since your medical insurance is showing as \\\"not active\\\", today´s visit will be marked as self-pay.\",\"example_es\":\"Señor, ya que su seguro médico se muestra como \\\"no activo\\\", su consulta de hoy se marcará como autopago.\",\"source\":\"Customer Service\"},{\"english\":\"Service fee\",\"spanish\":\"Cargo por servicio /\\nCuota por servicio\",\"definition\":\"An amount of money charged to provide a service.\",\"industry\":\"Customer Service\",\"example_en\":\"The company charges operators a five to 10 per cent service fee.\",\"example_es\":\"La compañía cobra a los operadores cinco a diez por ciento por cargo por servicio.\",\"source\":\"Customer Service\"},{\"english\":\"Service request\",\"spanish\":\"Petición de servicio /\\nPedido de servicio\",\"definition\":\"An act of asking for support or fulfillment of a service.\",\"industry\":\"Customer Service\",\"example_en\":\"Please file a service request in order to have that issue solved.\",\"example_es\":\"Por favor presente una petición de servicio a fin de que este problema sea resuelto.\",\"source\":\"Customer Service\"},{\"english\":\"Service upgrade\",\"spanish\":\"Mejora de servicios\",\"definition\":\"Refers to bump up or improve services by one or more levels upward.\",\"industry\":\"Customer Service\",\"example_en\":\"If you upgrade your phone services, an additional charge will appear every month.\",\"example_es\":\"Si usted mejora su servicio de teléfono, un cargo adicional aparecerá cada mes.\",\"source\":\"Customer Service\"},{\"english\":\"Settlement\",\"spanish\":\"Acuerdo\",\"definition\":\"A settlement, in the context of insurance, refers to a policy benefit or claims payment. The amount depends on the particular claim, the guidelines stipulated in the insurance policy, and the mutual agreement of the parties involved.\",\"industry\":\"Insurance (general)\",\"example_en\":\"As part of their divorce settlement, Jeff agreed to let Polly keep the house.\",\"example_es\":\"Como parte de su acuerdo de divorcio, Jeff estuvo de acuerdo en dejar que Polly se quedara con la casa.\",\"source\":\"Customer Service\"},{\"english\":\"Severity\",\"spanish\":\"Gravedad\",\"definition\":\"Condition that exacerbates. Serious or unpleasant condition.\",\"industry\":\"General\",\"example_en\":\"Due to the severity of their child’s disability, they are unable to work outside the home.\",\"example_es\":\"Debido a la gravedad de la discapacidad de su hijo, no pueden trabajar fuera de casa.\",\"source\":\"Customer Service\"},{\"english\":\"Sewage\",\"spanish\":\"Aguas residuales /\\nAguas negras /\\nAguas servidas\",\"definition\":\"Waste matter from domestic or industrial establishments that is carried away in sewers or drains for dumping or conversion into a form that is not toxic.\",\"industry\":\"Customer Service\",\"example_en\":\"The sewage is coming up through the kitchen sink so please send a plumber right away.\",\"example_es\":\"Las aguas residuales están subiendo por el lavadero de la cocina así que por favor envíe a un plomero rápidamente.\",\"source\":\"Customer Service\"},{\"english\":\"Sewer\",\"spanish\":\"Alcantarillado\",\"definition\":\"An underground conduit for carrying off drainage water and waste matter.\",\"industry\":\"Customer Service\",\"example_en\":\"The sewer carries away sewage.\",\"example_es\":\"El alcantarillado se lleva las aguas residuales.\",\"source\":\"Customer Service\"},{\"english\":\"Shackles\",\"spanish\":\"Grilletes\",\"definition\":\"Something that confines a person preventing free action as if by fetters —usually used in plural. Usually U-shaped fastening device secured by a bolt or pin through holes in the end of the two arms.\",\"industry\":\"Jail system\",\"example_en\":\"Shackles are used especially to restrain highly dangerous prisoners.\",\"example_es\":\"Los grilletes se usan especialmente para inmovilizar prisioneros de alta peligrosidad.\",\"source\":\"Customer Service\"},{\"english\":\"Shake / \\nTremble (verb)\",\"spanish\":\"Temblar\",\"definition\":\"To shake involuntarily with quick, short movements, as from fear, excitement, weakness, or cold; quake; quiver.\",\"industry\":\"Medical\",\"example_en\":\"It was so cold I was shaking.\",\"example_es\":\"Hacía tanto frio que estaba temblando.\",\"source\":\"Customer Service\"},{\"english\":\"Shaping\",\"spanish\":\"Moldeamiento\",\"definition\":\"Shaping is the use of reinforcement of successive approximations of a desired behavior. Specifically, when using a shaping technique, each approximate desired behavior that is demonstrated is reinforced, while behaviors that are not approximations of the desired behavior are not reinforced.\",\"industry\":\"School\",\"example_en\":\"We use shaping frequently in teaching speech and communication.\",\"example_es\":\"Usamos el moldeamiento con frecuencia en la enseñanza del lenguaje y la comunicación.\",\"source\":\"Customer Service\"},{\"english\":\"Sharp pain\",\"spanish\":\"Dolor agudo /\\nDolor intenso\",\"definition\":\"A sharp pain is sudden and severe.\",\"industry\":\"Medical\",\"example_en\":\"I have a sharp pain in the middle of my stomach; it feels like someone is stabbing me with a knife.\",\"example_es\":\"Tengo un dolor agudo en medio del estómago, se siente como si alguien me estuviera apuñalando con un cuchillo.\",\"source\":\"Customer Service\"},{\"english\":\"Sheathing\",\"spanish\":\"Revestimiento /\\nLaminado\",\"definition\":\"Sheathing is the outer layer or casing (often made from wood) that construction crews place on the building. Sheathing protects the floor, ceiling, roof, and wall framing and covers the entire building’s framework, giving it a solid shape.\",\"industry\":\"Home Insurance\",\"example_en\":\"The frame is covered by a glass and metal sheathing.\",\"example_es\":\"El marco está cubierto por un revestimiento de metal y vidrio.\",\"source\":\"Customer Service\"},{\"english\":\"Shed\",\"spanish\":\"Cobertizo\",\"definition\":\"A simple roofed structure, typically made of wood or metal, used as a storage space, a shelter for animals, or a workshop.\",\"industry\":\"General\",\"example_en\":\"The lawn mower is kept in the shed.\",\"example_es\":\"La cortadora de césped se guarda en el cobertizo.\",\"source\":\"Customer Service\"},{\"english\":\"Shelter\",\"spanish\":\"Refugio\",\"definition\":\"A shelter is a small building or covered place which is made to provide a place to stay or live for people, specially when they need protection from bad weather or danger.\",\"industry\":\"Social Services\",\"example_en\":\"He is living in a shelter for homeless people.\",\"example_es\":\"El está viviendo en un refugio para personas sin hogar.\",\"source\":\"Customer Service\"},{\"english\":\"Shin\",\"spanish\":\"Canilla /\\nEspinilla\",\"definition\":\"The front part of your leg between your knee and your foot.\",\"industry\":\"Medical\",\"example_en\":\"She has a nasty bruise on her shin.\",\"example_es\":\"Tiene un moretón horrible en la canilla.\",\"source\":\"Customer Service\"},{\"english\":\"Shingles\",\"spanish\":\"Culebrilla\",\"definition\":\"Shingles, also known as zoster or herpes zoster, is a viral disease characterized by a painful skin rash with blisters in a localized area.\",\"industry\":\"Medical\",\"example_en\":\"If you are over 50, you should receive the shingles vaccine.\",\"example_es\":\"Si usted tiene más de 50, debería recibir la vacuna contra la culebrilla.\",\"source\":\"Customer Service\"},{\"english\":\"Shortage\",\"spanish\":\"Escasez\",\"definition\":\"A state in which there is not enough of something that is needed.\",\"industry\":\"Finance\",\"example_en\":\"The payment went up because there was a shortage in your escrow account.\",\"example_es\":\"El pago subió porque había una escasez en su cuenta de depósito en garantía.\",\"source\":\"Customer Service\"},{\"english\":\"Shortness of breath\",\"spanish\":\"Falta de aliento /\\nFalta de respiración /\\nFalta de aire\",\"definition\":\"A feeling of difficult or labored breathing that is out of proportion to the patient's level of physical activity.\",\"industry\":\"Medical\",\"example_en\":\"Do you experience shortness of breath when going up or down the stairs?\",\"example_es\":\"¿Siente falta de aire al subir o bajar las escaleras?\",\"source\":\"Customer Service\"},{\"english\":\"Shoulder (road)\",\"spanish\":\"Borde del camino /\\nOrilla /\\nFranja lateral /\\nHombrillo\",\"definition\":\"A shoulder on a road is used as an emergency stopping lane, it is kind of a reserved lane by the verge of a road or motorway. A paved strip alongside a road for stopping on in an emergency.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We parked on the shoulder and waited for the police.\",\"example_es\":\"Nos estacionamos al borde del camino/en la orilla/ en el hombrillo y esperamos a la policía.\",\"source\":\"Customer Service\"},{\"english\":\"Shoulder blade\",\"spanish\":\"Omóplato\",\"definition\":\"The scapula (shoulder blade) is one of three bones that make up your shoulder joint.\",\"industry\":\"Medical\",\"example_en\":\"Move your arms back, squeezing your shoulder blades together.\",\"example_es\":\"Mueve los brazos hacia atrás, apretando los omóplatos entre sí.\",\"source\":\"Customer Service\"},{\"english\":\"Sick bay\",\"spanish\":\"Enfermería\",\"definition\":\"A room or building set aside for the treatment or accommodation of the sick, especially within a jail, military base or on board a ship.\",\"industry\":\"Jail system\",\"example_en\":\"Inmates who need to go to the sick bay must make a sick call.\",\"example_es\":\"Los encarcelados que necesiten ir a la enfermería deben solicitar una visita médica.\",\"source\":\"Customer Service\"},{\"english\":\"Sick call\",\"spanish\":\"Solicitar una visita médica\",\"definition\":\"A scheduled time at which individuals (such as soldiers or inmates) may report as sick to the medical officer in order to have a medical consultation.\",\"industry\":\"Jail system\",\"example_en\":\"We don’t have any more sick call request forms in the sick bay.\",\"example_es\":\"No tenemos más formularios de solicitud de visitas médicas en la enfermería.\",\"source\":\"Customer Service\"},{\"english\":\"Side effects\",\"spanish\":\"Efectos secundarios /\\nEfectos colaterales /\",\"definition\":\"A secondary, typically undesirable effect of a drug or treatment.\",\"industry\":\"Medical\",\"example_en\":\"Let the doctor know if you experience any side effects when you start this new medicine.\",\"example_es\":\"Avísele al doctor de cualquier efecto secundario que sienta cuando comience esta nueva medicina.\",\"source\":\"Customer Service\"},{\"english\":\"Side mirrors /\\nSide-view mirrors /\\nWing mirrors\",\"spanish\":\"Espejos laterales retrovisores\",\"definition\":\"Refers to mirrors found on either side of the exterior of motor vehicles for the purposes of helping the driver see areas behind and to the sides of the vehicle, outside of the driver's peripheral vision (in the 'blind spot').\",\"industry\":\"Auto Insurance\",\"example_en\":\"He got too close to my car and broke the side mirror.\",\"example_es\":\"Él se acercó demasiado a mi carro y rompió el espejo lateral/retrovisor.\",\"source\":\"Customer Service\"},{\"english\":\"Sidewalk\",\"spanish\":\"Acera /\\nBanqueta (Mexican regionalism, may also signify the curb)\",\"definition\":\"A walkway or a paved path for pedestrians at the side of a road.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The old man stepped on the accelerator and ended up on the sidewalk.\",\"example_es\":\"El viejo pisó el acelerador y terminó en la acera.\",\"source\":\"Customer Service\"},{\"english\":\"Signal\",\"spanish\":\"Señal\",\"definition\":\"A gesture, action, or sound that is used to convey information or instructions.\",\"industry\":\"General\",\"example_en\":\"Did you see the traffic signal?\",\"example_es\":\"¿Vio usted la señal de tránsito?\",\"source\":\"Customer Service\"},{\"english\":\"Signer\",\"spanish\":\"Firmante / Signatario\",\"definition\":\"A person, organization, or country that has signed an official document.\",\"industry\":\"Finance\",\"example_en\":\"Are you an authorized signer on this account?\",\"example_es\":\"¿Es usted un firmante autorizado en esta cuenta?\",\"source\":\"Customer Service\"},{\"english\":\"Single interest insurance\",\"spanish\":\"Seguro de interés único /\\nSeguro de interés sencillo\",\"definition\":\"Single interest insurance is a policy of insurance purchased by the seller to protect it in the event that the buyer defaults on the contract.\",\"industry\":\"Home Insurance\",\"example_en\":\"Single interest insurance covers the interests of one of the two parties that co-own a property.\",\"example_es\":\"El seguro de interés único cubre los intereses de una de las dos partes que son copropietarias de una propiedad.\",\"source\":\"Customer Service\"},{\"english\":\"Single vision lenses /\\nMonofocal lenses\",\"spanish\":\"Lentes de visión monofocal / \\nLentes monofocales\",\"definition\":\"Single vision lenses have one prescription over the lens surface. If you need help seeing at a single distance, such as close up, these lenses may help provide the appropriate vision correction.\",\"industry\":\"Health Insurance\",\"example_en\":\"Single vision lenses will often be prescribed to people who require a single vision correction.\",\"example_es\":\"Las lentes monofocales a menudo se recetan a personas que requieren una única corrección en la vista.\",\"source\":\"Customer Service\"},{\"english\":\"Ski Mask\",\"spanish\":\"Máscara para Skí / Pasamontañas\",\"definition\":\"A protective covering for the head and face, with holes for the eyes, nose, and mouth.\",\"industry\":\"General\",\"example_en\":\"The suspect was wearing a black ski mask, that was found later.\",\"example_es\":\"El sospechoso estaba usando una máscara para skí negra, que se encontró después.\",\"source\":\"Customer Service\"},{\"english\":\"Skid\",\"spanish\":\"Patinar /\\nDerrapar\",\"definition\":\"Refers to a vehicle that slides typically sideways or obliquely, on slippery ground, usually as a result of stopping or turning too quickly.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The car began to skid on the wet road.\",\"example_es\":\"El carro comenzó a patinar sobre la carretera mojada.\",\"source\":\"Customer Service\"},{\"english\":\"Skid marks\",\"spanish\":\"Huellas de frenazo /\\nMarcas de llanta (en la carretera)\",\"definition\":\"A long black mark left on a road surface by the tires of a skidding vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did you see any skid marks on the road?\",\"example_es\":\"¿Vio algunas huellas de frenazo en la carretera?\",\"source\":\"Customer Service\"},{\"english\":\"Slam\",\"spanish\":\"Embestir\",\"definition\":\"A heavy blow or impact; a noisy violent closing; a banging noise.\",\"industry\":\"General\",\"example_en\":\"The driver was really mad and slammed the door as he stepped out of his truck.\",\"example_es\":\"El conductor estaba muy enojado y embistió la puerta cuando se bajó de la camioneta.\",\"source\":\"Customer Service\"},{\"english\":\"Sling\",\"spanish\":\"Cabestrillo\",\"definition\":\"A supporting bandage or suspensory device; especially a loop suspended from the neck and supporting the flexed forearm.\",\"industry\":\"Medical\",\"example_en\":\"Be sure to keep your arm in the sling until your next appointment.\",\"example_es\":\"Asegúrese de mantener el brazo en el cabestrillo hasta su próxima cita.\",\"source\":\"Customer Service\"},{\"english\":\"Slippery\",\"spanish\":\"Resbaloso\",\"definition\":\"Refers to a surface or object that is difficult to hold firmly or stand on because it is smooth, wet, or slimy.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You mean the road was slippery, right?\",\"example_es\":\"¿Quiere decir que la carretera estaba resbalosa, correcto?\",\"source\":\"Customer Service\"},{\"english\":\"SNAP (Supplemental Nutrition Assistance Program)\",\"spanish\":\"Programa de asistencia nutricional suplementaria\",\"definition\":\"SNAP provides food benefits to low-income families to supplement their grocery budget so they can afford the nutritious food essential to health and well-being.\",\"industry\":\"Social Services\",\"example_en\":\"SNAP is the largest anti-hunger program in the United States, helping over 41 million people in 2022.\",\"example_es\":\"Programa de asistencia nutricional suplementaria es el mayor programa en contra del hambre en los Estados Unidos, ayudando a más de 41 millones de personas en el año 2022.\",\"source\":\"Customer Service\"},{\"english\":\"Social Security\",\"spanish\":\"Seguro Social /\\nSeguridad Social\",\"definition\":\"A federal insurance program that provides benefits for old age, survivors and disability.\",\"industry\":\"Social Services\",\"example_en\":\"Will my full social security benefits begin at the age of 65 or 67?\",\"example_es\":\"¿Mis beneficios completos del seguro social empezarían a la edad de 65 o 67?\",\"source\":\"Customer Service\"},{\"english\":\"Social Security\\nNumber (SSN)\",\"spanish\":\"Número de seguro social\",\"definition\":\"A number assigned by the government for taxation, employment, social security benefits, and identification purposes.\",\"industry\":\"Social Services\",\"example_en\":\"Please verify the last four digits of your social security number.\",\"example_es\":\"Por favor verifique los últimos cuatro dígitos de su número de seguro social.\",\"source\":\"Customer Service\"},{\"english\":\"Social Security Administration (SSA)\",\"spanish\":\"Administración del seguro social\",\"definition\":\"The Social Security Administration is an agency of the federal government that issues Social Security numbers and administers a number of public benefits programs.\",\"industry\":\"Social Services\",\"example_en\":\"The Social Security Administration (SSA) administers the social programs that cover disability or retirement benefits, among other services.\",\"example_es\":\"La administración del seguro social administra los programas sociales que cubren beneficios por incapacidad o jubilación, entre otros servicios.\",\"source\":\"Customer Service\"},{\"english\":\"Social worker\",\"spanish\":\"Trabajador(a) social\",\"definition\":\"A professional whose job is to facilitate the welfare of communities, individuals and societies.\",\"industry\":\"Social Services\",\"example_en\":\"The social worker assigned to your case will call you to determine what services are available to you and your family members.\",\"example_es\":\"El trabajador social asignado a su caso le llamará para determinar cuáles son los servicios disponibles para usted y los miembros de su familia.\",\"source\":\"Customer Service\"},{\"english\":\"Sole of the foot\",\"spanish\":\"Planta del pie\",\"definition\":\"The sole is the bottom of the foot. In humans, the sole of the foot is anatomically referred to as the plantar aspect.\",\"industry\":\"Medical\",\"example_en\":\"The soles of your feet are peeling, that indicates you have a vitamin deficiency.\",\"example_es\":\"Las plantas de sus pies se están pelando, eso indica que usted tiene una deficiencia vitamínica.\",\"source\":\"Customer Service\"},{\"english\":\"Son-in-law /\\nDaughter-in-law\",\"spanish\":\"Yerno / \\nNuera\",\"definition\":\"A daughter-in-law is the spouse of one's son, while a son-in-law is the spouse of one's daughter.\",\"industry\":\"General\",\"example_en\":\"My daughter-in-law moved in with my son.\",\"example_es\":\"Mi nuera se mudó con mi hijo.\",\"source\":\"Customer Service\"},{\"english\":\"Special Enrollment Period\",\"spanish\":\"Período Especial de Inscripción\",\"definition\":\"A Special Enrollment Period lets you enroll in health coverage or switch plans outside of the annual Open Enrollment Period, or during Open Enrollment, for an earlier coverage start date.\",\"industry\":\"Health Insurance\",\"example_en\":\"You qualify for a special enrollment period if you’ve had certain life events, including losing health coverage, moving, getting married, having a baby, or adopting a child.\",\"example_es\":\"Usted califica para un período especial de inscripción si ha tenido ciertos sucesos vitales, como perder la cobertura de salud, mudarse, casarse, tener un bebé o adoptar un niño.\",\"source\":\"Customer Service\"},{\"english\":\"Speech Therapy\",\"spanish\":\"Terapia del lenguaje /\\nTerapia del habla\",\"definition\":\"Speech therapy is the assessment and treatment of communication problems and speech disorders.\",\"industry\":\"Medical\",\"example_en\":\"To get speech therapy at school, children need to be evaluated for special education services.\",\"example_es\":\"Para recibir terapia del lenguaje en la escuela, los niños deben ser evaluados para recibir servicios de educación especial.\",\"source\":\"Customer Service\"},{\"english\":\"Speeding\",\"spanish\":\"Exceso de velocidad\",\"definition\":\"Driving faster than is allowed in a particular area.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The police officer fined him for speeding.\",\"example_es\":\"El oficial de policía lo multó por exceso de velocidad.\",\"source\":\"Customer Service\"},{\"english\":\"Spell\",\"spanish\":\"Episodio\",\"definition\":\"A period of bodily or mental distress or disorder.\",\"industry\":\"Medical\",\"example_en\":\"How many fainting spells do you experience in one month?\",\"example_es\":\"¿Cuántos episodios de desmayo experimenta\\nen un mes?\",\"source\":\"Customer Service\"},{\"english\":\"Spinal column /\\nSpine /\\nBackbone\",\"spanish\":\"Columna vertebral /\\nEspina dorsal\",\"definition\":\"The series of articulated vertebrae, separated by intervertebral disks and held together by muscles and tendons, that extends from the cranium to the coccyx or the end of the tail, encasing the spinal cord and forming the central support of the body.\",\"industry\":\"Medical\",\"example_en\":\"Spinal pain in this case is located in the lumbar region. The spine contains 33 vertebrae.\",\"example_es\":\"El dolor de la columna vertebral, en este caso, está localizado en la región lumbar. La espina dorsal contiene 33 vértebras.\",\"source\":\"Customer Service\"},{\"english\":\"Spleen\",\"spanish\":\"Bazo\",\"definition\":\"The spleen is the largest lymphatic organ in the body. The spleen also filters blood, serves as a major reservoir for blood, and destroys blood cells that are aged or abnormal.\",\"industry\":\"Medical\",\"example_en\":\"An enlarged spleen is a serious but treatable condition.\",\"example_es\":\"Un agrandamiento del bazo es una enfermedad grave pero tratable.\",\"source\":\"Customer Service\"},{\"english\":\"Sprain\",\"spanish\":\"Torcedura /\\nEsguince\",\"definition\":\"To injure (a joint) by a sudden twisting or wrenching of its ligaments.\",\"industry\":\"Medical\",\"example_en\":\"I sprained my ankle when I fell down the stairs.\",\"example_es\":\"Me torcí el tobillo cuando me caí de las escaleras.\",\"source\":\"Customer Service\"},{\"english\":\"SSDI (Social Security Disability Insurance)\",\"spanish\":\"Seguro por discapacidad del seguro social\",\"definition\":\"SSDI is tied to your work history. It pays benefits to you and certain members of your family if you have a disability, and worked enough years to qualify, having paid Social Security taxes during the years you worked.\",\"industry\":\"Social Services\",\"example_en\":\"Your eligibility for Social Security Disability Insurance (SSDI) is based on your age, disability, and how long you worked.\",\"example_es\":\"Su elegibilidad para el seguro por discapacidad del seguro social se basa en su edad, discapacidad y cuánto tiempo trabajó.\",\"source\":\"Customer Service\"},{\"english\":\"SSI (Supplemental Security Income)\",\"spanish\":\"Ingreso suplementario del seguro social\",\"definition\":\"A Federal income supplement program funded by general tax revenues. It is designed to help aged, blind, and disabled people, who have little or no income. It provides cash to meet basic needs for food, clothing, and shelter.\",\"industry\":\"Social Services\",\"example_en\":\"In order to be eligible to receive SSI, you must be older than 65 among other requirements.\",\"example_es\":\"A fin de ser elegible para recibir Ingreso suplementario del seguro social, usted debe de ser mayor de 65, entre otros requisitos.\",\"source\":\"Customer Service\"},{\"english\":\"State and districtwide assessments\",\"spanish\":\"Evaluaciones estatales y de distrito\",\"definition\":\"State and district-wide assessment is an integral aspect of educational accountability systems that provide valuable information that benefits individual students by measuring individual progress against standards.\",\"industry\":\"School\",\"example_en\":\"Appropriate accommodations for state and district-wide assessments are determined by the IEP team.\",\"example_es\":\"Las adaptaciones apropiadas para las evaluaciones estatales y de distrito son determinadas por el equipo del programa de educación individualizada.\",\"source\":\"Customer Service\"},{\"english\":\"State Employment Department.\",\"spanish\":\"Departamento de empleo estatal /\\nDepartamento de empleo del estado\",\"definition\":\"State employment departments are offices that deal with employment and labor issues. Every state has different laws and regulations when it comes to unemployment and employment law. These employment agencies help facilitate those laws and ensure they are practiced correctly by all employers in the state.\",\"industry\":\"Social Services\",\"example_en\":\"The state employment department can also provide services for employees that need help finding jobs or need certain benefits.\",\"example_es\":\"El departamento de empleo estatal también puede brindar servicios a los empleados que necesitan ayuda para encontrar trabajo o ciertos beneficios.\",\"source\":\"Customer Service\"},{\"english\":\"State law\",\"spanish\":\"Ley estatal / \\nDerecho estatal\",\"definition\":\"In the United States, state law refers to the law of each separate U.S. state.\",\"industry\":\"General\",\"example_en\":\"You will need to check the state law to know the legal qualifications for marriage.\",\"example_es\":\"Tendrá que consultar la ley estatal para conocer los requisitos legales para contraer matrimonio.\",\"source\":\"Customer Service\"},{\"english\":\"Status\",\"spanish\":\"Estado\",\"definition\":\"State or condition of matters of personal or business nature.\",\"industry\":\"Social Services\",\"example_en\":\"Call us back on Monday to check the status of your application.\",\"example_es\":\"Llámenos de vuelta el lunes para revisar el estado de su solicitud.\",\"source\":\"Customer Service\"},{\"english\":\"STD (Sexually Transmitted Disease) /\\nSTI (Sexually Transmitted Infection)\",\"spanish\":\"Enfermedad de transmisión sexual /\\nInfección de transmisión sexual\",\"definition\":\"Diseases that are passed on from one person to another through sexual contact, and sometimes by genital contact.\",\"industry\":\"Medical\",\"example_en\":\"Have you ever had a STD, such as gonorrhea, chlamydia, genital warts or herpes?\",\"example_es\":\"¿Alguna vez ha tenido enfermedades de transmisión sexual, como gonorrea, clamidia, verrugas genitales o herpes?\",\"source\":\"Customer Service\"},{\"english\":\"Steering wheel\",\"spanish\":\"Volante\",\"definition\":\"A wheel that a driver rotates in order to steer a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"He held the steering wheel during the accident.\",\"example_es\":\"Él sujetó el volante durante el accidente.\",\"source\":\"Customer Service\"},{\"english\":\"Sternum / \\nBreastbone\",\"spanish\":\"Esternón\",\"definition\":\"A flat bone located at the anterior aspect of the thorax. It lies in the midline of the chest and has a 'T' shape.\",\"industry\":\"Medical\",\"example_en\":\"The sternum protects the organs of your torso from injury, and serves as a connection point for other bones and muscles.\",\"example_es\":\"El esternón protege los órganos del torso de lesiones y sirve como punto de conexión para otros huesos y músculos.\",\"source\":\"Customer Service\"},{\"english\":\"Stipend\",\"spanish\":\"Estipendio\",\"definition\":\"Injured workers will generally receive 2/3% of their average weekly wage for lost wages due to a disability. This payment is generally called a stipend. A stipend is also a type of compensation for students, interns, apprentices, fellows, and clergy that don't receive a salary. It is normally provided on a daily, weekly, or monthly basis.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"She gets a monthly stipend from the university.\",\"example_es\":\"Ella recibe un estipendio mensual por parte de la universidad.\",\"source\":\"Customer Service\"},{\"english\":\"Stolen\",\"spanish\":\"Robado\",\"definition\":\"To take and use (ideas, credit, property, etc.) without right or acknowledgment.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"They found the stolen Bentley.\",\"example_es\":\"Encontraron el Bentley robado.\",\"source\":\"Customer Service\"},{\"english\":\"Stop sign\",\"spanish\":\"Señal de alto /\\nSeñal de pare\",\"definition\":\"Refers to a traffic sign to notify drivers that they must stop before proceeding.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I did not see the stop sign on the corner of the street.\",\"example_es\":\"No vi la señal de alto en la esquina de la calle.\",\"source\":\"Customer Service\"},{\"english\":\"Storage facility\",\"spanish\":\"Centro de almacenamiento /\\nDepósito\",\"definition\":\"Facilities that are specifically designed to provide a safe environment for long-term car storage.\",\"industry\":\"Auto Insurance\",\"example_en\":\"One of the services offered by a storage facility is that your car will be insured while in storage.\",\"example_es\":\"Uno de los servicios que ofrecen los centros de almacenamiento es que su carro estará asegurado mientras esté almacenado.\",\"source\":\"Customer Service\"},{\"english\":\"Strain (context dependent)\",\"spanish\":\"n. Distensión muscular /\\nCepa (viral, bacteriana)\\nv. Sufrir una distensión muscular /\\npujar\",\"definition\":\"Strain is a stretching or tearing of muscle or tendon. A tendon is a fibrous cord of tissue that connects muscles to bones.\\nStrain (Viral) is a genetic variant or subtype of microorganism (that could be a virus, but it also applies to bacteria and fungi).\",\"industry\":\"Medical\",\"example_en\":\"You suffered a muscle strain during the fall.\\n\\nThe vaccine contains three strains of the flu virus.\",\"example_es\":\"Usted sufrió una distensión muscular durante la caída.\\n\\nLa vacuna contiene tres cepas del virus de la gripe.\",\"source\":\"Customer Service\"},{\"english\":\"Stranded\",\"spanish\":\"Varada(o)\",\"definition\":\"Left helpless, without transportation. For example, when a car breaks down.\",\"industry\":\"Auto Insurance\",\"example_en\":\"He left me stranded in town with no car and no money for a bus.\",\"example_es\":\"Él me dejó varada en el pueblo sin carro ni dinero para el autobús.\",\"source\":\"Customer Service\"},{\"english\":\"Strength (of a medication)\",\"spanish\":\"Concentración\",\"definition\":\"The proportion of active drug substance to excipient, measured in units of volume or concentration. The strength of a drug product, which indicates the amount of active ingredient in each dose.\",\"industry\":\"Medical\",\"example_en\":\"The doctor changed the medication strength.\",\"example_es\":\"El médico cambió la concentración del medicamento.\",\"source\":\"Customer Service\"},{\"english\":\"Strep throat\",\"spanish\":\"Infección de la garganta por estreptococos / \\nFaringitis estreptocócica\",\"definition\":\"Throat infection caused by streptococcus bacteria. Symptoms include fever, redness of the throat, and inflammation of the tonsils.\",\"industry\":\"Medical\",\"example_en\":\"We need to do a strep throat test in your throat.\",\"example_es\":\"Tenemos que hacer una prueba de faringitis estreptocócica en la garganta.\",\"source\":\"Customer Service\"},{\"english\":\"Stretcher /\\nGurney\",\"spanish\":\"Camilla\",\"definition\":\"Although the words are sometimes used interchangeably, a stretcher is different from a gurney, which is fitted with wheels and can be moved by a single person. Stretchers are more portable and tend to be used in emergency situations, especially on battlefields and in wilderness search-and-rescue operations.\",\"industry\":\"Medical\",\"example_en\":\"The paramedics came and put me on a stretcher.\",\"example_es\":\"Los paramédicos llegaron y me pusieron en una camilla.\",\"source\":\"Customer Service\"},{\"english\":\"Stroke\",\"spanish\":\"Derrame cerebral /\\nApoplejía\",\"definition\":\"Occurs when blood supply to part of the brain is disrupted, causing brain cells to die. When blood flow to the brain is impaired, oxygen and glucose cannot be delivered to the brain.\",\"industry\":\"Medical\",\"example_en\":\"My father suffered a stroke last year and still has difficulty walking and speaking, but with continued therapy he should improve slowly.\",\"example_es\":\"Mi papá sufrió un derrame cerebral el año pasado y todavía tiene dificultad para caminar y hablar, pero con terapia continua él debería mejorar lentamente.\",\"source\":\"Customer Service\"},{\"english\":\"Stuffed up\",\"spanish\":\"Congestionada(o) /\\nTapada(o) /\\nConstipada(o)\",\"definition\":\"The presence of increased secretions and mucus in the nasal passages, most commonly arising as a result of a common cold, allergic reaction, or inflammation or infection of the paranasal sinuses (sinus infection).\",\"industry\":\"Medical\",\"example_en\":\"I can't sleep because I am really stuffed up.\",\"example_es\":\"No puedo dormir porque estoy realmente congestionada.\",\"source\":\"Customer Service\"},{\"english\":\"Subjects\",\"spanish\":\"Asignaturas /\\nMaterias /\\nDisciplinas\",\"definition\":\"Subjects are the parts into which learning can be divided. At school, each lesson usually covers one subject only. Some of the most common subjects at school are Language arts, history, mathematics, physical education and science.\",\"industry\":\"School\",\"example_en\":\"Math is my favorite school subject.\",\"example_es\":\"Las matemáticas son mi asignatura escolar favorita.\",\"source\":\"Customer Service\"},{\"english\":\"Subscriber\",\"spanish\":\"Suscriptor(a) / \\nAsegurado\",\"definition\":\"A person who receives a service or coverage regularly by paying in advance.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Some large companies will not sell, lease or rent its email subscriber list to third parties.\",\"example_es\":\"Algunas compañías grandes no venden, arriendan o alquilan su lista de correo electrónico de suscriptores a terceros.\",\"source\":\"Customer Service\"},{\"english\":\"Sufficient /\\nEnough\",\"spanish\":\"Suficiente\",\"definition\":\"Being as much as is needed; adequate; enough.\",\"industry\":\"General\",\"example_en\":\"There is sufficient balance to execute the transaction.\",\"example_es\":\"El saldo es suficiente para realizar la transacción.\",\"source\":\"Customer Service\"},{\"english\":\"Surcharges\",\"spanish\":\"Recargos\",\"definition\":\"To charge an additional sum to the usual payment, tax, etc.\",\"industry\":\"Customer Service\",\"example_en\":\"A surcharge may be made for deliveries outside normal hours.\",\"example_es\":\"Se podría realizar un recargo por envíos fuera de las horas normales.\",\"source\":\"Customer Service\"},{\"english\":\"Surrender\",\"spanish\":\"Ceder /\\nEntregar\",\"definition\":\"To return, turn in, give up, or give back an asset.\",\"industry\":\"Insurance (general)\",\"example_en\":\"You have 15 days to bring your account up to date or you will have to surrender your vehicle.\",\"example_es\":\"Usted tiene 15 días para poner su cuenta al día o tendrá que entregar su vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Suspend (verb)\",\"spanish\":\"Suspender\",\"definition\":\"Temporarily prevent from continuing or being in force or effect.\",\"industry\":\"Customer Service\",\"example_en\":\"Your driver's license is suspended for 90 days.\",\"example_es\":\"Su licencia de conducir está suspendida por 90 días.\",\"source\":\"Customer Service\"},{\"english\":\"Swerve (verb)\",\"spanish\":\"Desviarse bruscamente /\\nVirarse para evitar el golpe\",\"definition\":\"To zig zag or veer or change or cause to change direction abruptly.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I had to swerve to avoid hitting the dog.\",\"example_es\":\"Tuve que desviarme para evitar golpear al perro.\",\"source\":\"Customer Service\"},{\"english\":\"Swollen\",\"spanish\":\"Hinchada(o)\",\"definition\":\"Refers to the build-up of fluid in the soft tissue surrounding a body part like a joint, for example.\",\"industry\":\"Medical\",\"example_en\":\"My feet are swollen, I can't wear shoes.\",\"example_es\":\"Mis pies están hinchados, no puedo usar zapatos.\",\"source\":\"Customer Service\"},{\"english\":\"Symptoms\",\"spanish\":\"Síntomas\",\"definition\":\"An indication or sign of a disorder or disease, especially a subjective one such as pain, sensation or change in bodily function, experienced by a patient that is associated with a particular disease.\",\"industry\":\"Medical\",\"example_en\":\"Symptoms may differ from patient to patient.\",\"example_es\":\"Los síntomas pueden diferir entre paciente y paciente.\",\"source\":\"Customer Service\"},{\"english\":\"Tailgate (verb)\",\"spanish\":\"Pegarse o seguir de cerca a otro vehículo\",\"definition\":\"Driving too closely behind another vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"He hit the car in front of him because he was tailgating.\",\"example_es\":\"Él golpeó el carro delante de él porque iba pegado al otro/iba siguiendo al otro demasiado cerca.\",\"source\":\"Customer Service\"},{\"english\":\"Taillight\",\"spanish\":\"Luz trasera /\\nCalavera (regionalism only in Mexico)\",\"definition\":\"A light, usually red, located at the rear of a vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I stopped you because your taillight is broken.\",\"example_es\":\"Lo detuve porque su luz trasera está rota.\",\"source\":\"Customer Service\"},{\"english\":\"TANF Program (Temporary Assistance for Needy Families)\",\"spanish\":\"Programa de asistencia temporal para familias necesitadas\",\"definition\":\"Temporary Assistance for Needy Families (TANF) is a federally funded, state-run and time-limited program that helps families financially after experiencing hardship.\",\"industry\":\"Social Services\",\"example_en\":\"You can apply for TANF online or at a local office that serves the area where you live.\",\"example_es\":\"Usted puede hacer una solicitud para el programa de asistencia temporal para familias necesitadas por Internet o en una oficina local que preste servicio en la zona donde vive.\",\"source\":\"Customer Service\"},{\"english\":\"Task analysis\",\"spanish\":\"Análisis de tareas\",\"definition\":\"Task analysis is the process of learning about students by observing them in action to understand in detail how they perform their tasks and achieve their intended goals.\",\"industry\":\"School\",\"example_en\":\"Task analysis is a method of learning through observation.\",\"example_es\":\"El análisis de tareas es un método de aprendizaje a través de la observación.\",\"source\":\"Customer Service\"},{\"english\":\"Tax return\",\"spanish\":\"Declaración de impuestos\",\"definition\":\"A tax return is the completion of documentation that calculates an entity's or individual's income earned and the amount of taxes to be paid to the government.\",\"industry\":\"Finance\",\"example_en\":\"Tax returns are generally due on April 15th, for the prior year.\",\"example_es\":\"La declaración de impuestos generalmente corresponde al 15 de abril del año anterior.\",\"source\":\"Customer Service\"},{\"english\":\"Taxes\",\"spanish\":\"Impuestos\",\"definition\":\"An amount of money that a government requires people to pay according to their income, the value of their property, etc.\",\"industry\":\"General\",\"example_en\":\"Collecting taxes is a fundamental way for countries to generate public revenues.\",\"example_es\":\"El recolectar impuestos es una manera fundamental para que los países generen ingresos públicos.\",\"source\":\"Customer Service\"},{\"english\":\"Taxpayer\",\"spanish\":\"Contribuyente /\\nContribuyente tributario\",\"definition\":\"A taxpayer may be an individual or business entity that is obligated to pay taxes to a federal state, or local government.\",\"industry\":\"Finance\",\"example_en\":\"Taxpayers should not have to pay for the failure of private companies.\",\"example_es\":\"Los contribuyentes tributarios no deberían tener que pagar por el fracaso de empresas privadas.\",\"source\":\"Customer Service\"},{\"english\":\"TB (Tuberculosis)\",\"spanish\":\"Tuberculosis (TB)\",\"definition\":\"TB is a disease caused by a bacteria called Mycobacterium tuberculosis. The bacteria usually attacks the lungs, but they can also damage other parts of the body.\",\"industry\":\"Medical\",\"example_en\":\"As the TB skin test result is positive, we will need to order a chest x-ray.\",\"example_es\":\"Ya que la prueba cutánea de tuberculosis dio positiva, necesitaremos ordenar una radiografía de pecho.\",\"source\":\"Customer Service\"},{\"english\":\"Technician\",\"spanish\":\"Técnica(o)\",\"definition\":\"A person who has acquired special skills to do practical work in a particular field.\",\"industry\":\"Customer Service\",\"example_en\":\"The technician did not arrive on time.\",\"example_es\":\"El técnico no llegó a tiempo.\",\"source\":\"Customer Service\"},{\"english\":\"Temple\",\"spanish\":\"Sien\",\"definition\":\"The flat area on each side of your head in front of the top of your ear.\",\"industry\":\"Medical\",\"example_en\":\"Throbbing pain in the temples, especially on just one side of your head, is a common symptom of migraine headaches.\",\"example_es\":\"Dolor palpitante en las sienes, sobre todo en un solo lado de la cabeza, es un síntoma frecuente migraña.\",\"source\":\"Customer Service\"},{\"english\":\"Temporary block\",\"spanish\":\"Bloqueo temporal\",\"definition\":\"To help protect from fraud or abuse, an account may be suspended for a limited period of time.\",\"industry\":\"Customer Service\",\"example_en\":\"Your card will be unblocked automatically, 7 days after the first temporary block.\",\"example_es\":\"Su tarjeta será desbloqueada automáticamente, siete días luego del primer bloqueo temporal.\",\"source\":\"Customer Service\"},{\"english\":\"Temporary repairs\",\"spanish\":\"Reparaciones temporales /\\nReparaciones provisionales\",\"definition\":\"Repairs made to a damaged property to prevent further damages, until permanent repairs are done.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We can make some temporary repairs on your roof to avoid water damage from the pending storm.\",\"example_es\":\"Podemos realizar algunas reparaciones temporales en su techo para evitar daño por agua de la tormenta que se aproxima.\",\"source\":\"Customer Service\"},{\"english\":\"Tenant\",\"spanish\":\"Inquilina(o) /\\nArrendataria(o)\",\"definition\":\"A person who occupies land or property rented from a landlord.\",\"industry\":\"Customer Service\",\"example_en\":\"Are you a tenant or do you own the property?\",\"example_es\":\"¿Es usted un inquilino o es dueño de la propiedad?\",\"source\":\"Customer Service\"},{\"english\":\"Terminally ill\",\"spanish\":\"Desahuciada(o) /\\nEnferma(o) terminal\",\"definition\":\"Terminally ill refers to the condition of a person who is expected to be deceased within a few months, or no more than a year, because of a serious disease or illness.\",\"industry\":\"Medical\",\"example_en\":\"Hospice care is for terminally ill patients.\",\"example_es\":\"Los cuidados de hospicio son para pacientes desahuciados.\",\"source\":\"Customer Service\"},{\"english\":\"Test\",\"spanish\":\"Prueba /\\nAnálisis /\\nExamen\",\"definition\":\"A procedure intended to establish the quality, performance, or reliability of an individual's health.\",\"industry\":\"Medical\",\"example_en\":\"These are the doctor's orders for the tests you need.\",\"example_es\":\"Estas son las órdenes del doctor para los exámenes/pruebas que necesita.\",\"source\":\"Customer Service\"},{\"english\":\"Test strips\",\"spanish\":\"Tiritas reactivas\",\"definition\":\"A test strip is a strip of material containing chemicals that react to certain substances.\",\"industry\":\"General\",\"example_en\":\"The test strips indicate the acidity of urine by changing color on contact with it.\",\"example_es\":\"Las tiras reactivas indican la acidez de la orina cambiando de color al entrar en contacto con ella.\",\"source\":\"Customer Service\"},{\"english\":\"Tetanus\",\"spanish\":\"Tétanos\",\"definition\":\"A serious bacterial infection that causes painful muscle spasms and can lead to death.  A vaccine can easily prevent the infection, which has no cure.\",\"industry\":\"Medical\",\"example_en\":\"When was the last time you received the tetanus shot?\",\"example_es\":\"¿Cuándo fue la última vez que recibió la vacuna contra el tétanos?\",\"source\":\"Customer Service\"},{\"english\":\"The Monster / \\nThe Ninja\",\"spanish\":\"(Recluso) con SIDA\",\"definition\":\"Inmate talk: Refers to an inmate having HIV.\",\"industry\":\"Jail system\",\"example_en\":\"Watch out he's got 'the ninja'.\",\"example_es\":\"Cuidado, él tiene SIDA.\",\"source\":\"Customer Service\"},{\"english\":\"Theft\",\"spanish\":\"Hurto /\\nRobo /\\nDelito de hurto\",\"definition\":\"Theft refers to the unlawful taking of another person's property without that person's permission or consent with the intent to deprive the rightful owner of it.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Shoplifting is a form of theft. If you enter a store and leave the store without paying for the merchandise, that's shoplifting.\",\"example_es\":\"El hurto en tiendas es un modo de robo. Si usted entra en una tienda y se va de la tienda sin pagar por la mercancía, eso es hurto en tiendas.\",\"source\":\"Customer Service\"},{\"english\":\"Thermometer\",\"spanish\":\"Termómetro\",\"definition\":\"An instrument for measuring and indicating temperature.\",\"industry\":\"Medical\",\"example_en\":\"I do not have a thermometer at home.\",\"example_es\":\"No tengo un termómetro en casa.\",\"source\":\"Customer Service\"},{\"english\":\"Thigh\",\"spanish\":\"Muslo\",\"definition\":\"The part of the human leg between the hip and the knee.\",\"industry\":\"Medical\",\"example_en\":\"You can put his shirt back on, but make sure to leave his thighs uncovered for the vaccines.\",\"example_es\":\"Puede volver a ponerle la camiseta, pero asegúrese de dejarle los muslos al descubierto para las vacunas.\",\"source\":\"Customer Service\"},{\"english\":\"Thinking skills\",\"spanish\":\"Capacidad de razonar /\\nDestrezas de pensamiento\",\"definition\":\"Thinking skills refer to the ability to understand and address problems based on all available information and facts.\",\"industry\":\"School\",\"example_en\":\"Understanding your thinking skills can help you become a better decision-maker.\",\"example_es\":\"Entender su capacidad de razonar puede ayudarle a convertirse en un mejor decisor.\",\"source\":\"Customer Service\"},{\"english\":\"Throbbing pain /\\nPulsing pain\",\"spanish\":\"Dolor palpitante /\\nDolor que late /\\nDolor pulsante\",\"definition\":\"Throbbing pain consists of recurring achy pains. You may also experience pounding, beating, or pulsing pain.\",\"industry\":\"Medical\",\"example_en\":\"I have a throbbing pain in my left side that doesn't go away when I lay down and is keeping me up at night.\",\"example_es\":\"Tengo un dolor palpitante en mi lado izquierdo que no se va cuando me acuesto y me mantiene despierto durante la noche.\",\"source\":\"Customer Service\"},{\"english\":\"Ticket\",\"spanish\":\"Boleta de infracción (NO TIQUETE)\",\"definition\":\"Often issued by a police officer with an official notice of a traffic offense.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Did the police come to the scene of the accident? Did anyone receive a ticket?\",\"example_es\":\"¿Acudió la policía al lugar del accidente? ¿Recibió alguien una boleta de infracción?\",\"source\":\"Customer Service\"},{\"english\":\"Tie beam\",\"spanish\":\"Viga de amarre\",\"definition\":\"A tie beam is a horizontal beam connecting two rafters in a roof or roof truss.\",\"industry\":\"Home Insurance\",\"example_en\":\"Internally, the roof structure is exposed with tie beams and king post.\",\"example_es\":\"Internamente, la estructura del techo está expuesta con vigas de amarre y un pendolón.\",\"source\":\"Customer Service\"},{\"english\":\"Time sensitive\",\"spanish\":\"Atención inmediata / \\nSer una prioridad\",\"definition\":\"Useful or relevant for only a limited amount of time.\",\"industry\":\"General\",\"example_en\":\"These time-sensitive papers must be signed as soon as possible.\",\"example_es\":\"Estos papeles de atención inmediata deben ser firmados tan pronto como sea posible.\",\"source\":\"Customer Service\"},{\"english\":\"Timeout\",\"spanish\":\"Período de descanso /\\nAislamiento temporal /\\nTiempo de reflexión\",\"definition\":\"A behavioral support strategy in which a student temporarily separates from the learning activity or the classroom, either by choice or by direction from staff.\",\"industry\":\"School\",\"example_en\":\"Timeouts can be positive, they teach the student that it’s ok to take a break to regulate behaviors and/or emotions.\",\"example_es\":\"Los periodos de descanso pueden ser positivos, ya que enseñan al alumno que está bien tomarse un descanso para regular comportamientos y/o emociones.\",\"source\":\"Customer Service\"},{\"english\":\"Tingling\",\"spanish\":\"Hormigueo\",\"definition\":\"To feel or cause to feel a prickling, itching, or stinging sensation of the flesh, as from a cold plunge or electric shock.\",\"industry\":\"Medical\",\"example_en\":\"Are you feeling any tingling in your arms and legs and if so, is it constant or intermittent?\",\"example_es\":\"¿Está sintiendo algún hormigueo en sus brazos y piernas y, si es así, es constante o esporádico?\",\"source\":\"Customer Service\"},{\"english\":\"Title\",\"spanish\":\"Título\",\"definition\":\"A legal form, establishing a person or business as the legal owner of a vehicle. Also known as pink slip.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You have to sign and notarize your title.\",\"example_es\":\"Usted tiene que firmar y notarizar su título.\",\"source\":\"Customer Service\"},{\"english\":\"To be out of it (Context dependent)\",\"spanish\":\"Fuera de sí / \\nIdo\",\"definition\":\"Not conscious of where you are or what condition you are in.\",\"industry\":\"Medical\",\"example_en\":\"She was lying on the sofa, totally out of it.\",\"example_es\":\"Ella estaba acostada en el sofá, completamente fuera de sí.\",\"source\":\"Customer Service\"},{\"english\":\"To consolidate a debt\",\"spanish\":\"Consolidar una deuda\",\"definition\":\"Consolidating a debt is when you take out a single new loan to pay off several existing debts.\",\"industry\":\"Finance\",\"example_en\":\"To consolidate a debt is combining several loans into one new loan, often with a lower interest rate.\",\"example_es\":\"Consolidar una deuda consiste en combinar varios préstamos en un solo préstamo nuevo, a menudo con una tasa de interés más baja.\",\"source\":\"Customer Service\"},{\"english\":\"To deal (drugs)\",\"spanish\":\"Traficar\",\"definition\":\"An illegal business transaction where cash or something else of value is exchanged for illegal drugs, usually conducted in a clandestine manner.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"Neighbours say drug dealing has become more common in the area in recent months.\",\"example_es\":\"Los vecinos dicen que el tráfico de drogas se ha vuelto más común en el área en los meses recientes.\",\"source\":\"Customer Service\"},{\"english\":\"To determine liability\",\"spanish\":\"Determinar la responsabilidad civil\",\"definition\":\"Proving that someone was careless or negligent and therefore liable for an accident or injury. if one person involved in an accident was more careless than another, that person must pay for at least a portion of the damages suffered by the more careful person.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Recorded statements may be used later on during litigation proceedings to determine liability.\",\"example_es\":\"Las declaraciones grabadas pueden ser usadas más adelante en procedimientos judiciales para determinar la responsabilidad civil.\",\"source\":\"Customer Service\"},{\"english\":\"To feel down\",\"spanish\":\"Decaída(o)\",\"definition\":\"Feeling out of sorts, under the weather, weak, unwell.\",\"industry\":\"Medical\",\"example_en\":\"With all of his problems lately, he is feeling a bit down.\",\"example_es\":\"Con todos sus problemas últimamente, él se está sintiendo un poco decaído.\",\"source\":\"Customer Service\"},{\"english\":\"To file a claim\",\"spanish\":\"Presentar un reclamo /\\nAbrir un reclamo\",\"definition\":\"To file a claim means to make a request to an insurance company for payment of a sum of money according to the terms of an insurance policy.\",\"industry\":\"Insurance (general)\",\"example_en\":\"Are you calling to check the status of an existing claim or to file a new claim?\",\"example_es\":\"¿Está llamando para verificar el estado de un reclamo existente o para presentar un nuevo reclamo?\",\"source\":\"Customer Service\"},{\"english\":\"To fill (A prescription or medication)\",\"spanish\":\"Surtir una receta\",\"definition\":\"To go to a pharmacy to buy a dose or set of doses of a medicine as prescribed by a doctor.\",\"industry\":\"Medical\",\"example_en\":\"Please take the prescription to the pharmacy to have it filled and follow the instructions on the label.\",\"example_es\":\"Por favor lleve la receta a la farmacia para que la surtan y siga las instrucciones de la etiqueta.\",\"source\":\"Customer Service\"},{\"english\":\"To renew\",\"spanish\":\"Renovar /\\nReanudar\",\"definition\":\"To make effective for an additional period.\",\"industry\":\"General\",\"example_en\":\"You must renew your application for Medicaid every year if you want to continue receiving the same benefits.\",\"example_es\":\"Deberá renovar su solicitud de Medicaid cada año si quiere continuar recibiendo los mismos beneficios.\",\"source\":\"Customer Service\"},{\"english\":\"To squint\",\"spanish\":\"Entrecerrar los ojos\",\"definition\":\"To partly close your eyes in order to see more clearly.\",\"industry\":\"General\",\"example_en\":\"The sun was shining straight in her eyes and made her squint.\",\"example_es\":\"El sol brillaba directamente en sus ojos y le hacía entrecerrarlos.\",\"source\":\"Customer Service\"},{\"english\":\"To stare off\",\"spanish\":\"Mirada perdida\",\"definition\":\"To look straight ahead without looking at anything specific.\",\"industry\":\"General\",\"example_en\":\"He was staring off after the seizure.\",\"example_es\":\"Él estaba con la mirada perdida después del ataque de convulsión.\",\"source\":\"Customer Service\"},{\"english\":\"To the best of your knowledge\",\"spanish\":\"A su leal saber y entender / \\nA su fiel entendimiento\",\"definition\":\"If someone says that something is true to their knowledge or to the best of their knowledge, it means that they believe it to be true but it is possible that they do not know all the facts.\",\"industry\":\"General\",\"example_en\":\"Were all your answers true and correct to the best of your knowledge?\",\"example_es\":\"¿Fueron todas sus respuestas verdaderas y correctas a su leal saber y entender?\",\"source\":\"Customer Service\"},{\"english\":\"Toll-free number\",\"spanish\":\"Número gratuito\",\"definition\":\"Toll-free numbers are telephone numbers with distinct three-digit codes that can be dialed from landlines with no charge to the person placing the call.\",\"industry\":\"Customer Service\",\"example_en\":\"Call our toll-free number and speak to a customer service representative.\",\"example_es\":\"Llame a nuestro número gratuito y hable con un representante de servicio de atención al cliente.\",\"source\":\"Customer Service\"},{\"english\":\"Tonsillitis\",\"spanish\":\"Amigdalitis\",\"definition\":\"An infection and swelling of the tonsils, which are oval-shaped masses of lymph gland tissue located on both sides of the back of the throat.\",\"industry\":\"Medical\",\"example_en\":\"We can treat the tonsillitis with antibiotics first.\",\"example_es\":\"Podemos tratar la amigdalitis con antibióticos primero.\",\"source\":\"Customer Service\"},{\"english\":\"Tonsils\",\"spanish\":\"Amígdalas /\\nAnginas (MX regionalism. Not standard)\",\"definition\":\"Either of two small masses of lymphoid tissue in the throat, one on each side of the root of the tongue.\",\"industry\":\"Medical\",\"example_en\":\"Tonsils can become enlarged for many different reasons, including exposure to viruses and bacteria.\",\"example_es\":\"Las amígdalas pueden agrandarse por muchas razones diferentes, incluyendo la exposición a virus y bacteria.\",\"source\":\"Customer Service\"},{\"english\":\"Total loss\",\"spanish\":\"Pérdida total\",\"definition\":\"In insurance, a total loss is a judgment, by the insurer, that the lost value or repair cost of a damaged property exceeds the value of its policy.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Your vehicle has been deemed a total loss, as it would cost more to fix it than what it is worth.\",\"example_es\":\"Su vehículo ha sido declarado pérdida total, ya que costaría más arreglarlo de lo que vale.\",\"source\":\"Customer Service\"},{\"english\":\"Tow truck\",\"spanish\":\"Grúa /\\nCamión de remolque\",\"definition\":\"A truck with special equipment for pulling a vehicle that is not working to a place where it can be repaired.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The tow truck was parked behind my car.\",\"example_es\":\"Estacionaron la grúa detrás de mi carro.\",\"source\":\"Customer Service\"},{\"english\":\"Tow yard\",\"spanish\":\"Lote de vehículos remolcados /\\nCorralón (Mexican regionalism)\",\"definition\":\"A storage facility used to park disabled vehicles on a temporary basis.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We need you to call the tow yard and let them know that we will be picking up the car.\",\"example_es\":\"Necesitamos que llame al lote de vehículos remolcados y les haga saber que vamos a recoger el carro.\",\"source\":\"Customer Service\"},{\"english\":\"Towed\",\"spanish\":\"Remolcado\",\"definition\":\"Refers to a motor vehicle or boat pulling another vehicle or boat by means of chains, tow bars, or tow platform.\",\"industry\":\"Auto Insurance\",\"example_en\":\"My car was not drivable, so it was towed to the shop.\",\"example_es\":\"Mi carro no se podía manejar, por eso lo remolcaron al taller.\",\"source\":\"Customer Service\"},{\"english\":\"Traffic Control\",\"spanish\":\"Control del tráfico /\\nControl del tránsito\",\"definition\":\"Traffic control involves directing vehicular and pedestrian traffic around a construction zone, accident or other road disruption, thus ensuring the safety of emergency response teams, construction workers and the general public.\",\"industry\":\"Auto Insurance\",\"example_en\":\"There were some orange cones for traffic control on the off ramp.\",\"example_es\":\"Había unos conos anaranjados para control de tráfico en la rampa de salida.\",\"source\":\"Customer Service\"},{\"english\":\"Traffic jam /\\nGridlock\",\"spanish\":\"Atasco de tráfico / \\nEmbotellamiento\",\"definition\":\"A situation that happens when there is so much traffic on a road or highway that it slows to a stop.\",\"industry\":\"Auto Insurance\",\"example_en\":\"If you want to avoid the afternoon gridlock, I would recommend leaving 15 minutes earlier.\",\"example_es\":\"Si quiere evitar el atasco de tráfico de la tarde, le recomendaría salir 15 minutos antes.\",\"source\":\"Customer Service\"},{\"english\":\"Traffic light\",\"spanish\":\"Semáforo\",\"definition\":\"A set of automatically operated colored lights, typically red, amber, and green, for controlling traffic at road junctions and crosswalks.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You said you stopped at the traffic light, but in the picture, it shows you running (through) the red light.\",\"example_es\":\"Dice que se detuvo en el semáforo pero según la foto usted se pasó la luz roja.\",\"source\":\"Customer Service\"},{\"english\":\"Traffic sign\",\"spanish\":\"Señal de tránsito\",\"definition\":\"A sign conveying information, an instruction, or a warning to drivers.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Were there any traffic signs at the intersection?\",\"example_es\":\"¿Había señales de tráfico en la intersección?\",\"source\":\"Customer Service\"},{\"english\":\"Trailer\",\"spanish\":\"Remolque\",\"definition\":\"An unpowered vehicle towed by another, in particular.\",\"industry\":\"Auto Insurance\",\"example_en\":\"No sir, the trailer is not covered under your policy.\",\"example_es\":\"No señor, el remolque no está cubierto por su póliza.\",\"source\":\"Customer Service\"},{\"english\":\"Trailer hitch\",\"spanish\":\"Enganche de remolque\",\"definition\":\"A device attached to the chassis of a vehicle for towing.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did your vehicle come with a trailer hitch?\",\"example_es\":\"¿Su vehículo vino con un enganche de remolque?\",\"source\":\"Customer Service\"},{\"english\":\"Training\",\"spanish\":\"Adiestramiento /\\nEntrenamiento /\\nCapacitación\",\"definition\":\"The education, instruction, or discipline of a person learning a new skill or task.\",\"industry\":\"General\",\"example_en\":\"She completed training to become a physical therapist and graduated at the end of the summer.\",\"example_es\":\"Ella completó el entrenamiento para ser terapeuta físico y se graduó al final del verano.\",\"source\":\"Customer Service\"},{\"english\":\"Tram\",\"spanish\":\"Tranvía\",\"definition\":\"An electric vehicle that transports people, usually in cities, and goes along metal tracks in the road.\",\"industry\":\"Travel and Hospitality\",\"example_en\":\"The tram was running in darkness in early morning amid heavy rain.\",\"example_es\":\"El tranvía corría en la oscuridad temprano en la mañana en medio de las fuertes lluvias.\",\"source\":\"Customer Service\"},{\"english\":\"Transaction\",\"spanish\":\"Transacción\",\"definition\":\"An exchange or transfer of goods, services, or funds.\",\"industry\":\"Finance\",\"example_en\":\"If you have time, I'd like to review some transactions on your account.\",\"example_es\":\"Si tiene tiempo me gustaría revisar algunas transacciones en su cuenta.\",\"source\":\"Customer Service\"},{\"english\":\"Transfer\",\"spanish\":\"Transferir (Verb)\\nTransferencia (Noun)\",\"definition\":\"To take over the possession of an asset, a right, money, valuables, or a responsibility to someone else.\",\"industry\":\"General\",\"example_en\":\"The banker agreed to transfer the client's money to a different type of account since he was unhappy with the current fees.\",\"example_es\":\"El ejecutivo bancario aceptó transferir el dinero del cliente a un tipo de cuenta diferente, debido a que estaba descontento con los cargos actuales.\",\"source\":\"Customer Service\"},{\"english\":\"Transportation\",\"spanish\":\"Transporte\",\"definition\":\"The action of transporting someone or something, or the process of being transported.\",\"industry\":\"General\",\"example_en\":\"Do you need transportation to and from the doctor's office? If so, that can be arranged.\",\"example_es\":\"¿Necesita transporte para ir y regresar del consultorio del doctor? Si así es, eso puede ser acordado.\",\"source\":\"Customer Service\"},{\"english\":\"Treatment\",\"spanish\":\"Tratamiento\",\"definition\":\"Medication, surgery, psychotherapy, etc. given to a patient to treat a disease or symptom in an attempt to cure it.\",\"industry\":\"Medical\",\"example_en\":\"Your treatment may take up to six months.\",\"example_es\":\"Su tratamiento puede tomar hasta seis meses.\",\"source\":\"Customer Service\"},{\"english\":\"Triage nurse\",\"spanish\":\"Enfermera(o) de clasificación de emergencias\",\"definition\":\"A registered nurse (typically in the emergency room) who assesses patients and determines their need for medical attention in order of urgency to determine the order in which they will receive medical care.\",\"industry\":\"Medical\",\"example_en\":\"After the earthquake, the Red Cross sent triage nurses to assess the victims and treat them according to the severity of their injuries and symptoms.\",\"example_es\":\"Después del terremoto, la Cruz Roja envió enfermera(o)s de clasificación de emergencias para evaluar a las víctimas y proveer tratamiento de acuerdo a la gravedad de sus lesiones y síntomas.\",\"source\":\"Customer Service\"},{\"english\":\"Trifocal lenses\",\"spanish\":\"Lentes trifocales\",\"definition\":\"Trifocal glasses have three distinct prescriptions on the lenses, indicated by lines, to correct faraway, intermediate, and near vision.\",\"industry\":\"Medical\",\"example_en\":\"Bifocal and trifocal glasses result in a more complex lens profile, compounding multiple surfaces.\",\"example_es\":\"Los lentes bifocales y trifocales dan como resultado un perfil de lente más complejo, combinando múltiples superficies.\",\"source\":\"Customer Service\"},{\"english\":\"Troubleshooting\",\"spanish\":\"Ubicación de problemas /\\nLocalización de fallas /\\nLocalización de problemas /\\nDiagnóstico de problemas\",\"definition\":\"Refers to a form of technical problem solving, often applied to repair failed products or processes. It is a systematic search for the source of a problem in order to solve it, and make the product operational again.\",\"industry\":\"Customer Service\",\"example_en\":\"The computer technician will go through a process of troubleshooting, to resolve the issues you are having with your internet and phone service.\",\"example_es\":\"El técnico de computadoras hará un proceso de diagnóstico de problemas para resolver el problema que tiene con los servicios de internet y de teléfono.\",\"source\":\"Customer Service\"},{\"english\":\"Trunk\",\"spanish\":\"Maletero\",\"definition\":\"Refers to a vehicle's main storage compartment.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The car is not drivable because the trunk won't close and it obstructs my view.\",\"example_es\":\"El carro no se puede conducir debido a que el maletero no cierra y obstruye mi vista.\",\"source\":\"Customer Service\"},{\"english\":\"Tuition\",\"spanish\":\"Colegiatura /\\nPago de estudios /\\nTasa académica\",\"definition\":\"Tuition is a fee paid for instruction or teaching, usually for higher education.\",\"industry\":\"School\",\"example_en\":\"Many students need to get part-time jobs to pay their college tuition.\",\"example_es\":\"Muchos estudiantes necesitan conseguir trabajos a tiempo parcial para pagar su colegiatura.\",\"source\":\"Customer Service\"},{\"english\":\"Turn arrow\",\"spanish\":\"Flecha de cruce /\\nFlecha para voltear\",\"definition\":\"Turn arrow means that drivers must come to a stop at the marked stop line before moving into the crosswalk or intersection, and shall turn to the indicated direction when there is indication to proceed.\",\"industry\":\"Auto Insurance\",\"example_en\":\"I do not believe the driver saw the turn arrow and drove straight ahead.\",\"example_es\":\"No creo que el conductor haya visto la flecha de cruce y siguió manejando de frente.\",\"source\":\"Customer Service\"},{\"english\":\"Turn signal\",\"spanish\":\"Luz direccional /\\nLuces para doblar /\\nLuz de cruce /\\nSeñalero\",\"definition\":\"A flashing light on a vehicle to show that it is about to change lanes or turn.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Did you use the turn signal before you initiated the turn?\",\"example_es\":\"¿Puso la luz direccional antes de iniciar el cruce?\",\"source\":\"Customer Service\"},{\"english\":\"Turning lane\",\"spanish\":\"Carril para dar vuelta\",\"definition\":\"An auxiliary lane between lanes where vehicles can safely wait for oncoming traffic to abate in order to make a left turn.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Check the shared left turn lane for vehicles ahead.\",\"example_es\":\"Vigile el carril para dar vuelta a la izquierda para ver si hay vehículos adelante.\",\"source\":\"Customer Service\"},{\"english\":\"Turnpike / \\nToll road /\\nToll motorway\",\"spanish\":\"Autopista de Peaje / Carretera de Peaje\",\"definition\":\"A public or private road (almost always a freeway in the present day) for which a fee (or toll) is assessed for passage.\",\"industry\":\"Auto Insurance\",\"example_en\":\"We are driving down the New Jersey Turnpike on a Sunday morning in March.\",\"example_es\":\"Estamos manejando a lo largo de la autopista de peaje de New Jersey en una mañana de domingo en marzo.\",\"source\":\"Customer Service\"},{\"english\":\"Twins (identical) /\\nTwins (fraternal)\",\"spanish\":\"Gemelos /\\nMellizos\",\"definition\":\"Two offspring produced by the same pregnancy. Identical twins result from the fertilization of a single egg by a single sperm, with the fertilized egg then splitting into two. Fraternal twins result from the fertilization of two separate eggs with two different sperm during the same pregnancy.\",\"industry\":\"General\",\"example_en\":\"They told me that I am pregnant with twins, so I am going to need help, because I was prepared for just one baby. What do I need to do to receive assistance?\",\"example_es\":\"Me dijeron que estoy embarazada con mellizos, así que voy a necesitar ayuda porque estaba preparada para un solo bebé. ¿Qué necesito hacer para recibir asistencia?\",\"source\":\"Customer Service\"},{\"english\":\"Unauthorized\",\"spanish\":\"Sin autorizar /\\nNo autorizada(o)\",\"definition\":\"Not having been given permission or authority to do something.\",\"industry\":\"General\",\"example_en\":\"Unauthorized vehicles without an entrance pass will not be allowed to pass through the gate.\",\"example_es\":\"Los vehículos no autorizados sin un pase de entrada no podrán pasar por la puerta.\",\"source\":\"Customer Service\"},{\"english\":\"Underinsured Motorist Coverage\",\"spanish\":\"Cobertura contra conductor(a) con seguro insuficiente\",\"definition\":\"Underinsured motorist coverage provides protection in case of an accident in which the at-fault driver doesn't have enough insurance to cover all damages.\",\"industry\":\"Auto Insurance\",\"example_en\":\"If your car is damaged by a hit-and-run driver or a person whose liability coverage limits are not high enough to cover the damages, you will need underinsured motorist coverage to pay for that.\",\"example_es\":\"Si su vehículo es dañado por un conductor que se da a la fuga o una persona cuyos límites de cobertura de responsabilidad civil no son lo suficientemente altos para cubrir los daños, necesitará una cobertura contra conductor con seguro insuficiente para pagarlo.\",\"source\":\"Customer Service\"},{\"english\":\"Underwriter\",\"spanish\":\"Agente aprobador(a)\",\"definition\":\"Underwriters identify and calculate the risk of loss from policyholders, establish appropriate premium rates, and write policies that cover this risk.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Your life insurance policy application will be sent to our underwriter for review and you will be notified if you qualify.\",\"example_es\":\"Su solicitud para la póliza de seguro de vida será enviada a nuestro agente aprobador para su revisión y usted será notificado si cumple con los requisitos.\",\"source\":\"Customer Service\"},{\"english\":\"Underwriting\",\"spanish\":\"Evaluación de riesgos\",\"definition\":\"Refers to the process or practice that screens, evaluates, researches and quantifies a financial risk.\",\"industry\":\"Finance\",\"example_en\":\"The underwriting department of an insurance company decides which risks the company should take.\",\"example_es\":\"El departamento de evaluación de riesgos de una compañía de seguros decide los riesgos que la compañía debe correr.\",\"source\":\"Customer Service\"},{\"english\":\"Unearned premium\",\"spanish\":\"Prima no devengada\",\"definition\":\"The amount of a pre-paid premium that has not yet been used to buy coverage.\",\"industry\":\"Home Insurance\",\"example_en\":\"The unearned premium is to be returned when the insurer cancels the coverage.\",\"example_es\":\"La prima no devengada debe devolverse cuando el asegurador cancela la cobertura.\",\"source\":\"Customer Service\"},{\"english\":\"Unemployment benefits\",\"spanish\":\"Beneficios de desempleo\",\"definition\":\"A payment made by a government or a labor union to an unemployed person, while they look for work.\",\"industry\":\"Social Services\",\"example_en\":\"Since you were laid off you can apply for unemployment benefits for a maximum of 6 months.\",\"example_es\":\"Ya que sufrió un cese laboral, usted puede solicitar beneficios de desempleo por un máximo de 6 meses.\",\"source\":\"Customer Service\"},{\"english\":\"Unexcused absence\",\"spanish\":\"Ausencia injustificada\",\"definition\":\"Unexcused absences occur when the parent cannot produce any documentation that explains the absence, or if the parent presents documentation that does not meet criteria for excused absences.\",\"industry\":\"School\",\"example_en\":\"According to our records, Grace has accrued more than 5 unexcused absences this school year.\",\"example_es\":\"Según nuestros registros, Grace ha acumulado más de 5 ausencias injustificadas este año escolar.\",\"source\":\"Customer Service\"},{\"english\":\"Uninsured Motorist Coverage\",\"spanish\":\"Cobertura contra conductor(a) no asegurado(a)\",\"definition\":\"Uninsured motorist coverage (UM) is an add-on coverage for auto policies that will pay for injuries and damages caused by an uninsured driver. Hit-and-run drivers are also considered uninsured motorists.\",\"industry\":\"Auto Insurance\",\"example_en\":\"He incurred over $1 million in medical bills arising from an auto accident with a person without uninsured motorist coverage.\",\"example_es\":\"Contrajo más de 1 millón de dólares en facturas médicas que surgieron de un accidente automovilístico con una persona sin cobertura contra conductor no asegurado.\",\"source\":\"Customer Service\"},{\"english\":\"Union /\\nLabor union\",\"spanish\":\"Sindicato\",\"definition\":\"An organization of workers in a trade, industry, or company that is created to represent the workers in negotiations with management over issues of pay, benefits, and working conditions.\",\"industry\":\"General\",\"example_en\":\"At 14 years old, he started to work full-time in the construction industry, and joined a local labor union.\",\"example_es\":\"A los 14 años de edad empezó a trabajar a tiempo completo en la industria de la construcción y se unió a un sindicato local.\",\"source\":\"Customer Service\"},{\"english\":\"Update\",\"spanish\":\"Actualizar\",\"definition\":\"To bring up to date. To inform (someone) with the latest information.\",\"industry\":\"General\",\"example_en\":\"You need to update your contact information so we can ensure the correspondence is sent to the right place.\",\"example_es\":\"Necesita actualizar su información de contacto para asegurarnos que la correspondencia se envía al lugar correcto.\",\"source\":\"Customer Service\"},{\"english\":\"Upset\",\"spanish\":\"Alterado / \\nDisgustado (NOT DISGUSTED)\",\"definition\":\"A state of being unhappy, disappointed, or worried.\",\"industry\":\"General\",\"example_en\":\"No one had explained that to me, I am very upset.\",\"example_es\":\"Nadie me lo había explicado, estoy muy disgustado.\",\"source\":\"Customer Service\"},{\"english\":\"Urgent Care\",\"spanish\":\"Cuidados de urgencias /\\nAtención de urgencias\",\"definition\":\"Urgent care centers primarily treat injuries or illnesses requiring immediate care, but not serious enough to require an emergency department visit.\",\"industry\":\"Medical\",\"example_en\":\"Go to an urgent care center or a walk-in clinic to see a doctor for your son's minor injury; there is no need to rush to the emergency room.\",\"example_es\":\"Acuda a un centro de atención de urgencias o a una clínica sin cita previa para ver a un médico por la lesión menor de su hijo; no hay necesidad de correr a la sala de emergencias.\",\"source\":\"Customer Service\"},{\"english\":\"Urinalysis\",\"spanish\":\"Análisis de orina\",\"definition\":\"A test that evaluates a sample of urine to detect and assess a wide range of disorders, such as urinary tract infection, kidney disease and diabetes.\",\"industry\":\"Medical\",\"example_en\":\"According to your urinalysis, you have a bladder infection.\",\"example_es\":\"De acuerdo a su análisis de orina tiene una infección en la vejiga.\",\"source\":\"Customer Service\"},{\"english\":\"Urinary incontinence\",\"spanish\":\"Incontinencia urinaria\",\"definition\":\"The involuntary leakage of urine. The inability to hold urine in the bladder because voluntary control over the urinary sphincter is either lost or weakened.\",\"industry\":\"Medical\",\"example_en\":\"Shortly after the C section, I began to experience urinary incontinence.\",\"example_es\":\"Poco después de la cesárea empecé a experimentar incontinencia urinaria.\",\"source\":\"Customer Service\"},{\"english\":\"Username\",\"spanish\":\"Nombre de usuario\",\"definition\":\"Also known as \\\"user ID\\\". A sequence of characters, different from a password, that is used as identification and is required when logging on to a computer or website.\",\"industry\":\"General\",\"example_en\":\"You will need to create a username and password before you will have access to this system.\",\"example_es\":\"Necesitará crear un nombre de usuario y contraseña antes de tener acceso a este sistema.\",\"source\":\"Customer Service\"},{\"english\":\"Utilities\",\"spanish\":\"Servicios públicos / \\nServicios básicos \\n(NO UTILIDADES)\",\"definition\":\"Utilities are the basic services your home, apartment, or business needs to keep it comfortable and functioning properly. Common utilities include water, sewer, electric, gas, trash, and recycling.\",\"industry\":\"Customer Service\",\"example_en\":\"You have two basic options for setting up utilities: transfer your existing utilities to your new home, or establish new accounts.\",\"example_es\":\"Usted tiene dos opciones básicas para establecer los servicios públicos: Transferir sus servicios públicos existentes a su nueva casa, o establecer cuentas nuevas.\",\"source\":\"Customer Service\"},{\"english\":\"Utility bill\",\"spanish\":\"Factura de servicios públicos /\\nFactura de servicios básicos\",\"definition\":\"A bill containing the amount due for the consumption of a service such as electricity, gas, and water.\",\"industry\":\"Customer Service\",\"example_en\":\"I typically receive different utility bills from the companies providing water, electricity and gas.\",\"example_es\":\"Yo típicamente recibo diferentes facturas de servicios públicos de las compañías que proveen agua, electricidad y gas.\",\"source\":\"Customer Service\"},{\"english\":\"Vaccines /\\nVaccination /\\nImmunizations\",\"spanish\":\"Vacunas\",\"definition\":\"Biological preparations that provide active acquired immunity to a particular infectious disease. A vaccine typically contains an agent that resembles a disease-causing microorganism and is often made from weakened or killed forms of the microbe.\",\"industry\":\"Medical\",\"example_en\":\"It is important to keep your child's vaccines up to date.\",\"example_es\":\"Es importante mantener las vacunas de su hijo al día.\",\"source\":\"Customer Service\"},{\"english\":\"Vaginal discharge\",\"spanish\":\"Secreción vaginal /\\nFlujo vaginal\",\"definition\":\"Refers to secretions from the vagina; the discharge may be: Thick, pasty, or thin, clear, cloudy, odorless or have a bad odor.\",\"industry\":\"Medical\",\"example_en\":\"Does the vaginal discharge have a bad odor?\",\"example_es\":\"¿Tiene un mal olor el flujo vaginal?\",\"source\":\"Customer Service\"},{\"english\":\"Vaginal yeast infection\",\"spanish\":\"Infección vaginal por hongos /\\nCandidiasis vaginal\",\"definition\":\"A usually localized infection, as of the vagina or mucous membranes of the mouth, caused by fungi of the genus Candida.\",\"industry\":\"Medical\",\"example_en\":\"We're going to treat the vaginal yeast infection with pills instead of creams.\",\"example_es\":\"Vamos a tratar la infección vaginal por hongos con pastillas en lugar de cremas.\",\"source\":\"Customer Service\"},{\"english\":\"Vehicle\",\"spanish\":\"Vehículo\",\"definition\":\"A mechanical machine used for transporting people or goods, especially on land, such as a car, truck, etc.\",\"industry\":\"Auto Insurance\",\"example_en\":\"What's your vehicle's make and model?\",\"example_es\":\"¿Cuál es la marca y modelo de su vehículo?\",\"source\":\"Customer Service\"},{\"english\":\"Vendor\",\"spanish\":\"Proveedor\",\"definition\":\"A vendor is a person or company that sells goods or services for a profit. They can operate in a business-to-consumer (B2C) or business-to-business (B2B) environment. In B2B, vendors are often known as suppliers.\",\"industry\":\"Customer Service\",\"example_en\":\"A vendor is a company or person that sells a product or service.\",\"example_es\":\"Un proveedor es una compañía o persona que vende un producto o servicio.\",\"source\":\"Customer Service\"},{\"english\":\"Vent /\\nAir vents\",\"spanish\":\"Ventilación /\\nRendijas de ventilación\",\"definition\":\"A small opening that allows air, smoke, or gas to enter or leave a closed space.\",\"industry\":\"Customer Service\",\"example_en\":\"Yes, you can close your basement vents in the summer, but only for short periods, not for weeks at a time.\",\"example_es\":\"Sí, puede cerrar la ventilación de su sótano en el verano, pero sólo por periodos cortos, no por semanas cada vez.\",\"source\":\"Customer Service\"},{\"english\":\"Verify\",\"spanish\":\"Verificar\",\"definition\":\"To make sure or demonstrate that (something) is true, accurate, or justified.\",\"industry\":\"General\",\"example_en\":\"You may call the airline company to verify your flight reservation.\",\"example_es\":\"Puede llamar a la compañía aérea para verificar su reservación de vuelo.\",\"source\":\"Customer Service\"},{\"english\":\"VIN (Vehicle Identification Number)\",\"spanish\":\"Número de identificación vehicular\",\"definition\":\"A form of identification used by all modern motor vehicles. It contains data about the vehicle's manufacture and country of origin including some model-specific details and the vehicle's unique production serial number.\",\"industry\":\"Auto Insurance\",\"example_en\":\"In order to read your VIN number, please consider that the first character tells you where in the world the vehicle was built.\",\"example_es\":\"A fin de leer su número de identificación vehicular, por favor considere que el primer carácter le indica en qué parte del mundo se construyó el vehículo.\",\"source\":\"Customer Service\"},{\"english\":\"Visibility\",\"spanish\":\"Visibilidad\",\"definition\":\"The distance one can see as determined by light and weather conditions. How clearly objects can be seen, or how far you can see clearly, usually because of the weather conditions.\",\"industry\":\"Auto Insurance\",\"example_en\":\"The fog was so dense there was no visibility.\",\"example_es\":\"La niebla estaba tan densa que no había visibilidad.\",\"source\":\"Customer Service\"},{\"english\":\"Vital Signs\",\"spanish\":\"Signos vitales\",\"definition\":\"Clinical measurements, specifically pulse rate, temperature, respiration rate, and blood pressure.\",\"industry\":\"Medical\",\"example_en\":\"The babies in this unit have various devices attached to them that monitor the vital signs.\",\"example_es\":\"Los bebés en esta unidad tienen varios dispositivos conectados a ellos que monitorean los signos vitales.\",\"source\":\"Customer Service\"},{\"english\":\"Void\",\"spanish\":\"Nulo /\\nAnular\",\"definition\":\"Having no legal force or effect; not legally binding or enforceable.\",\"industry\":\"Finance\",\"example_en\":\"I will just void the check and pay you in cash.\",\"example_es\":\"Solo voy a anular el cheque y pagarle en efectivo.\",\"source\":\"Customer Service\"},{\"english\":\"Void\",\"spanish\":\"Vaciar la vejiga\",\"definition\":\"To discharge or emit -void urine.\",\"industry\":\"Medical\",\"example_en\":\"Can you void your bladder completely?\",\"example_es\":\"¿Usted puede vaciar completamente la vejiga?\",\"source\":\"Customer Service\"},{\"english\":\"Voided check\",\"spanish\":\"Cheque nulo /\\nCheque anulado\",\"definition\":\"A voided check is a check that has been cancelled. A voided check will have all of your bank information printed on it, so it can provide others everything they need to set up a direct deposit payment from your account.\",\"industry\":\"Finance\",\"example_en\":\"Make a copy of the voided check for your records, noting the check number.\",\"example_es\":\"Haga una copia del cheque nulo para su registro, anotando el número de cheque.\",\"source\":\"Customer Service\"},{\"english\":\"Vomiting\",\"spanish\":\"Vómito /\\nCon vómitos\",\"definition\":\"Refers to the involuntary, forceful expulsion of the contents of one's stomach through the mouth and sometimes the nose.\",\"industry\":\"Medical\",\"example_en\":\"My son has been vomiting since last night and has had diarrhea twice this morning. He may also have a fever as he feels warm to the touch.\",\"example_es\":\"Mi hijo ha estado vomitando desde anoche y ha tenido diarrea dos veces esta mañana. Tal vez también tenga fiebre ya que se siente caliente al tacto.\",\"source\":\"Customer Service\"},{\"english\":\"Wages\",\"spanish\":\"Salario\",\"definition\":\"An amount of money paid each hour or day to compensate an employee for the amount of time he/she spends working.\",\"industry\":\"General\",\"example_en\":\"He earns a good wage, because he works for a fair employer.\",\"example_es\":\"Él gana un buen salario, porque trabaja para un empleador justo.\",\"source\":\"Customer Service\"},{\"english\":\"Waive (verb)\",\"spanish\":\"Eximir /\\nExonerar /\\nCondonar\",\"definition\":\"To refrain from applying or enforcing (a rule, restriction, or fee).\",\"industry\":\"Finance\",\"example_en\":\"As a one time courtesy, we will waive the late fee.\",\"example_es\":\"Como cortesía única vamos a exonerar el cargo por mora.\",\"source\":\"Customer Service\"},{\"english\":\"Waiver\",\"spanish\":\"Exención / \\nRenuncia (Context dependent)\",\"definition\":\"A waiver is a formal statement giving up a right.\",\"industry\":\"General\",\"example_en\":\"My father did not do any military service; he got a waiver.\",\"example_es\":\"Mi padre no realizó ningún servicio militar; él obtuvo una exención.\",\"source\":\"Customer Service\"},{\"english\":\"Walk-in clinic\",\"spanish\":\"Clínica ambulatoria /\\nClínica donde se atiende sin cita y por orden de llegada\",\"definition\":\"Refers to a very broad category of facilities only loosely defined as those that accept patients on a walk-in basis and with no appointment required.\",\"industry\":\"Medical\",\"example_en\":\"I can give you the address to your nearest walk-in clinic.\",\"example_es\":\"Le puedo dar la dirección de la clínica ambulatoria más cercana.\",\"source\":\"Customer Service\"},{\"english\":\"Walker\",\"spanish\":\"Andadera /\\nAndador\",\"definition\":\"A frame that is designed to support someone such as a baby or an injured or elderly person who needs help walking.\",\"industry\":\"Medical\",\"example_en\":\"Please ask your doctor to write a prescription for a walker and the insurance will cover it.\",\"example_es\":\"Por favor, pídale a su médico que le escriba una receta para un andador y el seguro lo cubrirá.\",\"source\":\"Customer Service\"},{\"english\":\"Warning\",\"spanish\":\"Advertencia / \\nAlerta\",\"definition\":\"A warning is an advance notice of something that will happen, often something unpleasant or dangerous; something that makes us aware of possible danger.\",\"industry\":\"General\",\"example_en\":\"There were storm warnings issued for the area.\",\"example_es\":\"Se emitieron advertencias de tornado para el área.\",\"source\":\"Customer Service\"},{\"english\":\"Warrant\",\"spanish\":\"Orden\",\"definition\":\"A document issued by a legal or government official authorizing the police or some other body to make an arrest, search premises, or carry out some other action relating to the administration of justice.\",\"industry\":\"911 - Law enforcement\",\"example_en\":\"The police had a warrant to search the house.\",\"example_es\":\"La policía tenía una orden para registrar la vivienda.\",\"source\":\"Customer Service\"},{\"english\":\"Warranty\",\"spanish\":\"Garantía\",\"definition\":\"A written guarantee, issued to the purchaser of an article by its manufacturer, promising to repair or replace it if necessary within a specified period of time.\",\"industry\":\"Customer Service\",\"example_en\":\"The warranty covers the car for a year, with unlimited mileage.\",\"example_es\":\"La garantía cubre el carro por un año, con kilometraje ilimitado.\",\"source\":\"Customer Service\"},{\"english\":\"Wasp nest\",\"spanish\":\"Nido de avispas\",\"definition\":\"A wasp nest is made from chewed wood that gives them their distinctive papery walls, with the exception of mud daubers that use clay or mud. Queen wasps build small nests in the spring and lay the first batch of eggs\",\"industry\":\"General\",\"example_en\":\"Have you noticed a wasp nest near your home or suspect one?\",\"example_es\":\"¿Ha notado un nido de avispas cerca de su casa o sospecha que lo hay?\",\"source\":\"Customer Service\"},{\"english\":\"Water heater\",\"spanish\":\"Calentador de agua\",\"definition\":\"Refers to a thermodynamic device that uses an energy source (gas or power) to heat water above its initial temperature.\",\"industry\":\"Customer Service\",\"example_en\":\"The water heater appears to be broken. How much will it cost to repair it or get it replaced?\",\"example_es\":\"El calentador de agua parece estar estropeado. ¿Cuánto costaría repararlo o remplazarlo?\",\"source\":\"Customer Service\"},{\"english\":\"Watery stool\",\"spanish\":\"Defecación aguada\",\"definition\":\"Diarrhea is multiple bouts of very loose, watery stools with little to no form.\",\"industry\":\"Medical\",\"example_en\":\"The medicine is causing watery stools. Can I stop taking it?\",\"example_es\":\"El medicamento me está causando defecación aguada. ¿Puedo dejar de tomarlo?\",\"source\":\"Customer Service\"},{\"english\":\"Weakness\",\"spanish\":\"Debilidad\",\"definition\":\"The state or condition of lacking strength.\",\"industry\":\"Medical\",\"example_en\":\"How long have you had the weakness in your right leg?\",\"example_es\":\"¿Por cuánto tiempo ha tenido esta debilidad en la pierna derecha?\",\"source\":\"Customer Service\"},{\"english\":\"Wear and tear\",\"spanish\":\"Desgaste por uso / \\nDesgaste\",\"definition\":\"The damage that happens to an object in ordinary use during a period of time\",\"industry\":\"Insurance (general)\",\"example_en\":\"Most tires will last for four years with normal wear and tear.\",\"example_es\":\"La mayoría de los neumáticos duran cuatro años con un desgaste por uso normal.\",\"source\":\"Customer Service\"},{\"english\":\"Weather conditions\",\"spanish\":\"Condiciones climáticas /\\nEstado del tiempo\",\"definition\":\"The conditions of the atmosphere in terms of temperature, atmospheric pressure, wind, and moisture.\",\"industry\":\"Auto Insurance\",\"example_en\":\"What were the weather conditions the day of the accident?\",\"example_es\":\"¿Cuáles eran las condiciones climáticas el día del accidente?\",\"source\":\"Customer Service\"},{\"english\":\"Welfare\",\"spanish\":\"Bienestar Social\",\"definition\":\"Welfare refers to government-sponsored assistance programs for individuals and families in need. Welfare programs are typically funded through taxation.\",\"industry\":\"Social Services\",\"example_en\":\"Welfare encompasses a range of government programs designed for individuals and families who do not make enough money to have a decent standard of living.\",\"example_es\":\"Bienestar social engloba una serie de programas gubernamentales destinados a personas y familias que no ganan el dinero suficiente para tener un nivel de vida decente.\",\"source\":\"Customer Service\"},{\"english\":\"Well nourished\",\"spanish\":\"Bien alimentado(a) / \\nBien nutrido(a)\",\"definition\":\"Having been provided with plenty of the material necessary for life and growth.\",\"industry\":\"School\",\"example_en\":\"The nurse said Anna was strong and well nourished.\",\"example_es\":\"La enfermera dijo que Anna estaba fuerte y bien alimentada.\",\"source\":\"Customer Service\"},{\"english\":\"Wheelbarrow\",\"spanish\":\"Carretilla\",\"definition\":\"A wheelbarrow is a small hand-propelled vehicle, usually with just one wheel, designed to be pushed and guided by a single person using two handles at the rear.\",\"industry\":\"General\",\"example_en\":\"He trundled a wheelbarrow to the backyard.\",\"example_es\":\"El rodó la carretilla hasta el jardín trasero.\",\"source\":\"Customer Service\"},{\"english\":\"Wheelchair\",\"spanish\":\"Silla de ruedas\",\"definition\":\"Medical equipment that people who are unable to walk use for moving around. Used when walking is difficult or impossible due to illness, injury, problems related to age, or disability.\",\"industry\":\"General\",\"example_en\":\"He spent the last ten years of his life in a wheelchair after a fall that left him paralyzed from the waist down.\",\"example_es\":\"Pasó los últimos diez años de su vida en silla de ruedas tras una caída que lo dejó paralizado de cintura para abajo.\",\"source\":\"Customer Service\"},{\"english\":\"Wheezing\",\"spanish\":\"Sibilancia / \\nResuello\",\"definition\":\"Refers to a person that breathes with a whistling or rattling sound in the chest, as a result of obstruction in the air passages.\",\"industry\":\"Medical\",\"example_en\":\"Wheezing can be caused by many things, one being asthma.\",\"example_es\":\"La sibilancia puede ser causado por muchos factores, uno de ellos es asma.\",\"source\":\"Customer Service\"},{\"english\":\"Whiplash\",\"spanish\":\"Latigazo /\\nLatigazo cervical\",\"definition\":\"A neck injury caused by sudden jerking (backward, forward, or both) of the head.\",\"industry\":\"Medical\",\"example_en\":\"The doctor said I had whiplash and need therapy.\",\"example_es\":\"El doctor me dijo que sufrí un latigazo en la nuca y necesito terapia.\",\"source\":\"Customer Service\"},{\"english\":\"Whiteboard\",\"spanish\":\"Pizarra acrilica\",\"definition\":\"A whiteboard is a hard smooth white surface used for writing or drawing on with markers.\",\"industry\":\"School\",\"example_en\":\"The teacher used 3 different color markers when writing on the whiteboard.\",\"example_es\":\"El maestro usó 3 marcadores de diferentes colores al escribir en la pizarra acrílica.\",\"source\":\"Customer Service\"},{\"english\":\"Whooping cough\",\"spanish\":\"Tos ferina /\\nTos convulsiva\",\"definition\":\"Whooping cough (pertussis) is a bacterial infection of the lungs and breathing tubes. It spreads very easily and can sometimes cause serious problems. It's important for babies and children to get vaccinated against it.\",\"industry\":\"Medical\",\"example_en\":\"There are no safe or effective alternatives to the whooping cough vaccine to protect against the disease.\",\"example_es\":\"No existen alternativas seguras o eficaces a la vacuna contra la tos ferina para proteger contra la enfermedad.\",\"source\":\"Customer Service\"},{\"english\":\"WIC Program (Women, Infants and Children)\",\"spanish\":\"Programa para mujeres, lactantes y niños\",\"definition\":\"The WIC program provides federal grants to states for supplemental foods, health care referrals, and nutrition education for low-income pregnant, breastfeeding, and non-breastfeeding postpartum women, and to infants and children up to age 5 who are found to be at nutritional risk.\",\"industry\":\"Social Services\",\"example_en\":\"The WIC program is designed to help mothers with infants purchase items such as milk, eggs and baby formula.\",\"example_es\":\"El programa para mujeres, lactantes y niños está diseñado para ayudar a las madres con lactantes a comprar artículos como leche, huevos y fórmula para bebés.\",\"source\":\"Customer Service\"},{\"english\":\"Window sill\",\"spanish\":\"Alféizar de la ventana\",\"definition\":\"A window sill, also known as a window ledge or window bottom, is the shelf-like, flat piece of the window trim found at the base of the window.\",\"industry\":\"Home Insurance\",\"example_en\":\"Window sills are important to the design and functionality of the window.\",\"example_es\":\"Los alféizares de las ventanas son importantes para el diseño y funcionalidad de la ventana.\",\"source\":\"Customer Service\"},{\"english\":\"Windpipe /\\ntrachea\",\"spanish\":\"Tráquea\",\"definition\":\"The trachea, colloquially called the windpipe, is a cartilaginous tube that connects the pharynx and larynx to the lungs, allowing the passage of air, and so is present in almost all  air-breathing animals with lungs.\",\"industry\":\"Medical\",\"example_en\":\"A tube was inserted into his windpipe to help him breathe.\",\"example_es\":\"Le insertaron un tubo en la tráquea para ayudarle a respirar.\",\"source\":\"Customer Service\"},{\"english\":\"Windshield\",\"spanish\":\"Parabrisas\",\"definition\":\"A transparent screen (as of glass) that protects the occupants of a vehicle\",\"industry\":\"Auto Insurance\",\"example_en\":\"A rock hit my windshield and it cracked.\",\"example_es\":\"Una piedra golpeó el parabrisas y lo rompió.\",\"source\":\"Customer Service\"},{\"english\":\"Wipers\",\"spanish\":\"Limpiaparabrisas\",\"definition\":\"A motor-driven device designed to keep a windshield clear of rain, it typically has a rubber blade on an arm that moves in an arc.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Wipers should be replaced twice a year.\",\"example_es\":\"Los limpiaparabrisas deben ser reemplazados dos veces al año.\",\"source\":\"Customer Service\"},{\"english\":\"Wire transfer\",\"spanish\":\"Transferencia electrónica bancaria\",\"definition\":\"An electronic funds transfer (wire transfer) is a form of electronic payment that sends money directly from one bank account to another.\",\"industry\":\"Finance\",\"example_en\":\"With a wire transfer, the bank acts as an intermediary for payment.\",\"example_es\":\"Con una transferencia electrónica bancaria, el banco actúa como intermediario para el pago.\",\"source\":\"Customer Service\"},{\"english\":\"Wiring\",\"spanish\":\"Cableado\",\"definition\":\"Wiring is defined as the set of cables, connectors, pipes and devices that make up the interior telecommunications infrastructure of a building or enclosure.\",\"industry\":\"Home Insurance\",\"example_en\":\"All the wiring in the house needs to be replaced.\",\"example_es\":\"Todo el cableado de la casa necesita ser reemplazado.\",\"source\":\"Customer Service\"},{\"english\":\"Withdrawal\",\"spanish\":\"Retiro\",\"definition\":\"The act of taking money out of an account.\",\"industry\":\"Finance\",\"example_en\":\"A withdrawal was made from your account on July 5th.\",\"example_es\":\"Un retiro se hizo de su cuenta el 5 de julio.\",\"source\":\"Customer Service\"},{\"english\":\"Witness\",\"spanish\":\"Testigo\",\"definition\":\"A person who sees that something happens, such as an event or occurrence, typically a crime or accident.\",\"industry\":\"General\",\"example_en\":\"According to the witness, the robbery was carried out by two teenagers.\",\"example_es\":\"Según el testigo, el robo fue perpetrado por dos adolescentes.\",\"source\":\"Customer Service\"},{\"english\":\"Womb\",\"spanish\":\"Vientre /\\nÚtero /\\nMatriz\",\"definition\":\"The uterus. The organ in the body of a woman or other female mammal in which a baby develops before birth.\",\"industry\":\"Medical\",\"example_en\":\"During the sonogram the doctor saw some abnormalities in the womb.\",\"example_es\":\"Durante la ecografía el médico vio algunas anomalías en el vientre.\",\"source\":\"Customer Service\"},{\"english\":\"Woodcock-Johnson Revised (WJ-R)\",\"spanish\":\"Prueba Woodcock-Johnson corregida\",\"definition\":\"The Woodcock-Johnson Revised is a commonly used measure of children's achievement measuring various aspects of scholastic ability.\",\"industry\":\"School\",\"example_en\":\"Woodcock-Johnson Revised (WJ-R) test has been used for a broad range of ages, from young children to elderly individuals.\",\"example_es\":\"La prueba Woodcock-Johnson corregida se ha utilizado en una amplia gama de edades, desde niños pequeños hasta personas mayores.\",\"source\":\"Customer Service\"},{\"english\":\"Woodworking tools\",\"spanish\":\"Herramientas de carpintería\",\"definition\":\"Tools to cut, finish, assemble, measure and hold wooden parts while transforming raw materials into completed projects.\",\"industry\":\"General\",\"example_en\":\"You can buy the woodworking tools you need on Amazon.\",\"example_es\":\"Puede comprar las herramientas de carpintería que necesita en Amazon.\",\"source\":\"Customer Service\"},{\"english\":\"Workers' compensation\",\"spanish\":\"Indemnización laboral\",\"definition\":\"A form of insurance required from employers that provides money as compensation for workers who are injured at work or contract an occupational disease.\",\"industry\":\"Workers' Compensation\",\"example_en\":\"To get an exemption for workers’ compensation coverage, your business must go through your state’s screening process.\",\"example_es\":\"Para obtener una dispensa de la cobertura de compensación de los trabajadores, su empresa debe pasar por el proceso de selección de su estado.\",\"source\":\"Customer Service\"},{\"english\":\"Wound\",\"spanish\":\"Herida\",\"definition\":\"An injury to living tissue caused by a cut, blow, or other impact, typically one in which the skin is cut or broken.\",\"industry\":\"Medical\",\"example_en\":\"As a diabetic, you have to check your feet for wounds everyday.\",\"example_es\":\"Como diabético, todos los días se tiene que revisar sus pies por heridas.\",\"source\":\"Customer Service\"},{\"english\":\"Writing prompts\",\"spanish\":\"Estímulos para la escritura / \\nEjemplos de escritura\",\"definition\":\"The purposes of a writing prompt are to encourage the student's interest in a topic and encourage them to write about it in a thoughtful and creative way.\",\"industry\":\"School\",\"example_en\":\"Writing prompts introduce and focus the writing topic.\",\"example_es\":\"Los estímulos para la escritura presentan y se centran en el tema de la escritura.\",\"source\":\"Customer Service\"},{\"english\":\"Year/make/model\",\"spanish\":\"Año, marca, modelo\",\"definition\":\"These three terms are used to describe motor vehicles. They refer to the year a car was built for sale; make refers to the manufacturer's brand, and model refers to the different sizes or capabilities of that type of vehicle.\",\"industry\":\"Auto Insurance\",\"example_en\":\"Please, provide the year, make and model of your vehicle. We will look in our database to see how much your registration renewal will cost.\",\"example_es\":\"Por favor, brinde el año, marca y modelo de su vehículo. Revisaremos nuestra base de datos para ver cuánto costará la renovación de su registro.\",\"source\":\"Customer Service\"},{\"english\":\"Yield sign\",\"spanish\":\"Señal de ceder el paso /\\nSeñal de ceder la vía\",\"definition\":\"A yield sign calls on the driver to slow down, defer to oncoming or intersecting traffic, stop when necessary, proceed when safe, and remain aware of oncoming vehicles.\",\"industry\":\"Auto Insurance\",\"example_en\":\"You are mistaken, it wasn't a stop sign but a yield sign.\",\"example_es\":\"Se equivoca, no era una señal de alto, sino una señal de ceder el paso.\",\"source\":\"Customer Service\"}]; glossary=EMBEDDED_GLOSSARY; const ds=[...new Set(glossary.map(a=>a.industry).filter(Boolean))].sort(); ds.forEach(d=>{const o=document.createElement(\"option\");o.value=d;o.textContent=d;$('domain').appendChild(o)});\nfunction findTerms(t){const n=norm(t),d=$('domain').value,f=[];for(const g of glossary){if(d&&g.industry!==d)continue;const a=norm(g.english),b=norm(g.spanish);if((a.length>2&&n.includes(a))||(b.length>2&&n.includes(b)))f.push(g);if(f.length>=7)break}return f}\nfunction renderTerms(t){const f=findTerms(t);$('terms').innerHTML=f.length?f.map(g=>`<div class=\"termrow\"><div class=\"term\">${esc(g.english)} → ${esc(g.spanish)}</div><div class=\"explain\">${esc(g.definition||\"Sin explicación registrada.\")}</div><div class=\"meta\">${esc(g.industry||\"General\")}</div></div>`).join(''):'<div class=\"meta\">No se detectaron términos del glosario.</div>'}\nfunction renderDetails(t){const dates=(t.match(/\\b(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\\s+\\d{1,2}(?:st|nd|rd|th)?\\b|\\b\\d{1,2}[\\/-]\\d{1,2}[\\/-]\\d{2,4}\\b/gi)||[]);const nums=(t.match(/\\b\\d+(?:[.,]\\d+)?\\b/g)||[]);const addr=(t.match(/\\b\\d+\\s+[A-Za-z][A-Za-z .'-]{2,45}(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Drive|Dr|Lane|Ln|Court|Ct)\\b/gi)||[]);$('details').innerHTML=`<div class=\"detail\"><b>Fechas</b>${esc(dates.join(', ')||'—')}</div><div class=\"detail\"><b>Números</b>${esc(nums.join(', ')||'—')}</div><div class=\"detail\"><b>Direcciones</b>${esc(addr.join(', ')||'—')}</div><div class=\"detail\"><b>Otros</b>—</div>`}\nfunction showHeard(t,partial=false){$('heard').innerHTML=esc(t)+(partial?' <span class=\"partial\">…</span>':'');renderTerms(t);renderDetails(t)}\nfunction addHistory(src,tr){if(!src||!tr)return;history.unshift({src,tr});if(history.length>30)history.pop();$('history').innerHTML=history.map(x=>`<div class=\"item\">${esc(x.src)}<b>${esc(x.tr)}</b></div>`).join('')}\nasync function translateText(text){const direction=$('direction').value;const target=direction==='en-es'?'es':'en';translateController=new AbortController();const r=await fetch('/api/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text, target}),signal:translateController.signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo traducir');return d.translation||''}\nasync function interpret(text){if(!text.trim()||translationBusy)return;translationBusy=true;$('translation').textContent='Interpretando…';try{const tr=await translateText(text);if(!listening)return;$('translation').textContent=tr;addHistory(text,tr)}catch(e){if(e.name!=='AbortError'&&listening)$('translation').textContent='Error de traducción: '+e.message}finally{translationBusy=false;translateController=null}}\nfunction start(){\n const SR=window.SpeechRecognition||window.webkitSpeechRecognition;\n if(!SR){alert('Este navegador no ofrece reconocimiento de voz gratuito. En iPhone/iPad prueba Safari actualizado; si no aparece, usa Chrome/Edge en un dispositivo compatible.');return}\n recognition=new SR();recognition.continuous=true;recognition.interimResults=true;recognition.maxAlternatives=1;\n recognition.lang=$('direction').value==='en-es'?'en-US':'es-US';\n recognition.onstart=()=>{$('status').textContent='Escuchando';$('status').classList.add('live');listening=true;$('listen').classList.add('active');$('listen').textContent='⏹️ Detener escucha'};\n recognition.onresult=e=>{let interim='',finalText='';for(let i=e.resultIndex;i<e.results.length;i++){const txt=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=txt;else interim+=txt}if(finalText){lastFinal=(lastFinal+' '+finalText).trim();showHeard(lastFinal);interpret(finalText)}else showHeard((lastFinal+' '+interim).trim(),true)};\n recognition.onerror=e=>{console.warn(e);if(e.error==='not-allowed'||e.error==='service-not-allowed'){stop();alert('El micrófono o el reconocimiento de voz no tienen permiso. Activa el micrófono en el navegador.')}};\n recognition.onend=()=>{if(listening){try{recognition.start()}catch(e){}}};\n recognition.start();\n}\nfunction stop(){listening=false;if(recognition){try{recognition.stop()}catch(e){}recognition=null}$('listen').classList.remove('active');$('listen').textContent='🎙️ Escuchar';$('status').classList.remove('live');$('status').textContent='Pausado'}\nlet deferredInstallPrompt=null;\nconst installButton=$(\"install\");\nfunction isIOS(){return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform===\'MacIntel\' && navigator.maxTouchPoints>1)}\nfunction isStandalone(){return window.matchMedia(\'(display-mode: standalone)\').matches || window.navigator.standalone===true}\nfunction updateInstallButton(){if(isStandalone()){installButton.classList.add(\"hidden\");}else{installButton.classList.remove(\"hidden\");}}\nupdateInstallButton();\nwindow.addEventListener(\"beforeinstallprompt\",e=>{e.preventDefault();deferredInstallPrompt=e;installButton.classList.remove(\"hidden\");});\nwindow.addEventListener(\"appinstalled\",()=>{deferredInstallPrompt=null;installButton.classList.add(\"hidden\");$(\'status\').textContent=\'Aplicación instalada\'});\ninstallButton.onclick=async()=>{\n if(deferredInstallPrompt){deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice?.outcome===\'accepted\'){installButton.classList.add(\"hidden\");}return;}\n if(isIOS()){alert(\'Para instalar Interpretia en iPhone o iPad: toca Compartir (el cuadrado con la flecha hacia arriba) en Safari y selecciona “Añadir a pantalla de inicio”. Después toca “Añadir”.\');return;}\n const isAndroid=/android/i.test(navigator.userAgent);\n if(isAndroid()){alert(\'Para instalar Interpretia en Android: abre el menú ⋮ de Chrome y elige “Instalar aplicación” o “Añadir a pantalla de inicio”.\');return;}\n alert(\'Para instalar Interpretia en una PC o Mac: abre el menú de Chrome o Edge y busca “Instalar Interpretia” o el icono de instalación en la barra de direcciones.\');\n};\n$('listen').onclick=()=>listening?stop():start();\n$('direction').onchange=()=>{if(listening){stop();start()}};\nfunction clearSession(){\n  stop();\n  if(translateController){try{translateController.abort()}catch(e){} translateController=null}\n  lastFinal='';\n  history=[];\n  $('heard').textContent='Pulsa “Escuchar” y permite el micrófono.';\n  $('translation').textContent='La interpretación aparecerá aquí por fragmentos.';\n  $('history').innerHTML='<div class=\"meta\">Sin fragmentos todavía.</div>';\n  $('terms').innerHTML='<div class=\"meta\">Se consultará el glosario automáticamente.</div>';\n  $('details').innerHTML='<div class=\"detail\"><b>Fechas</b>—</div><div class=\"detail\"><b>Números</b>—</div><div class=\"detail\"><b>Direcciones</b>—</div><div class=\"detail\"><b>Otros</b>—</div>';\n  window.scrollTo({top:0,behavior:'smooth'});\n}\n$('new').onclick=clearSession;\n$('finish').onclick=()=>{\n  clearSession();\n  $('status').textContent='Interpretación finalizada';\n};\nif('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));}\n</script>\n</body>\n</html>\n";

app.get('/health', (_req, res) => res.json({ ok: true, service: 'Interpretia Live Free' }));

app.post('/api/translate', async (req, res) => {
  const text = typeof req.body?.text === 'string' ? req.body.text.trim() : '';
  const target = req.body?.target === 'es' ? 'es' : 'en';
  if (!text) return res.status(400).json({ error: 'Texto vacío.' });
  if (text.length > 1800) return res.status(400).json({ error: 'Fragmento demasiado largo.' });
  try {
    // MyMemory provides an unauthenticated endpoint suitable for light, free use.
    const langpair = target === 'es' ? 'en|es' : 'es|en';
    const url = 'https://api.mymemory.translated.net/get?q=' + encodeURIComponent(text) + '&langpair=' + langpair;
    const r = await fetch(url, { headers: { 'User-Agent': 'Interpretia-Live-Free/1.0' } });
    const data = await r.json();
    if (!r.ok) return res.status(r.status).json({ error: 'El servicio gratuito de traducción no respondió.' });
    const translation = data?.responseData?.translatedText;
    if (!translation) return res.status(502).json({ error: 'No se obtuvo traducción.' });
    res.json({ translation, provider: 'MyMemory' });
  } catch (e) {
    res.status(502).json({ error: 'No fue posible conectar con el traductor gratuito.' });
  }
});


app.get('/manifest.webmanifest', (_req, res) => {
  res.type('application/manifest+json').send(JSON.stringify({name:'Interpretia Live',short_name:'Interpretia',start_url:'/',display:'standalone',background_color:'#f3f5f7',theme_color:'#0b1220',description:'Asistente de interpretación Español ↔ Inglés',icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png'},{src:'/icon-512.png',sizes:'512x512',type:'image/png'}]}));
});
app.get('/icon-192.png', (_req,res)=>res.sendFile(require('path').join(__dirname,'icon-192.png')));
app.get('/icon-512.png', (_req,res)=>res.sendFile(require('path').join(__dirname,'icon-512.png')));
app.get('/sw.js', (_req,res)=>{res.type('application/javascript').send(`const CACHE='interpretia-live-v2';self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/']))));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&e.request.url.startsWith(self.location.origin)){e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(x=>{const y=x.clone();caches.open(CACHE).then(c=>c.put(e.request,y));return x;}).catch(()=>caches.match('/'))));}});`);});
app.use((req, res) => {
  if (req.path.startsWith('/api/')) return res.status(404).end();
  res.type('html').send(INDEX_HTML);
});

app.listen(PORT, () => console.log(`Interpretia Live Free running on port ${PORT}`));
